export interface BodyParserArgs {
  /**
   * Request that contains the (potential) body.
   */
  request: HttpRequest;
  /**
   * Metadata that has already been parsed from the request.
   * Can be updated by the BodyParser with extra metadata.
   */
  metadata: RepresentationMetadata;
}

/**
 * Parses the body of an incoming {@link HttpRequest} and converts it to a {@link Representation}.
 */
export abstract class BodyParser extends
  AsyncHandler<BodyParserArgs, Representation> {}

import type { NamedNode, Quad, Quad_Subject, Variable } from '@rdfjs/types';
import { DataFactory, Parser, Store } from 'n3';
import { getBlankNodes, getTerms, getVariables } from 'rdf-terms';
import { TEXT_N3 } from '../../../util/ContentTypes';
import { BadRequestHttpError } from '../../../util/errors/BadRequestHttpError';
import { createErrorMessage } from '../../../util/errors/ErrorUtil';
import { UnprocessableEntityHttpError } from '../../../util/errors/UnprocessableEntityHttpError';
import { UnsupportedMediaTypeHttpError } from '../../../util/errors/UnsupportedMediaTypeHttpError';
import { guardedStreamFrom, readableToString } from '../../../util/StreamUtil';
import { RDF, SOLID } from '../../../util/Vocabularies';
import type { N3Patch } from '../../representation/N3Patch';
import type { BodyParserArgs } from './BodyParser';
import { BodyParser } from './BodyParser';

const defaultGraph = DataFactory.defaultGraph();

/**
 * Parses an N3 Patch document and makes sure it conforms to the specification requirements.
 * Requirements can be found at Solid Protocol, §5.3.1: https://solid.github.io/specification/protocol#n3-patch
 */
export class N3PatchBodyParser extends BodyParser {
  public async canHandle({ metadata }: BodyParserArgs): Promise<void> {
    if (metadata.contentType !== TEXT_N3) {
      throw new UnsupportedMediaTypeHttpError('This parser only supports N3 Patch documents.');
    }
  }

  public async handle({ request, metadata }: BodyParserArgs): Promise<N3Patch> {
    const n3 = await readableToString(request);
    const parser = new Parser({ format: TEXT_N3, baseIRI: metadata.identifier.value });
    let store: Store;
    try {
      store = new Store(parser.parse(n3));
    } catch (error: unknown) {
      throw new BadRequestHttpError(`Invalid N3: ${createErrorMessage(error)}`, { cause: error });
    }

    // Solid, §5.3.1: "A patch resource MUST contain a triple ?patch rdf:type solid:InsertDeletePatch."
    // "The patch document MUST contain exactly one patch resource,
    // identified by one or more of the triple patterns described above, which all share the same ?patch subject."
    const patches = store.getSubjects(RDF.terms.type, SOLID.terms.InsertDeletePatch, defaultGraph);
    if (patches.length !== 1) {
      throw new UnprocessableEntityHttpError(
        `This patcher only supports N3 Patch documents with exactly 1 solid:InsertDeletePatch entry, but received ${
          patches.length}.`,
      );
    }
    return {
      ...this.parsePatch(patches[0], store),
      binary: true,
      data: guardedStreamFrom(n3),
      metadata,
      isEmpty: false,
    };
  }

  /**
   * Extracts the deletes/inserts/conditions from a solid:InsertDeletePatch entry.
   */
  private parsePatch(patch: Quad_Subject, store: Store): { deletes: Quad[]; inserts: Quad[]; conditions: Quad[] } {
    // Solid, §5.3.1: "A patch resource MUST be identified by a URI or blank node, which we refer to as ?patch
    // in the remainder of this section."
    if (patch.termType !== 'NamedNode' && patch.termType !== 'BlankNode') {
      throw new UnprocessableEntityHttpError('An N3 Patch subject needs to be a blank or named node.');
    }

    // Extract all quads from the corresponding formulae
    const deletes = this.findQuads(store, patch, SOLID.terms.deletes);
    const inserts = this.findQuads(store, patch, SOLID.terms.inserts);
    const conditions = this.findQuads(store, patch, SOLID.terms.where);

    // Make sure there are no forbidden combinations
    const conditionVars = this.findVariables(conditions);
    this.verifyQuads(deletes, conditionVars);
    this.verifyQuads(inserts, conditionVars);

    return { deletes, inserts, conditions };
  }

  /**
   * Finds all quads in a where/deletes/inserts formula.
   * The returned quads will be updated so their graph is the default graph instead of the N3 reference to the formula.
   * Will error in case there are multiple instances of the subject/predicate combination.
   */
  private findQuads(store: Store, subject: Quad_Subject, predicate: NamedNode): Quad[] {
    const graphs = store.getObjects(subject, predicate, defaultGraph);
    if (graphs.length > 1) {
      throw new UnprocessableEntityHttpError(`An N3 Patch can have at most 1 ${predicate.value}.`);
    }
    if (graphs.length === 0) {
      return [];
    }
    // This might not return all quads in case of nested formulae,
    // but these are not allowed and will throw an error later when checking for blank nodes.
    // Another check would be needed in case blank nodes are allowed in the future.
    const quads: Quad[] = store.getQuads(null, null, null, graphs[0]);

    // Remove the graph references so they can be interpreted as standard triples
    // independent of the formula they were in.
    return quads.map((quad): Quad => DataFactory.quad(quad.subject, quad.predicate, quad.object, defaultGraph));
  }

  /**
   * Finds all variables in a set of quads.
   */
  private findVariables(quads: Quad[]): Set<string> {
    return new Set(
      quads.flatMap((quad): Variable[] => getVariables(getTerms(quad)))
        .map((variable): string => variable.value),
    );
  }

  /**
   * Verifies if the delete/insert triples conform to the specification requirements:
   *  - They should not contain blank nodes.
   *  - They should not contain variables that do not occur in the conditions.
   */
  private verifyQuads(otherQuads: Quad[], conditionVars: Set<string>): void {
    for (const quad of otherQuads) {
      const terms = getTerms(quad);
      const blankNodes = getBlankNodes(terms);
      // Solid, §5.3.1: "The ?insertions and ?deletions formulae MUST NOT contain blank nodes."
      if (blankNodes.length > 0) {
        throw new UnprocessableEntityHttpError(`An N3 Patch delete/insert formula can not contain blank nodes.`);
      }
      const variables = getVariables(terms);
      for (const variable of variables) {
        // Solid, §5.3.1: "The ?insertions and ?deletions formulae
        // MUST NOT contain variables that do not occur in the ?conditions formula."
        if (!conditionVars.has(variable.value)) {
          throw new UnprocessableEntityHttpError(
            `An N3 Patch delete/insert formula can only contain variables found in the conditions formula.`,
          );
        }
      }
    }
  }
}

import { getLoggerFor } from '../../../logging/LogUtil';
import { BadRequestHttpError } from '../../../util/errors/BadRequestHttpError';
import { BasicRepresentation } from '../../representation/BasicRepresentation';
import type { Representation } from '../../representation/Representation';
import type { BodyParserArgs } from './BodyParser';
import { BodyParser } from './BodyParser';

/**
 * Converts incoming {@link HttpRequest} to a Representation without any further parsing.
 */
export class RawBodyParser extends BodyParser {
  protected readonly logger = getLoggerFor(this);

  // Note that the only reason this is a union is in case the body is empty.
  // If this check gets moved away from the BodyParsers this union could be removed
  public async handle({ request, metadata }: BodyParserArgs): Promise<Representation> {
    const {
      'content-type': contentType,
      'content-length': contentLength,
      'transfer-encoding': transferEncoding,
    } = request.headers;

    // RFC7230, §3.3: The presence of a message body in a request
    // is signaled by a Content-Length or Transfer-Encoding header field.
    // While clients SHOULD NOT use use a Content-Length header on GET,
    // some still provide a Content-Length of 0 (but without Content-Type).
    if ((!contentLength || (/^0+$/u.test(contentLength) && !contentType)) && !transferEncoding) {
      this.logger.debug('HTTP request does not have a body, or its empty body is missing a Content-Type header');
      return new BasicRepresentation([], metadata);
    }

    // While RFC7231 allows treating a body without content type as an octet stream,
    // such an omission likely signals a mistake, so force clients to make this explicit.
    if (!contentType) {
      this.logger.warn('HTTP request has a body, but no Content-Type header');
      throw new BadRequestHttpError('HTTP request body was passed without a Content-Type header');
    }

    return new BasicRepresentation(request, metadata);
  }
}

import type { Algebra } from 'sparqlalgebrajs';
import { translate } from 'sparqlalgebrajs';
import { getLoggerFor } from '../../../logging/LogUtil';
import { APPLICATION_SPARQL_UPDATE } from '../../../util/ContentTypes';
import { BadRequestHttpError } from '../../../util/errors/BadRequestHttpError';
import { createErrorMessage } from '../../../util/errors/ErrorUtil';
import { UnsupportedMediaTypeHttpError } from '../../../util/errors/UnsupportedMediaTypeHttpError';
import { guardedStreamFrom, readableToString } from '../../../util/StreamUtil';
import type { SparqlUpdatePatch } from '../../representation/SparqlUpdatePatch';
import type { BodyParserArgs } from './BodyParser';
import { BodyParser } from './BodyParser';

/**
 * {@link BodyParser} that supports `application/sparql-update` content.
 * Will convert the incoming update string to algebra in a {@link SparqlUpdatePatch}.
 */
export class SparqlUpdateBodyParser extends BodyParser {
  protected readonly logger = getLoggerFor(this);

  public async canHandle({ metadata }: BodyParserArgs): Promise<void> {
    if (metadata.contentType !== APPLICATION_SPARQL_UPDATE) {
      throw new UnsupportedMediaTypeHttpError('This parser only supports SPARQL UPDATE data.');
    }
  }

  public async handle({ request, metadata }: BodyParserArgs): Promise<SparqlUpdatePatch> {
    const sparql = await readableToString(request);
    let algebra: Algebra.Operation;
    try {
      algebra = translate(sparql, { quads: true, baseIRI: metadata.identifier.value }) as Algebra.Update;
    } catch (error: unknown) {
      const message = createErrorMessage(error);
      this.logger.warn(`Could not translate SPARQL query to SPARQL algebra: ${message}`);
      throw new BadRequestHttpError(message, { cause: error });
    }

    // Prevent body from being requested again
    return {
      algebra,
      binary: true,
      data: guardedStreamFrom(sparql),
      metadata,
      isEmpty: false,
    };
  }
}

import { getLoggerFor } from '../../../logging/LogUtil';
import type { HttpRequest } from '../../../server/HttpRequest';
import type { BasicConditionsOptions } from '../../../storage/conditions/BasicConditions';
import { BasicConditions } from '../../../storage/conditions/BasicConditions';
import type { Conditions } from '../../../storage/conditions/Conditions';
import type { ETagHandler } from '../../../storage/conditions/ETagHandler';
import { splitCommaSeparated } from '../../../util/StringUtil';
import { ConditionsParser } from './ConditionsParser';

/**
 * Creates a Conditions object based on the following headers:
 *  - If-Modified-Since
 *  - If-Unmodified-Since
 *  - If-Match
 *  - If-None-Match
 *
 * Implementation based on RFC7232
 */
export class BasicConditionsParser extends ConditionsParser {
  protected readonly logger = getLoggerFor(this);

  protected readonly eTagHandler: ETagHandler;

  public constructor(eTagHandler: ETagHandler) {
    super();
    this.eTagHandler = eTagHandler;
  }

  public async handle(request: HttpRequest): Promise<Conditions | undefined> {
    const options: BasicConditionsOptions = {
      matchesETag: this.parseTagHeader(request, 'if-match'),
      notMatchesETag: this.parseTagHeader(request, 'if-none-match'),
    };

    // A recipient MUST ignore If-Modified-Since if the request contains an If-None-Match header field
    // A recipient MUST ignore the If-Modified-Since header field ... if the request method is neither GET nor HEAD.
    if (!options.notMatchesETag && (request.method === 'GET' || request.method === 'HEAD')) {
      options.modifiedSince = this.parseDateHeader(request, 'if-modified-since');
    }

    // A recipient MUST ignore If-Unmodified-Since if the request contains an If-Match header field
    if (!options.matchesETag) {
      options.unmodifiedSince = this.parseDateHeader(request, 'if-unmodified-since');
    }

    // Only return a Conditions object if there is at least one condition; undefined otherwise
    this.logger.debug(`Found the following conditions: ${JSON.stringify(options)}`);
    if (Object.values(options).some((val): boolean => typeof val !== 'undefined')) {
      return new BasicConditions(this.eTagHandler, options);
    }
  }

  /**
   * Converts a request header containing a datetime string to an actual Date object.
   * Undefined if there is no value for the given header name.
   */
  private parseDateHeader(request: HttpRequest, header: 'if-modified-since' | 'if-unmodified-since'): Date | undefined {
    const headerVal = request.headers[header];
    if (headerVal) {
      const timestamp = Date.parse(headerVal);
      return Number.isNaN(timestamp) ? undefined : new Date(timestamp);
    }
  }

  /**
   * Converts a request header containing ETags to an array of ETags.
   * Undefined if there is no value for the given header name.
   */
  private parseTagHeader(request: HttpRequest, header: 'if-match' | 'if-none-match'): string[] | undefined {
    const headerValue = request.headers[header];
    if (headerValue) {
      return splitCommaSeparated(headerValue.trim());
    }
  }
}

import type { HttpRequest } from '../../../server/HttpRequest';
import type { Conditions } from '../../../storage/conditions/Conditions';
import { AsyncHandler } from '../../../util/handlers/AsyncHandler';

/**
 * Creates a Conditions object based on the input HttpRequest.
 */
export abstract class ConditionsParser extends AsyncHandler<HttpRequest, Conditions | undefined> {}

import type { TLSSocket } from 'node:tls';
import { getLoggerFor } from '../../../logging/LogUtil';
import type { HttpRequest } from '../../../server/HttpRequest';
import { BadRequestHttpError } from '../../../util/errors/BadRequestHttpError';
import { errorTermsToMetadata } from '../../../util/errors/HttpErrorUtil';
import { InternalServerError } from '../../../util/errors/InternalServerError';
import { parseForwarded } from '../../../util/HeaderUtil';
import type { IdentifierStrategy } from '../../../util/identifiers/IdentifierStrategy';
import { toCanonicalUriPath } from '../../../util/PathUtil';
import type { ResourceIdentifier } from '../../representation/ResourceIdentifier';
import { TargetExtractor } from './TargetExtractor';

export interface OriginalUrlExtractorArgs {
  /**
   * The IdentifierStrategy to use for checking the scope of the request
   */
  identifierStrategy: IdentifierStrategy;

  /**
   * Specify whether the OriginalUrlExtractor should include the request query string.
   */
  includeQueryString?: boolean;

  /**
   * Forces the server to always assume the host header to be the value of the defined base URL.
   * Useful for debugging when you're trying to access the server both internally and externally.
   */
  fixedBaseUrl?: string;
}

/**
 * Reconstructs the original URL of an incoming {@link HttpRequest}.
 */
export class OriginalUrlExtractor extends TargetExtractor {
  protected readonly logger = getLoggerFor(this);

  protected readonly identifierStrategy: IdentifierStrategy;
  protected readonly includeQueryString: boolean;
  protected readonly fixedHost?: string;

  public constructor(args: OriginalUrlExtractorArgs) {
    super();
    this.identifierStrategy = args.identifierStrategy;
    this.includeQueryString = args.includeQueryString ?? true;
    if (args.fixedBaseUrl) {
      const url = new URL(args.fixedBaseUrl);
      this.fixedHost = url.host;
      this.logger.warn([
        `The \`fixedBaseUrl\` parameter has been set `,
        `so the host header will be ignored and always assumed to be ${this.fixedHost}.`,
        `Don't use this in production.`,
      ].join(' '));
    }
  }

  public async handle({ request: { url, socket, headers }}: { request: HttpRequest }): Promise<ResourceIdentifier> {
    if (!url) {
      throw new InternalServerError('Missing URL');
    }

    // Extract host and protocol (possibly overridden by the Forwarded/X-Forwarded-* header)
    let { host } = headers;
    let protocol = (socket as TLSSocket)?.encrypted ? 'https' : 'http';

    // Check Forwarded/X-Forwarded-* headers
    const forwarded = parseForwarded(headers);
    if (forwarded.host) {
      ({ host } = forwarded);
    }
    if (forwarded.proto) {
      ({ proto: protocol } = forwarded);
    }
    if (this.fixedHost) {
      host = this.fixedHost;
    }

    // Perform a sanity check on the host
    if (!host) {
      throw new BadRequestHttpError('Missing Host header');
    }
    if (/[/\\*]/u.test(host)) {
      throw new BadRequestHttpError(`The request has an invalid Host header: ${host}`);
    }

    // URL object applies punycode encoding to domain
    const originalUrl = new URL(`${protocol}://${host}`);
    const [ , pathname, search ] = /^([^?]*)(.*)/u.exec(toCanonicalUriPath(url))!;
    originalUrl.pathname = pathname;
    if (this.includeQueryString && search) {
      originalUrl.search = search;
    }

    // Create ResourceIdentifier instance
    const identifier = { path: originalUrl.href };

    // Check if the configured IdentifierStrategy supports the identifier
    if (!this.identifierStrategy.supportsIdentifier(identifier)) {
      throw new InternalServerError(
        `The identifier ${identifier.path} is outside the configured identifier space.`,
        { errorCode: 'E0001', metadata: errorTermsToMetadata({ path: identifier.path }) },
      );
    }

    return identifier;
  }
}

import type { HttpRequest } from '../../../server/HttpRequest';
import { AsyncHandler } from '../../../util/handlers/AsyncHandler';
import type { ResourceIdentifier } from '../../representation/ResourceIdentifier';

/**
 * Extracts a {@link ResourceIdentifier} from an incoming {@link HttpRequest}.
 */
export abstract class TargetExtractor extends AsyncHandler<{ request: HttpRequest }, ResourceIdentifier> {}

import { DataFactory } from 'n3';
import type { NamedNode } from '@rdfjs/types';
import type { HttpRequest } from '../../../server/HttpRequest';
import { matchesAuthorizationScheme } from '../../../util/HeaderUtil';
import { SOLID_META } from '../../../util/Vocabularies';
import type { RepresentationMetadata } from '../../representation/RepresentationMetadata';
import { MetadataParser } from './MetadataParser';
import namedNode = DataFactory.namedNode;

/**
 * Parses specific authorization schemes and stores their value as metadata.
 * The keys of the input `authMap` should be the schemes,
 * and the values the corresponding predicate that should be used to store the value in the metadata.
 * The scheme will be sliced off the value, after which it is used as the object in the metadata triple.
 *
 * This should be used for custom authorization schemes,
 * for things like OIDC tokens a {@link CredentialsExtractor} should be used.
 */
export class AuthorizationParser extends MetadataParser {
  private readonly authMap: Record<string, NamedNode>;

  public constructor(authMap: Record<string, string>) {
    super();
    this.authMap = Object.fromEntries(
      Object.entries(authMap).map(([ scheme, uri ]): [string, NamedNode] => [ scheme, namedNode(uri) ]),
    );
  }

  public async handle(input: { request: HttpRequest; metadata: RepresentationMetadata }): Promise<void> {
    const authHeader = input.request.headers.authorization;
    if (!authHeader) {
      return;
    }
    for (const [ scheme, uri ] of Object.entries(this.authMap)) {
      if (matchesAuthorizationScheme(scheme, authHeader)) {
        // This metadata should not be stored
        input.metadata.add(uri, authHeader.slice(scheme.length + 1), SOLID_META.ResponseMetadata);
        // There can only be 1 match
        return;
      }
    }
  }
}

import { getLoggerFor } from '../../../logging/LogUtil';
import type { HttpRequest } from '../../../server/HttpRequest';
import type { RepresentationMetadata } from '../../representation/RepresentationMetadata';
import { MetadataParser } from './MetadataParser';

/**
 * Parser for the `content-length` header.
 */
export class ContentLengthParser extends MetadataParser {
  protected readonly logger = getLoggerFor(this);

  public async handle(input: { request: HttpRequest; metadata: RepresentationMetadata }): Promise<void> {
    const contentLength = input.request.headers['content-length'];
    if (contentLength) {
      const length = /^\s*(\d+)\s*(?:;.*)?$/u.exec(contentLength)?.[1];
      if (length) {
        input.metadata.contentLength = Number(length);
      } else {
        this.logger.warn(`Invalid content-length header found: ${contentLength}.`);
      }
    }
  }
}

import type { HttpRequest } from '../../../server/HttpRequest';
import { parseContentType } from '../../../util/HeaderUtil';
import type { RepresentationMetadata } from '../../representation/RepresentationMetadata';
import { MetadataParser } from './MetadataParser';

/**
 * Parser for the `content-type` header.
 */
export class ContentTypeParser extends MetadataParser {
  public async handle(input: { request: HttpRequest; metadata: RepresentationMetadata }): Promise<void> {
    const contentType = input.request.headers['content-type'];
    if (contentType) {
      input.metadata.contentTypeObject = parseContentType(contentType);
    }
  }
}

import { parse } from 'cookie';
import { DataFactory } from 'n3';
import type { NamedNode } from '@rdfjs/types';
import type { HttpRequest } from '../../../server/HttpRequest';
import { SOLID_META } from '../../../util/Vocabularies';
import type { RepresentationMetadata } from '../../representation/RepresentationMetadata';
import { MetadataParser } from './MetadataParser';
import namedNode = DataFactory.namedNode;

/**
 * Parses the cookie header and stores their values as metadata.
 * The keys of the input `cookieMap` should be the cookie names,
 * and the values the corresponding predicate that should be used to store the value in the metadata.
 * The values of the cookies will be used as objects in the generated triples
 */
export class CookieParser extends MetadataParser {
  private readonly cookieMap: Record<string, NamedNode>;

  public constructor(cookieMap: Record<string, string>) {
    super();
    this.cookieMap = Object.fromEntries(
      Object.entries(cookieMap).map(([ name, uri ]): [string, NamedNode] => [ name, namedNode(uri) ]),
    );
  }

  public async handle(input: { request: HttpRequest; metadata: RepresentationMetadata }): Promise<void> {
    const cookies = parse(input.request.headers.cookie ?? '');
    for (const [ name, uri ] of Object.entries(this.cookieMap)) {
      const value = cookies[name];
      if (value) {
        // This metadata should not be stored
        input.metadata.add(uri, value, SOLID_META.ResponseMetadata);
      }
    }
  }
}

import type { NamedNode } from '@rdfjs/types';
import { DataFactory } from 'n3';
import type { Logger } from '../../../logging/Logger';
import { getLoggerFor } from '../../../logging/LogUtil';
import type { HttpRequest } from '../../../server/HttpRequest';
import { parseLinkHeader } from '../../../util/HeaderUtil';
import { SOLID_META } from '../../../util/Vocabularies';
import type { RepresentationMetadata } from '../../representation/RepresentationMetadata';
import { MetadataParser } from './MetadataParser';
import namedNode = DataFactory.namedNode;

/**
 * Parses Link headers with a specific `rel` value and adds them as metadata with the given predicate.
 */
export class LinkRelParser extends MetadataParser {
  protected readonly logger = getLoggerFor(this);

  private readonly linkRelMap: Record<string, LinkRelObject>;

  public constructor(linkRelMap: Record<string, LinkRelObject>) {
    super();
    this.linkRelMap = linkRelMap;
  }

  public async handle(input: { request: HttpRequest; metadata: RepresentationMetadata }): Promise<void> {
    for (const { target, parameters } of parseLinkHeader(input.request.headers.link)) {
      this.linkRelMap[parameters.rel]?.addToMetadata(target, input.metadata, this.logger);
    }
  }
}

/**
 * Represents the values that are parsed as metadata
 */
export class LinkRelObject {
  public readonly value: NamedNode;
  public readonly ephemeral: boolean;
  public readonly allowList: string[] | undefined;

  /**
   * @param value - The value corresponding to the `rel` value that will be used as predicate in the metadata.
   * @param ephemeral - (Optional) Indicates whether it will be stored by the server.
   * @param allowList - (Optional) Contains the objects that are allowed to be used with the given predicate.
   */
  public constructor(value: string, ephemeral?: boolean, allowList?: string[]) {
    this.value = namedNode(value);
    this.ephemeral = ephemeral ?? false;
    this.allowList = allowList;
  }

  /**
   * Checks whether the object can be added to the metadata
   *
   * @param object - The link target.
   *
   * @returns a boolean to indicate whether it can be added to the metadata or not
   */
  private objectAllowed(object: string): boolean {
    return this.allowList?.includes(object) ?? true;
  }

  /**
   * Adds the object to the metadata when it is allowed
   *
   * @param object - The link target.
   * @param metadata - Metadata of the resource.
   * @param logger - Logger
   */
  public addToMetadata(object: string, metadata: RepresentationMetadata, logger: Logger): void {
    if (this.objectAllowed(object)) {
      if (this.ephemeral) {
        metadata.add(this.value, namedNode(object), SOLID_META.terms.ResponseMetadata);
        logger.debug(
          `"<${metadata.identifier.value}> <${this.value.value}> <${object}>." ` +
          `will not be stored permanently in the metadata.`,
        );
      } else {
        metadata.add(this.value, namedNode(object));
      }
    } else {
      logger.debug(
        `"<${metadata.identifier.value}> <${this.value.value}> <${object}>." will not be added to the metadata`,
      );
    }
  }
}

import type { HttpRequest } from '../../../server/HttpRequest';
import { AsyncHandler } from '../../../util/handlers/AsyncHandler';
import type { RepresentationMetadata } from '../../representation/RepresentationMetadata';

/**
 * A parser that takes a specific part of an HttpRequest and converts it into metadata,
 * such as the value of a header entry.
 */
export abstract class MetadataParser extends AsyncHandler<{ request: HttpRequest; metadata: RepresentationMetadata }> {}

import { getLoggerFor } from '../../../logging/LogUtil';
import type { HttpRequest } from '../../../server/HttpRequest';
import { NotImplementedHttpError } from '../../../util/errors/NotImplementedHttpError';
import { parseContentType, parseLinkHeader } from '../../../util/HeaderUtil';
import { JSON_LD } from '../../../util/Vocabularies';
import type { RepresentationMetadata } from '../../representation/RepresentationMetadata';
import { MetadataParser } from './MetadataParser';

/**
 * Filter that errors on JSON-LD with a plain application/json content-type.
 * This will not store metadata, only throw errors if necessary.
 */
export class PlainJsonLdFilter extends MetadataParser {
  protected readonly logger = getLoggerFor(this);

  public constructor() {
    super();
  }

  public async handle(input: {
    request: HttpRequest;
    metadata: RepresentationMetadata;
  }): Promise<void> {
    const contentTypeHeader = input.request.headers['content-type'];
    if (!contentTypeHeader) {
      return;
    }
    const { value: contentType } = parseContentType(contentTypeHeader);
    // Throw error on content-type application/json AND a link header that refers to a JSON-LD context.
    if (
      contentType === 'application/json' &&
      this.linkHasContextRelation(input.request.headers.link)
    ) {
      throw new NotImplementedHttpError(
        'JSON-LD is only supported with the application/ld+json content type.',
      );
    }
  }

  private linkHasContextRelation(link: string | string[] = []): boolean {
    return parseLinkHeader(link).some(
      ({ parameters }): boolean => parameters.rel === JSON_LD.context,
    );
  }
}

import { getLoggerFor } from '../../../logging/LogUtil';
import type { HttpRequest } from '../../../server/HttpRequest';
import { BadRequestHttpError } from '../../../util/errors/BadRequestHttpError';
import { SOLID_HTTP } from '../../../util/Vocabularies';
import type { RepresentationMetadata } from '../../representation/RepresentationMetadata';
import { MetadataParser } from './MetadataParser';

/**
 * Converts the contents of the slug header to metadata.
 */
export class SlugParser extends MetadataParser {
  protected readonly logger = getLoggerFor(this);

  public async handle(input: { request: HttpRequest; metadata: RepresentationMetadata }): Promise<void> {
    const { slug } = input.request.headers;
    if (slug) {
      if (Array.isArray(slug)) {
        this.logger.warn(`Expected 0 or 1 Slug headers but received ${slug.length}`);
        throw new BadRequestHttpError('Request has multiple Slug headers');
      }
      this.logger.debug(`Request Slug is '${slug}'.`);
      input.metadata.set(SOLID_HTTP.terms.slug, slug);
    }
  }
}

import type { HttpRequest } from '../../../server/HttpRequest';
import type { AcceptHeader } from '../../../util/Header';
import {
  parseAccept,
  parseAcceptCharset,
  parseAcceptDateTime,
  parseAcceptEncoding,
  parseAcceptLanguage,
} from '../../../util/HeaderUtil';
import type { RepresentationPreferences } from '../../representation/RepresentationPreferences';
import { PreferenceParser } from './PreferenceParser';

const parsers: {
  name: Exclude<keyof RepresentationPreferences, 'range'>;
  header: string;
  parse: (value: string) => AcceptHeader[];
}[] = [
  { name: 'type', header: 'accept', parse: parseAccept },
  { name: 'charset', header: 'accept-charset', parse: parseAcceptCharset },
  { name: 'encoding', header: 'accept-encoding', parse: parseAcceptEncoding },
  { name: 'language', header: 'accept-language', parse: parseAcceptLanguage },
  { name: 'datetime', header: 'accept-datetime', parse: parseAcceptDateTime },
];

/**
 * Extracts preferences from the Accept-* headers from an incoming {@link HttpRequest}.
 * Supports Accept, Accept-Charset, Accept-Encoding, Accept-Language and Accept-DateTime.
 */
export class AcceptPreferenceParser extends PreferenceParser {
  public async handle({ request: { headers }}: { request: HttpRequest }): Promise<RepresentationPreferences> {
    const preferences: RepresentationPreferences = {};
    for (const { name, header, parse } of parsers) {
      const value = headers[header];
      if (typeof value === 'string') {
        const result = Object.fromEntries(parse(value)
          .map(({ range, weight }): [string, number] => [ range, weight ]));
        // Interpret empty headers (or headers with no valid values) the same as missing headers
        if (Object.keys(result).length > 0) {
          preferences[name] = result;
        }
      }
    }
    return preferences;
  }
}

import type { HttpRequest } from '../../../server/HttpRequest';
import { AsyncHandler } from '../../../util/handlers/AsyncHandler';
import type { RepresentationPreferences } from '../../representation/RepresentationPreferences';

/**
 * Creates {@link RepresentationPreferences} based on the incoming HTTP headers in a {@link HttpRequest}.
 */
export abstract class PreferenceParser extends AsyncHandler<{ request: HttpRequest }, RepresentationPreferences> {}

import type { HttpRequest } from '../../../server/HttpRequest';
import { BadRequestHttpError } from '../../../util/errors/BadRequestHttpError';
import type { RepresentationPreferences } from '../../representation/RepresentationPreferences';
import { PreferenceParser } from './PreferenceParser';

/**
 * Parses the range header into range preferences.
 * If the range corresponds to a suffix-length range, it will be stored in `start` as a negative value.
 */
export class RangePreferenceParser extends PreferenceParser {
  public async handle({ request: { headers: { range }}}: { request: HttpRequest }): Promise<RepresentationPreferences> {
    if (!range) {
      return {};
    }

    const [ unit, rangeTail ] = range.split('=').map((entry): string => entry.trim());
    if (unit.length === 0) {
      throw new BadRequestHttpError(`Missing unit value from range header ${range}`);
    }
    if (!rangeTail) {
      throw new BadRequestHttpError(`Invalid range header format ${range}`);
    }

    const ranges = rangeTail.split(',').map((entry): string => entry.trim());
    const parts: { start: number; end?: number }[] = [];
    for (const rangeEntry of ranges) {
      const [ start, end ] = rangeEntry.split('-').map((entry): string => entry.trim());
      // This can actually be undefined if the split results in less than 2 elements
      if (typeof end !== 'string') {
        throw new BadRequestHttpError(`Invalid range header format ${range}`);
      }
      if (start.length === 0) {
        if (end.length === 0) {
          throw new BadRequestHttpError(`Invalid range header format ${range}`);
        }
        parts.push({ start: -Number.parseInt(end, 10) });
      } else {
        const part: typeof parts[number] = { start: Number.parseInt(start, 10) };
        if (end.length > 0) {
          part.end = Number.parseInt(end, 10);
        }
        parts.push(part);
      }
    }

    return { range: { unit, parts }};
  }
}

import { InternalServerError } from '../../../util/errors/InternalServerError';
import { UnionHandler } from '../../../util/handlers/UnionHandler';
import type { RepresentationPreferences } from '../../representation/RepresentationPreferences';
import type { PreferenceParser } from './PreferenceParser';

/**
 * Combines the results of multiple {@link PreferenceParser}s.
 * Will throw an error if multiple parsers return a range as these can't logically be combined.
 */
export class UnionPreferenceParser extends UnionHandler<PreferenceParser> {
  public constructor(parsers: PreferenceParser[]) {
    super(parsers, false, false);
  }

  protected async combine(results: RepresentationPreferences[]): Promise<RepresentationPreferences> {
    const rangeCount = results.filter((result): boolean => Boolean(result.range)).length;
    if (rangeCount > 1) {
      throw new InternalServerError('Found multiple range values. This implies a misconfiguration.');
    }

    const preferences: RepresentationPreferences = {};
    for (const result of results) {
      for (const key of Object.keys(result) as (keyof RepresentationPreferences)[]) {
        if (key === 'range') {
          preferences[key] = result[key];
        } else {
          preferences[key] = { ...preferences[key], ...result[key] };
        }
      }
    }
    return preferences;
  }
}

import type { HttpRequest } from '../../server/HttpRequest';
