import type { ResponseDescription } from '../output/response/ResponseDescription';
import type { OperationHandlerInput } from './OperationHandler';
import { OperationHandler } from './OperationHandler';

/**
 * Handles DELETE {@link Operation}s.
 * Calls the deleteResource function from a {@link ResourceStore}.
 */
export class DeleteOperationHandler extends OperationHandler {
  private readonly store: ResourceStore;

  public constructor(store: ResourceStore) {
    super();
    this.store = store;
  }

  public async canHandle({ operation }: OperationHandlerInput): Promise<void> {
    if (operation.method !== 'DELETE') {
      throw new NotImplementedHttpError('This handler only supports DELETE operations');
    }
  }

  public async handle({ operation }: OperationHandlerInput): Promise<ResponseDescription> {
    await this.store.deleteResource(operation.target, operation.conditions);
    return new ResetResponseDescription();
  }
}

import type { ETagHandler } from '../../storage/conditions/ETagHandler';
import type { ResourceStore } from '../../storage/ResourceStore';
import { NotImplementedHttpError } from '../../util/errors/NotImplementedHttpError';
import { assertReadConditions } from '../../util/ResourceUtil';
import { OkResponseDescription } from '../output/response/OkResponseDescription';
import type { ResponseDescription } from '../output/response/ResponseDescription';
import type { OperationHandlerInput } from './OperationHandler';
import { OperationHandler } from './OperationHandler';

/**
 * Handles GET {@link Operation}s.
 * Calls the getRepresentation function from a {@link ResourceStore}.
 */
export class GetOperationHandler extends OperationHandler {
  private readonly store: ResourceStore;
  private readonly eTagHandler: ETagHandler;

  public constructor(store: ResourceStore, eTagHandler: ETagHandler) {
    super();
    this.store = store;
    this.eTagHandler = eTagHandler;
  }

  public async canHandle({ operation }: OperationHandlerInput): Promise<void> {
    if (operation.method !== 'GET') {
      throw new NotImplementedHttpError('This handler only supports GET operations');
    }
  }

  public async handle({ operation }: OperationHandlerInput): Promise<ResponseDescription> {
    const body = await this.store.getRepresentation(operation.target, operation.preferences, operation.conditions);

    // Check whether the cached representation is still valid or it is necessary to send a new representation
    assertReadConditions(body, this.eTagHandler, operation.conditions);

    return new OkResponseDescription(body.metadata, body.data);
  }
}

import type { ETagHandler } from '../../storage/conditions/ETagHandler';
import type { ResourceStore } from '../../storage/ResourceStore';
import { NotImplementedHttpError } from '../../util/errors/NotImplementedHttpError';
import { assertReadConditions } from '../../util/ResourceUtil';
import { OkResponseDescription } from '../output/response/OkResponseDescription';
import type { ResponseDescription } from '../output/response/ResponseDescription';
import type { OperationHandlerInput } from './OperationHandler';
import { OperationHandler } from './OperationHandler';

/**
 * Handles HEAD {@link Operation}s.
 * Calls the getRepresentation function from a {@link ResourceStore}.
 */
export class HeadOperationHandler extends OperationHandler {
  private readonly store: ResourceStore;
  private readonly eTagHandler: ETagHandler;

  public constructor(store: ResourceStore, eTagHandler: ETagHandler) {
    super();
    this.store = store;
    this.eTagHandler = eTagHandler;
  }

  public async canHandle({ operation }: OperationHandlerInput): Promise<void> {
    if (operation.method !== 'HEAD') {
      throw new NotImplementedHttpError('This handler only supports HEAD operations');
    }
  }

  public async handle({ operation }: OperationHandlerInput): Promise<ResponseDescription> {
    const body = await this.store.getRepresentation(operation.target, operation.preferences, operation.conditions);

    // Check whether the cached representation is still valid or it is necessary to send a new representation.
    // Generally it doesn't make much sense to use condition headers with a HEAD request, but it should be supported.
    assertReadConditions(body, this.eTagHandler, operation.conditions);

    // Close the Readable as we will not return it.
    body.data.destroy();

    return new OkResponseDescription(body.metadata);
  }
}

import { AsyncHandler } from '../../util/handlers/AsyncHandler';
import type { Operation } from '../Operation';
import type { ResponseDescription } from '../output/response/ResponseDescription';

export interface OperationHandlerInput {
  operation: Operation;
}

/**
 * Handler for a specific operation type.
 */
export abstract class OperationHandler extends AsyncHandler<OperationHandlerInput, ResponseDescription> {}

import { getLoggerFor } from '../../logging/LogUtil';
import type { ResourceStore } from '../../storage/ResourceStore';
import { BadRequestHttpError } from '../../util/errors/BadRequestHttpError';
import { NotImplementedHttpError } from '../../util/errors/NotImplementedHttpError';
import { CreatedResponseDescription } from '../output/response/CreatedResponseDescription';
import { ResetResponseDescription } from '../output/response/ResetResponseDescription';
import type { ResponseDescription } from '../output/response/ResponseDescription';
import type { Patch } from '../representation/Patch';
import type { OperationHandlerInput } from './OperationHandler';
import { OperationHandler } from './OperationHandler';

/**
 * Handles PATCH {@link Operation}s.
 * Calls the modifyResource function from a {@link ResourceStore}.
 */
export class PatchOperationHandler extends OperationHandler {
  protected readonly logger = getLoggerFor(this);

  private readonly store: ResourceStore;

  public constructor(store: ResourceStore) {
    super();
    this.store = store;
  }

  public async canHandle({ operation }: OperationHandlerInput): Promise<void> {
    if (operation.method !== 'PATCH') {
      throw new NotImplementedHttpError('This handler only supports PATCH operations.');
    }
  }

  public async handle({ operation }: OperationHandlerInput): Promise<ResponseDescription> {
    // Solid, §2.1: "A Solid server MUST reject PUT, POST and PATCH requests
    // without the Content-Type header with a status code of 400."
    // https://solid.github.io/specification/protocol#http-server
    if (!operation.body.metadata.contentType) {
      this.logger.warn('PATCH requests require the Content-Type header to be set');
      throw new BadRequestHttpError('PATCH requests require the Content-Type header to be set');
    }

    // A more efficient approach would be to have the server return metadata indicating if a resource was new
    // See https://github.com/CommunitySolidServer/CommunitySolidServer/issues/632
    // RFC7231, §4.3.4: If the target resource does not have a current representation and the
    //   PUT successfully creates one, then the origin server MUST inform the
    //   user agent by sending a 201 (Created) response.
    const exists = await this.store.hasResource(operation.target);
    await this.store.modifyResource(operation.target, operation.body as Patch, operation.conditions);
    if (exists) {
      return new ResetResponseDescription();
    }
    return new CreatedResponseDescription(operation.target);
  }
}

import type { Term } from '@rdfjs/types';
import { getLoggerFor } from '../../logging/LogUtil';
import type { ResourceStore } from '../../storage/ResourceStore';
import { BadRequestHttpError } from '../../util/errors/BadRequestHttpError';
import { InternalServerError } from '../../util/errors/InternalServerError';
import { NotImplementedHttpError } from '../../util/errors/NotImplementedHttpError';
import { find } from '../../util/IterableUtil';
import { AS, LDP, RDF, SOLID_AS } from '../../util/Vocabularies';
import { CreatedResponseDescription } from '../output/response/CreatedResponseDescription';
import type { ResponseDescription } from '../output/response/ResponseDescription';
import type { OperationHandlerInput } from './OperationHandler';
import { OperationHandler } from './OperationHandler';

/**
 * Handles POST {@link Operation}s.
 * Calls the addResource function from a {@link ResourceStore}.
 */
export class PostOperationHandler extends OperationHandler {
  protected readonly logger = getLoggerFor(this);

  private readonly store: ResourceStore;

  public constructor(store: ResourceStore) {
    super();
    this.store = store;
  }

  public async canHandle({ operation }: OperationHandlerInput): Promise<void> {
    if (operation.method !== 'POST') {
      throw new NotImplementedHttpError('This handler only supports POST operations');
    }
  }

  public async handle({ operation }: OperationHandlerInput): Promise<ResponseDescription> {
    const type = new Set(operation.body.metadata.getAll(RDF.terms.type).map((term: Term): string => term.value));
    const isContainerType = type.has(LDP.Container) || type.has(LDP.BasicContainer);
    // Solid, §2.1: "A Solid server MUST reject PUT, POST and PATCH requests
    // without the Content-Type header with a status code of 400."
    // https://solid.github.io/specification/protocol#http-server
    // An exception is made for LDP Containers as nothing is done with the body, so a Content-type is not required
    if (!operation.body.metadata.contentType && !isContainerType) {
      this.logger.warn('POST requests require the Content-Type header to be set');
      throw new BadRequestHttpError('POST requests require the Content-Type header to be set');
    }
    const changes = await this.store.addResource(operation.target, operation.body, operation.conditions);
    const createdIdentifier = find(changes.keys(), (identifier): boolean =>
      Boolean(changes.get(identifier)?.has(SOLID_AS.terms.activity, AS.terms.Create)));
    if (!createdIdentifier) {
      throw new InternalServerError('Operation was successful but no created identifier was returned.');
    }
    return new CreatedResponseDescription(createdIdentifier);
  }
}

import { getLoggerFor } from '../../logging/LogUtil';
import type { ResourceStore } from '../../storage/ResourceStore';
import { BadRequestHttpError } from '../../util/errors/BadRequestHttpError';
import { MethodNotAllowedHttpError } from '../../util/errors/MethodNotAllowedHttpError';
import { NotImplementedHttpError } from '../../util/errors/NotImplementedHttpError';
import { isContainerPath } from '../../util/PathUtil';
import type { AuxiliaryStrategy } from '../auxiliary/AuxiliaryStrategy';
import { CreatedResponseDescription } from '../output/response/CreatedResponseDescription';
import { ResetResponseDescription } from '../output/response/ResetResponseDescription';
import type { ResponseDescription } from '../output/response/ResponseDescription';
import type { OperationHandlerInput } from './OperationHandler';
import { OperationHandler } from './OperationHandler';

/**
 * Handles PUT {@link Operation}s.
 * Calls the setRepresentation function from a {@link ResourceStore}.
 */
export class PutOperationHandler extends OperationHandler {
  protected readonly logger = getLoggerFor(this);

  private readonly store: ResourceStore;
  private readonly metadataStrategy: AuxiliaryStrategy;

  public constructor(store: ResourceStore, metadataStrategy: AuxiliaryStrategy) {
    super();
    this.store = store;
    this.metadataStrategy = metadataStrategy;
  }

  public async canHandle({ operation }: OperationHandlerInput): Promise<void> {
    if (operation.method !== 'PUT') {
      throw new NotImplementedHttpError('This handler only supports PUT operations');
    }
  }

  public async handle({ operation }: OperationHandlerInput): Promise<ResponseDescription> {
    const targetIsContainer = isContainerPath(operation.target.path);

    // Solid, §2.1: "A Solid server MUST reject PUT, POST and PATCH requests
    // without the Content-Type header with a status code of 400."
    // https://solid.github.io/specification/protocol#http-server
    // An exception is made for LDP Containers as nothing is done with the body, so a Content-type is not required
    if (!operation.body.metadata.contentType && !targetIsContainer) {
      this.logger.warn('PUT requests require the Content-Type header to be set');
      throw new BadRequestHttpError('PUT requests require the Content-Type header to be set');
    }

    // https://github.com/CommunitySolidServer/CommunitySolidServer/issues/1027#issuecomment-988664970
    // We do not allow PUT on metadata resources for simplicity.
    // Otherwise, all generated metadata triples would have to be identical, such as date modified.
    // We already reject the request here instead of `setRepresentation` so PATCH requests
    // can still use that function to update data.
    if (this.metadataStrategy.isAuxiliaryIdentifier(operation.target)) {
      throw new MethodNotAllowedHttpError(
        [ 'PUT' ],
        'Not allowed to create or edit metadata resources using PUT; use PATCH instead.',
      );
    }

    // A more efficient approach would be to have the server return metadata indicating if a resource was new
    // See https://github.com/CommunitySolidServer/CommunitySolidServer/issues/632
    const exists = await this.store.hasResource(operation.target);
    await this.store.setRepresentation(operation.target, operation.body, operation.conditions);
    if (exists) {
      return new ResetResponseDescription();
    }
    return new CreatedResponseDescription(operation.target);
  }
}

import type { Conditions } from '../storage/conditions/Conditions';
import type { Representation } from './representation/Representation';
import type { RepresentationPreferences } from './representation/RepresentationPreferences';
import type { ResourceIdentifier } from './representation/ResourceIdentifier';

/**
 * A single REST operation.
 */
export interface Operation {
  /**
   * The HTTP method (GET/POST/PUT/PATCH/DELETE/etc.).
   */
  method: string;
  /**
   * Identifier of the target.
   */
  target: ResourceIdentifier;
  /**
   * Representation preferences of the response. Will be empty if there are none.
   */
  preferences: RepresentationPreferences;
  /**
   * Conditions the resource must fulfill for a valid operation.
   */
  conditions?: Conditions;
  /**
   * Representation of the body and metadata headers.
   */
  body: Representation;
}

import { getLoggerFor } from '../../logging/LogUtil';
import type { HttpResponse } from '../../server/HttpResponse';
import { isInternalContentType } from '../../storage/conversion/ConversionUtil';
import { NotImplementedHttpError } from '../../util/errors/NotImplementedHttpError';
import { pipeSafely } from '../../util/StreamUtil';
import type { MetadataWriter } from './metadata/MetadataWriter';
import type { ResponseDescription } from './response/ResponseDescription';
import { ResponseWriter } from './ResponseWriter';

/**
 * Writes to an {@link HttpResponse} based on the incoming {@link ResponseDescription}.
 */
export class BasicResponseWriter extends ResponseWriter {
  protected readonly logger = getLoggerFor(this);
  private readonly metadataWriter: MetadataWriter;

  public constructor(metadataWriter: MetadataWriter) {
    super();
    this.metadataWriter = metadataWriter;
  }

  public async canHandle(input: { response: HttpResponse; result: ResponseDescription }): Promise<void> {
    const contentType = input.result.metadata?.contentType;
    if (isInternalContentType(contentType)) {
      throw new NotImplementedHttpError(`Cannot serialize the internal content type ${contentType}`);
    }
  }

  public async handle(input: { response: HttpResponse; result: ResponseDescription }): Promise<void> {
    if (input.result.metadata) {
      await this.metadataWriter.handleSafe({ response: input.response, metadata: input.result.metadata });
    }

    input.response.writeHead(input.result.statusCode);

    if (input.result.data) {
      const pipe = pipeSafely(input.result.data, input.response);
      pipe.on('error', (error): void => {
        this.logger.error(`Aborting streaming response because of server error; headers already sent.`);
        this.logger.error(`Response error: ${error.message}`);
      });
    } else {
      // If there is input data the response will end once the input stream ends
      input.response.end();
    }
  }
}

import type {
  RepresentationConverter,
  RepresentationConverterArgs,
} from '../../../storage/conversion/RepresentationConverter';
import { INTERNAL_ERROR } from '../../../util/ContentTypes';
import type { PreferenceParser } from '../../input/preferences/PreferenceParser';
import { BasicRepresentation } from '../../representation/BasicRepresentation';
import type { Representation } from '../../representation/Representation';
import type { ResponseDescription } from '../response/ResponseDescription';
import type { ErrorHandlerArgs } from './ErrorHandler';
import { ErrorHandler } from './ErrorHandler';

// Used by internal helper function
type PreparedArguments = {
  statusCode: number;
  conversionArgs: RepresentationConverterArgs;
};

/**
 * Converts an error into a Representation of content type internal/error.
 * Then feeds that representation into its converter to create a representation based on the given preferences.
 */
export class ConvertingErrorHandler extends ErrorHandler {
  private readonly converter: RepresentationConverter;
  private readonly preferenceParser: PreferenceParser;
  private readonly showStackTrace: boolean;

  public constructor(converter: RepresentationConverter, preferenceParser: PreferenceParser, showStackTrace = false) {
    super();
    this.converter = converter;
    this.preferenceParser = preferenceParser;
    this.showStackTrace = showStackTrace;
  }

  public async canHandle(input: ErrorHandlerArgs): Promise<void> {
    await this.preferenceParser.canHandle({ request: input.request });
    const { conversionArgs } = await this.extractErrorDetails(input);

    await this.converter.canHandle(conversionArgs);
  }

  public async handle(input: ErrorHandlerArgs): Promise<ResponseDescription> {
    const { statusCode, conversionArgs } = await this.extractErrorDetails(input);

    const converted = await this.converter.handle(conversionArgs);

    return this.createResponse(statusCode, converted);
  }

  public async handleSafe(input: ErrorHandlerArgs): Promise<ResponseDescription> {
    await this.preferenceParser.canHandle({ request: input.request });
    const { statusCode, conversionArgs } = await this.extractErrorDetails(input);

    const converted = await this.converter.handleSafe(conversionArgs);

    return this.createResponse(statusCode, converted);
  }

  /**
   * Prepares the arguments used by all functions.
   */
  private async extractErrorDetails({ error, request }: ErrorHandlerArgs): Promise<PreparedArguments> {
    if (!this.showStackTrace) {
      delete error.stack;
      // Cheating here to delete a readonly field
      delete (error as { cause: unknown }).cause;
    }
    const representation = new BasicRepresentation([ error ], error.metadata, INTERNAL_ERROR, false);
    const identifier = { path: representation.metadata.identifier.value };
    const preferences = await this.preferenceParser.handle({ request });
    return { statusCode: error.statusCode, conversionArgs: { identifier, representation, preferences }};
  }

  /**
   * Creates a ResponseDescription based on the Representation.
   */
  private createResponse(statusCode: number, converted: Representation): ResponseDescription {
    return {
      statusCode,
      metadata: converted.metadata,
      data: converted.data,
    };
  }
}

import { NotImplementedHttpError } from '../../../util/errors/NotImplementedHttpError';
import { SOLID_ERROR } from '../../../util/Vocabularies';
import { ResponseDescription } from '../response/ResponseDescription';
import type { ErrorHandlerArgs } from './ErrorHandler';
import { ErrorHandler } from './ErrorHandler';

/**
 * An {@link ErrorHandler} that returns an error response without adding a body.
 * For certain status codes, such as 304, it is important to not change anything
 * in the headers, such as content-type.
 *
 * The `statusCodes` array contains the status codes of error types for which
 * a body should never be added.
 *
 * The `always` boolean can be set to `true` to indicate that all errors should
 * be handled here.
 *
 * For errors with different status codes, a metadata field can be added
 * to indicate that this specific error response should not receive a body.
 * The predicate should be `urn:npm:solid:community-server:error:emptyBody`
 * and the value `true`.
 */
export class EmptyErrorHandler extends ErrorHandler {
  protected readonly statusCodes: number[];
  protected readonly always: boolean;

  public constructor(statusCodes = [ 304 ], always = false) {
    super();
    this.statusCodes = statusCodes;
    this.always = always;
  }

  public async canHandle({ error }: ErrorHandlerArgs): Promise<void> {
    if (this.always || this.statusCodes.includes(error.statusCode) ||
      error.metadata.get(SOLID_ERROR.terms.emptyBody)?.value === 'true') {
      return;
    }
    throw new NotImplementedHttpError();
  }

  public async handle({ error }: ErrorHandlerArgs): Promise<ResponseDescription> {
    return new ResponseDescription(error.statusCode, error.metadata);
  }
}

import type { HttpRequest } from '../../../server/HttpRequest';
import type { HttpError } from '../../../util/errors/HttpError';
import { AsyncHandler } from '../../../util/handlers/AsyncHandler';
import type { ResponseDescription } from '../response/ResponseDescription';

export interface ErrorHandlerArgs {
  error: HttpError;
  request: HttpRequest;
}

/**
 * Converts an error into a {@link ResponseDescription} based on the request preferences.
 */
export abstract class ErrorHandler extends AsyncHandler<ErrorHandlerArgs, ResponseDescription> {}

import { NotImplementedHttpError } from '../../../util/errors/NotImplementedHttpError';
import { RedirectHttpError } from '../../../util/errors/RedirectHttpError';
import { RedirectResponseDescription } from '../response/RedirectResponseDescription';
import type { ResponseDescription } from '../response/ResponseDescription';
import type { ErrorHandlerArgs } from './ErrorHandler';
import { ErrorHandler } from './ErrorHandler';

/**
 * Internally we create redirects by throwing specific {@link RedirectHttpError}s.
 * This Error handler converts those to {@link RedirectResponseDescription}s that are used for output.
 */
export class RedirectingErrorHandler extends ErrorHandler {
  public async canHandle({ error }: ErrorHandlerArgs): Promise<void> {
    if (!RedirectHttpError.isInstance(error)) {
      throw new NotImplementedHttpError('Only redirect errors are supported.');
    }
  }

  public async handle({ error }: ErrorHandlerArgs): Promise<ResponseDescription> {
    // Cast verified by canHandle
    return new RedirectResponseDescription(error as RedirectHttpError);
  }
}

import { getLoggerFor } from '../../../logging/LogUtil';
import { createErrorMessage } from '../../../util/errors/ErrorUtil';
import { guardedStreamFrom } from '../../../util/StreamUtil';
import type { ResponseDescription } from '../response/ResponseDescription';
import type { ErrorHandlerArgs } from './ErrorHandler';
import { ErrorHandler } from './ErrorHandler';

/**
 * Returns a simple text description of an error.
 * This class is a failsafe in case the wrapped error handler fails.
 */
export class SafeErrorHandler extends ErrorHandler {
  protected readonly logger = getLoggerFor(this);

  private readonly errorHandler: ErrorHandler;
  private readonly showStackTrace: boolean;

  public constructor(errorHandler: ErrorHandler, showStackTrace = false) {
    super();
    this.errorHandler = errorHandler;
    this.showStackTrace = showStackTrace;
  }

  public async handle(input: ErrorHandlerArgs): Promise<ResponseDescription> {
    try {
      return await this.errorHandler.handleSafe(input);
    } catch (error: unknown) {
      this.logger.debug(`Recovering from error handler failure: ${createErrorMessage(error)}`);
    }
    const { error } = input;
    error.metadata.contentType = 'text/plain';

    const text = typeof error.stack === 'string' && this.showStackTrace ?
      `${error.stack}\n` :
      `${error.name}: ${error.message}\n`;

    return {
      statusCode: error.statusCode,
      metadata: error.metadata,
      data: guardedStreamFrom(text),
    };
  }
}

import { DataFactory } from 'n3';
import { getLoggerFor } from '../../../logging/LogUtil';
import { createErrorMessage } from '../../../util/errors/ErrorUtil';
import { SOLID_ERROR } from '../../../util/Vocabularies';
import type { TargetExtractor } from '../../input/identifier/TargetExtractor';
import type { ResponseDescription } from '../response/ResponseDescription';
import type { ErrorHandlerArgs } from './ErrorHandler';
import { ErrorHandler } from './ErrorHandler';

/**
 * Adds metadata to an error to indicate the identifier of the originally targeted resource.
 */
export class TargetExtractorErrorHandler extends ErrorHandler {
  protected readonly logger = getLoggerFor(this);

  protected readonly errorHandler: ErrorHandler;
  protected readonly targetExtractor: TargetExtractor;

  public constructor(errorHandler: ErrorHandler, targetExtractor: TargetExtractor) {
    super();
    this.errorHandler = errorHandler;
    this.targetExtractor = targetExtractor;
  }

  public async canHandle(input: ErrorHandlerArgs): Promise<void> {
    return this.errorHandler.canHandle(input);
  }

  public async handle(input: ErrorHandlerArgs): Promise<ResponseDescription> {
    try {
      const target = await this.targetExtractor.handleSafe(input);
      input.error.metadata.add(SOLID_ERROR.terms.target, DataFactory.namedNode(target.path));
    } catch (error) {
      this.logger.warn(`Unable to add identifier to error metadata: ${createErrorMessage(error)}`);
    }
    return this.errorHandler.handle(input);
  }
}

import type { HttpResponse } from '../../../server/HttpResponse';
import { MethodNotAllowedHttpError } from '../../../util/errors/MethodNotAllowedHttpError';
import { NotFoundHttpError } from '../../../util/errors/NotFoundHttpError';
import { UnsupportedMediaTypeHttpError } from '../../../util/errors/UnsupportedMediaTypeHttpError';
import { addHeader } from '../../../util/HeaderUtil';
import { isContainerPath } from '../../../util/PathUtil';
import { LDP, PIM, RDF, SOLID_ERROR, SOLID_META } from '../../../util/Vocabularies';
import type { RepresentationMetadata } from '../../representation/RepresentationMetadata';
import { MetadataWriter } from './MetadataWriter';

enum ResourceType {
  document,
  container,
  unknown,
}

/**
 * Generates Allow, Accept-Patch, Accept-Post, and Accept-Put headers.
 * The resulting values depend on the choses input methods and types.
 * The input metadata also gets used to remove methods from that list
 * if they are not valid in the given situation.
 */
export class AllowAcceptHeaderWriter extends MetadataWriter {
  private readonly supportedMethods: string[];
  private readonly acceptTypes: { patch: string[]; post: string[]; put: string[] };

  public constructor(supportedMethods: string[], acceptTypes: { patch?: string[]; post?: string[]; put?: string[] }) {
    super();
    this.supportedMethods = supportedMethods;
    this.acceptTypes = { patch: [], post: [], put: [], ...acceptTypes };
  }

  public async handle(input: { response: HttpResponse; metadata: RepresentationMetadata }): Promise<void> {
    const { response, metadata } = input;

    let resourceType: ResourceType;
    if (metadata.has(RDF.terms.type, LDP.terms.Resource)) {
      resourceType = isContainerPath(metadata.identifier.value) ? ResourceType.container : ResourceType.document;
    } else {
      const target = metadata.get(SOLID_ERROR.terms.target)?.value;
      if (target) {
        resourceType = isContainerPath(target) ? ResourceType.container : ResourceType.document;
      } else {
        resourceType = ResourceType.unknown;
      }
    }

    // Filter out methods which are not allowed
    const allowedMethods = this.filterAllowedMethods(metadata, resourceType);

    // Generate the Allow headers (if required)
    const generateAllow = this.generateAllow(allowedMethods, response, metadata);

    // Generate Accept-[Method] headers (if required)
    this.generateAccept(allowedMethods, generateAllow, response, metadata);
  }

  /**
   * Starts from the stored set of methods and removes all those that are not allowed based on the metadata.
   */
  private filterAllowedMethods(metadata: RepresentationMetadata, resourceType: ResourceType): Set<string> {
    const disallowedMethods = new Set(metadata.getAll(SOLID_ERROR.terms.disallowedMethod)
      .map((term): string => term.value));
    const allowedMethods = new Set(this.supportedMethods.filter((method): boolean => !disallowedMethods.has(method)));

    // POST is only allowed on containers.
    // Metadata only has the resource URI in case it has resource metadata.
    if (!this.isPostAllowed(resourceType)) {
      allowedMethods.delete('POST');
    }

    if (!this.isPutAllowed(metadata, resourceType)) {
      allowedMethods.delete('PUT');
    }

    if (!this.isPatchAllowed(resourceType)) {
      allowedMethods.delete('PATCH');
    }

    if (!this.isDeleteAllowed(metadata, resourceType)) {
      allowedMethods.delete('DELETE');
    }

    // If we are sure the resource does not exist: only keep methods that can create a new resource.
    if (metadata.has(SOLID_ERROR.terms.errorResponse, NotFoundHttpError.uri)) {
      for (const method of allowedMethods) {
        // Containers can only be created by PUT; documents by PUT or PATCH
        if (method !== 'PUT' && (method !== 'PATCH' || resourceType === ResourceType.container)) {
          allowedMethods.delete(method);
        }
      }
    }

    return allowedMethods;
  }

  /**
   * POST is only allowed on containers.
   */
  private isPostAllowed(resourceType: ResourceType): boolean {
    return resourceType !== ResourceType.document;
  }

  /**
   * PUT is not allowed on description resources or existing containers.
   */
  private isPutAllowed(metadata: RepresentationMetadata, resourceType: ResourceType): boolean {
    return !metadata.has(RDF.terms.type, SOLID_META.terms.DescriptionResource) &&
      (resourceType !== ResourceType.container || !metadata.has(RDF.terms.type, LDP.terms.Resource));
  }

  /**
   * PATCH is not allowed on containers.
   */
  private isPatchAllowed(resourceType: ResourceType): boolean {
    return resourceType !== ResourceType.container;
  }

  /**
   * DELETE is allowed if the target exists,
   * is not a container or description resource,
   * or is an empty container that isn't a storage.
   *
   * Note that the identifier value check only works if the metadata is not about an error.
   */
  private isDeleteAllowed(metadata: RepresentationMetadata, resourceType: ResourceType): boolean {
    if (metadata.has(RDF.terms.type, SOLID_META.terms.DescriptionResource)) {
      return false;
    }
    if (resourceType !== ResourceType.container) {
      return true;
    }

    const isStorage = metadata.has(RDF.terms.type, PIM.terms.Storage);
    const isEmpty = !metadata.has(LDP.terms.contains);
    return !isStorage && isEmpty;
  }

  /**
   * Generates the Allow header if required.
   * It only needs to get added for successful GET/HEAD requests, 404s, or 405s.
   * The spec only requires it for GET/HEAD requests and 405s.
   * In the case of other error messages we can't deduce what the request method was,
   * so we do not add the header as we don't have enough information.
   */
  private generateAllow(methods: Set<string>, response: HttpResponse, metadata: RepresentationMetadata): boolean {
    const methodDisallowed = metadata.has(SOLID_ERROR.terms.errorResponse, MethodNotAllowedHttpError.uri);
    // 405s indicate the target resource exists.
    // This is a heuristic, but one that should always be correct in our case.
    const resourceExists = methodDisallowed || metadata.has(RDF.terms.type, LDP.terms.Resource);
    const generateAllow = resourceExists || metadata.has(SOLID_ERROR.terms.errorResponse, NotFoundHttpError.uri);
    if (generateAllow) {
      addHeader(response, 'Allow', [ ...methods ].join(', '));
    }
    return generateAllow;
  }

  /**
   * Generates the Accept-[Method] headers if required.
   * Will be added if the Allow header was added, or in case of a 415 error.
   * Specific Accept-[Method] headers will only be added if the method is in the `methods` set.
   */
  private generateAccept(
    methods: Set<string>,
    generateAllow: boolean,
    response: HttpResponse,
    metadata: RepresentationMetadata,
  ): void {
    const typeWasUnsupported = metadata.has(SOLID_ERROR.terms.errorResponse, UnsupportedMediaTypeHttpError.uri);
    const generateAccept = generateAllow || typeWasUnsupported;
    if (generateAccept) {
      if (methods.has('PATCH')) {
        addHeader(response, 'Accept-Patch', this.acceptTypes.patch.join(', '));
      }
      if (methods.has('POST')) {
        addHeader(response, 'Accept-Post', this.acceptTypes.post.join(', '));
      }
      if (methods.has('PUT')) {
        addHeader(response, 'Accept-Put', this.acceptTypes.put.join(', '));
      }
    }
  }
}

import { getLoggerFor } from '../../../logging/LogUtil';
import type { HttpResponse } from '../../../server/HttpResponse';
import { addHeader } from '../../../util/HeaderUtil';
import { LDP, RDF, SOLID_ERROR } from '../../../util/Vocabularies';
import type { AuxiliaryStrategy } from '../../auxiliary/AuxiliaryStrategy';
import type { RepresentationMetadata } from '../../representation/RepresentationMetadata';
import type { ResourceIdentifier } from '../../representation/ResourceIdentifier';
import { MetadataWriter } from './MetadataWriter';

/**
 * A {@link MetadataWriter} that takes a specific auxiliaryStrategy and relation type as input and
 * creates a Link header with the strategy identifier and the relation type as "rel" value.
 */
export class AuxiliaryLinkMetadataWriter extends MetadataWriter {
  protected readonly logger = getLoggerFor(this);

  private readonly auxiliaryStrategy: AuxiliaryStrategy;
  private readonly specificStrategy: AuxiliaryStrategy;
  private readonly relationType: string;

  /**
   * @param auxiliaryStrategy - The strategy used to check if an identifier is any kind of auxiliary identifier.
   * @param specificStrategy - The strategy used to create a specific kind of auxiliary identifier.
   * @param relationType - The value used to create the "rel" value of the Link header.
   */
  public constructor(auxiliaryStrategy: AuxiliaryStrategy, specificStrategy: AuxiliaryStrategy, relationType: string) {
    super();
    this.auxiliaryStrategy = auxiliaryStrategy;
    this.specificStrategy = specificStrategy;
    this.relationType = relationType;
  }

  public async handle(input: { response: HttpResponse; metadata: RepresentationMetadata }): Promise<void> {
    let identifier: ResourceIdentifier | undefined;
    if (input.metadata.has(RDF.terms.type, LDP.terms.Resource)) {
      identifier = { path: input.metadata.identifier.value };
    } else {
      const target = input.metadata.get(SOLID_ERROR.terms.target);
      if (target) {
        identifier = { path: target.value };
      }
    }
    // The metadata identifier will be a blank node in case an error was thrown.
    if (identifier && !this.auxiliaryStrategy.isAuxiliaryIdentifier(identifier)) {
      const auxiliaryIdentifier = this.specificStrategy.getAuxiliaryIdentifier(identifier);
      addHeader(input.response, 'Link', `<${auxiliaryIdentifier.path}>; rel="${this.relationType}"`);
    }
  }
}

import type { HttpResponse } from '../../../server/HttpResponse';
import { addHeader } from '../../../util/HeaderUtil';
import { MetadataWriter } from './MetadataWriter';

/**
 * A {@link MetadataWriter} that takes a constant map of header names and values.
 */
export class ConstantMetadataWriter extends MetadataWriter {
  private readonly headers: [string, string][];

  public constructor(headers: Record<string, string>) {
    super();
    this.headers = Object.entries(headers);
  }

  public async handle({ response }: { response: HttpResponse }): Promise<void> {
    for (const [ key, value ] of this.headers) {
      addHeader(response, key, value);
    }
  }
}

import type { HttpResponse } from '../../../server/HttpResponse';
import type { RepresentationMetadata } from '../../representation/RepresentationMetadata';
import { MetadataWriter } from './MetadataWriter';

/**
 * Adds the `Content-Type` header containing value and parameters (if available).
 */
export class ContentTypeMetadataWriter extends MetadataWriter {
  public async handle(input: { response: HttpResponse; metadata: RepresentationMetadata }): Promise<void> {
    const { contentTypeObject } = input.metadata;
    if (contentTypeObject) {
      input.response.setHeader('Content-Type', contentTypeObject.toHeaderValueString());
    }
  }
}

import { serialize } from 'cookie';
import type { NamedNode } from 'n3';
import { DataFactory } from 'n3';
import type { HttpResponse } from '../../../server/HttpResponse';
import { addHeader } from '../../../util/HeaderUtil';
import type { RepresentationMetadata } from '../../representation/RepresentationMetadata';
import { MetadataWriter } from './MetadataWriter';

/**
 * Generates the necessary `Set-Cookie` header if a cookie value is detected in the metadata.
 * The keys of the input `cookieMap` should be the URIs of the predicates
 * used in the metadata when the object is a cookie value.
 * The value of the map are objects that contain the name of the cookie,
 * and the URI that is used to store the expiration date in the metadata, if any.
 * If no expiration date is found in the metadata, none will be set for the cookie,
 * causing it to be a session cookie.
 */
export class CookieMetadataWriter extends MetadataWriter {
  private readonly cookieMap: Map<NamedNode, { name: string; expirationUri?: NamedNode }>;

  public constructor(cookieMap: Record<string, { name: string; expirationUri?: string }>) {
    super();
    this.cookieMap = new Map<NamedNode, { name: string; expirationUri?: NamedNode }>(Object.entries(cookieMap)
      .map(([ uri, { name, expirationUri }]): [ NamedNode, { name: string; expirationUri?: NamedNode } ] =>
        [
          DataFactory.namedNode(uri),
          {
            name,
            expirationUri: expirationUri ? DataFactory.namedNode(expirationUri) : undefined,
          },
        ]));
  }

  public async handle(input: { response: HttpResponse; metadata: RepresentationMetadata }): Promise<void> {
    const { response, metadata } = input;
    for (const [ uri, { name, expirationUri }] of this.cookieMap.entries()) {
      const value = metadata.get(uri)?.value;
      if (value) {
        const expiration = expirationUri && metadata.get(expirationUri)?.value;
        const expires = typeof expiration === 'string' ? new Date(expiration) : undefined;
        // Not setting secure flag since not all tools realize those cookies are also valid for http://localhost.
        // Not setting the httpOnly flag as that would prevent JS API access.
        // SameSite: Lax makes it so the cookie gets sent if the origin is the server,
        // or if the browser navigates there from another site.
        // Setting the path to `/` so it applies to the entire server.
        addHeader(response, 'Set-Cookie', serialize(name, value, { path: '/', sameSite: 'lax', expires }));
      }
    }
  }
}

import type { NamedNode } from 'n3';
import { DataFactory } from 'n3';
import { getLoggerFor } from '../../../logging/LogUtil';
import type { HttpResponse } from '../../../server/HttpResponse';
import { addHeader } from '../../../util/HeaderUtil';
import type { RepresentationMetadata } from '../../representation/RepresentationMetadata';
import { MetadataWriter } from './MetadataWriter';

/**
 * A {@link MetadataWriter} that takes a linking metadata predicates to Link header "rel" values.
 * The values of the objects will be put in a Link header with the corresponding "rel" value.
 */
export class LinkRelMetadataWriter extends MetadataWriter {
  private readonly linkRelMap: Map<NamedNode, string>;
  protected readonly logger = getLoggerFor(this);

  public constructor(linkRelMap: Record<string, string>) {
    super();

    this.linkRelMap = new Map<NamedNode, string>();
    for (const [ key, value ] of Object.entries(linkRelMap)) {
      this.linkRelMap.set(DataFactory.namedNode(key), value);
    }
  }

  public async handle(input: { response: HttpResponse; metadata: RepresentationMetadata }): Promise<void> {
    this.logger.debug(`Available link relations: ${this.linkRelMap.size}`);
    for (const [ predicate, relValue ] of this.linkRelMap) {
      const values = input.metadata.getAll(predicate)
        .map((term): string => `<${term.value}>; rel="${relValue}"`);
      if (values.length > 0) {
        this.logger.debug(`Adding Link header ${values.join(',')}`);
        addHeader(input.response, 'Link', values);
      }
    }
  }
}

import type { NamedNode } from 'n3';
import { DataFactory } from 'n3';
import type { HttpResponse } from '../../../server/HttpResponse';
import { addHeader } from '../../../util/HeaderUtil';
import type { RepresentationMetadata } from '../../representation/RepresentationMetadata';
import { MetadataWriter } from './MetadataWriter';

/**
 * A {@link MetadataWriter} that takes a map directly converting metadata predicates to headers.
 * The header value(s) will be the same as the corresponding object value(s).
 */
export class MappedMetadataWriter extends MetadataWriter {
  private readonly headerMap: Map<NamedNode, string>;

  public constructor(headerMap: Record<string, string>) {
    super();

    this.headerMap = new Map<NamedNode, string>();
    for (const [ key, value ] of Object.entries(headerMap)) {
      this.headerMap.set(DataFactory.namedNode(key), value);
    }
  }

  public async handle(input: { response: HttpResponse; metadata: RepresentationMetadata }): Promise<void> {
    for (const [ predicate, header ] of this.headerMap) {
      const terms = input.metadata.getAll(predicate);
      if (terms.length > 0) {
        addHeader(input.response, header, terms.map((term): string => term.value));
      }
    }
  }
}

import type { HttpResponse } from '../../../server/HttpResponse';
import { AsyncHandler } from '../../../util/handlers/AsyncHandler';
import type { RepresentationMetadata } from '../../representation/RepresentationMetadata';

export interface MetadataWriterInput {
  response: HttpResponse;
  metadata: RepresentationMetadata;
}

/**
 * A serializer that converts metadata to headers for an HttpResponse.
 */
export abstract class MetadataWriter extends AsyncHandler<MetadataWriterInput> {}

import type { HttpResponse } from '../../../server/HttpResponse';
import { addHeader } from '../../../util/HeaderUtil';
import { DC, HH } from '../../../util/Vocabularies';
import type { RepresentationMetadata } from '../../representation/RepresentationMetadata';
import { MetadataWriter } from './MetadataWriter';

/**
 * A {@link MetadataWriter} that generates all the necessary headers related to the modification date of a resource.
 */
export class ModifiedMetadataWriter extends MetadataWriter {
  public async handle(input: { response: HttpResponse; metadata: RepresentationMetadata }): Promise<void> {
    const modified = input.metadata.get(DC.terms.modified);
    if (modified) {
      const date = new Date(modified.value);
      addHeader(input.response, 'Last-Modified', date.toUTCString());
    }
    const etag = input.metadata.get(HH.terms.etag);
    if (etag) {
      addHeader(input.response, 'ETag', etag.value);
    }
  }
}

import { getLoggerFor } from '../../../logging/LogUtil';
import type { HttpResponse } from '../../../server/HttpResponse';
import { addHeader } from '../../../util/HeaderUtil';
import { termToInt } from '../../../util/QuadUtil';
import { POSIX, SOLID_HTTP } from '../../../util/Vocabularies';
import type { RepresentationMetadata } from '../../representation/RepresentationMetadata';
import { MetadataWriter } from './MetadataWriter';

/**
 * Generates the necessary `content-range` header if there is range metadata.
 * If the start or end is unknown, a `*` will be used instead.
 * According to the RFC, this is incorrect,
 * but is all we can do as long as we don't know the full length of the representation in advance.
 * For the same reason, the total length of the representation will always be `*`.
 *
 * This class also adds the content-length header.
 * This will contain either the full size for standard requests,
 * or the size of the slice for range requests.
 */
export class RangeMetadataWriter extends MetadataWriter {
  protected readonly logger = getLoggerFor(this);

  public async handle(input: { response: HttpResponse; metadata: RepresentationMetadata }): Promise<void> {
    const size = termToInt(input.metadata.get(POSIX.terms.size));
    const unit = input.metadata.get(SOLID_HTTP.terms.unit)?.value;
    if (!unit) {
      if (typeof size === 'number') {
        addHeader(input.response, 'Content-Length', `${size}`);
      }
      return;
    }

    let start = termToInt(input.metadata.get(SOLID_HTTP.terms.start));
    if (typeof start === 'number' && start < 0 && typeof size === 'number') {
      start = size + start;
    }
    let end = termToInt(input.metadata.get(SOLID_HTTP.terms.end));
    if (typeof end !== 'number' && typeof size === 'number') {
      end = size - 1;
    }

    const rangeHeader = `${unit} ${start ?? '*'}-${end ?? '*'}/${size ?? '*'}`;
    addHeader(input.response, 'Content-Range', rangeHeader);
    if (typeof start === 'number' && typeof end === 'number') {
      addHeader(input.response, 'Content-Length', `${end - start + 1}`);
    } else {
      this.logger.warn(`Generating invalid content-range header due to missing size information: ${rangeHeader}`);
    }
  }
}

import { getLoggerFor } from '../../../logging/LogUtil';
import type { StorageLocationStrategy } from '../../../server/description/StorageLocationStrategy';
import { createErrorMessage } from '../../../util/errors/ErrorUtil';
import { addHeader } from '../../../util/HeaderUtil';
import { joinUrl } from '../../../util/PathUtil';
import { LDP, RDF, SOLID } from '../../../util/Vocabularies';
import type { ResourceIdentifier } from '../../representation/ResourceIdentifier';
import type { MetadataWriterInput } from './MetadataWriter';
import { MetadataWriter } from './MetadataWriter';

/**
 * Adds a link header pointing to the relevant storage description resource.
 * Recursively checks parent containers until a storage container is found,
 * and then appends the provided relative path to determine the storage description resource.
 */
export class StorageDescriptionAdvertiser extends MetadataWriter {
  protected readonly logger = getLoggerFor(this);

  private readonly storageStrategy: StorageLocationStrategy;
  private readonly relativePath: string;

  public constructor(storageStrategy: StorageLocationStrategy, relativePath: string) {
    super();
    this.storageStrategy = storageStrategy;
    this.relativePath = relativePath;
  }

  public async handle({ response, metadata }: MetadataWriterInput): Promise<void> {
    // This indicates this is the response of a successful GET/HEAD request
    if (!metadata.has(RDF.terms.type, LDP.terms.Resource)) {
      return;
    }
    const identifier = { path: metadata.identifier.value };
    let storageRoot: ResourceIdentifier;
    try {
      storageRoot = await this.storageStrategy.getStorageIdentifier(identifier);
      this.logger.debug(`Found storage root ${storageRoot.path}`);
    } catch (error: unknown) {
      this.logger.error(`Unable to find storage root: ${createErrorMessage(error)
      }. The storage/location import in the server configuration is probably wrong.`);
      return;
    }
    const storageDescription = joinUrl(storageRoot.path, this.relativePath);
    addHeader(response, 'Link', `<${storageDescription}>; rel="${SOLID.storageDescription}"`);
  }
}

import type { Term } from '@rdfjs/types';
import type { HttpResponse } from '../../../server/HttpResponse';
import { addHeader } from '../../../util/HeaderUtil';
import { ACL, AUTH } from '../../../util/Vocabularies';
import type { RepresentationMetadata } from '../../representation/RepresentationMetadata';
import { MetadataWriter } from './MetadataWriter';

/**
 * Add the necessary WAC-Allow header values.
 * Solid, §10.1: "Servers exposing client’s access privileges on a resource URL MUST advertise
 * by including the WAC-Allow HTTP header in the response of HTTP HEAD and GET requests."
 * https://solid.github.io/specification/protocol#web-access-control
 */
export class WacAllowMetadataWriter extends MetadataWriter {
  public async handle(input: { response: HttpResponse; metadata: RepresentationMetadata }): Promise<void> {
    let userModes = new Set(input.metadata.getAll(AUTH.terms.userMode).map(this.aclToPermission));
    const publicModes = new Set(input.metadata.getAll(AUTH.terms.publicMode).map(this.aclToPermission));

    // Public access implies user access
    userModes = new Set([ ...userModes, ...publicModes ]);

    const headerStrings: string[] = [];
    if (userModes.size > 0) {
      headerStrings.push(this.createAccessParam('user', userModes));
    }
    if (publicModes.size > 0) {
      headerStrings.push(this.createAccessParam('public', publicModes));
    }

    // Only add the header if there are permissions to show
    if (headerStrings.length > 0) {
      addHeader(input.response, 'WAC-Allow', headerStrings.join(','));
    }
  }

  private aclToPermission(this: void, aclTerm: Term): string {
    return aclTerm.value.slice(ACL.namespace.length).toLowerCase();
  }

  private createAccessParam(name: string, modes: Set<string>): string {
    // Sort entries to have consistent output
    return `${name}="${[ ...modes ].sort((left, right): number => left.localeCompare(right)).join(' ')}"`;
  }
}

import type { HttpResponse } from '../../../server/HttpResponse';
import { addHeader } from '../../../util/HeaderUtil';
import { HTTP } from '../../../util/Vocabularies';
import type { RepresentationMetadata } from '../../representation/RepresentationMetadata';
import { MetadataWriter } from './MetadataWriter';

/**
 * Adds the `WWW-Authenticate` header with the injected value in case the response status code is 401.
 */
export class WwwAuthMetadataWriter extends MetadataWriter {
  private readonly auth: string;

  public constructor(auth: string) {
    super();
    this.auth = auth;
  }

  public async handle(input: { response: HttpResponse; metadata: RepresentationMetadata }): Promise<void> {
    const statusLiteral = input.metadata.get(HTTP.terms.statusCodeNumber);
    if (statusLiteral?.value === '401') {
      addHeader(input.response, 'WWW-Authenticate', this.auth);
    }
  }
}

