  extends AsyncHandler<{ response: HttpResponse; result: ResponseDescription }> {}

import type { Readable } from 'node:stream';
import { INTERNAL_QUADS } from '../../util/ContentTypes';
import type { Guarded } from '../../util/GuardedStream';
import { guardStream } from '../../util/GuardedStream';
import { guardedStreamFrom } from '../../util/StreamUtil';
import type { Representation } from './Representation';
import type { MetadataIdentifier, MetadataRecord } from './RepresentationMetadata';
import { isRepresentationMetadata, RepresentationMetadata } from './RepresentationMetadata';

/**
 * Class with various constructors to facilitate creating a representation.
 *
 * A representation consists of 1) data, 2) metadata, and 3) a binary flag
 * to indicate whether the data is a binary stream or an object stream.
 *
 * 1. The data can be given as a stream, array, or string.
 * 2. The metadata can be specified as one or two parameters
 *    that will be passed to the {@link RepresentationMetadata} constructor.
 * 3. The binary field is optional, and if not specified,
 *    is determined from the content type inside the metadata.
 */
export class BasicRepresentation implements Representation {
  public readonly data: Guarded<Readable>;
  public readonly metadata: RepresentationMetadata;
  public readonly binary: boolean;

  /**
   * An empty Representation
   */
  public constructor();

  /**
   * @param data - The representation data
   * @param metadata - The representation metadata
   * @param binary - Whether the representation is a binary or object stream
   */
  public constructor(
    data: Guarded<Readable> | Readable | unknown[] | string,
    metadata: RepresentationMetadata | MetadataRecord,
    binary?: boolean,
  );

  /**
   * @param data - The representation data
   * @param metadata - The representation metadata
   * @param contentType - The representation's content type
   * @param binary - Whether the representation is a binary or object stream
   */
  public constructor(
    data: Guarded<Readable> | Readable | unknown[] | string,
    metadata: RepresentationMetadata | MetadataRecord,
    contentType?: string,
    binary?: boolean,
  );

  /**
   * @param data - The representation data
   * @param contentType - The representation's content type
   * @param binary - Whether the representation is a binary or object stream
   */
  public constructor(
    data: Guarded<Readable> | Readable | unknown[] | string,
    contentType: string,
    binary?: boolean,
  );

  /**
   * @param data - The representation data
   * @param identifier - The representation's identifier
   * @param metadata - The representation metadata
   * @param binary - Whether the representation is a binary or object stream
   */
  public constructor(
    data: Guarded<Readable> | Readable | unknown[] | string,
    identifier: MetadataIdentifier,
    metadata?: MetadataRecord,
    binary?: boolean,
  );

  /**
   * @param data - The representation data
   * @param identifier - The representation's identifier
   * @param contentType - The representation's content type
   * @param binary - Whether the representation is a binary or object stream
   */
  public constructor(
    data: Guarded<Readable> | Readable | unknown[] | string,
    identifier: MetadataIdentifier,
    contentType?: string,
    binary?: boolean,
  );

  public constructor(
    data?: Readable | unknown[] | string,
    metadata?: RepresentationMetadata | MetadataRecord | MetadataIdentifier | string,
    metadataRest?: MetadataRecord | string | boolean,
    binary?: boolean,
  ) {
    if (typeof data === 'string' || Array.isArray(data)) {
      data = guardedStreamFrom(data);
    } else if (!data) {
      data = guardedStreamFrom([]);
    }
    this.data = guardStream(data);

    if (typeof metadataRest === 'boolean') {
      binary = metadataRest;
      metadataRest = undefined;
    }
    if (!isRepresentationMetadata(metadata) || typeof metadataRest === 'string') {
      // This combination will always match with a valid overload
      metadata = new RepresentationMetadata(metadata as RepresentationMetadata, metadataRest as string);
    }
    this.metadata = metadata;

    if (typeof binary !== 'boolean') {
      binary = metadata.contentType !== INTERNAL_QUADS;
    }
    this.binary = binary;
  }

  /**
   * Data should only be interpreted if there is a content type.
   */
  public get isEmpty(): boolean {
    return !this.metadata.contentType;
  }
}

import type { Quad } from '@rdfjs/types';
import type { Patch } from './Patch';

/**
 * A Representation of an N3 Patch.
 * All quads should be in the default graph.
 */
export interface N3Patch extends Patch {
  deletes: Quad[];
  inserts: Quad[];
  conditions: Quad[];
}

export function isN3Patch(patch: unknown): patch is N3Patch {
  return Array.isArray((patch as N3Patch).deletes) &&
    Array.isArray((patch as N3Patch).inserts) &&
    Array.isArray((patch as N3Patch).conditions);
}

import type { Representation } from './Representation';

/**
 * Represents the changes needed for a PATCH request.
 */
export interface Patch extends Representation {
}

import type { Store } from 'n3';
import type { Representation } from './Representation';

/**
 * A {@link Representation} that contains an RDF/JS Dataset instead of a raw data stream.
 */
export interface RdfDatasetRepresentation extends Representation {
  /**
   * In {@link RdfDatasetRepresentation}, there is no data stream.
   */
  data: never;
  /**
   * The data of this representation which conforms to the RDF/JS Dataset interface
   * (https://rdf.js.org/dataset-spec/#dataset-interface).
   */
  dataset: Store;
}

import type { Readable } from 'node:stream';
import type { Guarded } from '../../util/GuardedStream';
import type { RepresentationMetadata } from './RepresentationMetadata';

/**
 * A representation of a resource.
 */
export interface Representation {
  /**
   * The corresponding metadata.
   */
  metadata: RepresentationMetadata;
  /**
   * The raw data stream for this representation.
   */
  data: Guarded<Readable>;
  /**
   * Whether the data stream consists of binary/string chunks
   * (as opposed to complex objects).
   */
  binary: boolean;
  /**
   * Whether the data stream is empty.
   * This being true does not imply that the data stream has a length of more than 0,
   * only that it is a possibility and should be read to be sure.
   */
  isEmpty: boolean;
}

import { DataFactory, Store } from 'n3';
import type { BlankNode, DefaultGraph, Literal, NamedNode, Quad, Term } from '@rdfjs/types';
import { getLoggerFor } from '../../logging/LogUtil';
import { ContentType, SIMPLE_MEDIA_RANGE } from '../../util/Header';
import { isTerm, toLiteral, toNamedTerm, toObjectTerm } from '../../util/TermUtil';
import { CONTENT_LENGTH_TERM, CONTENT_TYPE_TERM, RDFS, SOLID_META, XSD } from '../../util/Vocabularies';
import type { ResourceIdentifier } from './ResourceIdentifier';
import { isResourceIdentifier } from './ResourceIdentifier';

export type MetadataIdentifier = ResourceIdentifier | NamedNode | BlankNode;
export type MetadataValue = NamedNode | BlankNode | Literal | string | (NamedNode | Literal | BlankNode | string)[];
export type MetadataRecord = Record<string, MetadataValue>;
export type MetadataGraph = NamedNode | BlankNode | DefaultGraph | string;

/**
 * Determines whether the object is a `RepresentationMetadata`.
 */
export function isRepresentationMetadata(object: unknown): object is RepresentationMetadata {
  return typeof (object as RepresentationMetadata)?.setMetadata === 'function';
}

// Caches named node conversions
const cachedNamedNodes: Record<string, NamedNode> = {};

/**
 * Converts the incoming name (URI or shorthand) to a named node.
 * The generated terms get cached to reduce the number of created nodes,
 * so only use this for internal constants!
 *
 * @param name - Predicate to potentially transform.
 */
function toCachedNamedNode(name: string): NamedNode {
  if (!(name in cachedNamedNodes)) {
    cachedNamedNodes[name] = DataFactory.namedNode(name);
  }
  return cachedNamedNodes[name];
}

/**
 * Stores the metadata triples and provides methods for easy access.
 * Most functions return the metadata object to allow for chaining.
 */
export class RepresentationMetadata {
  protected readonly logger = getLoggerFor(this);

  private store: Store;
  private id: NamedNode | BlankNode;

  /**
   * @param identifier - Identifier of the resource relevant to this metadata.
   *                     A blank node will be generated if none is provided.
   *                     Strings will be converted to named nodes. @ignored
   * @param overrides - Key/value map of extra values that need to be added to the metadata. @ignored
   *
   * `@ignored` tag is necessary for Components-Generator.js
   */
  public constructor(identifier?: MetadataIdentifier, overrides?: MetadataRecord);

  /**
   * @param metadata - Starts as a copy of the input metadata.
   * @param overrides - Key/value map of extra values that need to be added to the metadata.
   *                    Will override values that were set by the input metadata.
   */
  public constructor(metadata?: RepresentationMetadata, overrides?: MetadataRecord);

  /**
   * @param identifier - Identifier of the resource relevant to this metadata.
   * @param contentType - Override for the content type of the representation.
   */
  public constructor(identifier?: MetadataIdentifier, contentType?: string | ContentType);

  /**
   * @param metadata - Starts as a copy of the input metadata.
   * @param contentType - Override for the content type of the representation.
   */
  public constructor(metadata?: RepresentationMetadata, contentType?: string | ContentType);

  /**
   * @param contentType - The content type of the representation.
   */
  public constructor(contentType?: string | ContentType);

  /**
   * @param metadata - Metadata values (defaulting to content type if a string)
   */
  public constructor(metadata?: RepresentationMetadata | MetadataRecord | string);

  public constructor(
    input?: MetadataIdentifier | RepresentationMetadata | MetadataRecord | ContentType | string,
    overrides?: MetadataRecord | string | ContentType,
  ) {
    this.store = new Store();
    if (isResourceIdentifier(input)) {
      this.id = DataFactory.namedNode(input.path);
    } else if (isTerm(input)) {
      this.id = input;
    } else if (isRepresentationMetadata(input)) {
      this.id = input.identifier;
      this.addQuads(input.quads());
    } else {
      overrides = input;
      this.id = this.store.createBlankNode();
    }

    if (overrides) {
      if (typeof overrides === 'string') {
        this.contentType = overrides;
      } else if (overrides instanceof ContentType) {
        this.contentTypeObject = overrides;
      } else {
        this.setOverrides(overrides);
      }
    }
  }

  private setOverrides(overrides: Record<string, MetadataValue>): void {
    for (const predicate of Object.keys(overrides)) {
      const namedPredicate = toCachedNamedNode(predicate);
      this.removeAll(namedPredicate);

      let objects = overrides[predicate];
      if (!Array.isArray(objects)) {
        objects = [ objects ];
      }
      for (const object of objects) {
        this.store.addQuad(this.id, namedPredicate, toObjectTerm(object, true));
      }
    }
  }

  /**
   * @returns All matching metadata quads.
   */
  public quads(
    subject: NamedNode | BlankNode | string | null = null,
    predicate: NamedNode | null = null,
    object: NamedNode | BlankNode | Literal | string | null = null,
    graph: MetadataGraph | null = null,
  ): Quad[] {
    return this.store.getQuads(subject, predicate, object, graph);
  }

  /**
   * Identifier of the resource this metadata is relevant to.
   * Will update all relevant triples if this value gets changed.
   */
  public get identifier(): NamedNode | BlankNode {
    return this.id;
  }

  public set identifier(id: NamedNode | BlankNode) {
    if (!id.equals(this.id)) {
      // Convert all instances of the old identifier to the new identifier in the stored quads
      const quads = this.quads().map((quad): Quad => {
        if (quad.subject.equals(this.id)) {
          return DataFactory.quad(id, quad.predicate, quad.object, quad.graph);
        }
        if (quad.object.equals(this.id)) {
          return DataFactory.quad(quad.subject, quad.predicate, id, quad.graph);
        }
        return quad;
      });
      this.store = new Store(quads);
      this.id = id;
    }
  }

  /**
   * Helper function to import all entries from the given metadata.
   * If the new metadata has a different identifier the internal one will be updated.
   *
   * @param metadata - Metadata to import.
   */
  public setMetadata(metadata: RepresentationMetadata): this {
    this.identifier = metadata.identifier;
    this.addQuads(metadata.quads());
    return this;
  }

  /**
   * @param subject - Subject of quad to add.
   * @param predicate - Predicate of quad to add.
   * @param object - Object of quad to add.
   * @param graph - Optional graph of quad to add.
   */
  public addQuad(
    subject: NamedNode | BlankNode | string,
    predicate: NamedNode,
    object: NamedNode | BlankNode | Literal | string,
    graph?: MetadataGraph,
  ): this {
    this.store.addQuad(
      toNamedTerm(subject),
      predicate,
      toObjectTerm(object, true),
      graph ? toNamedTerm(graph) : undefined,
    );
    return this;
  }

  /**
   * @param quads - Quads to add to the metadata.
   */
  public addQuads(quads: Quad[]): this {
    this.store.addQuads(quads);
    return this;
  }

  /**
   * @param subject - Subject of quad to remove.
   * @param predicate - Predicate of quad to remove.
   * @param object - Object of quad to remove.
   * @param graph - Optional graph of quad to remove.
   */
  public removeQuad(
    subject: NamedNode | BlankNode | string,
    predicate: NamedNode,
    object: NamedNode | BlankNode | Literal | string,
    graph?: MetadataGraph,
  ): this {
    const quads = this.quads(
      toNamedTerm(subject),
      predicate,
      toObjectTerm(object, true),
      graph ? toNamedTerm(graph) : undefined,
    );
    return this.removeQuads(quads);
  }

  /**
   * @param quads - Quads to remove from the metadata.
   */
  public removeQuads(quads: Quad[]): this {
    this.store.removeQuads(quads);
    return this;
  }

  /**
   * Adds a value linked to the identifier. Strings get converted to literals.
   *
   * @param predicate - Predicate linking identifier to value.
   * @param object - Value(s) to add.
   * @param graph - Optional graph of where to add the values to.
   */
  public add(predicate: NamedNode, object: MetadataValue, graph?: MetadataGraph): this {
    return this.forQuads(predicate, object, (pred, obj): unknown => this.addQuad(this.id, pred, obj, graph));
  }

  /**
   * Removes the given value from the metadata. Strings get converted to literals.
   *
   * @param predicate - Predicate linking identifier to value.
   * @param object - Value(s) to remove.
   * @param graph - Optional graph of where to remove the values from.
   */
  public remove(predicate: NamedNode, object: MetadataValue, graph?: MetadataGraph): this {
    return this.forQuads(predicate, object, (pred, obj): unknown => this.removeQuad(this.id, pred, obj, graph));
  }

  /**
   * Helper function to simplify add/remove
   * Runs the given function on all predicate/object pairs, but only converts the predicate to a named node once.
   */
  private forQuads(
    predicate: NamedNode,
    object: MetadataValue,
    forFn: (pred: NamedNode, obj: NamedNode | BlankNode | Literal) => void,
  ): this {
    const objects = Array.isArray(object) ? object : [ object ];
    for (const obj of objects) {
      forFn(predicate, toObjectTerm(obj, true));
    }
    return this;
  }

  /**
   * Removes all values linked through the given predicate.
   *
   * @param predicate - Predicate to remove.
   * @param graph - Optional graph where to remove from.
   */
  public removeAll(predicate: NamedNode, graph?: MetadataGraph): this {
    this.removeQuads(this.store.getQuads(this.id, predicate, null, graph ?? null));
    return this;
  }

  /**
   * Verifies if a specific triple can be found in the metadata.
   * Undefined parameters are interpreted as wildcards.
   */
  public has(
    predicate: NamedNode | string | null = null,
    object: NamedNode | BlankNode | Literal | string | null = null,
    graph: MetadataGraph | null = null,
  ): boolean {
    // This works with N3.js but at the time of writing the typings have not been updated yet.
    // If you see this line of code check if the typings are already correct and update this if so.
    return (this.store as unknown as {
      has: (
        subject: Term,
        predicate: Term | string | null,
        object: Term | string | null,
        graph: Term | string | null
      ) => boolean;
    }).has(this.id, predicate, object, graph);
  }

  /**
   * Finds all object values matching the given predicate and/or graph.
   *
   * @param predicate - Optional predicate to get the values for.
   * @param graph - Optional graph where to get from.
   *
   * @returns An array with all matches.
   */
  public getAll(predicate: NamedNode, graph?: MetadataGraph): Term[] {
    return this.store.getQuads(this.id, predicate, null, graph ?? null)
      .map((quad): Term => quad.object);
  }

  /**
   * @param predicate - Predicate to get the value for.
   * @param graph - Optional graph where the triple should be found.
   *
   * @returns The corresponding value. Undefined if there is no match
   *
   * @throws Error
   * If there are multiple matching values.
   */
  public get(predicate: NamedNode, graph?: MetadataGraph): Term | undefined {
    const terms = this.getAll(predicate, graph);
    if (terms.length === 0) {
      return;
    }
    if (terms.length > 1) {
      this.logger.error(`Multiple results for ${predicate.value}`);
      // We can not use an `InternalServerError` here as otherwise errors and metadata files would depend on each other
      throw new Error(
        `Multiple results for ${predicate.value}`,
      );
    }
    return terms[0];
  }

  /**
   * Sets the value for the given predicate, removing all other instances.
   * In case the object is undefined this is identical to `removeAll(predicate)`.
   *
   * @param predicate - Predicate linking to the value.
   * @param object - Value(s) to set.
   * @param graph - Optional graph where the triple should be stored.
   */
  public set(predicate: NamedNode, object?: MetadataValue, graph?: MetadataGraph): this {
    this.removeAll(predicate, graph);
    if (object) {
      this.add(predicate, object, graph);
    }
    return this;
  }

  private setContentType(input?: ContentType | string): void {
    // Make sure complete Content-Type RDF structure is gone
    this.removeContentType();

    if (!input) {
      return;
    }

    if (typeof input === 'string') {
      // Simple check to estimate if this is a simple content type.
      // If not, mention that the `contentTypeObject` should be used instead.
      // Not calling `parseContentType` here as that would cause a dependency loop with `HttpError`.
      if (!SIMPLE_MEDIA_RANGE.test(input)) {
        // Not using an HttpError as HttpError depends on metadata
        throw new Error(
          'Only simple content types can be set by string. Use the `contentTypeObject` function for complexer types.',
        );
      }
      input = new ContentType(input);
    }

    for (const [ key, value ] of Object.entries(input.parameters)) {
      const node = DataFactory.blankNode();
      this.addQuad(this.id, SOLID_META.terms.contentTypeParameter, node);
      this.addQuad(node, RDFS.terms.label, key);
      this.addQuad(node, SOLID_META.terms.value, value);
    }

    // Set base content type string
    this.set(CONTENT_TYPE_TERM, input.value);
  }

  /**
   * Parse the internal RDF structure to retrieve the Record with ContentType Parameters.
   *
   * @returns A {@link ContentType} object containing the value and optional parameters if there is one.
   */
  private getContentType(): ContentType | undefined {
    const value = this.get(CONTENT_TYPE_TERM)?.value;
    if (!value) {
      return;
    }
    const params = this.getAll(SOLID_META.terms.contentTypeParameter);
    const parameters = Object.fromEntries(params.map((param): [string, string] => {
      const labels = this.store.getObjects(param, RDFS.terms.label, null);
      const values = this.store.getObjects(param, SOLID_META.terms.value, null);
      if (labels.length !== 1 || values.length !== 1) {
        this.logger.error(`Detected invalid content-type metadata for ${this.id.value}`);
        return [ 'invalid', '' ];
      }
      return [ labels[0].value, values[0].value ];
    }));
    return new ContentType(value, parameters);
  }

  private removeContentType(): void {
    this.removeAll(CONTENT_TYPE_TERM);
    const params = this.quads(this.id, SOLID_META.terms.contentTypeParameter);
    for (const quad of params) {
      const paramEntries = this.quads(quad.object as BlankNode);
      this.store.removeQuads(paramEntries);
    }
    this.store.removeQuads(params);
  }

  // Syntactic sugar for common predicates

  /**
   * Shorthand for the CONTENT_TYPE predicate.
   */
  public get contentType(): string | undefined {
    return this.get(CONTENT_TYPE_TERM)?.value;
  }

  public set contentType(input) {
    this.setContentType(input);
  }

  /**
   * Shorthand for the ContentType as an object (with parameters)
   */
  public get contentTypeObject(): ContentType | undefined {
    return this.getContentType();
  }

  public set contentTypeObject(contentType) {
    this.setContentType(contentType);
  }

  /**
   * Shorthand for the CONTENT_LENGTH predicate.
   */
  public get contentLength(): number | undefined {
    const length = this.get(CONTENT_LENGTH_TERM);
    return length?.value ? Number(length.value) : undefined;
  }

  public set contentLength(input) {
    if (input) {
      this.set(CONTENT_LENGTH_TERM, toLiteral(input, XSD.terms.integer));
    }
  }
}

/**
 * Represents preferred values along a single content negotiation dimension.
 *
 * The number represents how preferred this value is from 0 to 1.
 * Follows the quality values rule from RFC 7231:
 * "The weight is normalized to a real number in the range 0 through 1,
 * where 0.001 is the least preferred and 1 is the most preferred; a
 * value of 0 means "not acceptable"."
 *
 * Because of an open issue in Components.js we cannot use `Record<string, number>` right now.
 * https://github.com/LinkedSoftwareDependencies/Components-Generator.js/issues/103
 */
// eslint-disable-next-line @typescript-eslint/consistent-indexed-object-style
export type ValuePreferences = {[key: string ]: number };

/**
 * A single entry of a {@link ValuePreferences} object.
 * Useful when doing operations on such an object.
 */
export type ValuePreference = { value: string; weight: number };

/**
 * Contains preferences along multiple content negotiation dimensions.
 *
 * All dimensions are optional for ease of constructing; either `undefined`
 * or an empty `ValuePreferences` can indicate that no preferences were specified.
 */
export interface RepresentationPreferences {
  type?: ValuePreferences;
  charset?: ValuePreferences;
  datetime?: ValuePreferences;
  encoding?: ValuePreferences;
  language?: ValuePreferences;
  // `start` can be negative and implies the last X of a stream
  range?: { unit: string; parts: { start: number; end?: number }[] };
}

/**
 * The unique identifier of a resource.
 */
export interface ResourceIdentifier {
  /**
   * Path to the relevant resource.
   */
  path: string;
}

/**
 * Determines whether the object is a {@link ResourceIdentifier}.
 */
export function isResourceIdentifier(object: unknown): object is ResourceIdentifier {
  return Boolean(object) && typeof (object as ResourceIdentifier).path === 'string';
}

import type { Algebra } from 'sparqlalgebrajs';
import type { Patch } from './Patch';

/**
 * A specific type of {@link Patch} corresponding to a SPARQL update.
 */
export interface SparqlUpdatePatch extends Patch {
  /**
   * Algebra corresponding to the SPARQL update.
   */
  algebra: Algebra.Update;
}

import type { IncomingMessage } from 'node:http';
import type { TLSSocket } from 'node:tls';
import type { WebSocket } from 'ws';
import type { SingleThreaded } from '../init/cluster/SingleThreaded';
import { getLoggerFor } from '../logging/LogUtil';
import type { ActivityEmitter } from '../server/notifications/ActivityEmitter';
import type { WebSocketHandlerInput } from '../server/WebSocketHandler';
import { WebSocketHandler } from '../server/WebSocketHandler';
import { createErrorMessage } from '../util/errors/ErrorUtil';
import { NotImplementedHttpError } from '../util/errors/NotImplementedHttpError';
import type { GenericEventEmitter } from '../util/GenericEventEmitter';
import { createGenericEventEmitterClass } from '../util/GenericEventEmitter';
import { parseForwarded } from '../util/HeaderUtil';
import { splitCommaSeparated } from '../util/StringUtil';
import type { ResourceIdentifier } from './representation/ResourceIdentifier';

const VERSION = 'solid-0.1';

// eslint-disable-next-line @typescript-eslint/naming-convention
const WebSocketListenerEmitter = createGenericEventEmitterClass<GenericEventEmitter<'closed', () => void>>();

/**
 * Implementation of Solid WebSockets API Spec solid-0.1
 * at https://github.com/solid/solid-spec/blob/master/api-websockets.md
 */
class WebSocketListener extends WebSocketListenerEmitter {
  private host = '';
  private protocol = '';
  private readonly socket: WebSocket;
  private readonly subscribedPaths = new Set<string>();
  private readonly logger = getLoggerFor(this);

  public constructor(socket: WebSocket) {
    super();
    this.socket = socket;
    socket.addListener('error', (): void => this.stop());
    socket.addListener('close', (): void => this.stop());
    socket.addListener('message', (message: string): void => this.onMessage(message));
  }

  public start({ headers, socket }: IncomingMessage): void {
    // Greet the client
    this.sendMessage('protocol', VERSION);

    // Verify the WebSocket protocol version
    const protocolHeader = headers['sec-websocket-protocol'];
    if (protocolHeader) {
      const supportedProtocols = splitCommaSeparated(protocolHeader);
      if (!supportedProtocols.includes(VERSION)) {
        this.sendMessage('error', `Client does not support protocol ${VERSION}`);
        this.stop();
      }
    } else {
      this.sendMessage('warning', `Missing Sec-WebSocket-Protocol header, expected value '${VERSION}'`);
    }

    // Store the HTTP host and protocol
    const forwarded = parseForwarded(headers);
    this.host = forwarded.host ?? headers.host ?? 'localhost';
    this.protocol = forwarded.proto === 'https' || (socket as TLSSocket).encrypted ? 'https:' : 'http:';
  }

  private stop(): void {
    try {
      this.socket.close();
    } catch {
      // Ignore
    }
    this.subscribedPaths.clear();
    this.socket.removeAllListeners();
    this.emit('closed');
  }

  public onResourceChanged({ path }: ResourceIdentifier): void {
    if (this.subscribedPaths.has(path)) {
      this.sendMessage('pub', path);
    }
  }

  private onMessage(message: string): void {
    // Parse the message
    const match = /^(\w+)\s+(\S.+)$/u.exec(message);
    if (!match) {
      this.sendMessage('warning', `Unrecognized message format: ${message}`);
      return;
    }

    // Process the message
    const [ , type, value ] = match;
    switch (type) {
      case 'sub':
        this.subscribe(value);
        break;
      default:
        this.sendMessage('warning', `Unrecognized message type: ${type}`);
    }
  }

  private subscribe(path: string): void {
    try {
      // Resolve and verify the URL
      const resolved = new URL(path, `${this.protocol}${this.host}`);
      if (resolved.host !== this.host) {
        throw new Error(`Mismatched host: expected ${this.host} but got ${resolved.host}`);
      }
      if (resolved.protocol !== this.protocol) {
        throw new Error(`Mismatched protocol: expected ${this.protocol} but got ${resolved.protocol}`);
      }
      // Subscribe to the URL
      const url = resolved.href;
      this.subscribedPaths.add(url);
      this.sendMessage('ack', url);
      this.logger.debug(`WebSocket subscribed to changes on ${url}`);
    } catch (error: unknown) {
      // Report errors to the socket
      const errorText: string = createErrorMessage(error);
      this.sendMessage('error', errorText);
      this.logger.warn(`WebSocket could not subscribe to ${path}: ${errorText}`);
    }
  }

  private sendMessage(type: string, value: string): void {
    this.socket.send(`${type} ${value}`);
  }
}

/**
 * Provides live update functionality following
 * the Solid WebSockets API Spec solid-0.1.
 *
 * The `baseUrl` parameter should be the same one that is used to advertise with the Updates-Via header.
 */
export class UnsecureWebSocketsProtocol extends WebSocketHandler implements SingleThreaded {
  protected readonly logger = getLoggerFor(this);

  private readonly path: string;
  private readonly listeners = new Set<WebSocketListener>();

  public constructor(source: ActivityEmitter, baseUrl: string) {
    super();

    this.logger.warn('The chosen configuration includes Solid WebSockets API 0.1, which is unauthenticated.');
    this.logger.warn('This component will be removed from default configurations in future versions.');

    this.path = new URL(baseUrl).pathname;

    source.on('changed', (changed: ResourceIdentifier): void => this.onResourceChanged(changed));
  }

  public async canHandle({ upgradeRequest }: WebSocketHandlerInput): Promise<void> {
    if (upgradeRequest.url !== this.path) {
      throw new NotImplementedHttpError(`Only WebSocket requests to ${this.path} are supported.`);
    }
  }

  public async handle({ webSocket, upgradeRequest }: WebSocketHandlerInput): Promise<void> {
    const listener = new WebSocketListener(webSocket);
    this.listeners.add(listener);
    this.logger.info(`New WebSocket added, ${this.listeners.size} in total`);

    listener.on('closed', (): void => {
      this.listeners.delete(listener);
      this.logger.info(`WebSocket closed, ${this.listeners.size} remaining`);
    });
    listener.start(upgradeRequest);
  }

  private onResourceChanged(changed: ResourceIdentifier): void {
    for (const listener of this.listeners) {
      listener.onResourceChanged(changed);
    }
  }
}

import { Initializer } from '../init/Initializer';
import { getLoggerFor } from '../logging/LogUtil';
import type { AccountStore } from './interaction/account/util/AccountStore';
import type { PasswordStore } from './interaction/password/util/PasswordStore';
import type { PodCreator } from './interaction/pod/util/PodCreator';

export interface AccountInitializerArgs {
  /**
   * Creates the accounts.
   */
  accountStore: AccountStore;
  /**
   * Adds the login methods.
   */
  passwordStore: PasswordStore;
  /**
   * Creates the pods.
   */
  podCreator: PodCreator;
  /**
   * Email address for the account login.
   */
  email: string;
  /**
   * Password for the account login.
   */
  password: string;
  /**
   * Name to use for the pod. If undefined the pod will be made in the root of the server.
   */
  name?: string;
}

/**
 * Initializes an account with email/password login and a pod with the provided name.
 */
export class AccountInitializer extends Initializer {
  protected readonly logger = getLoggerFor(this);

  private readonly accountStore: AccountStore;
  private readonly passwordStore: PasswordStore;
  private readonly podCreator: PodCreator;
  private email: string | undefined;
  private password: string | undefined;
  private readonly name: string | undefined;

  public constructor(args: AccountInitializerArgs) {
    super();
    this.accountStore = args.accountStore;
    this.passwordStore = args.passwordStore;
    this.podCreator = args.podCreator;

    this.email = args.email;
    this.password = args.password;
    this.name = args.name;
  }

  public async handle(): Promise<void> {
    this.logger.info(`Creating account for ${this.email}`);
    const accountId = await this.accountStore.create();
    const id = await this.passwordStore.create(this.email!, accountId, this.password!);
    await this.passwordStore.confirmVerification(id);
    this.logger.info(`Creating pod ${this.name ? `with name ${this.name}` : 'at the root'}`);
    await this.podCreator.handleSafe({ accountId, name: this.name });

    // Not really necessary but don't want to keep passwords in memory if not required
    delete this.email;
    delete this.password;
  }
}

import type { interactionPolicy, KoaContextWithOIDC } from '../../../templates/types/oidc-provider';
import { getLoggerFor } from '../../logging/LogUtil';
import { InternalServerError } from '../../util/errors/InternalServerError';
import { importOidcProvider } from '../IdentityUtil';
import type { CookieStore } from '../interaction/account/util/CookieStore';
import { ACCOUNT_PROMPT } from '../interaction/InteractionUtil';
import type { WebIdStore } from '../interaction/webid/util/WebIdStore';
import { PromptFactory } from './PromptFactory';

type OIDCContext = NonNullable<KoaContextWithOIDC['oidc']['entities']['OIDCContext']>;
type ExtendedContext = OIDCContext & { internalAccountId?: string };

/**
 * Creates the prompt necessary to ensure a user is logged in with their account when doing an OIDC interaction.
 * This is done by checking the presence of the account-related cookie.
 *
 * Adds a Check to the login policy that verifies if the stored accountId, which corresponds to the chosen WebID,
 * belongs to the currently logged in account.
 */
export class AccountPromptFactory extends PromptFactory {
  protected readonly logger = getLoggerFor(this);

  private readonly webIdStore: WebIdStore;
  private readonly cookieStore: CookieStore;
  private readonly cookieName: string;

  public constructor(webIdStore: WebIdStore, cookieStore: CookieStore, cookieName: string) {
    super();
    this.webIdStore = webIdStore;
    this.cookieStore = cookieStore;
    this.cookieName = cookieName;
  }

  public async handle(policy: interactionPolicy.DefaultPolicy): Promise<void> {
    const { interactionPolicy: ip } = await importOidcProvider();
    this.addAccountPrompt(policy, ip);
    this.addWebIdVerificationPrompt(policy, ip);
  }

  private addAccountPrompt(policy: interactionPolicy.DefaultPolicy, ip: typeof interactionPolicy): void {
    const check = new ip.Check('no_account', 'An account cookie is required.', async(ctx): Promise<boolean> => {
      const cookie = ctx.cookies.get(this.cookieName);
      let accountId: string | undefined;
      if (cookie) {
        accountId = await this.cookieStore.get(cookie);
        // This is an ugly way to pass a value to the other prompts/checks,
        // but the oidc-provider library does similar things internally.
        (ctx.oidc as ExtendedContext).internalAccountId = accountId;
      }
      this.logger.debug(`Found account cookie ${cookie} and accountID ${accountId}`);

      // Check needs to return true if the prompt has to trigger
      return !accountId;
    });
    const accountPrompt = new ip.Prompt({ name: ACCOUNT_PROMPT, requestable: true }, check);
    policy.add(accountPrompt, 0);
  }

  private addWebIdVerificationPrompt(policy: interactionPolicy.DefaultPolicy, ip: typeof interactionPolicy): void {
    const check = new ip.Check(
      'no_webid_ownserhip',
      'The stored WebID does not belong to the account.',
      async(ctx): Promise<boolean> => {
        const webId = ctx.oidc.session?.accountId;
        if (!webId) {
          return false;
        }

        const accountId = (ctx.oidc as ExtendedContext).internalAccountId;
        if (!accountId) {
          this.logger.error(`Missing 'internalAccountId' value in OIDC context`);
          return false;
        }

        const isLinked = await this.webIdStore.isLinked(webId, accountId);
        this.logger.debug(`Session has WebID ${webId
        }, which ${isLinked ? 'belongs' : 'does not belong'} to the authenticated account`);

        return !isLinked;
      },
    );
    const loginPrompt = policy.get('login');
    if (!loginPrompt) {
      throw new InternalServerError('Missing default login policy');
    }
    loginPrompt.checks.add(check);
  }
}

import { createPublicKey } from 'node:crypto';
import type { KeyObject } from 'node:crypto';
import { exportJWK, generateKeyPair, importJWK } from 'jose';
import type { AsymmetricSigningAlgorithm, JWKS } from '../../../templates/types/oidc-provider';
import type { KeyValueStorage } from '../../storage/keyvalue/KeyValueStorage';
import type { AlgJwk, JwkGenerator } from './JwkGenerator';

/**
 * Generates a key pair once and then caches it using both an internal variable and a {@link KeyValueStorage}.
 * The storage makes sure the keys remain the same between server restarts,
 * while the internal variable makes it so the storage doesn't have to be accessed every time a key is needed.
 *
 * Only the private key is stored in the internal storage, using the `storageKey` parameter.
 * The public key is determined based on the private key and then also stored in memory.
 */
export class CachedJwkGenerator implements JwkGenerator {
  public readonly alg: AsymmetricSigningAlgorithm;

  private readonly key: string;
  private readonly storage: KeyValueStorage<string, JWKS>;

  private privateJwk?: AlgJwk;
  private publicJwk?: AlgJwk;

  public constructor(alg: AsymmetricSigningAlgorithm, storageKey: string, storage: KeyValueStorage<string, JWKS>) {
    this.alg = alg;
    this.key = storageKey;
    this.storage = storage;
  }

  public async getPrivateKey(): Promise<AlgJwk> {
    if (this.privateJwk) {
      return this.privateJwk;
    }

    // We store in JWKS format for backwards compatibility reasons.
    // If we want to just store the key instead we will need some way to do the migration.
    const jwks = await this.storage.get(this.key);
    if (jwks) {
      this.privateJwk = jwks.keys[0] as AlgJwk;
      return this.privateJwk;
    }

    const { privateKey } = await generateKeyPair(this.alg);

    // Make sure the JWK is a plain node object for storage
    const privateJwk = { ...await exportJWK(privateKey) } as AlgJwk;
    privateJwk.alg = this.alg;

    await this.storage.set(this.key, { keys: [ privateJwk ]});
    this.privateJwk = privateJwk;
    return privateJwk;
  }

  public async getPublicKey(): Promise<AlgJwk> {
    if (this.publicJwk) {
      return this.publicJwk;
    }

    const privateJwk = await this.getPrivateKey();

    // The main reason we generate the public key from the private key is, so we don't have to store it.
    // This allows our storage to not break previous versions where we only used the private key.
    // In practice this results in the same key.
    const privateKey = await importJWK(privateJwk);
    const publicKey = createPublicKey(privateKey as KeyObject);

    const publicJwk = { ...await exportJWK(publicKey) } as AlgJwk;
    // These fields get lost during the above proces
    publicJwk.alg = privateJwk.alg;

    this.publicJwk = publicJwk;

    return publicJwk;
  }
}

/* eslint-disable @typescript-eslint/naming-convention */
import { randomBytes } from 'node:crypto';
import type {
