  /**
   * Store containing the generated client credentials with their associated WebID.
   */
  clientCredentialsStore: ClientCredentialsStore;
  /**
   * Storage used to store cookie keys, so they can be re-used in case of multithreading.
   */
  storage: KeyValueStorage<string, string[]>;
  /**
   * Generates the JWK used for signing and decryption.
   */
  jwkGenerator: JwkGenerator;
  /**
   * Extra information will be added to the error output if this is true.
   */
  showStackTrace: boolean;
  /**
   * Used to convert errors thrown by the OIDC library.
   */
  errorHandler: ErrorHandler;
  /**
   * Used to write out errors thrown by the OIDC library.
   */
  responseWriter: ResponseWriter;
}

const COOKIES_KEY = 'cookie-secret';

/**
 * Creates an OIDC Provider based on the provided configuration and parameters.
 * The provider will be cached and returned on subsequent calls.
 * Cookie and JWT keys will be stored in an internal storage, so they can be re-used over multiple threads.
 * Necessary claims for Solid OIDC interactions will be added.
 * Routes will be updated based on the `baseUrl` and `oidcPath`.
 */
export class IdentityProviderFactory implements ProviderFactory {
  protected readonly logger = getLoggerFor(this);

  private readonly promptFactory: PromptFactory;
  private readonly config: Configuration;
  private readonly adapterFactory: AdapterFactory;
  private readonly baseUrl: string;
  private readonly oidcPath: string;
  private readonly interactionRoute: InteractionRoute;
  private readonly clientCredentialsStore: ClientCredentialsStore;
  private readonly storage: KeyValueStorage<string, string[]>;
  private readonly jwkGenerator: JwkGenerator;
  private readonly showStackTrace: boolean;
  private readonly errorHandler: ErrorHandler;
  private readonly responseWriter: ResponseWriter;

  private provider?: Provider;

  /**
   * @param config - JSON config for the OIDC library @range {json}
   * @param args - Remaining parameters required for the factory.
   */
  public constructor(config: Configuration, args: IdentityProviderFactoryArgs) {
    this.config = config;

    this.promptFactory = args.promptFactory;
    this.adapterFactory = args.adapterFactory;
    this.baseUrl = args.baseUrl;
    this.oidcPath = args.oidcPath;
    this.interactionRoute = args.interactionRoute;
    this.clientCredentialsStore = args.clientCredentialsStore;
    this.storage = args.storage;
    this.jwkGenerator = args.jwkGenerator;
    this.showStackTrace = args.showStackTrace;
    this.errorHandler = args.errorHandler;
    this.responseWriter = args.responseWriter;
  }

  public async getProvider(): Promise<Provider> {
    if (this.provider) {
      return this.provider;
    }
    this.provider = await this.createProvider();
    return this.provider;
  }

  /**
   * Creates a Provider by building a Configuration using all the stored parameters.
   */
  private async createProvider(): Promise<Provider> {
    const key = await this.jwkGenerator.getPrivateKey();

    const config = await this.initConfig(key);

    // Add correct claims to IdToken/AccessToken responses
    this.configureClaims(config, key.alg);

    // Make sure routes are contained in the IDP space
    this.configureRoutes(config);

    // Render errors with our own error handler
    this.configureErrors(config);

    const oidcImport = await importOidcProvider();

    // Adds new prompts
    const policy = oidcImport.interactionPolicy.base();
    await this.promptFactory.handleSafe(policy);
    config.interactions!.policy = policy;

    // eslint-disable-next-line new-cap
    const provider = new oidcImport.default(this.baseUrl, config);

    // Allow provider to interpret reverse proxy headers.
    provider.proxy = true;

    this.captureErrorResponses(provider);

    return provider;
  }

  /**
   * In the `configureErrors` function below, we configure the `renderError` function of the provider configuration.
   * This function is called by the OIDC provider library to render errors,
   * but only does this if the accept header is HTML.
   * Otherwise, it just returns the error object itself as a JSON object.
   * See https://github.com/panva/node-oidc-provider/blob/0fcc112e0a95b3b2dae4eba6da812253277567c9/lib/shared/error_handler.js#L48-L52.
   *
   * In this function we override the `ctx.accepts` function
   * to make the above code think HTML is always requested there.
   * This way we have full control over error representation as configured in `configureErrors`.
   * We still check the accept headers ourselves so there still is content negotiation on the output,
   * the client will not simply always receive HTML.
   *
   * Should this part of the OIDC library code ever change, our function will break,
   * at which point behaviour will simply revert to what it was before.
   */
  private captureErrorResponses(provider: Provider): void {
    provider.use(async(ctx, next): Promise<void> => {
      const accepts = ctx.accepts.bind(ctx);

      // This is how you get the correct typing for an overloaded function
      type AcceptFn = {
        (): string[];
        (...types: string[]): string | false;
        (types: string[]): string | false;
      };

      ctx.accepts = ((...types): string[] | string | false => {
        // Make sure we only override our specific case
        if (types.length === 2 && types[0] === 'json' && types[1] === 'html') {
          return 'html';
        }
        return accepts(...types as string[]);
      }) as AcceptFn;

      return next();
    });
  }

  /**
   * Creates a configuration by copying the internal configuration
   * and adding the adapter, default audience and jwks/cookie keys.
   */
  private async initConfig(key: AlgJwk): Promise<Configuration> {
    // Create a deep copy
    // Not sure why the structuredClone call is causing issues with the library.
    /* eslint-disable-next-line unicorn/prefer-structured-clone */
    const config = JSON.parse(JSON.stringify(this.config)) as Configuration;

    // Indicates which Adapter should be used for storing oidc data
    // The adapter function MUST be a named function.
    // See https://github.com/panva/node-oidc-provider/issues/799
    const factory = this.adapterFactory;
    config.adapter = function loadAdapter(name: string): Adapter {
      return factory.createStorageAdapter(name);
    };

    config.jwks = { keys: [ key ]};
    config.cookies = {
      ...config.cookies,
      keys: await this.generateCookieKeys(),
    };

    // Solid OIDC requires pkce https://solid.github.io/solid-oidc/#concepts
    config.pkce = {
      methods: [ 'S256' ],
      required: (): true => true,
    };

    // Default client settings that might not be defined.
    // Mostly relevant for WebID clients.
    config.clientDefaults = {
      id_token_signed_response_alg: key.alg,
    };

    return config;
  }

  /**
   * Generates a cookie secret to be used for cookie signing.
   * The key will be cached so subsequent calls return the same key.
   */
  private async generateCookieKeys(): Promise<string[]> {
    // Check to see if the keys are already saved
    const cookieSecret = await this.storage.get(COOKIES_KEY);
    if (Array.isArray(cookieSecret)) {
      return cookieSecret;
    }
    // If they are not, generate and save them
    const newCookieSecret = [ randomBytes(64).toString('hex') ];
    await this.storage.set(COOKIES_KEY, newCookieSecret);
    return newCookieSecret;
  }

  /**
   * Checks whether the given token is an access token.
   * The AccessToken interface is not exported, so we have to access it like this.
   */
  private isAccessToken(token: unknown): token is KoaContextWithOIDC['oidc']['accessToken'] {
    return (token as KoaContextWithOIDC['oidc']['accessToken'])?.kind === 'AccessToken';
  }

  /**
   * Adds the necessary claims to the id and access tokens based on the Solid OIDC spec.
   */
  private configureClaims(config: Configuration, jwtAlg: AsymmetricSigningAlgorithm): void {
    // Returns the id_token
    // See https://solid.github.io/authentication-panel/solid-oidc/#tokens-id
    // Some fields are still missing, see https://github.com/CommunitySolidServer/CommunitySolidServer/issues/1154#issuecomment-1040233385
    config.findAccount = async(ctx: KoaContextWithOIDC, sub: string): Promise<Account> => ({
      accountId: sub,
      async claims(): Promise<{ sub: string; [key: string]: unknown }> {
        return { sub, webid: sub, azp: ctx.oidc.client?.clientId };
      },
    });

    // Add extra claims in case an AccessToken is being issued.
    // Specifically this sets the required webid and client_id claims for the access token
    // See https://solid.github.io/solid-oidc/#resource-access-validation
    config.extraTokenClaims = async(ctx, token): Promise<UnknownObject> => {
      if (this.isAccessToken(token)) {
        return { webid: token.accountId };
      }
      const clientId = token.client?.clientId;
      if (!clientId) {
        throw new BadRequestHttpError('Missing client ID from client credentials.');
      }
      const webId = (await this.clientCredentialsStore.findByLabel(clientId))?.webId;
      if (!webId) {
        throw new BadRequestHttpError(`Unknown client credentials token ${clientId}`);
      }
      return { webid: webId };
    };

    config.features = {
      ...config.features,
      resourceIndicators: {
        defaultResource(): string {
          // This value is irrelevant, but is necessary to trigger the `getResourceServerInfo` call below,
          // where it will be an input parameter in case the client provided no value.
          // Note that an empty string is not a valid value.
          return 'http://example.com/';
        },
        enabled: true,
        // This call is necessary to force the OIDC library to return a JWT access token.
        // See https://github.com/panva/node-oidc-provider/discussions/959#discussioncomment-524757
        getResourceServerInfo: (): ResourceServer => ({
          // The scopes of the Resource Server.
          // These get checked when requesting client credentials.
          scope: '',
          audience: 'solid',
          accessTokenFormat: 'jwt',
          jwt: {
            sign: { alg: jwtAlg },
          },
        }),
      },
    };
  }

  /**
   * Creates the route string as required by the `oidc-provider` library.
   * In case base URL is `http://test.com/foo/`, `oidcPath` is `/idp` and `relative` is `device/auth`,
   * this would result in `/foo/idp/device/auth`.
   */
  private createRoute(relative: string): string {
    return new URL(joinUrl(this.baseUrl, this.oidcPath, relative)).pathname;
  }

  /**
   * Sets up all the IDP routes relative to the IDP path.
   */
  private configureRoutes(config: Configuration): void {
    // When oidc-provider cannot fulfill the authorization request for any of the possible reasons
    // (missing user session, requested ACR not fulfilled, prompt requested, ...)
    // it will resolve the interactions.url helper function and redirect the User-Agent to that url.
    // Another requirement is that `features.userinfo` is disabled in the configuration.
    config.interactions = {
      url: async(): Promise<string> => this.interactionRoute.getPath(),
    };

    config.routes = {
      authorization: this.createRoute('auth'),
      backchannel_authentication: this.createRoute('backchannel'),
      code_verification: this.createRoute('device'),
      device_authorization: this.createRoute('device/auth'),
      end_session: this.createRoute('session/end'),
      introspection: this.createRoute('token/introspection'),
      jwks: this.createRoute('jwks'),
      pushed_authorization_request: this.createRoute('request'),
      registration: this.createRoute('reg'),
      revocation: this.createRoute('token/revocation'),
      token: this.createRoute('token'),
      userinfo: this.createRoute('me'),
    };
  }

  /**
   * Pipes library errors to the provided ErrorHandler and ResponseWriter.
   */
  private configureErrors(config: Configuration): void {
    config.renderError = async(ctx: KoaContextWithOIDC, out: ErrorOut, error: errors.OIDCProviderError | Error):
    Promise<void> => {
      // This allows us to stream directly to the response object, see https://github.com/koajs/koa/issues/944
      ctx.respond = false;

      // Doesn't really matter which type it is since all relevant fields are optional
      const oidcError = error as errors.OIDCProviderError;

      // Create a more detailed error message for logging and to show is `showStackTrace` is enabled.
      let detailedError = oidcError.message;
      if (oidcError.error_description) {
        detailedError += ` - ${oidcError.error_description}`;
      }
      if (oidcError.error_detail) {
        detailedError += ` - ${oidcError.error_detail}`;
      }

      this.logger.warn(`OIDC request failed: ${detailedError}`);

      // Convert to our own error object.
      // This ensures serializing the error object will generate the correct output later on.
      // We specifically copy the fields instead of passing the object to contain the `oidc-provider` dependency
      // to the current file.
      let resultingError: HttpError = new OAuthHttpError(out, oidcError.name, oidcError.statusCode, oidcError.message);
      // Keep the original stack to make debugging easier
      resultingError.stack = oidcError.stack;

      if (this.showStackTrace) {
        // Expose more information if `showStackTrace` is enabled
        resultingError.message = detailedError;

        // Also change the error message in the stack trace
        if (resultingError.stack) {
          resultingError.stack = resultingError.stack.replace(/.*/u, `${oidcError.name}: ${oidcError.message}`);
        }
      }

      // A client not being found is quite often the result of cookies being stored by the authn client,
      // so we want to provide a more detailed error message explaining what to do.
      if (oidcError.error_description === 'client is invalid' && oidcError.error_detail === 'client not found') {
        const unknownClientError = new BadRequestHttpError(
          'Unknown client, you might need to clear the local storage on the client.',
          {
            errorCode: 'E0003',
            metadata: errorTermsToMetadata({
              client_id: ctx.request.query.client_id as string,
              redirect_uri: ctx.request.query.redirect_uri as string,
            }),
          },
        );
        unknownClientError.stack = oidcError.stack;
        resultingError = unknownClientError;
      }

      const result = await this.errorHandler.handleSafe({ error: resultingError, request: guardStream(ctx.req) });
      await this.responseWriter.handleSafe({ response: ctx.res, result });
    };
  }
}

import type { JWK } from 'jose';
import type { AsymmetricSigningAlgorithm } from '../../../templates/types/oidc-provider';

/**
 * A {@link JWK} where the `alg` parameter is always defined.
 */
export interface AlgJwk extends JWK {
  alg: AsymmetricSigningAlgorithm;
}

/**
 * Generates an asymmetric JWK.
 *
 * The functions always need to return the same value.
 */
export interface JwkGenerator {
  /**
   * The algorithm used for the keys.
   */
  readonly alg: AsymmetricSigningAlgorithm;

  /**
   * @returns The public key of the asymmetric JWK.
   */
  getPublicKey: () => Promise<AlgJwk>;

  /**
   * @returns The private key of the asymmetric JWK.
   */
  getPrivateKey: () => Promise<AlgJwk>;
}

import type { interactionPolicy } from '../../../templates/types/oidc-provider';
import { AsyncHandler } from '../../util/handlers/AsyncHandler';

/**
 * Used to generate custom {@link interactionPolicy.Prompt}s.
 */
export abstract class PromptFactory extends AsyncHandler<interactionPolicy.DefaultPolicy> {}

import type Provider from '../../../templates/types/oidc-provider';

/**
 * Returns a Provider of OIDC interactions.
 */
export interface ProviderFactory {
  /**
   * Gets a provider from the factory.
   * Multiple calls to this function should return providers that produce the same results.
   * This is mostly relevant for signing keys.
   */
  getProvider: () => Promise<Provider>;
}

import { OkResponseDescription } from '../http/output/response/OkResponseDescription';
import type { ResponseDescription } from '../http/output/response/ResponseDescription';
import { getLoggerFor } from '../logging/LogUtil';
import type { OperationHttpHandlerInput } from '../server/OperationHttpHandler';
import { OperationHttpHandler } from '../server/OperationHttpHandler';
import { createErrorMessage } from '../util/errors/ErrorUtil';
import { SOLID_HTTP } from '../util/Vocabularies';
import type { ProviderFactory } from './configuration/ProviderFactory';
import type { CookieStore } from './interaction/account/util/CookieStore';
import type { Interaction, InteractionHandler } from './interaction/InteractionHandler';

export interface IdentityProviderHttpHandlerArgs {
  /**
   * Used to generate the OIDC provider.
   */
  providerFactory: ProviderFactory;
  /**
   * Used to determine the account of the requesting agent.
   */
  cookieStore: CookieStore;
  /**
   * Handles the requests.
   */
  handler: InteractionHandler;
}

/**
 * Generates the active Interaction object if there is an ongoing OIDC interaction.
 * Finds the account ID if there is cookie metadata.
 *
 * Calls the stored {@link InteractionHandler} with that information and returns the result.
 */
export class IdentityProviderHttpHandler extends OperationHttpHandler {
  protected readonly logger = getLoggerFor(this);

  private readonly providerFactory: ProviderFactory;
  private readonly cookieStore: CookieStore;
  private readonly handler: InteractionHandler;

  public constructor(args: IdentityProviderHttpHandlerArgs) {
    super();
    this.providerFactory = args.providerFactory;
    this.cookieStore = args.cookieStore;
    this.handler = args.handler;
  }

  public async handle({ operation, request, response }: OperationHttpHandlerInput): Promise<ResponseDescription> {
    // This being defined means we're in an OIDC session
    let oidcInteraction: Interaction | undefined;
    try {
      const provider = await this.providerFactory.getProvider();
      oidcInteraction = await provider.interactionDetails(request, response);
      this.logger.debug('Found an active OIDC interaction.');
    } catch (error: unknown) {
      this.logger.debug(`No active OIDC interaction found: ${createErrorMessage(error)}`);
    }

    // Determine account
    let accountId: string | undefined;
    const cookie = operation.body.metadata.get(SOLID_HTTP.terms.accountCookie)?.value;
    if (cookie) {
      accountId = await this.cookieStore.get(cookie);
    }

    const representation = await this.handler.handleSafe({ operation, oidcInteraction, accountId });
    return new OkResponseDescription(representation.metadata, representation.data);
  }
}

import type { CanBePromise } from '../../templates/types/oidc-provider';

/**
 * Import the OIDC-provider package.
 *
 * As oidc-provider is an ESM package and CSS is CJS, we have to use a dynamic import here.
 * Unfortunately, there is a Node/Jest bug that causes segmentation faults when doing such an import in Jest:
 * https://github.com/nodejs/node/issues/35889
 * To work around that, we do the import differently, in case we are in a Jest test run.
 * This can be detected via the env variables: https://jestjs.io/docs/environment-variables.
 * There have been reports of `JEST_WORKER_ID` being undefined, so to be sure we check both.
 */
export function importOidcProvider(): CanBePromise<typeof import('../../templates/types/oidc-provider')> {
  if (process.env.JEST_WORKER_ID ?? process.env.NODE_ENV === 'test') {
    return jest.requireActual('oidc-provider');
  }
  return import('oidc-provider');
}

import { IdInteractionRoute } from '../routing/IdInteractionRoute';
import type { InteractionRoute } from '../routing/InteractionRoute';

// AccountIdKey = typeof ACCOUNT_ID_KEY does not work because Components.js doesn't support typeof like that

export type AccountIdKey = 'accountId';
export const ACCOUNT_ID_KEY: AccountIdKey = 'accountId';

/**
 * A route that includes an account identifier.
 */
export type AccountIdRoute = InteractionRoute<AccountIdKey>;

/**
 * Implementation of an {@link AccountIdRoute} that adds the identifier relative to a base {@link InteractionRoute}.
 */
export class BaseAccountIdRoute extends IdInteractionRoute<never, AccountIdKey> implements AccountIdRoute {
  public constructor(base: InteractionRoute) {
    super(base, 'accountId');
  }
}

import type { EmptyObject } from '../../../util/map/MapUtil';
import type { JsonRepresentation } from '../InteractionUtil';
import type { JsonView } from '../JsonView';
import type { LoginOutputType } from '../login/ResolveLoginHandler';
import { ResolveLoginHandler } from '../login/ResolveLoginHandler';
import type { AccountStore } from './util/AccountStore';
import type { CookieStore } from './util/CookieStore';

/**
 * Creates new accounts using an {@link AccountStore};
 */
export class CreateAccountHandler extends ResolveLoginHandler implements JsonView {
  public constructor(accountStore: AccountStore, cookieStore: CookieStore) {
    super(accountStore, cookieStore);
  }

  public async getView(): Promise<JsonRepresentation<EmptyObject>> {
    return { json: {}};
  }

  public async login(): Promise<JsonRepresentation<LoginOutputType>> {
    const accountId = await this.accountStore.create();

    return { json: { accountId }};
  }
}

import type {
  IndexObject,
  StringKey,
  TypeObject,
  ValueTypeDescription,
} from '../../../../storage/keyvalue/IndexedStorage';
import type { ACCOUNT_TYPE } from './LoginStorage';

/**
 * Settings parameter used to determine if the user wants the login to be remembered.
 */
export const ACCOUNT_SETTINGS_REMEMBER_LOGIN = 'rememberLogin';

export type GenericAccountSettings = Record<string, ValueTypeDescription<typeof ACCOUNT_TYPE> & `${string}?`>;

/**
 * The index type description of the minimal account settings.
 */
export type MinimalAccountSettings = { [ACCOUNT_SETTINGS_REMEMBER_LOGIN]: 'boolean?' };

/**
 * The JS object representation of the minimal account settings.
 */
export type AccountSettings = IndexObject<MinimalAccountSettings>;

/**
 * Used to store account data.
 */
export interface AccountStore<TSettings extends GenericAccountSettings = MinimalAccountSettings> {
  /**
   * Creates a new and empty account.
   * Since this account will not yet have a login method,
   * implementations should restrict what is possible with this account,
   * and should potentially have something in place to clean these accounts up if they are unused.
   */
  create: () => Promise<string>;

  /**
   * Finds the setting of the account with the given identifier.
   * Returns undefined if there is no matching account.
   *
   * @param id - The account identifier.
   * @param setting - The setting to find the value of.
   */
  getSetting: <TKey extends keyof TSettings>(id: string, setting: TKey)
  => Promise<TypeObject<TSettings>[TKey] | undefined>;

  /**
   * Updates the settings for the account with the given identifier to the new values.
   *
   * @param id - The account identifier.
   * @param setting - The setting to update.
   * @param value - The new value for the setting.
   */
  updateSetting: <TKey extends StringKey<TSettings>>(id: string, setting: TKey, value: TypeObject<TSettings>[TKey])
  => Promise<void>;
}

import { getLoggerFor } from '../../../../logging/LogUtil';
import { InternalServerError } from '../../../../util/errors/InternalServerError';
import { NotFoundHttpError } from '../../../../util/errors/NotFoundHttpError';
import type { InteractionRoute } from '../../routing/InteractionRoute';

const logger = getLoggerFor('AccountUtil');

/**
 * Asserts that the ID is defined. Throws a 404 otherwise.
 */
export function assertAccountId(accountId?: string): asserts accountId is string {
  if (!accountId) {
    throw new NotFoundHttpError();
  }
}

/**
 * Parses the given path with the given {@link InteractionRoute}.
 * This assumes this call will succeed and thus expects the path to have the correct format.
 * If not, a 500 error will be thrown.
 *
 * @param route - Route to parse with.
 * @param path - Path to parse.
 */
export function parsePath<T extends InteractionRoute<string>>(route: T, path: string):
NonNullable<ReturnType<T['matchPath']>> {
  const match = route.matchPath(path) as ReturnType<T['matchPath']> | undefined;
  if (!match) {
    logger.error(`Unable to parse path ${path}. This usually implies a server misconfiguration.`);
    throw new InternalServerError(`Unable to parse path ${path}. This usually implies a server misconfiguration.`);
  }
  return match;
}

/**
 * Asserts that the two given IDs are identical.
 * To be used when a request tries to access a resource to ensure they're not accessing someone else's data.
 *
 * @param input - Input ID.
 * @param expected - Expected ID.
 */
export function verifyAccountId(input?: string, expected?: string): asserts expected is string {
  if (input !== expected) {
    throw new NotFoundHttpError();
  }
}

import type { MinimalAccountSettings } from './AccountStore';
import { ACCOUNT_SETTINGS_REMEMBER_LOGIN } from './AccountStore';
import { GenericAccountStore } from './GenericAccountStore';
import type { AccountLoginStorage } from './LoginStorage';

export const ACCOUNT_STORAGE_DESCRIPTION = {
  [ACCOUNT_SETTINGS_REMEMBER_LOGIN]: 'boolean?',
} as const;

/**
 * A {@link GenericAccountStore} that supports the minimal account settings.
 * Needs to be initialized before it can be used.
 */
export class BaseAccountStore extends GenericAccountStore<MinimalAccountSettings> {
  // Wrong typings to prevent Components.js typing issues
  public constructor(storage: AccountLoginStorage<Record<string, never>>) {
    super(storage, ACCOUNT_STORAGE_DESCRIPTION);
  }
}

import { v4 } from 'uuid';
import type { ExpiringStorage } from '../../../../storage/keyvalue/ExpiringStorage';
import type { CookieStore } from './CookieStore';

/**
 * A {@link CookieStore} that uses an {@link ExpiringStorage} to keep track of the stored cookies.
 * Cookies have a specified time to live in seconds, default is 14 days,
 * after which they will be removed.
 */
export class BaseCookieStore implements CookieStore {
  private readonly storage: ExpiringStorage<string, string>;
  private readonly ttl: number;

  public constructor(storage: ExpiringStorage<string, string>, ttl = 14 * 24 * 60 * 60) {
    this.storage = storage;
    this.ttl = ttl * 1000;
  }

  public async generate(accountId: string): Promise<string> {
    const cookie = v4();
    await this.storage.set(cookie, accountId, this.ttl);
    return cookie;
  }

  public async get(cookie: string): Promise<string | undefined> {
    return this.storage.get(cookie);
  }

  public async refresh(cookie: string): Promise<Date | undefined> {
    const accountId = await this.storage.get(cookie);
    if (accountId) {
      await this.storage.set(cookie, accountId, this.ttl);
      return new Date(Date.now() + this.ttl);
    }
  }

  public async delete(cookie: string): Promise<boolean> {
    return this.storage.delete(cookie);
  }
}

import { getLoggerFor } from '../../../../logging/LogUtil';
import type {
  CreateTypeObject,
  IndexedQuery,
  IndexedStorage,
  IndexTypeCollection,
  StringKey,
  TypeObject,
  ValueType,
} from '../../../../storage/keyvalue/IndexedStorage';
import { BadRequestHttpError } from '../../../../util/errors/BadRequestHttpError';
import { NotFoundHttpError } from '../../../../util/errors/NotFoundHttpError';
import type { LoginStorage } from './LoginStorage';
import { ACCOUNT_TYPE } from './LoginStorage';

const LOGIN_COUNT = 'linkedLoginsCount';

const MINIMUM_ACCOUNT_DESCRIPTION = {
  [LOGIN_COUNT]: 'number',
} as const;

/**
 * A {@link LoginStorage} that wraps around another {@link IndexedStorage} to add specific account requirements.
 *   * New accounts will be removed after expiration time, in seconds, default is 1800,
 *     if no login method was added to them in that time.
 *   * Non-login types can not be created until the associated account has at least 1 login method.
 *   * Login types can not be deleted if they are the last login of the associated account.
 *
 * All of this is tracked by adding a new field to the account object,
 * that keeps track of how many login objects are associated with the account.
 */
export class BaseLoginAccountStorage<T extends IndexTypeCollection<T>> implements LoginStorage<T> {
  private readonly logger = getLoggerFor(this);

  protected readonly loginTypes: string[];
  protected readonly storage: IndexedStorage<T>;
  private readonly expiration: number;
  protected readonly accountKeys: NodeJS.Dict<string>;

  public constructor(storage: IndexedStorage<T>, expiration = 30 * 60) {
    this.loginTypes = [];
    this.storage = storage;
    this.expiration = expiration * 1000;
    this.accountKeys = {};
  }

  public async defineType<TType extends StringKey<T>>(type: TType, description: T[TType], isLogin: boolean):
  Promise<void> {
    // Determine potential new key pointing to account ID
    this.accountKeys[type] = Object.entries(description)
      .find(([ , desc ]): boolean => desc === `id:${ACCOUNT_TYPE}` as `id:${string & keyof T}`)?.[0];

    if (type === ACCOUNT_TYPE) {
      description = { ...description, ...MINIMUM_ACCOUNT_DESCRIPTION };
    }

    if (isLogin) {
      this.loginTypes.push(type);
    }

    return this.storage.defineType(type, description);
  }

  public async createIndex<TType extends StringKey<T>>(type: TType, key: StringKey<T[TType]>): Promise<void> {
    return this.storage.createIndex(type, key);
  }

  public async create<TType extends StringKey<T>>(type: TType, value: CreateTypeObject<T[TType]>):
  Promise<TypeObject<T[TType]>> {
    // Check login count if it is not a new login method that we are trying to add,
    // to make sure the account is already valid.
    // If we are adding a new login method: increase the login counter by 1.
    const accountKey = this.accountKeys[type];
    if (accountKey) {
      const accountId = value[accountKey] as string;
      await this.checkAccount(type, accountId, true);
    }

    if (type === ACCOUNT_TYPE) {
      value = { ...value, [LOGIN_COUNT]: 0 };
    }

    const result = await this.storage.create(type, value);

    if (type === ACCOUNT_TYPE) {
      this.createAccountTimeout(result.id);
    }

    return this.cleanOutput(result);
  }

  public async has<TType extends StringKey<T>>(type: TType, id: string): Promise<boolean> {
    return this.storage.has(type, id);
  }

  public async get<TType extends StringKey<T>>(type: TType, id: string): Promise<TypeObject<T[TType]> | undefined> {
    return this.cleanOutput(await this.storage.get(type, id));
  }

  public async find<TType extends StringKey<T>>(type: TType, query: IndexedQuery<T, TType>):
  Promise<TypeObject<T[TType]>[]> {
    return (await this.storage.find(type, query)).map(this.cleanOutput);
  }

  public async findIds<TType extends StringKey<T>>(type: TType, query: IndexedQuery<T, TType>): Promise<string[]> {
    return this.storage.findIds(type, query);
  }

  public async set<TType extends StringKey<T>>(type: TType, value: TypeObject<T[TType]>): Promise<void> {
    if (type === ACCOUNT_TYPE) {
      // Get login count from original object
      const original = await this.storage.get(type, value.id);
      if (!original) {
        throw new NotFoundHttpError();
      }
      // This makes sure we don't lose the login count
      value = { ...value, [LOGIN_COUNT]: original[LOGIN_COUNT] };
    }

    return this.storage.set(type, value);
  }

  public async setField<TType extends StringKey<T>, TKey extends StringKey<T[TType]>>(
    type: TType,
    id: string,
    key: TKey,
    value: ValueType<T[TType][TKey]>,
  ): Promise<void> {
    return this.storage.setField(type, id, key, value);
  }

  public async delete<TType extends StringKey<T>>(type: TType, id: string): Promise<void> {
    const accountKey = this.accountKeys[type];
    if (accountKey && this.loginTypes.includes(type)) {
      const original = await this.storage.get(type, id);
      if (!original) {
        throw new NotFoundHttpError();
      }
      const accountId = original[accountKey] as string;
      await this.checkAccount(type, accountId, false);
    }
    return this.storage.delete(type, id);
  }

  public async* entries<TType extends StringKey<T>>(type: TType): AsyncIterableIterator<TypeObject<T[TType]>> {
    for await (const entry of this.storage.entries(type)) {
      yield this.cleanOutput(entry);
    }
  }

  /**
   * Creates a timer that removes the account with the given ID if
   * it doesn't have a login method when the timer runs out.
   */
  protected createAccountTimeout(id: string): void {
    // eslint-disable-next-line @typescript-eslint/no-misused-promises
    const timer = setTimeout(async(): Promise<void> => {
      const account = await this.storage.get(ACCOUNT_TYPE, id);
      if (account && account[LOGIN_COUNT] === 0) {
        this.logger.debug(`Removing account with no login methods ${id}`);
        await this.storage.delete(ACCOUNT_TYPE, id);
      }
    }, this.expiration);
    timer.unref();
  }

  /**
   * Makes sure of the operation, adding or removing an object of the given type,
   * is allowed, based on the current amount of login methods on the given account.
   */
  protected async checkAccount(type: string, accountId: string, add: boolean): Promise<void> {
    const account = await this.storage.get(ACCOUNT_TYPE, accountId);
    if (!account) {
      throw new NotFoundHttpError();
    }

    if (this.loginTypes.includes(type)) {
      if (!add && account[LOGIN_COUNT] === 1) {
        this.logger.warn(`Trying to remove last login method from account ${accountId}`);
        throw new BadRequestHttpError('An account needs at least 1 login method.');
      }
      (account as TypeObject<typeof MINIMUM_ACCOUNT_DESCRIPTION>)[LOGIN_COUNT] += add ? 1 : -1;
      await this.storage.set(ACCOUNT_TYPE, account);
    } else if (account[LOGIN_COUNT] === 0) {
      this.logger.warn(`Trying to update account ${accountId} without login methods`);
      throw new BadRequestHttpError('An account needs at least 1 login method.');
    }
  }

  /**
   * Removes the field that keeps track of the login counts, to hide this from the output.
   */
  protected cleanOutput<TVal extends Record<string, unknown> | undefined>(this: void, value: TVal): TVal {
    if (value) {
      delete value[LOGIN_COUNT];
    }
    return value;
  }
}

/**
 * Used to generate and store cookies.
 */
export interface CookieStore {
  /**
   * Generates and stores a new cookie for the given accountId.
   * This does not replace previously generated cookies.
   *
   * @param accountId - Account to create a cookie for.
   *
   * @returns The generated cookie.
   */
  generate: (accountId: string) => Promise<string>;

  /**
   * Return the accountID associated with the given cookie.
   *
   * @param cookie - Cookie to find the account for.
   */
  get: (cookie: string) => Promise<string | undefined>;

  /**
   * Refreshes the cookie expiration and returns when it will expire if the cookie exists.
   *
   * @param cookie - Cookie to refresh.
   */
  refresh: (cookie: string) => Promise<Date | undefined>;

  /**
   * Deletes the given cookie.
   *
   * @param cookie - Cookie to delete.
   */
  delete: (cookie: string) => Promise<boolean>;
}

import { Initializer } from '../../../../init/Initializer';
import { getLoggerFor } from '../../../../logging/LogUtil';
import type {
  CreateTypeObject,
  StringKey,
  TypeObject,
} from '../../../../storage/keyvalue/IndexedStorage';
import { createErrorMessage } from '../../../../util/errors/ErrorUtil';
import { InternalServerError } from '../../../../util/errors/InternalServerError';
import type { AccountStore, MinimalAccountSettings } from './AccountStore';
import type { AccountLoginStorage } from './LoginStorage';
import { ACCOUNT_TYPE } from './LoginStorage';

/**
 * A {@link AccountStore} that uses an {@link AccountLoginStorage} to keep track of the accounts.
 * Needs to be initialized before it can be used.
 */
export class GenericAccountStore<TDesc extends MinimalAccountSettings>
  extends Initializer implements AccountStore<TDesc> {
  protected readonly logger = getLoggerFor(this);

  protected readonly description: TDesc;
  protected readonly storage: AccountLoginStorage<{ [ACCOUNT_TYPE]: TDesc }>;
  protected initialized = false;

  // Wrong typings to prevent Components.js typing issues
  public constructor(storage: AccountLoginStorage<Record<string, never>>, description: TDesc) {
    super();
    this.description = description;
    this.storage = storage as unknown as typeof this.storage;
  }

  // Initialize the type definitions
  public async handle(): Promise<void> {
    if (this.initialized) {
      return;
    }
    try {
      await this.storage.defineType(ACCOUNT_TYPE, this.description, false);
      this.initialized = true;
    } catch (cause: unknown) {
      throw new InternalServerError(`Error defining account in storage: ${createErrorMessage(cause)}`, { cause });
    }
  }

  public async create(): Promise<string> {
    // {} is valid as only optional fields are allowed in the description
    const { id } = await this.storage.create(ACCOUNT_TYPE, {} as CreateTypeObject<TDesc>);
    this.logger.debug(`Created new account ${id}`);

    return id;
  }

  public async getSetting<TKey extends keyof TDesc>(id: string, setting: TKey):
  Promise<TypeObject<TDesc>[TKey] | undefined> {
    const account = await this.storage.get(ACCOUNT_TYPE, id);
    if (!account) {
      return;
    }
    return account[setting];
  }

  public async updateSetting<TKey extends StringKey<TDesc>>(id: string, setting: TKey, value: TypeObject<TDesc>[TKey]):
  Promise<void> {
    await this.storage.setField(ACCOUNT_TYPE, id, setting, value);
  }
}

import type {
  IndexedStorage,
  IndexTypeCollection,
  StringKey,
  ValueTypeDescription,
} from '../../../../storage/keyvalue/IndexedStorage';

export const ACCOUNT_TYPE = 'account';

/**
 * A {@link IndexedStorage} where the `defineType` function
 * takes an extra parameter to indicate if the type corresponds to a login method.
 * This is useful for storages that want to add extra requirements based on the data being edited.
 *
 * In practice, we use this because we want to require accounts to have at least 1 login method.
 */
export interface LoginStorage<T extends IndexTypeCollection<T>> extends Omit<IndexedStorage<T>, 'defineType'> {
  /**
   * Defines a type in the storage, just like in an {@link IndexedStorage},
   * but additionally it needs to be indicated if the type corresponds to a login method or not.
   *
   * @param type - Type to define.
   * @param description - Description of the type.
   * @param isLogin - Whether this type corresponds to a login method or not.
   */
  defineType: <TType extends StringKey<T>>(type: TType, description: T[TType], isLogin: boolean) => Promise<void>;
}

/**
 * A {@link LoginStorage} with specific typings to ensure other types can reference account IDs
 * without actually needing to specify it explicitly in their storage type.
 */
export type AccountLoginStorage<T extends
Record<string, Record<string, ValueTypeDescription<keyof T | typeof ACCOUNT_TYPE>>>> =
  LoginStorage<T & { [ACCOUNT_TYPE]: unknown }>;

import type { Adapter, AdapterPayload } from '../../../../templates/types/oidc-provider';
import { getLoggerFor } from '../../../logging/LogUtil';
import type { AdapterFactory } from '../../storage/AdapterFactory';
import { PassthroughAdapter, PassthroughAdapterFactory } from '../../storage/PassthroughAdapterFactory';
import type { WebIdStore } from '../webid/util/WebIdStore';
import type { ClientCredentialsStore } from './util/ClientCredentialsStore';

/**
 * A {@link PassthroughAdapter} that overrides the `find` function
 * by checking if there are stored client credentials for the given ID
 * if no payload is found in the source.
 */
export class ClientCredentialsAdapter extends PassthroughAdapter {
  protected readonly logger = getLoggerFor(this);

  private readonly webIdStore: WebIdStore;
  private readonly clientCredentialsStore: ClientCredentialsStore;

  public constructor(
    name: string,
    source: Adapter,
    webIdStore: WebIdStore,
    clientCredentialsStore: ClientCredentialsStore,
  ) {
    super(name, source);
    this.webIdStore = webIdStore;
    this.clientCredentialsStore = clientCredentialsStore;
  }

  public async find(label: string): Promise<AdapterPayload | void | undefined> {
    let payload = await this.source.find(label);

    if (!payload && this.name === 'Client') {
      const credentials = await this.clientCredentialsStore.findByLabel(label);
      if (!credentials) {
        return payload;
      }

      // Make sure the WebID wasn't unlinked in the meantime
      const valid = await this.webIdStore.isLinked(credentials.webId, credentials.accountId);
      if (!valid) {
        this.logger.error(
          `Client credentials token ${label} contains WebID that is no longer linked to the account. Removing...`,
        );
        await this.clientCredentialsStore.delete(credentials.id);
        return payload;
      }

      this.logger.debug(`Authenticating as ${credentials.webId} using client credentials`);

      /* eslint-disable @typescript-eslint/naming-convention */
      payload = {
        client_id: label,
        client_secret: credentials.secret,
        grant_types: [ 'client_credentials' ],
        redirect_uris: [],
        response_types: [],
      };
      /* eslint-enable @typescript-eslint/naming-convention */
    }
    return payload;
  }
}

export class ClientCredentialsAdapterFactory extends PassthroughAdapterFactory {
  private readonly webIdStore: WebIdStore;
  private readonly clientCredentialsStore: ClientCredentialsStore;

  public constructor(source: AdapterFactory, webIdStore: WebIdStore, clientCredentialsStore: ClientCredentialsStore) {
    super(source);
    this.webIdStore = webIdStore;
    this.clientCredentialsStore = clientCredentialsStore;
  }

  public createStorageAdapter(name: string): Adapter {
    const adapter = this.source.createStorageAdapter(name);
    return new ClientCredentialsAdapter(name, adapter, this.webIdStore, this.clientCredentialsStore);
  }
}

import { getLoggerFor } from '../../../logging/LogUtil';
import { parsePath, verifyAccountId } from '../account/util/AccountUtil';
import type { JsonRepresentation } from '../InteractionUtil';
import type { JsonInteractionHandlerInput } from '../JsonInteractionHandler';
import { JsonInteractionHandler } from '../JsonInteractionHandler';
import type { ClientCredentialsIdRoute } from './util/ClientCredentialsIdRoute';
import type { ClientCredentialsStore } from './util/ClientCredentialsStore';

type OutType = {
  id: string;
  webId: string;
};

/**
 * Provides a view on a client credentials token, indicating the token identifier and its associated WebID.
 */
export class ClientCredentialsDetailsHandler extends JsonInteractionHandler<OutType> {
  protected readonly logger = getLoggerFor(this);

  private readonly clientCredentialsStore: ClientCredentialsStore;
  private readonly clientCredentialsRoute: ClientCredentialsIdRoute;

  public constructor(clientCredentialsStore: ClientCredentialsStore, clientCredentialsRoute: ClientCredentialsIdRoute) {
    super();
    this.clientCredentialsStore = clientCredentialsStore;
    this.clientCredentialsRoute = clientCredentialsRoute;
  }

  public async handle({ target, accountId }: JsonInteractionHandlerInput): Promise<JsonRepresentation<OutType>> {
    const match = parsePath(this.clientCredentialsRoute, target.path);

    const credentials = await this.clientCredentialsStore.get(match.clientCredentialsId);
    verifyAccountId(accountId, credentials?.accountId);

    return { json: {
      id: credentials.label,
      webId: credentials.webId,
    }};
  }
}

import { v4 } from 'uuid';
import { object, string } from 'yup';
import { getLoggerFor } from '../../../logging/LogUtil';
import { BadRequestHttpError } from '../../../util/errors/BadRequestHttpError';
import { sanitizeUrlPart } from '../../../util/StringUtil';
import { assertAccountId } from '../account/util/AccountUtil';
import type { JsonRepresentation } from '../InteractionUtil';
import { JsonInteractionHandler } from '../JsonInteractionHandler';
import type { JsonInteractionHandlerInput } from '../JsonInteractionHandler';
import type { JsonView } from '../JsonView';
import type { WebIdStore } from '../webid/util/WebIdStore';
import { parseSchema, validateWithError } from '../YupUtil';
import type { ClientCredentialsIdRoute } from './util/ClientCredentialsIdRoute';
import type { ClientCredentialsStore } from './util/ClientCredentialsStore';

const inSchema = object({
  name: string().trim().optional(),
  webId: string().trim().required(),
});

type OutType = {
  id: string;
  secret: string;
  resource: string;
};

/**
 * Handles the creation of client credential tokens.
 */
export class CreateClientCredentialsHandler extends JsonInteractionHandler<OutType> implements JsonView {
  protected readonly logger = getLoggerFor(this);

  private readonly webIdStore: WebIdStore;
  private readonly clientCredentialsStore: ClientCredentialsStore;
  private readonly clientCredentialsRoute: ClientCredentialsIdRoute;

  public constructor(
    webIdStore: WebIdStore,
    clientCredentialsStore: ClientCredentialsStore,
    clientCredentialsRoute: ClientCredentialsIdRoute,
  ) {
    super();
    this.webIdStore = webIdStore;
    this.clientCredentialsStore = clientCredentialsStore;
    this.clientCredentialsRoute = clientCredentialsRoute;
  }

  public async getView({ accountId }: JsonInteractionHandlerInput): Promise<JsonRepresentation> {
    assertAccountId(accountId);
    const clientCredentials: Record<string, string> = {};
    for (const { id, label } of await this.clientCredentialsStore.findByAccount(accountId)) {
      clientCredentials[label] = this.clientCredentialsRoute.getPath({ accountId, clientCredentialsId: id });
    }
    return { json: { ...parseSchema(inSchema), clientCredentials }};
  }

  public async handle({ accountId, json }: JsonInteractionHandlerInput): Promise<JsonRepresentation<OutType>> {
    assertAccountId(accountId);

    const { name, webId } = await validateWithError(inSchema, json);

    if (!await this.webIdStore.isLinked(webId, accountId)) {
      this.logger.warn(`Trying to create token for ${webId} which does not belong to account ${accountId}`);
      throw new BadRequestHttpError('WebID does not belong to this account.');
    }

    const cleanedName = name ? sanitizeUrlPart(name.trim()) : '';
    const label = `${cleanedName}_${v4()}`;

    const { secret, id } = await this.clientCredentialsStore.create(label, webId, accountId);
    const resource = this.clientCredentialsRoute.getPath({ accountId, clientCredentialsId: id });

    // Exposing the field as `id` as that is how we originally defined the client credentials API
    // and is more consistent with how the field names are explained in other places
    return { json: { id: label, secret, resource }};
  }
}

import type { EmptyObject } from '../../../util/map/MapUtil';
import { parsePath, verifyAccountId } from '../account/util/AccountUtil';
import type { JsonRepresentation } from '../InteractionUtil';
import type { JsonInteractionHandlerInput } from '../JsonInteractionHandler';
import { JsonInteractionHandler } from '../JsonInteractionHandler';
import type { ClientCredentialsIdRoute } from './util/ClientCredentialsIdRoute';
import type { ClientCredentialsStore } from './util/ClientCredentialsStore';

/**
 * Handles the deletion of client credentials tokens.
 */
export class DeleteClientCredentialsHandler extends JsonInteractionHandler<EmptyObject> {
  private readonly clientCredentialsStore: ClientCredentialsStore;
  private readonly clientCredentialsRoute: ClientCredentialsIdRoute;

  public constructor(clientCredentialsStore: ClientCredentialsStore, clientCredentialsRoute: ClientCredentialsIdRoute) {
    super();
    this.clientCredentialsStore = clientCredentialsStore;
    this.clientCredentialsRoute = clientCredentialsRoute;
  }

  public async handle({ target, accountId }: JsonInteractionHandlerInput): Promise<JsonRepresentation<EmptyObject>> {
    const match = parsePath(this.clientCredentialsRoute, target.path);

    const credentials = await this.clientCredentialsStore.get(match.clientCredentialsId);
    verifyAccountId(accountId, credentials?.accountId);

    await this.clientCredentialsStore.delete(match.clientCredentialsId);

    return { json: {}};
  }
}

import { randomBytes } from 'node:crypto';
import { Initializer } from '../../../../init/Initializer';
import { getLoggerFor } from '../../../../logging/LogUtil';
import { createErrorMessage } from '../../../../util/errors/ErrorUtil';
import { InternalServerError } from '../../../../util/errors/InternalServerError';
import { ACCOUNT_TYPE } from '../../account/util/LoginStorage';
import type { AccountLoginStorage } from '../../account/util/LoginStorage';
import type { ClientCredentials, ClientCredentialsStore } from './ClientCredentialsStore';

export const CLIENT_CREDENTIALS_STORAGE_TYPE = 'clientCredentials';
export const CLIENT_CREDENTIALS_STORAGE_DESCRIPTION = {
  label: 'string',
  accountId: `id:${ACCOUNT_TYPE}`,
  secret: 'string',
  webId: 'string',
} as const;

/**
 * A {@link ClientCredentialsStore} that uses a {@link AccountLoginStorage} for storing the tokens.
 * Needs to be initialized before it can be used.
 */
export class BaseClientCredentialsStore extends Initializer implements ClientCredentialsStore {
  private readonly logger = getLoggerFor(this);

  private readonly storage: AccountLoginStorage<{ [CLIENT_CREDENTIALS_STORAGE_TYPE]:
      typeof CLIENT_CREDENTIALS_STORAGE_DESCRIPTION; }>;

  private initialized = false;

  // Wrong typings to prevent Components.js typing issues
  public constructor(storage: AccountLoginStorage<Record<string, never>>) {
    super();
    this.storage = storage as unknown as typeof this.storage;
  }

  // Initialize the type definitions
  public async handle(): Promise<void> {
    if (this.initialized) {
      return;
    }
    try {
      await this.storage.defineType(CLIENT_CREDENTIALS_STORAGE_TYPE, CLIENT_CREDENTIALS_STORAGE_DESCRIPTION, false);
      await this.storage.createIndex(CLIENT_CREDENTIALS_STORAGE_TYPE, 'accountId');
      await this.storage.createIndex(CLIENT_CREDENTIALS_STORAGE_TYPE, 'label');
      this.initialized = true;
    } catch (cause: unknown) {
      throw new InternalServerError(
        `Error defining client credentials in storage: ${createErrorMessage(cause)}`,
        { cause },
      );
    }
  }

  public async get(id: string): Promise<ClientCredentials | undefined> {
    return this.storage.get(CLIENT_CREDENTIALS_STORAGE_TYPE, id);
  }

  public async findByLabel(label: string): Promise<ClientCredentials | undefined> {
    const result = await this.storage.find(CLIENT_CREDENTIALS_STORAGE_TYPE, { label });
    if (result.length === 0) {
      return;
    }
    return result[0];
  }

  public async findByAccount(accountId: string): Promise<ClientCredentials[]> {
    return this.storage.find(CLIENT_CREDENTIALS_STORAGE_TYPE, { accountId });
  }

  public async create(label: string, webId: string, accountId: string): Promise<ClientCredentials> {
    const secret = randomBytes(64).toString('hex');

    this.logger.debug(
      `Creating client credentials token with label ${label} for WebID ${webId} and account ${accountId}`,
    );

    return this.storage.create(CLIENT_CREDENTIALS_STORAGE_TYPE, { accountId, label, webId, secret });
  }

  public async delete(id: string): Promise<void> {
    this.logger.debug(`Deleting client credentials token with ID ${id}`);
    return this.storage.delete(CLIENT_CREDENTIALS_STORAGE_TYPE, id);
  }
}

import type { AccountIdKey, AccountIdRoute } from '../../account/AccountIdRoute';
import { IdInteractionRoute } from '../../routing/IdInteractionRoute';
import type { ExtendedRoute } from '../../routing/InteractionRoute';

export type CredentialsIdKey = 'clientCredentialsId';

/**
 * An {@link AccountIdRoute} that also includes a credentials identifier.
 */
export type ClientCredentialsIdRoute = ExtendedRoute<AccountIdRoute, CredentialsIdKey>;

/**
 * Implementation of an {@link ClientCredentialsIdRoute}
 * that adds the identifier relative to a base {@link AccountIdRoute}.
 */
export class BaseClientCredentialsIdRoute extends IdInteractionRoute<AccountIdKey, CredentialsIdKey> {
  public constructor(base: AccountIdRoute) {
    super(base, 'clientCredentialsId');
  }
}

export interface ClientCredentials {
  id: string;
  label: string;
  webId: string;
  accountId: string;
  secret: string;
}

/**
 * Stores and creates {@link ClientCredentials}.
 */
export interface ClientCredentialsStore {
  /**
   * Find the {@link ClientCredentials} with the given ID.
   *
   * @param id - ID of the token.
   */
  get: (id: string) => Promise<ClientCredentials | undefined>;

  /**
   * Find the {@link ClientCredentials} with the given label.
   *
   * @param label - Label of the token.
   */
  findByLabel: (label: string) => Promise<ClientCredentials | undefined>;

  /**
   * Find all tokens created by the given account.
   *
   * @param accountId - ID of the account.
   */
  findByAccount: (accountId: string) => Promise<ClientCredentials[]>;

  /**
   * Creates new token.
   *
   * @param label - Identifier to use for the new token.
   * @param webId - WebID to identify as when using this token.
   * @param account - Account that is associated with this token.
   */
  create: (label: string, webId: string, accountId: string) => Promise<ClientCredentials>;

  /**
   * Deletes the token with the given ID.
   *
   * @param id - ID of the token.
   */
  delete: (id: string) => Promise<void>;
}

import type { Json } from '../../util/Json';
import { ACCOUNT_ID_KEY } from './account/AccountIdRoute';
import type { JsonRepresentation } from './InteractionUtil';
import type { JsonInteractionHandlerInput } from './JsonInteractionHandler';
import { JsonInteractionHandler } from './JsonInteractionHandler';
import type { InteractionRoute } from './routing/InteractionRoute';
import Dict = NodeJS.Dict;

/**
 * Creates an object with the keys matching those of the input `controls`,
 * and the values being the results received by the matching values in the same input.
 *
 * If `source` is defined, the controls will be added to the output of that handler after passing the input.
 * In case the control keys conflict with a key already present in the resulting object,
 * the results will be merged.
 */
export class ControlHandler extends JsonInteractionHandler {
  private readonly controls: Record<string, InteractionRoute | JsonInteractionHandler>;
  private readonly source?: JsonInteractionHandler;

  public constructor(
    controls: Record<string, InteractionRoute | JsonInteractionHandler>,
    source?: JsonInteractionHandler,
  ) {
    super();
    this.controls = controls;
    this.source = source;
  }

  public async canHandle(input: JsonInteractionHandlerInput): Promise<void> {
    await this.source?.canHandle(input);
  }

  public async handle(input: JsonInteractionHandlerInput): Promise<JsonRepresentation> {
    const result = await this.source?.handle(input);
    const controls = await this.generateControls(input);

    const json = this.mergeControls(result?.json, controls) as Dict<Json>;

    return {
      json,
      metadata: result?.metadata,
    };
  }

  protected isRoute(value: InteractionRoute | JsonInteractionHandler): value is InteractionRoute {
    return Boolean((value as InteractionRoute).getPath);
  }

  /**
   * Generate the controls for all the stored keys.
   */
  protected async generateControls(input: JsonInteractionHandlerInput): Promise<Dict<Json>> {
    let controls: Record<string, Json> = {};

    for (const [ key, value ] of Object.entries(this.controls)) {
      const controlSet = await this.generateControlSet(input, value);
      if (controlSet) {
        controls = this.mergeControls(controls, { [key]: controlSet }) as Record<string, Json>;
      }
    }

    return controls;
  }

  protected async generateControlSet(
    input: JsonInteractionHandlerInput,
    value: InteractionRoute | JsonInteractionHandler,
  ): Promise<Json | undefined> {
    if (this.isRoute(value)) {
      try {
        return value.getPath({ [ACCOUNT_ID_KEY]: input.accountId });
      } catch {
        // Path required an account ID which is missing
        return;
      }
    }
    const { json } = await value.handleSafe(input);
    if (Array.isArray(json) && json.length === 0) {
      return;
    }
    if (typeof json === 'object' && Object.keys(json).length === 0) {
      return;
    }
    return json;
  }

  /**
   * Merge the two objects.
   * Generally this will probably not be necessary, or be very simple merges,
   * but this ensures that we handle all possibilities.
   */
  protected mergeControls(original?: Json, controls?: Json): Json {
    if (typeof original === 'undefined') {
      return controls!;
    }

    if (typeof controls === 'undefined') {
      return original;
    }

    if (typeof original !== 'object' || typeof controls !== 'object') {
      return original;
    }

    if (Array.isArray(original)) {
      if (Array.isArray(controls)) {
        return [ ...original, ...controls ];
      }
      return original;
    }

    if (Array.isArray(controls)) {
      return original;
    }

    const result: Record<string, Json> = {};
    for (const key of new Set([ ...Object.keys(original), ...Object.keys(controls) ])) {
      result[key] = this.mergeControls(original[key], controls[key]);
    }
    return result;
  }
}

import { RepresentationMetadata } from '../../http/representation/RepresentationMetadata';
import { SOLID_HTTP } from '../../util/Vocabularies';
import { ACCOUNT_SETTINGS_REMEMBER_LOGIN } from './account/util/AccountStore';
import type { AccountStore } from './account/util/AccountStore';
import type { CookieStore } from './account/util/CookieStore';
import type { JsonRepresentation } from './InteractionUtil';
import type { JsonInteractionHandlerInput } from './JsonInteractionHandler';
import { JsonInteractionHandler } from './JsonInteractionHandler';

/**
 * Handles all the necessary steps for having cookies.
 * Refreshes the cookie expiration if there was a successful account interaction.
 * Adds the cookie and cookie expiration data to the output metadata,
 * unless it is already present in that metadata.
 * Checks the account settings to see if the cookie needs to be remembered.
 */
export class CookieInteractionHandler extends JsonInteractionHandler {
  private readonly source: JsonInteractionHandler;
  private readonly accountStore: AccountStore;
  private readonly cookieStore: CookieStore;

  public constructor(source: JsonInteractionHandler, accountStore: AccountStore, cookieStore: CookieStore) {
    super();
    this.source = source;
    this.accountStore = accountStore;
    this.cookieStore = cookieStore;
  }

  public async canHandle(input: JsonInteractionHandlerInput): Promise<void> {
    return this.source.canHandle(input);
  }

  public async handle(input: JsonInteractionHandlerInput): Promise<JsonRepresentation> {
    const output = await this.source.handle(input);

    let { metadata: outputMetadata } = output;

    // The cookie could be new, in the output, or the one received in the input if no new cookie is made
    const cookie = outputMetadata?.get(SOLID_HTTP.terms.accountCookie)?.value ??
      input.metadata.get(SOLID_HTTP.terms.accountCookie)?.value;
    // Only update the expiration if it wasn't set by the source handler,
    // as that might have a specific reason, such as logging out.
    if (!cookie || outputMetadata?.has(SOLID_HTTP.terms.accountCookieExpiration)) {
      return output;
    }
    // Not reusing the account ID from the input,
    // as that could potentially belong to a different account if this is a new login action.
    const accountId = await this.cookieStore.get(cookie);

    // Only refresh the cookie if it points to an account that exists and wants to be remembered
    if (!accountId) {
      return output;
    }
    const setting = await this.accountStore.getSetting(accountId, ACCOUNT_SETTINGS_REMEMBER_LOGIN);
    if (!setting) {
      return output;
    }

    // Refresh the cookie, could be undefined if it was deleted by the operation
    const expiration = await this.cookieStore.refresh(cookie);
    if (expiration) {
      outputMetadata = outputMetadata ?? new RepresentationMetadata(input.target);
      outputMetadata.set(SOLID_HTTP.terms.accountCookie, cookie);
      outputMetadata.set(SOLID_HTTP.terms.accountCookieExpiration, expiration.toISOString());
      output.metadata = outputMetadata;
    }

    return output;
  }
}

import { BasicRepresentation } from '../../http/representation/BasicRepresentation';
import type { Representation } from '../../http/representation/Representation';
import { cleanPreferences, getTypeWeight } from '../../storage/conversion/ConversionUtil';
import { APPLICATION_JSON, TEXT_HTML } from '../../util/ContentTypes';
import { MethodNotAllowedHttpError } from '../../util/errors/MethodNotAllowedHttpError';
import { NotFoundHttpError } from '../../util/errors/NotFoundHttpError';
import { NotImplementedHttpError } from '../../util/errors/NotImplementedHttpError';
import type { TemplateEngine } from '../../util/templates/TemplateEngine';
import type { InteractionHandlerInput } from './InteractionHandler';
import { InteractionHandler } from './InteractionHandler';
import type { InteractionRoute } from './routing/InteractionRoute';

/**
 * Used to link file paths and URLs together.
 * The reason we use a separate object instead of a key/value Record,
 * is that this makes it easier to override the values in Components.js,
 * which can be useful if someone wants to replace the HTML for certain URLs.
 */
export class HtmlViewEntry {
  public constructor(
    public readonly route: InteractionRoute,
    public readonly filePath: string,
  ) {}
}

/**
 * Stores the HTML templates associated with specific InteractionRoutes.
 *
 * This class will only handle GET operations for which there is a matching template,
 * if HTML is more preferred than JSON.
 * The reason for doing it like this instead of a standard content negotiation flow,
 * is because we only want to return the HTML pages on GET requests.
 *
 * Templates will receive the parameter `idpIndex` in their context pointing to the root index URL of the IDP API
 * and an `authenticating` parameter indicating if this is an active OIDC interaction.
 */
export class HtmlViewHandler extends InteractionHandler {
  private readonly idpIndex: string;
  private readonly templateEngine: TemplateEngine;
  private readonly templates: HtmlViewEntry[];

  public constructor(index: InteractionRoute, templateEngine: TemplateEngine, templates: HtmlViewEntry[]) {
    super();
    this.idpIndex = index.getPath();
    this.templateEngine = templateEngine;
    this.templates = templates;
  }

  public async canHandle({ operation }: InteractionHandlerInput): Promise<void> {
    if (operation.method !== 'GET') {
      throw new MethodNotAllowedHttpError([ operation.method ]);
    }

    const preferences = cleanPreferences(operation.preferences.type);
    const htmlWeight = getTypeWeight(TEXT_HTML, preferences);
    const jsonWeight = getTypeWeight(APPLICATION_JSON, preferences);
    if (jsonWeight >= htmlWeight) {
      throw new NotImplementedHttpError('HTML views are only returned when they are preferred.');
    }

    // Will throw error if no match is found
    this.findTemplate(operation.target.path);
  }

  public async handle({ operation, oidcInteraction }: InteractionHandlerInput): Promise<Representation> {
    const template = this.findTemplate(operation.target.path);
    const contents = { idpIndex: this.idpIndex, authenticating: Boolean(oidcInteraction) };
    const result = await this.templateEngine.handleSafe({ contents, template: { templateFile: template }});
    return new BasicRepresentation(result, operation.target, TEXT_HTML);
  }

  /**
   * Finds the template for the given URL.
   */
  private findTemplate(target: string): string {
    for (const template of this.templates) {
      if (template.route.matchPath(target)) {
        return template.filePath;
      }
    }
    throw new NotFoundHttpError();
  }
}

import type { KoaContextWithOIDC } from '../../../templates/types/oidc-provider';
import type { Operation } from '../../http/Operation';
import type { Representation } from '../../http/representation/Representation';
import { AsyncHandler } from '../../util/handlers/AsyncHandler';

// OIDC library does not directly export the Interaction type
export type Interaction = NonNullable<KoaContextWithOIDC['oidc']['entities']['Interaction']>;

export interface InteractionHandlerInput {
  /**
   * The operation to execute.
   */
  operation: Operation;
  /**
   * Will be defined if the OIDC library expects us to resolve an interaction it can't handle itself,
   * such as logging a user in.
   */
  oidcInteraction?: Interaction;
  /**
   * The account id of the agent doing the request if one could be found.
   */
  accountId?: string;
}

/**
 * Handler used for IDP interactions.
 */
export abstract class InteractionHandler extends AsyncHandler<InteractionHandlerInput, Representation> {}

import type { InteractionResults } from '../../../templates/types/oidc-provider';
import type Provider from '../../../templates/types/oidc-provider';
import type { RepresentationMetadata } from '../../http/representation/RepresentationMetadata';
import { getLoggerFor } from '../../logging/LogUtil';
import { BadRequestHttpError } from '../../util/errors/BadRequestHttpError';
import type { Json } from '../../util/Json';
import type { Interaction } from './InteractionHandler';
import Dict = NodeJS.Dict;

const logger = getLoggerFor('AccountUtil');

/**
 * Contains a JSON object and any associated metadata.
 * Similar to a {@link Representation} but with all the data in memory instead of as a stream
 * and specific to JSON.
 */
export interface JsonRepresentation<T extends Dict<Json> = Dict<Json>> {
  json: T;
  metadata?: RepresentationMetadata;
}

/**
 * Asserts `oidcInteraction` is defined, throws the correct error in case this is not the case.
 * The error contains the relevant error code that can be used to explain more extensively what the issue is
 * and why an OIDC interaction is needed.
 *
 * @param oidcInteraction - Interaction object to check.
 */
export function assertOidcInteraction(oidcInteraction?: Interaction): asserts oidcInteraction is Interaction {
  if (!oidcInteraction) {
    logger.warn(`Trying to perform OIDC operation without being in an OIDC authentication flow`);
    throw new BadRequestHttpError(
      'This action can only be performed as part of an OIDC authentication flow.',
      { errorCode: 'E0002' },
    );
  }
}

/**
 * The prompt that is used to track the account ID of a user during an OIDC interaction.
 * The already existing `login` prompt in the {@link InteractionResults}
 * is used to track the WebID that is chosen in an OIDC interaction.
 */
export const ACCOUNT_PROMPT = 'account';
/**
 * {@link InteractionResults} extended with our custom key for tracking a user's account ID.
 */
export type AccountInteractionResults = { [ACCOUNT_PROMPT]?: string } & InteractionResults;

/**
 * Updates the `oidcInteraction` object with the necessary data in case a prompt gets updated.
 *
 * @param oidcInteraction - Interaction to update.
 * @param result - New data to add to the interaction.
 * @param mergeWithLastSubmission - If this new data needs to be merged with already existing data in the interaction.
 */
export async function finishInteraction(
  oidcInteraction: Interaction,
  result: AccountInteractionResults,
  mergeWithLastSubmission: boolean,
): Promise<string> {
  if (mergeWithLastSubmission) {
    result = { ...oidcInteraction.lastSubmission, ...result };
  }

  oidcInteraction.result = result;
  await oidcInteraction.persist();

  return oidcInteraction.returnTo;
}

/**
 * Removes the WebID, the `accountId`, from the OIDC session object,
 * allowing us to replace it with a new value.
 * If there is no session in the Interaction, nothing will happen.
 *
 * @param provider - The OIDC provider.
 * @param oidcInteraction - The current interaction.
 */
export async function forgetWebId(provider: Provider, oidcInteraction: Interaction): Promise<void> {
  if (oidcInteraction.session) {
    const session = (await provider.Session.find(oidcInteraction.session.cookie))!;
    logger.debug(`Forgetting WebID ${session.accountId} in active session`);
    delete session.accountId;
    await session.persist();
  }

  // If a client previously successfully completed an interaction, a grant will have been created.
  // If such a session is reused to authenticate with a different WebID, we need to
  // first delete the previously created grant, as the oidc-provider will try to reuse it as well.
  if (oidcInteraction.grantId) {
    const grant = await provider.Grant.find(oidcInteraction.grantId);
    await grant?.destroy();
  }
}

import { BasicRepresentation } from '../../http/representation/BasicRepresentation';
import type { Representation } from '../../http/representation/Representation';
import { RepresentationMetadata } from '../../http/representation/RepresentationMetadata';
import type { RepresentationConverter } from '../../storage/conversion/RepresentationConverter';
import { APPLICATION_JSON } from '../../util/ContentTypes';
import type { Json } from '../../util/Json';
import { readJsonStream } from '../../util/StreamUtil';
import type { InteractionHandlerInput } from './InteractionHandler';
import { InteractionHandler } from './InteractionHandler';
import type { JsonInteractionHandler, JsonInteractionHandlerInput } from './JsonInteractionHandler';

/**
 * An {@link InteractionHandler} that sits in-between
 * an {@link InteractionHandler} and a {@link JsonInteractionHandler}.
 * It converts the input data stream into a JSON object to be used by the stored handler.
 *
 * Since the JSON body is only made during the `handle` call, it can not be used during the `canHandle`,
 * so the `canHandle` call of the stored handler is not called,
 * meaning this class accepts all input that can be converted to JSON.
 */
export class JsonConversionHandler extends InteractionHandler {
  private readonly source: JsonInteractionHandler;
  private readonly converter: RepresentationConverter;

  public constructor(source: JsonInteractionHandler, converter: RepresentationConverter) {
    super();
    this.source = source;
    this.converter = converter;
  }

  public async canHandle({ operation }: InteractionHandlerInput): Promise<void> {
    if (!operation.body.isEmpty) {
      await this.converter.canHandle({
        identifier: operation.target,
        preferences: { type: { [APPLICATION_JSON]: 1 }},
        representation: operation.body,
      });
    }
  }

  public async handle({ operation, oidcInteraction, accountId }: InteractionHandlerInput): Promise<Representation> {
    let json: Json = {};
    let jsonMetadata = operation.body.metadata;

    // Convert to JSON and read out if there is a body
    if (!operation.body.isEmpty) {
      const converted = await this.converter.handle({
        identifier: operation.target,
        preferences: { type: { [APPLICATION_JSON]: 1 }},
        representation: operation.body,
      });
      json = await readJsonStream(converted.data);
      jsonMetadata = converted.metadata;
    }

    // Input for the handler
    const input: JsonInteractionHandlerInput = {
      method: operation.method,
      target: operation.target,
      metadata: jsonMetadata,
      json,
      oidcInteraction,
      accountId,
    };

    const result = await this.source.handleSafe(input);

    // Convert the response JSON back to a Representation
    const responseMetadata = result.metadata ?? new RepresentationMetadata(operation.target);
    return new BasicRepresentation(JSON.stringify(result.json), responseMetadata, APPLICATION_JSON);
  }
}

import type { RepresentationMetadata } from '../../http/representation/RepresentationMetadata';
import type { ResourceIdentifier } from '../../http/representation/ResourceIdentifier';
import { AsyncHandler } from '../../util/handlers/AsyncHandler';
import type { Json } from '../../util/Json';
import type { Interaction } from './InteractionHandler';
import type { JsonRepresentation } from './InteractionUtil';
import Dict = NodeJS.Dict;

export interface JsonInteractionHandlerInput {
  /**
   * The operation to execute.
   */
  method: string;
  /**
   * The resource that is being targeted.
   */
  target: ResourceIdentifier;
  /**
   * The JSON body of the request.
   */
  json: unknown;
  /**
   * The metadata of the request.
   */
  metadata: RepresentationMetadata;
  /**
   * Will be defined if the OIDC library expects us to resolve an interaction it can't handle itself,
   * such as logging a user in.
   */
  oidcInteraction?: Interaction;
  /**
   * The account id of the agent doing the request if one could be found.
   */
  accountId?: string;
}

/**
 * A handler that consumes and returns a JSON object,
 * designed to be used for IDP/OIDC interactions.
 */
export abstract class JsonInteractionHandler<TOut extends Dict<Json> = Dict<Json>>
  extends AsyncHandler<JsonInteractionHandlerInput, JsonRepresentation<TOut>> {}

import type { JsonRepresentation } from './InteractionUtil';
import type { JsonInteractionHandlerInput } from './JsonInteractionHandler';

/**
 * An interface that can be used by classes that can provide a view besides doing an action.
 * Designed to be used by a {@link JsonInteractionHandler} that has a view explaining what JSON input it supports.
 */
export interface JsonView {
  getView: (input: JsonInteractionHandlerInput) => Promise<JsonRepresentation>;
}

import { RepresentationMetadata } from '../../http/representation/RepresentationMetadata';
import { getLoggerFor } from '../../logging/LogUtil';
import { RedirectHttpError } from '../../util/errors/RedirectHttpError';
import { SOLID_HTTP } from '../../util/Vocabularies';
import type { JsonRepresentation } from './InteractionUtil';
import type { JsonInteractionHandlerInput } from './JsonInteractionHandler';
import { JsonInteractionHandler } from './JsonInteractionHandler';

/**
 * Transforms an HTTP redirect into a hypermedia document with a redirection link,
 * such that scripts running in a browser can redirect the user to the next page.
 *
 * This handler addresses the situation where:
 * - the user visits a first page
 * - this first page contains a script that performs interactions with a JSON API
 * - as a result of a certain interaction, the user needs to be redirected to a second page
 *
 * Regular HTTP redirects are performed via responses with 3xx status codes.
 * However, since the consumer of the API in this case is a browser script,
 * a 3xx response would only reach that script and not move the page for the user.
 *
 * Therefore, this handler changes a 3xx response into a 200 response
 * with an explicit link to the next page,
 * enabling the script to move the user to the next page.
 */
export class LocationInteractionHandler extends JsonInteractionHandler {
  private readonly logger = getLoggerFor(this);

  private readonly source: JsonInteractionHandler;

  public constructor(source: JsonInteractionHandler) {
    super();
    this.source = source;
  }

  public async canHandle(input: JsonInteractionHandlerInput): Promise<void> {
    await this.source.canHandle(input);
  }

  public async handle(input: JsonInteractionHandlerInput): Promise<JsonRepresentation> {
    try {
      return await this.source.handle(input);
    } catch (error: unknown) {
      if (RedirectHttpError.isInstance(error)) {
        this.logger.debug(`Converting redirect error to location field in JSON body with location ${error.location}`);
        const metadata = new RepresentationMetadata(input.target);
        metadata.set(SOLID_HTTP.terms.location, error.location);
        return { json: { location: error.location }, metadata };
      }
      throw error;
    }
  }
}

import type { Representation } from '../../http/representation/Representation';
import type { ReadWriteLocker } from '../../util/locking/ReadWriteLocker';
import type { AccountIdRoute } from './account/AccountIdRoute';
import type { InteractionHandlerInput } from './InteractionHandler';
import { InteractionHandler } from './InteractionHandler';

const READ_METHODS = new Set([ 'OPTIONS', 'HEAD', 'GET' ]);

/**
 * An {@link InteractionHandler} that locks the path generated with the stored route during an operation.
 * If the route is the base account route, this can be used to prevent multiple operations on the same account.
 */
export class LockingInteractionHandler extends InteractionHandler {
  private readonly locker: ReadWriteLocker;
  private readonly accountRoute: AccountIdRoute;
  private readonly source: InteractionHandler;

  public constructor(locker: ReadWriteLocker, accountRoute: AccountIdRoute, source: InteractionHandler) {
    super();
    this.locker = locker;
    this.accountRoute = accountRoute;
    this.source = source;
  }

  public async canHandle(input: InteractionHandlerInput): Promise<void> {
    return this.source.canHandle(input);
  }

  public async handle(input: InteractionHandlerInput): Promise<Representation> {
    const { accountId, operation } = input;

    // No lock if there is no account
    if (!accountId) {
      return this.source.handle(input);
    }

    const identifier = { path: this.accountRoute.getPath({ accountId }) };
    if (READ_METHODS.has(operation.method)) {
      return this.locker.withReadLock(identifier, async(): Promise<Representation> => this.source.handle(input));
    }

    return this.locker.withWriteLock(identifier, async(): Promise<Representation> => this.source.handle(input));
  }
}

import { RepresentationMetadata } from '../../../http/representation/RepresentationMetadata';
import { BadRequestHttpError } from '../../../util/errors/BadRequestHttpError';
import type { EmptyObject } from '../../../util/map/MapUtil';
import { SOLID_HTTP } from '../../../util/Vocabularies';
import type { CookieStore } from '../account/util/CookieStore';
import type { JsonRepresentation } from '../InteractionUtil';
import type { JsonInteractionHandlerInput } from '../JsonInteractionHandler';
import { JsonInteractionHandler } from '../JsonInteractionHandler';

/**
 * Responsible for logging a user out.
 * In practice this means making sure the cookie is no longer valid.
 */
export class LogoutHandler extends JsonInteractionHandler<EmptyObject> {
  private readonly cookieStore: CookieStore;

  public constructor(cookieStore: CookieStore) {
    super();
    this.cookieStore = cookieStore;
  }

  public async handle(input: JsonInteractionHandlerInput): Promise<JsonRepresentation<EmptyObject>> {
    const { metadata, accountId, target } = input;
    const cookie = metadata.get(SOLID_HTTP.terms.accountCookie)?.value;
    if (cookie) {
      // Make sure the cookie belongs to the logged-in user.
      const foundId = await this.cookieStore.get(cookie);
      if (foundId !== accountId) {
        throw new BadRequestHttpError('Invalid cookie.');
      }

      await this.cookieStore.delete(cookie);

      // Setting the expiration time of a cookie to somewhere in the past causes browsers to delete that cookie
      const outputMetadata = new RepresentationMetadata(target);
      outputMetadata.set(SOLID_HTTP.terms.accountCookie, cookie);
      outputMetadata.set(SOLID_HTTP.terms.accountCookieExpiration, new Date(0).toISOString());
      return { json: {}, metadata: outputMetadata };
    }

    return { json: {}};
  }
}

import { RepresentationMetadata } from '../../../http/representation/RepresentationMetadata';
import { getLoggerFor } from '../../../logging/LogUtil';
import type { Json } from '../../../util/Json';
import { SOLID_HTTP } from '../../../util/Vocabularies';
import { ACCOUNT_SETTINGS_REMEMBER_LOGIN } from '../account/util/AccountStore';
import type { AccountStore } from '../account/util/AccountStore';
import type { CookieStore } from '../account/util/CookieStore';
import type { JsonRepresentation } from '../InteractionUtil';
import { finishInteraction } from '../InteractionUtil';
import type { JsonInteractionHandlerInput } from '../JsonInteractionHandler';
import { JsonInteractionHandler } from '../JsonInteractionHandler';

/**
 * Output type that is expected of handlers logging an account in.
 */
export type LoginOutputType = {
  /**
   * The ID of the account that logged in.
   */
  accountId: string;
  /**
   * If this account should be remembered or not.
   * Setting this to `undefined` will keep the setting as it currently is.
   */
  remember?: boolean;
};

/**
 * A handler that takes care of all the necessary steps when logging a user in,
 * such as generating a cookie and setting the necessary OIDC information.
 * Classes that resolve login methods should extend this class and implement the `login` method.
 */
export abstract class ResolveLoginHandler extends JsonInteractionHandler {
  protected readonly logger = getLoggerFor(this);

  protected readonly accountStore: AccountStore;
  protected readonly cookieStore: CookieStore;

  protected constructor(accountStore: AccountStore, cookieStore: CookieStore) {
    super();
    this.accountStore = accountStore;
    this.cookieStore = cookieStore;
  }

  public async handle(input: JsonInteractionHandlerInput): Promise<JsonRepresentation> {
    const result = await this.login(input);
    const { accountId, remember } = result.json;

    const json: Json = { ...result.json };

    // There is no need to output these fields in the response JSON
    delete json.accountId;
    delete json.remember;

    // The cookie that is used to identify that a user has logged in.
    // Putting it in the metadata, so it can be converted into an HTTP response header.
    // Putting it in the response JSON so users can also use it in an Authorization header.
    const metadata = result.metadata ?? new RepresentationMetadata(input.target);
    json.authorization = await this.cookieStore.generate(accountId);
    metadata.add(SOLID_HTTP.terms.accountCookie, json.authorization);

    // Delete the old cookie if there was one, to prevent unused cookies from being stored.
    // We are not reusing this cookie as it could be associated with a different account.
    const oldCookie = input.metadata.get(SOLID_HTTP.terms.accountCookie)?.value;
    if (oldCookie) {
      this.logger.debug(`Replacing old cookie ${oldCookie} with ${json.cookie as string}`);
      await this.cookieStore.delete(oldCookie);
    }

    // Update the account settings
    await this.updateRememberSetting(accountId, remember);

    // Not throwing redirect error otherwise the cookie metadata would be lost.
    // See {@link LocationInteractionHandler} why this field is added.
    if (input.oidcInteraction) {
      // Finish the interaction so the policies are checked again, where they will find the new cookie
      json.location = await finishInteraction(input.oidcInteraction, {}, true);
    }

    return { json, metadata };
  }

  /**
   * Updates the account setting that determines whether the login status needs to be remembered.
   *
   * @param accountId - ID of the account.
   * @param remember - If the account should be remembered or not. The setting will not be updated if this is undefined.
   */
  protected async updateRememberSetting(accountId: string, remember?: boolean): Promise<void> {
    if (typeof remember === 'boolean') {
      // Store the setting indicating if the user wants the cookie to persist
      await this.accountStore.updateSetting(accountId, ACCOUNT_SETTINGS_REMEMBER_LOGIN, remember);
      this.logger.debug(`Updating account remember setting to ${remember}`);
    }
  }

  /**
   * Takes the necessary steps to log a user in.
   *
   * @param input - Same input that was passed to the handle function.
   */
  public abstract login(input: JsonInteractionHandlerInput): Promise<JsonRepresentation<LoginOutputType>>;
}

import { FoundHttpError } from '../../../util/errors/FoundHttpError';
import { assertOidcInteraction, finishInteraction } from '../InteractionUtil';
import type { JsonRepresentation } from '../InteractionUtil';
import type { JsonInteractionHandlerInput } from '../JsonInteractionHandler';
import { JsonInteractionHandler } from '../JsonInteractionHandler';

/**
 * Cancel an active OIDC interaction.
 */
export class CancelOidcHandler extends JsonInteractionHandler<never> {
  public async handle({ oidcInteraction }: JsonInteractionHandlerInput): Promise<JsonRepresentation<never>> {
    assertOidcInteraction(oidcInteraction);
    const error = {
      error: 'access_denied',
      // eslint-disable-next-line @typescript-eslint/naming-convention
      error_description: 'User cancelled the interaction.',
    };

    const location = await finishInteraction(oidcInteraction, error, false);

    throw new FoundHttpError(location);
  }
}

import type { AllClientMetadata } from '../../../../templates/types/oidc-provider';
import type { ArrayElement } from '../../../util/map/MapUtil';
import type { ProviderFactory } from '../../configuration/ProviderFactory';
import type { JsonRepresentation } from '../InteractionUtil';
import { assertOidcInteraction } from '../InteractionUtil';
import type { JsonInteractionHandlerInput } from '../JsonInteractionHandler';
import { JsonInteractionHandler } from '../JsonInteractionHandler';

// Only extract specific fields to prevent leaking information
// Based on https://www.w3.org/ns/solid/oidc-context.jsonld
const CLIENT_KEYS = [
  'client_id',
  'client_uri',
  'logo_uri',
  'policy_uri',
  'client_name',
  'contacts',
  'grant_types',
  'scope',
] as const;

// Possible keys in client metadata
type KeyType = ArrayElement<typeof CLIENT_KEYS>;
// Possible values for client metadata
type ValType = AllClientMetadata[KeyType];
// Simplified to keep Components.js happy
type OutType = {
  client: Record<string, string | string[] | undefined>;
  webId?: string;
};

/**
 * Returns a JSON representation with metadata of the client that is requesting the OIDC interaction.
 */
export class ClientInfoHandler extends JsonInteractionHandler<OutType> {
  private readonly providerFactory: ProviderFactory;

  public constructor(providerFactory: ProviderFactory) {
    super();
    this.providerFactory = providerFactory;
  }

  public async handle({ oidcInteraction }: JsonInteractionHandlerInput): Promise<JsonRepresentation<OutType>> {
    assertOidcInteraction(oidcInteraction);
    const provider = await this.providerFactory.getProvider();
    const client = await provider.Client.find(oidcInteraction.params.client_id as string);
    const metadata: AllClientMetadata = client?.metadata() ?? {};

    const jsonLd = Object.fromEntries(
      CLIENT_KEYS.filter((key): boolean => key in metadata)
        .map((key): [ KeyType, ValType ] => [ key, metadata[key] ]),
      // eslint-disable-next-line @typescript-eslint/naming-convention
    ) as Record<KeyType, ValType> & { '@context': 'https://www.w3.org/ns/solid/oidc-context.jsonld' };
    jsonLd['@context'] = 'https://www.w3.org/ns/solid/oidc-context.jsonld';

    // Note: this is the `accountId` from the OIDC library, in which we store the WebID
    const webId = oidcInteraction?.session?.accountId;

    return { json: { client: jsonLd, webId }};
  }
}

import { boolean, object } from 'yup';
import type { InteractionResults, KoaContextWithOIDC, UnknownObject } from '../../../../templates/types/oidc-provider';
import { FoundHttpError } from '../../../util/errors/FoundHttpError';
import { NotImplementedHttpError } from '../../../util/errors/NotImplementedHttpError';
import type { ProviderFactory } from '../../configuration/ProviderFactory';
import type { Interaction } from '../InteractionHandler';
import { assertOidcInteraction, finishInteraction } from '../InteractionUtil';
import type { JsonInteractionHandlerInput } from '../JsonInteractionHandler';
import { JsonInteractionHandler } from '../JsonInteractionHandler';
import { validateWithError } from '../YupUtil';

type Grant = NonNullable<KoaContextWithOIDC['oidc']['entities']['Grant']>;

const inSchema = object({
  remember: boolean().default(false),
});

/**
 * Handles the OIDC consent prompts where the user confirms they want to log in for the given client.
 */
export class ConsentHandler extends JsonInteractionHandler<never> {
  private readonly providerFactory: ProviderFactory;

  public constructor(providerFactory: ProviderFactory) {
    super();
    this.providerFactory = providerFactory;
  }

  public async handle({ oidcInteraction, json }: JsonInteractionHandlerInput): Promise<never> {
    assertOidcInteraction(oidcInteraction);

    const { remember } = await validateWithError(inSchema, json);

    const grant = await this.getGrant(oidcInteraction);
    this.updateGrant(grant, oidcInteraction.prompt.details, remember);

    const location = await this.updateInteraction(oidcInteraction, grant);

    throw new FoundHttpError(location);
  }

  /**
   * Either returns the grant associated with the given interaction or creates a new one if it does not exist yet.
   */
  private async getGrant(oidcInteraction: Interaction): Promise<Grant> {
    if (!oidcInteraction.session) {
      throw new NotImplementedHttpError('Only interactions with a valid session are supported.');
    }

    const { params, session: { accountId }, grantId } = oidcInteraction;
    const provider = await this.providerFactory.getProvider();

    let grant: Grant;
    if (grantId) {
      grant = (await provider.Grant.find(grantId))!;
    } else {
      grant = new provider.Grant({
        accountId,
        clientId: params.client_id as string,
      });
    }
    return grant;
  }

  /**
   * Updates the grant with all the missing scopes and claims requested by the interaction.
   *
   * Will reject the `offline_access` scope if `remember` is false.
   */
  private updateGrant(grant: Grant, details: UnknownObject, remember: boolean): void {
    // Reject the offline_access scope if the user does not want to be remembered
    if (!remember) {
      grant.rejectOIDCScope('offline_access');
    }

    // Grant all the requested scopes and claims
    if (details.missingOIDCScope) {
      grant.addOIDCScope((details.missingOIDCScope as string[]).join(' '));
    }
    if (details.missingOIDCClaims) {
      grant.addOIDCClaims(details.missingOIDCClaims as string[]);
    }
    if (details.missingResourceScopes) {
      for (const [ indicator, scopes ] of Object.entries(details.missingResourceScopes as Record<string, string[]>)) {
        grant.addResourceScope(indicator, scopes.join(' '));
      }
    }
  }

  /**
   * Updates the interaction with the new grant and returns the resulting redirect URL.
   */
  private async updateInteraction(oidcInteraction: Interaction, grant: Grant): Promise<string> {
    const grantId = await grant.save();

    const consent: InteractionResults['consent'] = {};
    // Only need to update the grantId if it is new
    if (!oidcInteraction.grantId) {
      consent.grantId = grantId;
    }

    return finishInteraction(oidcInteraction, { consent }, true);
  }
}

import { FoundHttpError } from '../../../util/errors/FoundHttpError';
import type { ProviderFactory } from '../../configuration/ProviderFactory';
import { assertOidcInteraction, finishInteraction, forgetWebId } from '../InteractionUtil';
import type { JsonRepresentation } from '../InteractionUtil';
import type { JsonInteractionHandlerInput } from '../JsonInteractionHandler';
import { JsonInteractionHandler } from '../JsonInteractionHandler';

/**
 * Forgets the chosen WebID in an OIDC interaction,
 * causing the next policy trigger to be one where a new WebID has to be chosen.
 */
export class ForgetWebIdHandler extends JsonInteractionHandler<never> {
  private readonly providerFactory: ProviderFactory;

  public constructor(providerFactory: ProviderFactory) {
    super();
    this.providerFactory = providerFactory;
  }

  public async handle({ oidcInteraction }: JsonInteractionHandlerInput): Promise<JsonRepresentation<never>> {
    assertOidcInteraction(oidcInteraction);

    await forgetWebId(await this.providerFactory.getProvider(), oidcInteraction);

    // Finish the interaction so the policies get checked again
    const location = await finishInteraction(oidcInteraction, {}, false);

    throw new FoundHttpError(location);
  }
}

import { boolean, object, string } from 'yup';
import type { InteractionResults } from '../../../../templates/types/oidc-provider';
import { getLoggerFor } from '../../../logging/LogUtil';
import { BadRequestHttpError } from '../../../util/errors/BadRequestHttpError';
import { FoundHttpError } from '../../../util/errors/FoundHttpError';
import type { ProviderFactory } from '../../configuration/ProviderFactory';
import { assertAccountId } from '../account/util/AccountUtil';
import type { JsonRepresentation } from '../InteractionUtil';
import { assertOidcInteraction, finishInteraction, forgetWebId } from '../InteractionUtil';
import type { JsonInteractionHandlerInput } from '../JsonInteractionHandler';
import { JsonInteractionHandler } from '../JsonInteractionHandler';
import type { JsonView } from '../JsonView';
import type { WebIdStore } from '../webid/util/WebIdStore';
import { parseSchema, validateWithError } from '../YupUtil';

const inSchema = object({
  webId: string().trim().required(),
  remember: boolean().default(false),
});

/**
 * Allows users to choose which WebID they want to authenticate as during an OIDC interaction.
 *
 * One of the main reason picking a WebID is a separate class/request from consenting to the OIDC interaction,
 * is because the OIDC-provider will only give the information we need for consent
 * once we have added an accountId to the OIDC interaction, which we do in this class.
 * The library also really wants to use that accountId as the value that you use for generating the tokens,
 * meaning we can't just use another value there, so we need to assign the WebID to it,
 * unless we use a hacky workaround.
 */
export class PickWebIdHandler extends JsonInteractionHandler<never> implements JsonView {
  private readonly logger = getLoggerFor(this);

  private readonly webIdStore: WebIdStore;
  private readonly providerFactory: ProviderFactory;

  public constructor(webIdStore: WebIdStore, providerFactory: ProviderFactory) {
    super();
    this.webIdStore = webIdStore;
    this.providerFactory = providerFactory;
  }

  public async getView({ accountId }: JsonInteractionHandlerInput): Promise<JsonRepresentation> {
    assertAccountId(accountId);
    const description = parseSchema(inSchema);
    const webIds = (await this.webIdStore.findLinks(accountId)).map((link): string => link.webId);
    return { json: { ...description, webIds }};
  }

  public async handle({ oidcInteraction, accountId, json }: JsonInteractionHandlerInput): Promise<never> {
    assertOidcInteraction(oidcInteraction);
    assertAccountId(accountId);

    const { webId, remember } = await validateWithError(inSchema, json);
    if (!await this.webIdStore.isLinked(webId, accountId)) {
      this.logger.warn(`Trying to pick WebID ${webId} which does not belong to account ${accountId}`);
      throw new BadRequestHttpError('WebID does not belong to this account.');
    }

    // We need to explicitly forget the WebID from the session or the library won't allow us to update the value
    await forgetWebId(await this.providerFactory.getProvider(), oidcInteraction);

    // Update the interaction to get the redirect URL
    const login: InteractionResults['login'] = {
      // Note that `accountId` here is unrelated to our user accounts but is part of the OIDC library
      accountId: webId,
      remember,
    };

    const location = await finishInteraction(oidcInteraction, { login }, true);
    throw new FoundHttpError(location);
  }
}

import { getLoggerFor } from '../../../logging/LogUtil';
import { BadRequestHttpError } from '../../../util/errors/BadRequestHttpError';
import type { JsonRepresentation } from '../InteractionUtil';
import type { JsonInteractionHandlerInput } from '../JsonInteractionHandler';
import { JsonInteractionHandler } from '../JsonInteractionHandler';
import type { InteractionRoute } from '../routing/InteractionRoute';

type OutType = { location: string; prompt: string };

/**
 * Redirects requests based on the OIDC Interaction prompt.
 * Errors in case no match was found.
 *
 * The reason we use this intermediate handler
 * instead of letting the OIDC library redirect directly to the correct page,
 * is because that library creates a cookie with of scope of the target page.
 * By having the library always redirect to the index page,
 * the cookie is relevant for all pages and other pages can see if we are still in an interaction.
 */
export class PromptHandler extends JsonInteractionHandler<OutType> {
  private readonly logger = getLoggerFor(this);

  private readonly promptRoutes: Record<string, InteractionRoute>;

  public constructor(promptRoutes: Record<string, InteractionRoute>) {
    super();
    this.promptRoutes = promptRoutes;
  }

  public async handle({ oidcInteraction }: JsonInteractionHandlerInput): Promise<JsonRepresentation<OutType>> {
    const prompt = oidcInteraction?.prompt.name;
    if (prompt && this.promptRoutes[prompt]) {
      const location = this.promptRoutes[prompt].getPath();
      this.logger.debug(`Current prompt is ${prompt} with URL ${location}`);
      // Not throwing redirect error since we also want to the prompt to the output json.
      return { json: { location, prompt }};
    }
    this.logger.warn(`Received unsupported prompt ${prompt}`);
    throw new BadRequestHttpError(`Unsupported prompt: ${prompt}`);
  }
}

import type { Json } from '../../util/Json';
import { ControlHandler } from './ControlHandler';
import type { JsonInteractionHandlerInput } from './JsonInteractionHandler';

/**
 * A {@link ControlHandler} that only returns results if there is an active OIDC interaction.
 */
export class OidcControlHandler extends ControlHandler {
  protected async generateControls(input: JsonInteractionHandlerInput): Promise<NodeJS.Dict<Json>> {
    if (!input.oidcInteraction) {
      return {};
    }

    return super.generateControls(input);
  }
}

import { object, string } from 'yup';
import { getLoggerFor } from '../../../logging/LogUtil';
import { assertAccountId } from '../account/util/AccountUtil';
import type { JsonRepresentation } from '../InteractionUtil';
import { JsonInteractionHandler } from '../JsonInteractionHandler';
import type { JsonInteractionHandlerInput } from '../JsonInteractionHandler';
import type { JsonView } from '../JsonView';
import { parseSchema, validateWithError } from '../YupUtil';
import type { PasswordIdRoute } from './util/PasswordIdRoute';
import type { PasswordStore } from './util/PasswordStore';

type OutType = { resource: string };

const inSchema = object({
  email: string().trim().email().required(),
  password: string().trim().min(1).required(),
});

/**
 * Handles the creation of email/password login combinations for an account.
 */
export class CreatePasswordHandler extends JsonInteractionHandler<OutType> implements JsonView {
  protected readonly logger = getLoggerFor(this);

  private readonly passwordStore: PasswordStore;
  private readonly passwordRoute: PasswordIdRoute;

  public constructor(passwordStore: PasswordStore, passwordRoute: PasswordIdRoute) {
    super();
    this.passwordStore = passwordStore;
    this.passwordRoute = passwordRoute;
  }

  public async getView({ accountId }: JsonInteractionHandlerInput): Promise<JsonRepresentation> {
    assertAccountId(accountId);
    const passwordLogins: Record<string, string> = {};
    for (const { id, email } of await this.passwordStore.findByAccount(accountId)) {
      passwordLogins[email] = this.passwordRoute.getPath({ accountId, passwordId: id });
    }
    return { json: { ...parseSchema(inSchema), passwordLogins }};
  }

  public async handle({ accountId, json }: JsonInteractionHandlerInput): Promise<JsonRepresentation<OutType>> {
    // Email will be in lowercase
    const { email, password } = await validateWithError(inSchema, json);
    assertAccountId(accountId);

    const passwordId = await this.passwordStore.create(email, accountId, password);
    const resource = this.passwordRoute.getPath({ accountId, passwordId });

    // If we ever want to add email verification this would have to be checked separately
    await this.passwordStore.confirmVerification(passwordId);

    return { json: { resource }};
  }
}

import type { EmptyObject } from '../../../util/map/MapUtil';
import { parsePath, verifyAccountId } from '../account/util/AccountUtil';
import type { JsonRepresentation } from '../InteractionUtil';
import type { JsonInteractionHandlerInput } from '../JsonInteractionHandler';
import { JsonInteractionHandler } from '../JsonInteractionHandler';
import type { PasswordIdRoute } from './util/PasswordIdRoute';
import type { PasswordStore } from './util/PasswordStore';

/**
 * Handles the deletion of a password login method.
 */
export class DeletePasswordHandler extends JsonInteractionHandler<EmptyObject> {
  private readonly passwordStore: PasswordStore;
  private readonly passwordRoute: PasswordIdRoute;

  public constructor(passwordStore: PasswordStore, passwordRoute: PasswordIdRoute) {
    super();
    this.passwordStore = passwordStore;
    this.passwordRoute = passwordRoute;
  }

  public async handle({ target, accountId }: JsonInteractionHandlerInput): Promise<JsonRepresentation<EmptyObject>> {
    const match = parsePath(this.passwordRoute, target.path);

    const login = await this.passwordStore.get(match.passwordId);
    verifyAccountId(accountId, login?.accountId);

    await this.passwordStore.delete(match.passwordId);

    return { json: {}};
  }
}

import { object, string } from 'yup';
import { getLoggerFor } from '../../../logging/LogUtil';
import { createErrorMessage } from '../../../util/errors/ErrorUtil';
import type { TemplateEngine } from '../../../util/templates/TemplateEngine';
import type { JsonRepresentation } from '../InteractionUtil';
import type { JsonInteractionHandlerInput } from '../JsonInteractionHandler';
import { JsonInteractionHandler } from '../JsonInteractionHandler';
import type { JsonView } from '../JsonView';
import type { InteractionRoute } from '../routing/InteractionRoute';
import { parseSchema, validateWithError } from '../YupUtil';
import type { EmailSender } from './util/EmailSender';
import type { ForgotPasswordStore } from './util/ForgotPasswordStore';
import type { PasswordStore } from './util/PasswordStore';

const inSchema = object({
  email: string().trim().email().required(),
});

export interface ForgotPasswordHandlerArgs {
  /**
   * Store containing the password login information.
   */
  passwordStore: PasswordStore;
  /**
   * Store containing the forgot password records.
   */
  forgotPasswordStore: ForgotPasswordStore;
  /**
   * Template engine that will be used to generate the email body.
   */
  templateEngine: TemplateEngine<{ resetLink: string }>;
  /**
   * Sender to send the actual email.
   */
  emailSender: EmailSender;
  /**
   * Route used to generate the reset link for the user.
   */
  resetRoute: InteractionRoute;
}

type OutType = { email: string };

/**
 * Responsible for the case where a user forgot their password and asks for a reset.
 * Will send out the necessary mail if the email address is known.
 * The JSON response will always be the same to prevent leaking which email addresses are stored.
 */
export class ForgotPasswordHandler extends JsonInteractionHandler<OutType> implements JsonView {
  protected readonly logger = getLoggerFor(this);

  private readonly passwordStore: PasswordStore;
  private readonly forgotPasswordStore: ForgotPasswordStore;
  private readonly templateEngine: TemplateEngine<{ resetLink: string }>;
  private readonly emailSender: EmailSender;
  private readonly resetRoute: InteractionRoute;

  public constructor(args: ForgotPasswordHandlerArgs) {
    super();
    this.passwordStore = args.passwordStore;
    this.forgotPasswordStore = args.forgotPasswordStore;
    this.templateEngine = args.templateEngine;
    this.emailSender = args.emailSender;
    this.resetRoute = args.resetRoute;
  }

  public async getView(): Promise<JsonRepresentation> {
    return { json: parseSchema(inSchema) };
  }

  /**
   * Generates a record to reset the password for the given email address and then mails it.
   * In case there is no account, no error wil be thrown for privacy reasons.
   * Nothing will happen instead.
   */
  public async handle({ json }: JsonInteractionHandlerInput): Promise<JsonRepresentation<OutType>> {
    const { email } = await validateWithError(inSchema, json);

    const payload = await this.passwordStore.findByEmail(email);

    if (payload?.id) {
      try {
        const recordId = await this.forgotPasswordStore.generate(payload.id);
        await this.sendResetMail(recordId, email);
      } catch (error: unknown) {
        // This error can not be thrown for privacy reasons.
        // If there always is an error, because there is a problem with the mail server for example,
        // errors would only be thrown for registered accounts.
        // Although we do also leak this information when an account tries to register an email address,
        // so this might be removed in the future.
        this.logger.error(`Problem sending a recovery mail: ${createErrorMessage(error)}`);
      }
    } else {
      // Don't emit an error for privacy reasons
      this.logger.warn(`Password reset request for unknown email ${email}`);
    }

    return { json: { email }};
  }

  /**
   * Generates the link necessary for resetting the password and mails it to the given email address.
   */
  private async sendResetMail(recordId: string, email: string): Promise<void> {
    this.logger.info(`Sending password reset to ${email}`);
    const resetLink = `${this.resetRoute.getPath()}?rid=${encodeURIComponent(recordId)}`;
    const renderedEmail = await this.templateEngine.handleSafe({ contents: { resetLink }});
    await this.emailSender.handleSafe({
      recipient: email,
      subject: 'Reset your password',
      text: `To reset your password, go to this link: ${resetLink}`,
      html: renderedEmail,
    });
  }
}

import { boolean, object, string } from 'yup';
import { getLoggerFor } from '../../../logging/LogUtil';
import type { AccountStore } from '../account/util/AccountStore';
import type { CookieStore } from '../account/util/CookieStore';
import type { JsonRepresentation } from '../InteractionUtil';
import type { JsonInteractionHandlerInput } from '../JsonInteractionHandler';
import type { JsonView } from '../JsonView';
import type { LoginOutputType } from '../login/ResolveLoginHandler';
import { ResolveLoginHandler } from '../login/ResolveLoginHandler';
import { parseSchema, validateWithError } from '../YupUtil';
import type { PasswordStore } from './util/PasswordStore';

const inSchema = object({
  email: string().trim().email().required(),
  password: string().trim().required(),
  remember: boolean().default(false),
});

export interface PasswordLoginHandlerArgs {
  accountStore: AccountStore;
  passwordStore: PasswordStore;
  cookieStore: CookieStore;
}

/**
 * Handles the submission of the Login Form and logs the user in.
 */
export class PasswordLoginHandler extends ResolveLoginHandler implements JsonView {
  protected readonly logger = getLoggerFor(this);

  private readonly passwordStore: PasswordStore;

  public constructor(args: PasswordLoginHandlerArgs) {
    super(args.accountStore, args.cookieStore);
    this.passwordStore = args.passwordStore;
  }

  public async getView(): Promise<JsonRepresentation> {
    return { json: parseSchema(inSchema) };
  }

  public async login({ json }: JsonInteractionHandlerInput): Promise<JsonRepresentation<LoginOutputType>> {
    const { email, password, remember } = await validateWithError(inSchema, json);
    // Try to log in, will error if email/password combination is invalid
    const { accountId } = await this.passwordStore.authenticate(email, password);
    this.logger.debug(`Logging in user ${email}`);

    return { json: { accountId, remember }};
  }
}

import { object, string } from 'yup';
import { getLoggerFor } from '../../../logging/LogUtil';
import { BadRequestHttpError } from '../../../util/errors/BadRequestHttpError';
import type { EmptyObject } from '../../../util/map/MapUtil';
import type { JsonRepresentation } from '../InteractionUtil';
import type { JsonInteractionHandlerInput } from '../JsonInteractionHandler';
import { JsonInteractionHandler } from '../JsonInteractionHandler';
import type { JsonView } from '../JsonView';
import { parseSchema, validateWithError } from '../YupUtil';
import type { ForgotPasswordStore } from './util/ForgotPasswordStore';
import type { PasswordStore } from './util/PasswordStore';

const inSchema = object({
  recordId: string().trim().min(1).required(),
  password: string().trim().required(),
});

/**
 * Resets a password if a valid `recordId` is provided,
 * which should have been generated by a different handler.
 */
export class ResetPasswordHandler extends JsonInteractionHandler<EmptyObject> implements JsonView {
  protected readonly logger = getLoggerFor(this);

  private readonly passwordStore: PasswordStore;
  private readonly forgotPasswordStore: ForgotPasswordStore;

  public constructor(passwordStore: PasswordStore, forgotPasswordStore: ForgotPasswordStore) {
    super();
    this.passwordStore = passwordStore;
    this.forgotPasswordStore = forgotPasswordStore;
  }

  public async getView(): Promise<JsonRepresentation> {
    return { json: parseSchema(inSchema) };
  }

  public async handle({ json }: JsonInteractionHandlerInput): Promise<JsonRepresentation<EmptyObject>> {
    // Validate input data
    const { password, recordId } = await validateWithError(inSchema, json);

    await this.resetPassword(recordId, password);
    return { json: {}};
  }

  /**
   * Resets the password for the account associated with the given recordId.
   */
  private async resetPassword(recordId: string, newPassword: string): Promise<void> {
    const id = await this.forgotPasswordStore.get(recordId);

    if (!id) {
      this.logger.warn(`Trying to use invalid reset URL with record ID ${recordId}`);
      throw new BadRequestHttpError('This reset password link is no longer valid.');
    }

    await this.passwordStore.update(id, newPassword);
    await this.forgotPasswordStore.delete(recordId);

    this.logger.debug(`Resetting password for login ${id}`);
  }
}

import { object, string } from 'yup';
import { getLoggerFor } from '../../../logging/LogUtil';
import { BadRequestHttpError } from '../../../util/errors/BadRequestHttpError';
import type { EmptyObject } from '../../../util/map/MapUtil';
import { parsePath, verifyAccountId } from '../account/util/AccountUtil';
import type { JsonRepresentation } from '../InteractionUtil';
import type { JsonInteractionHandlerInput } from '../JsonInteractionHandler';
import { JsonInteractionHandler } from '../JsonInteractionHandler';
import type { JsonView } from '../JsonView';
import { parseSchema, validateWithError } from '../YupUtil';
import type { PasswordIdRoute } from './util/PasswordIdRoute';
import type { PasswordStore } from './util/PasswordStore';

const inSchema = object({
  oldPassword: string().trim().min(1).required(),
  newPassword: string().trim().min(1).required(),
});

/**
 * Allows the password of a login to be updated.
 */
export class UpdatePasswordHandler extends JsonInteractionHandler<EmptyObject> implements JsonView {
  private readonly logger = getLoggerFor(this);

  private readonly passwordStore: PasswordStore;
  private readonly passwordRoute: PasswordIdRoute;

  public constructor(passwordStore: PasswordStore, passwordRoute: PasswordIdRoute) {
    super();
    this.passwordStore = passwordStore;
    this.passwordRoute = passwordRoute;
  }

  public async getView(): Promise<JsonRepresentation> {
    return { json: parseSchema(inSchema) };
  }

  public async handle(input: JsonInteractionHandlerInput): Promise<JsonRepresentation<EmptyObject>> {
    const { target, accountId, json } = input;

    const { oldPassword, newPassword } = await validateWithError(inSchema, json);
    const match = parsePath(this.passwordRoute, target.path);

    const login = await this.passwordStore.get(match.passwordId);
    verifyAccountId(accountId, login?.accountId);

    // Make sure the old password is correct
    try {
      await this.passwordStore.authenticate(login.email, oldPassword);
    } catch {
      this.logger.warn(`Invalid password when trying to reset for email ${login.email}`);
      throw new BadRequestHttpError('Old password is invalid.');
    }

    await this.passwordStore.update(match.passwordId, newPassword);

    return { json: {}};
  }
}

import { createTransport } from 'nodemailer';
import type Mail from 'nodemailer/lib/mailer';
import { getLoggerFor } from '../../../../logging/LogUtil';
import { EmailSender } from './EmailSender';
import type { EmailArgs } from './EmailSender';

export interface EmailSenderArgs {
  emailConfig: {
    host: string;
    port: number;
    auth: {
      user: string;
      pass: string;
    };
  };
  senderName?: string;
}

/**
 * Sends e-mails using nodemailer.
 */
export class BaseEmailSender extends EmailSender {
  private readonly logger = getLoggerFor(this);

  private readonly mailTransporter: Mail;
  private readonly senderName: string;

  public constructor(args: EmailSenderArgs) {
    super();
    this.mailTransporter = createTransport(args.emailConfig);
    this.senderName = args.senderName ?? 'Solid';
  }

  public async handle({ recipient, subject, text, html }: EmailArgs): Promise<void> {
    await this.mailTransporter.sendMail({
      from: this.senderName,
      to: recipient,
      subject,
      text,
      html,
    });
    this.logger.debug(`Sending recovery mail to ${recipient}`);
  }
}

import { v4 } from 'uuid';
import type { ExpiringStorage } from '../../../../storage/keyvalue/ExpiringStorage';
import type { ForgotPasswordStore } from './ForgotPasswordStore';

/**
 * A {@link ForgotPasswordStore} using an {@link ExpiringStorage} to hold the necessary records.
 */
export class BaseForgotPasswordStore implements ForgotPasswordStore {
  private readonly storage: ExpiringStorage<string, string>;
  private readonly ttl: number;

  public constructor(storage: ExpiringStorage<string, string>, ttl = 15) {
    this.storage = storage;
    this.ttl = ttl * 60 * 1000;
  }

  public async generate(email: string): Promise<string> {
    const recordId = v4();
    await this.storage.set(recordId, email, this.ttl);
    return recordId;
  }

  public async get(recordId: string): Promise<string | undefined> {
    return this.storage.get(recordId);
  }

  public async delete(recordId: string): Promise<boolean> {
    return this.storage.delete(recordId);
  }
}

import { compare, hash } from 'bcryptjs';
import { Initializer } from '../../../../init/Initializer';
import { getLoggerFor } from '../../../../logging/LogUtil';
import { BadRequestHttpError } from '../../../../util/errors/BadRequestHttpError';
import { createErrorMessage } from '../../../../util/errors/ErrorUtil';
import { ForbiddenHttpError } from '../../../../util/errors/ForbiddenHttpError';
import { InternalServerError } from '../../../../util/errors/InternalServerError';
import { ACCOUNT_TYPE } from '../../account/util/LoginStorage';
import type { AccountLoginStorage } from '../../account/util/LoginStorage';
import type { PasswordStore } from './PasswordStore';

export const PASSWORD_STORAGE_TYPE = 'password';
export const PASSWORD_STORAGE_DESCRIPTION = {
  email: 'string',
  password: 'string',
  verified: 'boolean',
  accountId: `id:${ACCOUNT_TYPE}`,
} as const;

/**
 * A {@link PasswordStore} that uses a {@link KeyValueStorage} to store the entries.
 * Passwords are hashed and salted.
 * Default `saltRounds` is 10.
 */
export class BasePasswordStore extends Initializer implements PasswordStore {
  private readonly logger = getLoggerFor(this);

  private readonly storage: AccountLoginStorage<{ [PASSWORD_STORAGE_TYPE]: typeof PASSWORD_STORAGE_DESCRIPTION }>;
  private readonly saltRounds: number;
  private initialized = false;

  // Wrong typings to prevent Components.js typing issues
  public constructor(storage: AccountLoginStorage<Record<string, never>>, saltRounds = 10) {
    super();
    this.storage = storage as unknown as typeof this.storage;
    this.saltRounds = saltRounds;
  }

  // Initialize the type definitions
  public async handle(): Promise<void> {
    if (this.initialized) {
      return;
    }
    try {
      await this.storage.defineType(PASSWORD_STORAGE_TYPE, PASSWORD_STORAGE_DESCRIPTION, true);
      await this.storage.createIndex(PASSWORD_STORAGE_TYPE, 'accountId');
      await this.storage.createIndex(PASSWORD_STORAGE_TYPE, 'email');
      this.initialized = true;
    } catch (cause: unknown) {
      throw new InternalServerError(
        `Error defining email/password in storage: ${createErrorMessage(cause)}`,
        { cause },
      );
    }
  }

  public async create(email: string, accountId: string, password: string): Promise<string> {
    if (await this.findByEmail(email)) {
      this.logger.warn(`Trying to create duplicate login for email ${email}`);
      throw new BadRequestHttpError('There already is a login for this e-mail address.');
    }
    const payload = await this.storage.create(PASSWORD_STORAGE_TYPE, {
      accountId,
      email: email.toLowerCase(),
      password: await hash(password, this.saltRounds),
      verified: false,
    });
    return payload.id;
  }

  public async get(id: string): Promise<{ email: string; accountId: string } | undefined> {
    const result = await this.storage.get(PASSWORD_STORAGE_TYPE, id);
    if (!result) {
      return;
    }
    return { email: result.email, accountId: result.accountId };
  }

  public async findByEmail(email: string): Promise<{ accountId: string; id: string } | undefined> {
    const payload = await this.storage.find(PASSWORD_STORAGE_TYPE, { email: email.toLowerCase() });
    if (payload.length === 0) {
      return;
    }
    return { accountId: payload[0].accountId, id: payload[0].id };
  }

  public async findByAccount(accountId: string): Promise<{ id: string; email: string }[]> {
    return (await this.storage.find(PASSWORD_STORAGE_TYPE, { accountId }))
      .map(({ id, email }): { id: string; email: string } => ({ id, email }));
  }

  public async confirmVerification(id: string): Promise<void> {
    if (!await this.storage.has(PASSWORD_STORAGE_TYPE, id)) {
      this.logger.warn(`Trying to verify unknown password login ${id}`);
      throw new ForbiddenHttpError('Login does not exist.');
    }

    await this.storage.setField(PASSWORD_STORAGE_TYPE, id, 'verified', true);
  }

  public async authenticate(email: string, password: string): Promise<{ accountId: string; id: string }> {
    const payload = await this.storage.find(PASSWORD_STORAGE_TYPE, { email: email.toLowerCase() });
    if (payload.length === 0) {
      this.logger.warn(`Trying to get account info for unknown email ${email}`);
      throw new ForbiddenHttpError('Invalid email/password combination.');
    }
    if (!await compare(password, payload[0].password)) {
      this.logger.warn(`Incorrect password for email ${email}`);
      throw new ForbiddenHttpError('Invalid email/password combination.');
    }
    const { verified, accountId, id } = payload[0];
    if (!verified) {
      this.logger.warn(`Trying to get account info for unverified email ${email}`);
      throw new ForbiddenHttpError('Login still needs to be verified.');
    }
    return { accountId, id };
  }

  public async update(id: string, password: string): Promise<void> {
    if (!await this.storage.has(PASSWORD_STORAGE_TYPE, id)) {
      this.logger.warn(`Trying to update unknown password login ${id}`);
      throw new ForbiddenHttpError('Login does not exist.');
    }
    await this.storage.setField(PASSWORD_STORAGE_TYPE, id, 'password', await hash(password, this.saltRounds));
  }

  public async delete(id: string): Promise<void> {
    return this.storage.delete(PASSWORD_STORAGE_TYPE, id);
  }
}

import { AsyncHandler } from '../../../../util/handlers/AsyncHandler';

export interface EmailArgs {
  recipient: string;
  subject: string;
  text: string;
  html: string;
}

/**
 * A class that can send an e-mail.
 */
export abstract class EmailSender extends AsyncHandler<EmailArgs> {}

/**
 * Responsible for storing the records that are used when a user forgets their password.
 */
export interface ForgotPasswordStore {
  /**
   * Creates a Forgot Password Confirmation Record. This will be to remember that
   * a user has made a request to reset a password. Throws an error if the email doesn't
   * exist.
   *
   * @param id - ID of the email/password login object.
   *
   * @returns The record id. This should be included in the reset password link.
   */
  generate: (id: string) => Promise<string>;

  /**
   * Gets the email associated with the forgot password confirmation record
   * or undefined if it's not present.
   *
   * @param recordId - The record id retrieved from the link.
   *
   * @returns The user's email.
   */
  get: (recordId: string) => Promise<string | undefined>;

  /**
   * Deletes the Forgot Password Confirmation Record.
   *
   * @param recordId - The record id of the forgot password confirmation record.
   */
  delete: (recordId: string) => Promise<boolean>;
}

import type { AccountIdKey, AccountIdRoute } from '../../account/AccountIdRoute';
import { IdInteractionRoute } from '../../routing/IdInteractionRoute';
import type { ExtendedRoute } from '../../routing/InteractionRoute';

export type PasswordIdKey = 'passwordId';

/**
 * An {@link AccountIdRoute} that also includes a password login identifier.
 */
export type PasswordIdRoute = ExtendedRoute<AccountIdRoute, PasswordIdKey>;

/**
 * Implementation of an {@link PasswordIdRoute} that adds the identifier relative to a base {@link AccountIdRoute}.
 */
export class BasePasswordIdRoute extends IdInteractionRoute<AccountIdKey, PasswordIdKey> {
  public constructor(base: AccountIdRoute) {
    super(base, 'passwordId');
  }
}

/**
 * The constant used to identify email/password based login combinations in the map of logins an account has.
 */
export const PASSWORD_METHOD = 'password';

/**
 * Responsible for storing everything related to email/password based login combinations.
 */
export interface PasswordStore {
  /**
   * Creates a new login entry for this account.
   *
   * @param email - Email to log in with.
   * @param accountId - Account ID.
   * @param password - Password to authenticate with.
   */
  create: (email: string, accountId: string, password: string) => Promise<string>;

  /**
   * Finds the account and email associated with this login ID.
   *
   * @param id - The ID of the login object.
   */
  get: (id: string) => Promise<{ email: string; accountId: string } | undefined>;

  /**
   * Finds the account and login ID associated with this email.
   *
   * @param email - Email to find the information for.
   */
  findByEmail: (email: string) => Promise<{ accountId: string; id: string } | undefined>;

  /**
   * Find all login objects created by this account.
   *
   * @param accountId - ID of the account to find the logins for.
   */
  findByAccount: (accountId: string) => Promise<{ id: string; email: string }[]>;

  /**
   * Confirms that the login has been verified.
   * This can be used with, for example, email verification.
   * The login can only be used after it is verified.
   * In case verification is not required, this should be called immediately after the `create` call.
   *
   * @param id - ID of the login.
   */
  confirmVerification: (id: string) => Promise<void>;

  /**
   * Authenticate if the email and password are correct and return the account and login ID if they are.
   * Throw an error if they are not.
   *
   * @param email - The user's email.
   * @param password - This user's password.
   */
  authenticate: (email: string, password: string) => Promise<{ accountId: string; id: string }>;

  /**
   * Changes the password.
   *
   * @param id - ID of the login object.
   * @param password - The new password.
   */
  update: (id: string, password: string) => Promise<void>;

  /**
   * Delete the login entry.
   *
   * @param id - ID of the login object.
   */
  delete: (id: string) => Promise<void>;
}

import type { StringSchema } from 'yup';
import { object, string } from 'yup';
import { getLoggerFor } from '../../../logging/LogUtil';
import { assertAccountId } from '../account/util/AccountUtil';
import type { JsonRepresentation } from '../InteractionUtil';
import { JsonInteractionHandler } from '../JsonInteractionHandler';
import type { JsonInteractionHandlerInput } from '../JsonInteractionHandler';
import type { JsonView } from '../JsonView';
import type { WebIdLinkRoute } from '../webid/WebIdLinkRoute';
import { parseSchema, URL_SCHEMA, validateWithError } from '../YupUtil';
import type { PodIdRoute } from './PodIdRoute';
import type { PodCreator } from './util/PodCreator';
import type { PodStore } from './util/PodStore';

const inSchema = object({
  name: string().trim().min(1).optional(),
  settings: object({
    webId: URL_SCHEMA,
  }).optional(),
});

type OutType = {
  pod: string;
  podResource: string;
  webId: string;
  webIdResource?: string;
};

/**
 * Handles the creation of pods.
 * Will call the stored {@link PodCreator} with the settings found in the input JSON.
 */
export class CreatePodHandler extends JsonInteractionHandler<OutType> implements JsonView {
  private readonly logger = getLoggerFor(this);

  private readonly podStore: PodStore;
  private readonly podCreator: PodCreator;
  private readonly webIdLinkRoute: WebIdLinkRoute;
  private readonly podIdRoute: PodIdRoute;

  private readonly inSchema: typeof inSchema;

  public constructor(
    podStore: PodStore,
    podCreator: PodCreator,
    webIdLinkRoute: WebIdLinkRoute,
    podIdRoute: PodIdRoute,
    allowRoot = false,
  ) {
    super();
    this.podStore = podStore;
    this.podCreator = podCreator;
    this.webIdLinkRoute = webIdLinkRoute;
    this.podIdRoute = podIdRoute;

    this.inSchema = inSchema.clone();

    if (!allowRoot) {
      // Casting is necessary to prevent errors
      this.inSchema.fields.name = (this.inSchema.fields.name as StringSchema).required();
    }
  }

  public async getView({ accountId }: JsonInteractionHandlerInput): Promise<JsonRepresentation> {
    assertAccountId(accountId);
    const pods: Record<string, string> = {};
    for (const { id, baseUrl } of await this.podStore.findPods(accountId)) {
      pods[baseUrl] = this.podIdRoute.getPath({ accountId, podId: id });
    }
    return { json: { ...parseSchema(this.inSchema), pods }};
  }

  public async handle({ json, accountId }: JsonInteractionHandlerInput): Promise<JsonRepresentation<OutType>> {
    // In case the class was not initialized with allowRoot: false, missing name values will result in an error
    const { name, settings } = await validateWithError(inSchema, json);
    assertAccountId(accountId);

    const result = await this.podCreator.handleSafe({
      accountId,
      webId: settings?.webId,
      name,
      settings,
    });

    const webIdResource = result.webIdLink && this.webIdLinkRoute.getPath({ accountId, webIdLink: result.webIdLink });
    const podResource = this.podIdRoute.getPath({ accountId, podId: result.podId });

    return { json: { pod: result.podUrl, webId: result.webId, podResource, webIdResource }};
  }
}

import type { AccountIdKey, AccountIdRoute } from '../account/AccountIdRoute';
import { IdInteractionRoute } from '../routing/IdInteractionRoute';
import type { ExtendedRoute } from '../routing/InteractionRoute';

export type PodIdKey = 'podId';

/**
 * An {@link AccountIdRoute} that also includes a pod identifier.
 */
export type PodIdRoute = ExtendedRoute<AccountIdRoute, PodIdKey>;

/**
 * Implementation of an {@link PodIdRoute} that adds the identifier relative to a base {@link AccountIdRoute}.
 */
export class BasePodIdRoute extends IdInteractionRoute<AccountIdKey, PodIdKey> {
  public constructor(base: AccountIdRoute) {
    super(base, 'podId');
  }
}

import { boolean, object, string } from 'yup';
import type { ResourceIdentifier } from '../../../http/representation/ResourceIdentifier';
import type { EmptyObject } from '../../../util/map/MapUtil';
import { parsePath, verifyAccountId } from '../account/util/AccountUtil';
import type { JsonRepresentation } from '../InteractionUtil';
import type { JsonInteractionHandlerInput } from '../JsonInteractionHandler';
import { JsonInteractionHandler } from '../JsonInteractionHandler';
import type { JsonView } from '../JsonView';
import { parseSchema, validateWithError } from '../YupUtil';
import type { PodIdRoute } from './PodIdRoute';
import type { PodStore } from './util/PodStore';

const inSchema = object({
  webId: string().trim().required(),
  visible: boolean().optional().default(false),
  // If true: remove the WebID as owner
  remove: boolean().optional().default(false),
});

/**
 * Responsible for adding/updating/deleting owners in pods.
 */
export class UpdateOwnerHandler extends JsonInteractionHandler implements JsonView {
  private readonly podStore: PodStore;
  private readonly podRoute: PodIdRoute;

  public constructor(podStore: PodStore, podRoute: PodIdRoute) {
    super();
    this.podStore = podStore;
    this.podRoute = podRoute;
  }

  public async getView({ accountId, target }: JsonInteractionHandlerInput): Promise<JsonRepresentation> {
    const pod = await this.findVerifiedPod(target, accountId);
    const owners = await this.podStore.getOwners(pod.id);

    return { json: { ...parseSchema(inSchema), baseUrl: pod?.baseUrl, owners }};
  }

  public async handle(input: JsonInteractionHandlerInput): Promise<JsonRepresentation<EmptyObject>> {
    const { accountId, target, json } = input;

    const { webId, visible, remove } = await validateWithError(inSchema, json);
    const pod = await this.findVerifiedPod(target, accountId);

    if (remove) {
      await this.podStore.removeOwner(pod.id, webId);
    } else {
      await this.podStore.updateOwner(pod.id, webId, visible);
    }

    return { json: {}};
  }

  /**
   * Extract the pod ID from the path and find the associated pod.
   * Asserts that the given account ID is the creator of this pod.
   */
  protected async findVerifiedPod(target: ResourceIdentifier, accountId?: string):
  Promise<{ id: string; baseUrl: string; accountId: string }> {
    const { podId } = parsePath(this.podRoute, target.path);
    const pod = await this.podStore.get(podId);
    verifyAccountId(accountId, pod?.accountId);
    return { id: podId, ...pod };
  }
}

import type { ResourceIdentifier } from '../../../../http/representation/ResourceIdentifier';
import { getLoggerFor } from '../../../../logging/LogUtil';
import type { IdentifierGenerator } from '../../../../pods/generate/IdentifierGenerator';
import type { PodSettings } from '../../../../pods/settings/PodSettings';
import { BadRequestHttpError } from '../../../../util/errors/BadRequestHttpError';
import { joinUrl } from '../../../../util/PathUtil';
import type { WebIdStore } from '../../webid/util/WebIdStore';
import { PodCreator } from './PodCreator';
import type { PodCreatorInput, PodCreatorOutput } from './PodCreator';
import type { PodStore } from './PodStore';

export interface BasePodCreatorArgs {
  /**
   * Base URL of the server.
   * Used to potentially set the `solid:oidcIssuer` triple
   * and/or the pod URL if it is a root pod.
   */
  baseUrl: string;
  /**
   * Generates the base URL of the pod based on the input `name`.
   */
  identifierGenerator: IdentifierGenerator;
  /**
   * The path of where the WebID will be generated by the template, relative to the pod URL.
   */
  relativeWebIdPath: string;
  /**
   * WebID data store.
   */
  webIdStore: WebIdStore;
  /**
   * Pod data store.
   */
  podStore: PodStore;
}

/**
 * Handles the creation of pods.
 * Will call the stored {@link PodStore} with the provided settings.
 */
export class BasePodCreator extends PodCreator {
  protected readonly logger = getLoggerFor(this);

  protected readonly baseUrl: string;
  protected readonly identifierGenerator: IdentifierGenerator;
  protected readonly relativeWebIdPath: string;
  protected readonly webIdStore: WebIdStore;
  protected readonly podStore: PodStore;

  public constructor(args: BasePodCreatorArgs) {
    super();
    this.baseUrl = args.baseUrl;
    this.identifierGenerator = args.identifierGenerator;
    this.relativeWebIdPath = args.relativeWebIdPath;
    this.webIdStore = args.webIdStore;
    this.podStore = args.podStore;
  }

  public async handle(input: PodCreatorInput): Promise<PodCreatorOutput> {
    const baseIdentifier = this.generateBaseIdentifier(input.name);
    // Either the input WebID or the one generated in the pod
    const webId = input.webId ?? joinUrl(baseIdentifier.path, this.relativeWebIdPath);

    const podSettings: PodSettings = {
      ...input.settings,
      base: baseIdentifier,
      webId,
    };

    // Link the WebID to the account immediately if no WebID was provided as this is expected behaviour.
    // We do this first as we can't undo creating the pod if this would fail.
    // If an external WebID is the owner we do not want to link it to the account automatically
    const webIdLink = await this.handleWebId(!input.webId, webId, input.accountId, podSettings);

    // Create the pod
    const podId = await this.createPod(input.accountId, podSettings, !input.name, webIdLink);

    return {
      podUrl: baseIdentifier.path,
      webId,
      podId,
      webIdLink,
    };
  }

  protected generateBaseIdentifier(name?: string): ResourceIdentifier {
    if (name) {
      return this.identifierGenerator.generate(name);
    }
    return { path: this.baseUrl };
  }

  /**
   * Links the WebID to the account if `linkWebId` is true.
   * Also updates the `oidcIssuer` value in the settings object in that case.
   */
  protected async handleWebId(linkWebId: boolean, webId: string, accountId: string, settings: PodSettings):
  Promise<string | undefined> {
    if (linkWebId) {
      // It is important that this check happens here.
      // Otherwise, if the account already has this WebID link,
      // this link would be deleted if pod creation fails,
      // since we clean up the WebID link again afterwards.
      // Current implementation of the {@link WebIdStore} also has this check but better safe than sorry.
      if (await this.webIdStore.isLinked(webId, accountId)) {
        this.logger.warn('Trying to create pod which would generate a WebID that is already linked to this account');
        throw new BadRequestHttpError(`${webId} is already registered to this account.`);
      }
      // Need to have the necessary `solid:oidcIssuer` triple if the WebID is linked
      settings.oidcIssuer = this.baseUrl;

      return this.webIdStore.create(webId, accountId);
    }
  }

  /**
   * Creates a pod with the given settings.
   * In case pod creation fails, the given WebID link will be removed, if there is one, before throwing an error.
   */
  protected async createPod(accountId: string, settings: PodSettings, overwrite: boolean, webIdLink?: string):
  Promise<string> {
    try {
      return await this.podStore.create(accountId, settings, overwrite);
    } catch (error: unknown) {
      // Undo the WebID linking if pod creation fails
      if (webIdLink) {
        await this.webIdStore.delete(webIdLink);
      }
      throw error;
    }
  }
}

import { Initializer } from '../../../../init/Initializer';
import { getLoggerFor } from '../../../../logging/LogUtil';
import type { PodManager } from '../../../../pods/PodManager';
import type { PodSettings } from '../../../../pods/settings/PodSettings';
import { BadRequestHttpError } from '../../../../util/errors/BadRequestHttpError';
import { createErrorMessage } from '../../../../util/errors/ErrorUtil';
import { InternalServerError } from '../../../../util/errors/InternalServerError';
import { ACCOUNT_TYPE } from '../../account/util/LoginStorage';
import type { AccountLoginStorage } from '../../account/util/LoginStorage';
import type { PodStore } from './PodStore';

export const POD_STORAGE_TYPE = 'pod';
export const POD_STORAGE_DESCRIPTION = {
  baseUrl: 'string',
  accountId: `id:${ACCOUNT_TYPE}`,
} as const;

export const OWNER_STORAGE_TYPE = 'owner';
export const OWNER_STORAGE_DESCRIPTION = {
  webId: 'string',
  visible: 'boolean',
  podId: `id:${POD_STORAGE_TYPE}`,
} as const;

/**
 * A {@link PodStore} implementation using a {@link PodManager} to create pods
 * and a {@link AccountLoginStorage} to store the data.
 * Needs to be initialized before it can be used.
 *
 * Adds the initial WebID as the owner of the pod.
 * By default, this owner is not exposed through a link header.
 * This can be changed by setting the constructor `visible` parameter to `true`.
 */
export class BasePodStore extends Initializer implements PodStore {
  private readonly logger = getLoggerFor(this);

  private readonly storage: AccountLoginStorage<{
    [POD_STORAGE_TYPE]: typeof POD_STORAGE_DESCRIPTION;
    [OWNER_STORAGE_TYPE]: typeof OWNER_STORAGE_DESCRIPTION;
  }>;

  private readonly manager: PodManager;
  private readonly visible: boolean;

  private initialized = false;

  // Wrong typings to prevent Components.js typing issues
  public constructor(storage: AccountLoginStorage<Record<string, never>>, manager: PodManager, visible = false) {
    super();
    this.storage = storage as unknown as typeof this.storage;
    this.visible = visible;
    this.manager = manager;
  }

  // Initialize the type definitions
  public async handle(): Promise<void> {
    if (this.initialized) {
      return;
    }
    try {
      await this.storage.defineType(POD_STORAGE_TYPE, POD_STORAGE_DESCRIPTION, false);
      await this.storage.createIndex(POD_STORAGE_TYPE, 'accountId');
      await this.storage.createIndex(POD_STORAGE_TYPE, 'baseUrl');
      await this.storage.defineType(OWNER_STORAGE_TYPE, OWNER_STORAGE_DESCRIPTION, false);
      await this.storage.createIndex(OWNER_STORAGE_TYPE, 'podId');
      this.initialized = true;
    } catch (cause: unknown) {
      throw new InternalServerError(`Error defining pods in storage: ${createErrorMessage(cause)}`, { cause });
    }
  }

  public async create(accountId: string, settings: PodSettings, overwrite: boolean): Promise<string> {
    // Adding pod to storage first as we cannot undo creating the pod below.
    // This call might also fail because there is no login method yet on the account.
    const pod = await this.storage.create(POD_STORAGE_TYPE, { baseUrl: settings.base.path, accountId });
    await this.storage.create(OWNER_STORAGE_TYPE, { podId: pod.id, webId: settings.webId, visible: this.visible });

    try {
      await this.manager.createPod(settings, overwrite);
    } catch (error: unknown) {
      this.logger.warn(`Pod creation failed for account ${accountId}: ${createErrorMessage(error)}`);
      await this.storage.delete(POD_STORAGE_TYPE, pod.id);
      throw new BadRequestHttpError(`Pod creation failed: ${createErrorMessage(error)}`, { cause: error });
    }
    this.logger.debug(`Created pod ${settings.name} for account ${accountId}`);

    return pod.id;
  }

  public async get(id: string): Promise<{ baseUrl: string; accountId: string } | undefined> {
    const pod = await this.storage.get(POD_STORAGE_TYPE, id);
    if (!pod) {
      return;
    }
    return { baseUrl: pod.baseUrl, accountId: pod.accountId };
  }

  public async findByBaseUrl(baseUrl: string): Promise<{ id: string; accountId: string } | undefined> {
    const result = await this.storage.find(POD_STORAGE_TYPE, { baseUrl });
    if (result.length === 0) {
      return;
    }
    return { id: result[0].id, accountId: result[0].accountId };
  }

  public async findPods(accountId: string): Promise<{ id: string; baseUrl: string }[]> {
    return (await this.storage.find(POD_STORAGE_TYPE, { accountId }))
      .map(({ id, baseUrl }): { id: string; baseUrl: string } => ({ id, baseUrl }));
  }

  public async getOwners(id: string): Promise<{ webId: string; visible: boolean }[] | undefined> {
    const results = await this.storage.find(OWNER_STORAGE_TYPE, { podId: id });
    if (results.length === 0) {
      return;
    }
    return results.map((result): { webId: string; visible: boolean } =>
      ({ webId: result.webId, visible: result.visible }));
  }

  public async updateOwner(id: string, webId: string, visible: boolean): Promise<void> {
    // Need to first check if there already is an owner with the given WebID
    // so we know if we need to create or update.
    const matches = await this.storage.find(OWNER_STORAGE_TYPE, { webId, podId: id });
    if (matches.length === 0) {
      await this.storage.create(OWNER_STORAGE_TYPE, { webId, visible, podId: id });
    } else {
      await this.storage.setField(OWNER_STORAGE_TYPE, matches[0].id, 'visible', visible);
    }
  }

  public async removeOwner(id: string, webId: string): Promise<void> {
    const owners = await this.storage.find(OWNER_STORAGE_TYPE, { podId: id });
    const match = owners.find((owner): boolean => owner.webId === webId);
    if (!match) {
      return;
    }
    if (owners.length === 1) {
      throw new BadRequestHttpError('Unable to remove the last owner of a pod.');
    }
    await this.storage.delete(OWNER_STORAGE_TYPE, match.id);
  }
}

import { Util } from 'n3';
import type { MetadataWriterInput } from '../../../../http/output/metadata/MetadataWriter';
import { MetadataWriter } from '../../../../http/output/metadata/MetadataWriter';
import type { ResourceIdentifier } from '../../../../http/representation/ResourceIdentifier';
import { getLoggerFor } from '../../../../logging/LogUtil';
import type { StorageLocationStrategy } from '../../../../server/description/StorageLocationStrategy';
import { createErrorMessage } from '../../../../util/errors/ErrorUtil';
import { addHeader } from '../../../../util/HeaderUtil';
import type { PodStore } from './PodStore';
import isBlankNode = Util.isBlankNode;

/**
 * Adds link headers indicating who the owners are when accessing the base URL of a pod.
 * Only owners that have decided to be visible will be shown.
 *
 * Solid, §4.1: "When a server wants to advertise the owner of a storage,
 * the server MUST include the Link header with rel="http://www.w3.org/ns/solid/terms#owner"
 * targeting the URI of the owner in the response of HTTP HEAD or GET requests targeting the root container."
 * https://solidproject.org/TR/2022/protocol-20221231#server-storage-link-owner
 */
export class OwnerMetadataWriter extends MetadataWriter {
  protected logger = getLoggerFor(this);

  protected podStore: PodStore;
  protected storageStrategy: StorageLocationStrategy;

  public constructor(podStore: PodStore, storageStrategy: StorageLocationStrategy) {
    super();
    this.podStore = podStore;
    this.storageStrategy = storageStrategy;
  }

  public async handle({ metadata, response }: MetadataWriterInput): Promise<void> {
    // Doing all checks here instead of in `canHandle` as this is currently used in a ParallelHandler,
    // which doesn't correctly check the canHandle/handle combination.
    if (isBlankNode(metadata.identifier)) {
      // Blank nodes indicate errors
      this.logger.debug('Skipping owner link headers as metadata identifier is a blank node.');
      return;
    }
    const identifier = { path: metadata.identifier.value };

    let storageIdentifier: ResourceIdentifier;
    try {
      storageIdentifier = await this.storageStrategy.getStorageIdentifier(identifier);
    } catch (error: unknown) {
      this.logger
        .debug(`Skipping owner link headers as no storage identifier could be found: ${createErrorMessage(error)}`);
      return;
    }

    // Only need to expose headers when requesting the base URl of the pod
    if (identifier.path !== storageIdentifier.path) {
      return;
    }

    const pod = await this.podStore.findByBaseUrl(identifier.path);
    if (!pod) {
      this.logger.debug(`No pod object found for base URL ${identifier.path}`);
      return;
    }

    const owners = await this.podStore.getOwners(pod.id);
    if (!owners) {
      this.logger.error(`Unable to find owners for pod ${identifier.path}`);
      return;
    }

    for (const { webId, visible } of owners) {
      if (visible) {
        addHeader(response, 'Link', `<${webId}>; rel="http://www.w3.org/ns/solid/terms#owner"`);
      }
    }
  }
}

import { AsyncHandler } from '../../../../util/handlers/AsyncHandler';

export interface PodCreatorInput {
  /**
   * The ID of the account to create the pod for.
   */
