  /**
   * The WebID to use for creation of the pod.
   * This WebID will be used in the templates to, for example, determine who has access.
   * If none is provided, the WebID generated by the creator will be used,
   * in which case that WebID will also be linked to the account.
   */
  webId?: string;
  /**
   * Additional settings to use when generating a pod.
   */
  settings?: Record<string, unknown>;
}

export interface PodCreatorOutput {
  /**
   * The ID of the generated pod.
   */
  podId: string;
  /**
   * The URl of the generated pod.
   */
  podUrl: string;
  /**
   * The WebID that was used to generate the pod.
   */
  webId: string;
  /**
   * The ID of the WebID link if one was generated.
   */
  webIdLink?: string;
}

/**
 * Handles creating a pod and linking the created WebID.
 */
export abstract class PodCreator extends AsyncHandler<PodCreatorInput, PodCreatorOutput> {}

import type { PodSettings } from '../../../../pods/settings/PodSettings';
/** * Can be used to create new pods and find relevant information. * Also keeps track of the owners of a pod. * The `visible` parameter indicates if an owner should be publicly exposed or not. */ export interface PodStore { /** * Creates a new pod and updates the account accordingly. * * @param accountId - Identifier of the account that is creating the account. * @param settings - Settings to create a pod with. * @param overwrite - If the pod is allowed to overwrite existing data. * * @returns The ID of the new pod resource. */ create: (accountId: string, settings: PodSettings, overwrite: boolean) => Promise<string>;
/** * Returns the baseURl and account that created the pod for the given pod ID. * * @param id - ID of the pod. */ get: (id: string) => Promise<{ baseUrl: string; accountId: string } | undefined>;
/** * Find the ID of the account that created the given pod. * * @param baseUrl - The pod base URL. */ findByBaseUrl: (baseUrl: string) => Promise<{ id: string; accountId: string } | undefined>;
/** * Find all the pod resources created by the given account ID. * * @param accountId - Account ID to find pod resources for. */ findPods: (accountId: string) => Promise<{ id: string; baseUrl: string }[]>;
/** * Find all owners for the given pod ID. * * @param id - ID of the pod. */ getOwners: (id: string) => Promise<{ webId: string; visible: boolean }[] | undefined>;
/** * Add or update an owner of a pod. * In case there already is an owner with this WebID, it will be updated, * otherwise a new owner will be added. * * @param id - ID of the pod. * @param webId - WebID of the owner. * @param visible - Whether the owner wants to be exposed or not. */ updateOwner: (id: string, webId: string, visible: boolean) => Promise<void>;
/** * Remove an owner from a pod. * This should not remove the last owner as a pod always needs to have at least one owner. * https://solidproject.org/TR/2022/protocol-20221231#server-storage-track-owner * * @param id - ID of the pod. * @param webId - WebID of the owner. */ removeOwner: (id: string, webId: string) => Promise<void>; }

import type { EmptyObject } from '../../../util/map/MapUtil';
import { ensureTrailingSlash } from '../../../util/PathUtil';
import type { InteractionRoute } from './InteractionRoute';

/**
 * A route that stores a single absolute path.
 */
export class AbsolutePathInteractionRoute implements InteractionRoute {
  private readonly path: string;

  public constructor(path: string, ensureSlash = true) {
    this.path = path;
    if (ensureSlash) {
      this.path = ensureTrailingSlash(this.path);
    }
  }

  public getPath(): string {
    return this.path;
  }

  public matchPath(path: string): EmptyObject | undefined {
    if (path === this.path) {
      return {};
    }
  }
}

import { getLoggerFor } from '../../../logging/LogUtil';
import { ForbiddenHttpError } from '../../../util/errors/ForbiddenHttpError';
import { UnauthorizedHttpError } from '../../../util/errors/UnauthorizedHttpError';
import type { AccountIdRoute } from '../account/AccountIdRoute';
import type { JsonRepresentation } from '../InteractionUtil';
import type {
  JsonInteractionHandler,
  JsonInteractionHandlerInput,

} from '../JsonInteractionHandler';
import { InteractionRouteHandler } from './InteractionRouteHandler';

/**
 * An {@link InteractionRouteHandler} specifically for an {@link AccountIdRoute}.
 * If there is no account ID, implying the user is not logged in,
 * an {@link UnauthorizedHttpError} will be thrown.
 * If there is an account ID, but it does not match the one in target resource,
 * a {@link ForbiddenHttpError} will be thrown.
 */
export class AuthorizedRouteHandler extends InteractionRouteHandler<AccountIdRoute> {
  private readonly logger = getLoggerFor(this);

  public constructor(route: AccountIdRoute, source: JsonInteractionHandler) {
    super(route, source);
  }

  public async handle(input: JsonInteractionHandlerInput): Promise<JsonRepresentation> {
    const { target, accountId } = input;

    if (!accountId) {
      this.logger.warn(`Trying to access ${target.path} without authorization`);
      throw new UnauthorizedHttpError();
    }

    const match = this.route.matchPath(target.path)!;
    if (match.accountId !== accountId) {
      this.logger.warn(`Trying to access ${target.path} with wrong authorization: ${accountId}`);
      throw new ForbiddenHttpError();
    }

    return this.source.handle(input);
  }
}

import { InternalServerError } from '../../../util/errors/InternalServerError';
import { ensureTrailingSlash, joinUrl } from '../../../util/PathUtil';
import type { InteractionRoute } from './InteractionRoute';

/**
 * An {@link InteractionRoute} for routes that have a dynamic identifier in their path.
 */
export class IdInteractionRoute<TBase extends string, TId extends string> implements InteractionRoute<TBase | TId> {
  private readonly base: InteractionRoute<TBase>;
  private readonly idName: TId;
  private readonly ensureSlash: boolean;
  private readonly matchRegex: RegExp;

  public constructor(base: InteractionRoute<TBase>, idName: TId, ensureSlash = true) {
    this.base = base;
    this.idName = idName;
    this.ensureSlash = ensureSlash;
    this.matchRegex = ensureSlash ? /(.*\/)([^/]+)\/$/u : /(.*\/)([^/]+)$/u;
  }

  public getPath(parameters?: Record<TBase | TId, string>): string {
    const id = parameters?.[this.idName];
    if (!id) {
      throw new InternalServerError(`Missing ${this.idName} from getPath call. This implies a misconfigured path.`);
    }

    const path = this.base.getPath(parameters);
    return joinUrl(path, this.ensureSlash ? ensureTrailingSlash(id) : id);
  }

  public matchPath(path: string): Record<TBase | TId, string> | undefined {
    const match = this.matchRegex.exec(path);

    if (!match) {
      return;
    }

    const id = match[2];
    const head = match[1];

    const baseParameters = this.base.matchPath(head);

    if (!baseParameters) {
      return;
    }

    // Cast needed because TS always assumes type is { [x: string]: string; } when using [] like this
    // https://github.com/microsoft/TypeScript/issues/13948
    return { ...baseParameters, [this.idName]: id } as Record<TBase | TId, string>;
  }
}

/**
 * The parameters supported for the given route.
 */
export type RouteParameter<TRoute extends InteractionRoute<string>> =
  TRoute extends InteractionRoute<infer TParam> ? TParam : never;

/**
 * A route that adds a parameter to an existing route type.
 */
export type ExtendedRoute<TRoute extends InteractionRoute<string>, TParam extends string> =
  InteractionRoute<RouteParameter<TRoute> | TParam>;

/**
 * Routes are used to handle the pathing for API calls.
 *
 * They can have dynamic values in the paths they support.
 * Typings are used to indicate the keys used to indicate what the corresponding values are.
 */
export interface InteractionRoute<T extends string = never> {
  /**
   * Returns the path that is the result of having the specified values for the dynamic parameters.
   *
   * Will throw an error in case the input `parameters` object is missing one of the expected keys.
   *
   * @param parameters - Values for the dynamic parameters.
   */
  getPath: (parameters?: Record<T, string>) => string;

  /**
   * Checks if the provided path matches the route (pattern).
   *
   * The result will be `undefined` if there is no match.
   *
   * If there is a match the result object will have the corresponding values for all the parameters.
   *
   * @param path - The path to verify.
   */
  matchPath: (path: string) => Record<T, string> | undefined;
}

import { NotFoundHttpError } from '../../../util/errors/NotFoundHttpError';
import type { JsonRepresentation } from '../InteractionUtil';
import type { JsonInteractionHandlerInput } from '../JsonInteractionHandler';
import { JsonInteractionHandler } from '../JsonInteractionHandler';
import type { InteractionRoute } from './InteractionRoute';

/**
 * InteractionHandler that only accepts input of which the target matches the stored route.
 *
 * Rejects operations that target a different route,
 * otherwise the input parameters are passed to the source handler.
 */
export class InteractionRouteHandler<T extends InteractionRoute<string>> extends JsonInteractionHandler {
  protected readonly route: T;
  protected readonly source: JsonInteractionHandler;

  public constructor(route: T, source: JsonInteractionHandler) {
    super();
    this.route = route;
    this.source = source;
  }

  public async canHandle(input: JsonInteractionHandlerInput): Promise<void> {
    const { target } = input;

    if (!this.route.matchPath(target.path)) {
      throw new NotFoundHttpError();
    }
    await this.source.canHandle(input);
  }

  public async handle(input: JsonInteractionHandlerInput): Promise<JsonRepresentation> {
    return this.source.handle(input);
  }
}

import { InternalServerError } from '../../../util/errors/InternalServerError';
import { ensureTrailingSlash, joinUrl, trimLeadingSlashes } from '../../../util/PathUtil';
import type { InteractionRoute } from './InteractionRoute';

/**
 * A route that is relative to another route.
 * The relative path will be joined to the input base,
 * which can either be an absolute URL or an InteractionRoute of which the path will be used.
 */
export class RelativePathInteractionRoute<TBase extends string> implements InteractionRoute<TBase> {
  private readonly base: InteractionRoute<TBase>;
  private readonly relativePath: string;

  public constructor(base: InteractionRoute<TBase>, relativePath: string, ensureSlash = true) {
    this.base = base;
    this.relativePath = trimLeadingSlashes(relativePath);
    if (ensureSlash) {
      this.relativePath = ensureTrailingSlash(this.relativePath);
    }
  }

  public getPath(parameters?: Record<TBase, string>): string {
    const path = this.base.getPath(parameters);
    if (!path.endsWith('/')) {
      throw new InternalServerError(
        `Expected ${path} to end on a slash so it could be extended. This indicates a configuration error.`,
      );
    }
    return joinUrl(path, this.relativePath);
  }

  public matchPath(path: string): Record<TBase, string> | undefined {
    if (!path.endsWith(this.relativePath)) {
      return;
    }

    const head = path.slice(0, -this.relativePath.length);

    return this.base.matchPath(head);
  }
}

import type { Json } from '../../util/Json';
import type { JsonRepresentation } from './InteractionUtil';
import { JsonInteractionHandler } from './JsonInteractionHandler';

/**
 * An {@link JsonInteractionHandler} that always returns the same JSON response on all requests.
 */
export class StaticInteractionHandler extends JsonInteractionHandler {
  private readonly response: Record<string, Json>;

  /**
   * @param response - @range {json}
   */
  public constructor(response: Record<string, Json>) {
    super();
    this.response = response;
  }

  public async handle(): Promise<JsonRepresentation> {
    return { json: this.response };
  }
}

import type { JsonRepresentation } from './InteractionUtil';
import type { JsonInteractionHandlerInput } from './JsonInteractionHandler';
import { JsonInteractionHandler } from './JsonInteractionHandler';

const INTERNAL_API_VERSION = '0.5';

/**
 * Adds the current version of the API to the JSON output.
 * This version number should be updated every time the API changes.
 */
export class VersionHandler extends JsonInteractionHandler {
  private readonly source: JsonInteractionHandler;

  public constructor(source: JsonInteractionHandler) {
    super();
    this.source = source;
  }

  public async canHandle(input: JsonInteractionHandlerInput): Promise<void> {
    await this.source.canHandle(input);
  }

  public async handle(input: JsonInteractionHandlerInput): Promise<JsonRepresentation> {
    const result = await this.source.handle(input);
    result.json.version = INTERNAL_API_VERSION;
    return result;
  }
}

import { MethodNotAllowedHttpError } from '../../util/errors/MethodNotAllowedHttpError';
import type { JsonRepresentation } from './InteractionUtil';
import type { JsonInteractionHandlerInput } from './JsonInteractionHandler';
import { JsonInteractionHandler } from './JsonInteractionHandler';
import type { JsonView } from './JsonView';

/**
 * Utility class for the common case of a {@link JsonInteractionHandler}
 * describing the expected input on a GET request which is needed to do a POST request.
 *
 * Returns the result of a {@link JsonView} on GET requests.
 * POST requests are sent to the {@link JsonInteractionHandler}.
 * Other methods will be rejected.
 */
export class ViewInteractionHandler extends JsonInteractionHandler {
  private readonly source: JsonInteractionHandler & JsonView;

  public constructor(source: JsonInteractionHandler & JsonView) {
    super();
    this.source = source;
  }

  public async canHandle(input: JsonInteractionHandlerInput): Promise<void> {
    const { method } = input;
    if (method !== 'GET' && method !== 'POST') {
      throw new MethodNotAllowedHttpError([ method ], 'Only GET/POST requests are supported.');
    }

    if (method === 'POST') {
      await this.source.canHandle(input);
    }
  }

  public async handle(input: JsonInteractionHandlerInput): Promise<JsonRepresentation> {
    if (input.method === 'GET') {
      return this.source.getView(input);
    }
    return this.source.handle(input);
  }
}

import { object } from 'yup';
import { getLoggerFor } from '../../../logging/LogUtil';
import type { StorageLocationStrategy } from '../../../server/description/StorageLocationStrategy';
import { BadRequestHttpError } from '../../../util/errors/BadRequestHttpError';
import type { OwnershipValidator } from '../../ownership/OwnershipValidator';
import { assertAccountId } from '../account/util/AccountUtil';
import type { JsonRepresentation } from '../InteractionUtil';
import { JsonInteractionHandler } from '../JsonInteractionHandler';
import type { JsonInteractionHandlerInput } from '../JsonInteractionHandler';
import type { JsonView } from '../JsonView';
import type { PodStore } from '../pod/util/PodStore';
import { parseSchema, URL_SCHEMA, validateWithError } from '../YupUtil';
import type { WebIdStore } from './util/WebIdStore';
import type { WebIdLinkRoute } from './WebIdLinkRoute';

const inSchema = object({
  webId: URL_SCHEMA.required(),
});

type OutType = {
  resource: string;
  webId: string;
  oidcIssuer: string;
};

export interface LinkWebIdHandlerArgs {
  /**
   * Base URL of the server.
   * Used to indicate in the response what the object of the `solid:oidcIssuer` triple should be.
   */
  baseUrl: string;
  /**
   * Validates whether the user trying to link the WebID is the actual owner of that WebID.
   */
  ownershipValidator: OwnershipValidator;
  /**
   * Pod store to find out if the account created the pod containing the WebID.
   */
  podStore: PodStore;
  /**
   * WebID store to store WebID links.
   */
  webIdStore: WebIdStore;
  /**
   * Route used to generate the WebID link resource URL.
   */
  webIdRoute: WebIdLinkRoute;
  /**
   * Before calling the {@link OwnershipValidator}, we first check if the target WebID is in a pod owned by the user.
   */
  storageStrategy: StorageLocationStrategy;
}

/**
 * Handles the linking of WebIDs to account,
 * thereby registering them to the server IDP.
 */
export class LinkWebIdHandler extends JsonInteractionHandler<OutType> implements JsonView {
  private readonly logger = getLoggerFor(this);

  private readonly baseUrl: string;
  private readonly ownershipValidator: OwnershipValidator;
  private readonly podStore: PodStore;
  private readonly webIdStore: WebIdStore;
  private readonly webIdRoute: WebIdLinkRoute;
  private readonly storageStrategy: StorageLocationStrategy;

  public constructor(args: LinkWebIdHandlerArgs) {
    super();
    this.baseUrl = args.baseUrl;
    this.ownershipValidator = args.ownershipValidator;
    this.podStore = args.podStore;
    this.webIdStore = args.webIdStore;
    this.webIdRoute = args.webIdRoute;
    this.storageStrategy = args.storageStrategy;
  }

  public async getView({ accountId }: JsonInteractionHandlerInput): Promise<JsonRepresentation> {
    assertAccountId(accountId);
    const webIdLinks: Record<string, string> = {};
    for (const { id, webId } of await this.webIdStore.findLinks(accountId)) {
      webIdLinks[webId] = this.webIdRoute.getPath({ accountId, webIdLink: id });
    }
    return { json: { ...parseSchema(inSchema), webIdLinks }};
  }

  public async handle({ accountId, json }: JsonInteractionHandlerInput): Promise<JsonRepresentation<OutType>> {
    assertAccountId(accountId);

    const { webId } = await validateWithError(inSchema, json);

    if (await this.webIdStore.isLinked(webId, accountId)) {
      this.logger.warn(`Trying to link WebID ${webId} to account ${accountId} which already has this link`);
      throw new BadRequestHttpError(`${webId} is already registered to this account.`);
    }

    // Only need to check ownership if the account did not create the pod
    let isCreator = false;
    try {
      const baseUrl = await this.storageStrategy.getStorageIdentifier({ path: webId });
      const pod = await this.podStore.findByBaseUrl(baseUrl.path);
      isCreator = accountId === pod?.accountId;
    } catch {
      // Probably a WebID not hosted on the server
    }

    if (!isCreator) {
      await this.ownershipValidator.handleSafe({ webId });
    }

    const webIdLink = await this.webIdStore.create(webId, accountId);
    const resource = this.webIdRoute.getPath({ accountId, webIdLink });

    return { json: { resource, webId, oidcIssuer: this.baseUrl }};
  }
}

import type { EmptyObject } from '../../../util/map/MapUtil';
import { parsePath, verifyAccountId } from '../account/util/AccountUtil';
import type { JsonRepresentation } from '../InteractionUtil';
import type { JsonInteractionHandlerInput } from '../JsonInteractionHandler';
import { JsonInteractionHandler } from '../JsonInteractionHandler';
import type { WebIdStore } from './util/WebIdStore';
import type { WebIdLinkRoute } from './WebIdLinkRoute';

/**
 * Allows users to remove WebIDs linked to their account.
 */
export class UnlinkWebIdHandler extends JsonInteractionHandler<EmptyObject> {
  private readonly webIdStore: WebIdStore;
  private readonly webIdRoute: WebIdLinkRoute;

  public constructor(webIdStore: WebIdStore, webIdRoute: WebIdLinkRoute) {
    super();
    this.webIdStore = webIdStore;
    this.webIdRoute = webIdRoute;
  }

  public async handle({ target, accountId }: JsonInteractionHandlerInput): Promise<JsonRepresentation<EmptyObject>> {
    const match = parsePath(this.webIdRoute, target.path);

    const link = await this.webIdStore.get(match.webIdLink);
    verifyAccountId(accountId, link?.accountId);

    await this.webIdStore.delete(match.webIdLink);

    return { json: {}};
  }
}

import { Initializer } from '../../../../init/Initializer';
import { getLoggerFor } from '../../../../logging/LogUtil';
import { BadRequestHttpError } from '../../../../util/errors/BadRequestHttpError';
import { createErrorMessage } from '../../../../util/errors/ErrorUtil';
import { InternalServerError } from '../../../../util/errors/InternalServerError';
import { ACCOUNT_TYPE } from '../../account/util/LoginStorage';
import type { AccountLoginStorage } from '../../account/util/LoginStorage';
import type { WebIdStore } from './WebIdStore';

export const WEBID_STORAGE_TYPE = 'webIdLink';
export const WEBID_STORAGE_DESCRIPTION = {
  webId: 'string',
  accountId: `id:${ACCOUNT_TYPE}`,
} as const;

/**
 * A {@link WebIdStore} using a {@link AccountLoginStorage} to store the links.
 * Needs to be initialized before it can be used.
 */
export class BaseWebIdStore extends Initializer implements WebIdStore {
  private readonly logger = getLoggerFor(this);

  private readonly storage: AccountLoginStorage<{ [WEBID_STORAGE_TYPE]: typeof WEBID_STORAGE_DESCRIPTION }>;
  private initialized = false;

  // Wrong typings to prevent Components.js typing issues
  public constructor(storage: AccountLoginStorage<Record<string, never>>) {
    super();
    this.storage = storage as unknown as typeof this.storage;
  }

  // Initialize the type definitions
  public async handle(): Promise<void> {
    if (this.initialized) {
      return;
    }
    try {
      await this.storage.defineType(WEBID_STORAGE_TYPE, WEBID_STORAGE_DESCRIPTION, false);
      await this.storage.createIndex(WEBID_STORAGE_TYPE, 'accountId');
      await this.storage.createIndex(WEBID_STORAGE_TYPE, 'webId');
      this.initialized = true;
    } catch (cause: unknown) {
      throw new InternalServerError(
        `Error defining WebID links in storage: ${createErrorMessage(cause)}`,
        { cause },
      );
    }
  }

  public async get(id: string): Promise<{ accountId: string; webId: string } | undefined> {
    return this.storage.get(WEBID_STORAGE_TYPE, id);
  }

  public async isLinked(webId: string, accountId: string): Promise<boolean> {
    const result = await this.storage.find(WEBID_STORAGE_TYPE, { webId, accountId });
    return result.length > 0;
  }

  public async findLinks(accountId: string): Promise<{ id: string; webId: string }[]> {
    return (await this.storage.find(WEBID_STORAGE_TYPE, { accountId }))
      .map(({ id, webId }): { id: string; webId: string } => ({ id, webId }));
  }

  public async create(webId: string, accountId: string): Promise<string> {
    if (await this.isLinked(webId, accountId)) {
      this.logger.warn(`Trying to link WebID ${webId} which is already linked to this account ${accountId}`);
      throw new BadRequestHttpError(`${webId} is already registered to this account.`);
    }

    const result = await this.storage.create(WEBID_STORAGE_TYPE, { webId, accountId });

    this.logger.debug(`Linked WebID ${webId} to account ${accountId}`);

    return result.id;
  }

  public async delete(linkId: string): Promise<void> {
    this.logger.debug(`Deleting WebID link with ID ${linkId}`);
    return this.storage.delete(WEBID_STORAGE_TYPE, linkId);
  }
}

/**
 * Stores and updates WebID to Account links.
 */
export interface WebIdStore {
  /**
   * Finds the account and WebID of the link with the given ID.
   *
   * @param webId - ID of the link.
   */
  get: (linkId: string) => Promise<{ accountId: string; webId: string } | undefined>;

  /**
   * Determines if a WebID is linked to an account.
   *
   * @param webId - WebID to check.
   * @param accountId - ID of the account.
   */
  isLinked: (webId: string, accountId: string) => Promise<boolean>;

  /**
   * Finds all links associated with the given account.
   *
   * @param accountId - ID of the account.
   */
  findLinks: (accountId: string) => Promise<{ id: string; webId: string }[]>;

  /**
   * Creates a new WebID link for the given WebID and account.
   *
   * @param webId - WebID to link.
   * @param account - ID of the account to link the WebID to.
   *
   * @returns ID of the link.
   */
  create: (webId: string, accountId: string) => Promise<string>;

  /**
   * Deletes the link with the given ID
   *
   * @param linkId - ID of the link.
   */
  delete: (linkId: string) => Promise<void>;
}

