const DEFAULT_CONFIG = resolveModulePath('config/default.json');

const DEFAULT_CLI_RESOLVER = 'urn:solid-server-app-setup:default:CliResolver';
const DEFAULT_APP = 'urn:solid-server:default:App';

const CORE_CLI_PARAMETERS = {
  config: { type: 'array', alias: 'c', default: [ DEFAULT_CONFIG ], requiresArg: true },
  loggingLevel: { type: 'string', alias: 'l', default: 'info', requiresArg: true, choices: LOG_LEVELS },
  mainModulePath: { type: 'string', alias: 'm', requiresArg: true },
} as const;

const ENV_VAR_PREFIX = 'CSS';

/**
 * Parameters that can be used to instantiate the server through code.
 */
export interface AppRunnerInput {
  /**
   * Properties that will be used when building the Components.js manager.
   * Default values:
   *  - `typeChecking`: `false`, as the server components would otherwise error.
   *  - `mainModulePath`: `@css:`, which resolves to the directory of the CSS package.
   *                      This is useful for packages that depend on the CSS
   *                      but do not create any new modules themselves.
   */
  loaderProperties?: Partial<IComponentsManagerBuilderOptions<App>>;
  /**
   * Path to the server config file(s). Defaults to `@css:config/default.json`.
   */
  config?: string | string[];
  /**
   * Values to apply to the Components.js variables.
   * These are the variables CLI values will be converted to.
   * The keys should be the variable URIs.
   * E.g.: `{ 'urn:solid-server:default:variable:rootFilePath': '.data' }`.
   */
  variableBindings?: VariableBindings;
  /**
   * CLI argument names and their corresponding values.
   * E.g.: `{ rootFilePath: '.data' }`.
   * Abbreviated parameter names can not be used, so `{ f: '.data' }` would not work.
   *
   * In case both `shorthand` and `variableBindings` have entries that would result in a value for the same variable,
   * `variableBindings` has priority.
   */
  shorthand?: Shorthand;
  /**
   * An array containing CLI arguments passed to start the process.
   * Entries here have the lowest priority for assigning values to variables.
   */
  argv?: string[];
}

/**
 * A class that can be used to instantiate and start a server based on a Component.js configuration.
 */
export class AppRunner {
  private readonly logger = getLoggerFor(this);

  /**
   * Starts the server with a given config.
   *
   * @param input - All values necessary to configure the server.
   */
  public async run(input: AppRunnerInput): Promise<void> {
    const app = await this.create(input);
    await app.start();
  }

  /**
   * Returns an App object, created with the given config, that can start and stop the Solid server.
   *
   * @param input - All values necessary to configure the server.
   */
  public async create(input: AppRunnerInput = {}): Promise<App> {
    const loaderProperties = {
      typeChecking: false,
      mainModulePath: '@css:',
      dumpErrorState: false,
      ...input.loaderProperties,
    };
    // Expand mainModulePath as needed
    loaderProperties.mainModulePath = resolveAssetPath(loaderProperties.mainModulePath);

    // Potentially expand config paths as needed
    let configs = input.config ?? [ '@css:config/default.json' ];
    configs = (Array.isArray(configs) ? configs : [ configs ]).map(resolveAssetPath);

    let componentsManager: ComponentsManager<App | CliResolver>;
    try {
      componentsManager = await this.createComponentsManager<App>(loaderProperties, configs);
    } catch (error: unknown) {
      this.resolveError(`Could not build the config files from ${configs.join(',')}`, error);
    }

    const cliResolver = await this.createCliResolver(componentsManager as ComponentsManager<CliResolver>);
    let extracted: Shorthand = {};
    if (input.argv) {
      extracted = await this.extractShorthand(cliResolver.cliExtractor, input.argv);
    }
    const parsedVariables = await this.resolveShorthand(cliResolver.shorthandResolver, {
      ...extracted,
      ...input.shorthand,
    });

    // Create the application using the translated variable values.
    // `variableBindings` override those resolved from the `shorthand` input.
    return this.createApp(
      componentsManager as ComponentsManager<App>,
      { ...parsedVariables, ...input.variableBindings },
    );
  }

  /**
   * Starts the server as a command-line application.
   * Will exit the process on failure.
   *
   * Made non-async to lower the risk of unhandled promise rejections.
   * This is only relevant when this is used to start as a Node.js application on its own,
   * if you use this as part of your code you probably want to use the async version.
   *
   * @param argv - Input parameters.
   * @param argv.argv - Command line arguments.
   * @param argv.stderr - Stream that should be used to output errors before the logger is enabled.
   */
  public runCliSync({ argv, stderr = process.stderr }: { argv?: CliArgv; stderr?: WriteStream }): void {
    this.runCli(argv).catch((error: unknown): never => {
      stderr.write(createErrorMessage(error));
      // eslint-disable-next-line unicorn/no-process-exit
      process.exit(1);
    });
  }

  /**
   * Starts the server as a command-line application.
   *
   * @param argv - Command line arguments.
   */
  public async runCli(argv?: CliArgv): Promise<void> {
    const app = await this.createCli(argv);
    try {
      await app.start();
    } catch (error: unknown) {
      this.logger.error(`Could not start the server: ${createErrorMessage(error)}`);
      this.resolveError('Could not start the server', error);
    }
  }

  /**
   * Returns an App object, created by parsing the Command line arguments, that can start and stop the Solid server.
   * Will exit the process on failure.
   *
   * @param argv - Command line arguments.
   */
  public async createCli(argv: CliArgv = process.argv): Promise<App> {
    // Parse only the core CLI arguments needed to load the configuration
    let yargv = yargs(argv.slice(2))
      .usage('node ./bin/server.js [args]')
      .options(CORE_CLI_PARAMETERS)
      // We disable help here as it would only show the core parameters
      .help(false)
      // We also read from environment variables
      .env(ENV_VAR_PREFIX);

    const settings = await this.getPackageSettings();
    if (typeof settings !== 'undefined') {
      yargv = yargv.default<object>(settings);
    }

    const params = await yargv.parse();

    const loaderProperties: AppRunnerInput['loaderProperties'] = {
      mainModulePath: params.mainModulePath,
      logLevel: params.loggingLevel,
    };

    return this.create({
      loaderProperties,
      config: params.config as string[],
      argv,
      shorthand: settings,
    });
  }

  /**
   * Retrieves settings from package.json or configuration file when
   * part of an npm project.
   *
   * @returns The settings defined in the configuration file
   */
  public async getPackageSettings(): Promise<undefined | Record<string, unknown>> {
    // Only try and retrieve config file settings if there is a package.json in the
    // scope of the current directory
    const packageJsonPath = joinFilePath(process.cwd(), 'package.json');
    if (!existsSync(packageJsonPath)) {
      return;
    }

    // First see if there is a dedicated .json configuration file
    const cssConfigPath = joinFilePath(process.cwd(), '.community-solid-server.config.json');
    if (existsSync(cssConfigPath)) {
      return readJSON(cssConfigPath) as Promise<Record<string, unknown>>;
    }

    // Next see if there is a dedicated .js file
    const cssConfigPathJs = joinFilePath(process.cwd(), '.community-solid-server.config.js');
    if (existsSync(cssConfigPathJs)) {
      return import(cssConfigPathJs) as Promise<Record<string, unknown>>;
    }

    // Finally try to read from the config.community-solid-server
    // field in the root package.json
    const pkg = await readJSON(packageJsonPath) as { config?: Record<string, unknown> };
    if (typeof pkg.config?.['community-solid-server'] === 'object') {
      return pkg.config['community-solid-server'] as Record<string, unknown>;
    }
  }

  /**
   * Creates the Components Manager that will be used for instantiating.
   */
  public async createComponentsManager<T>(
    loaderProperties: IComponentsManagerBuilderOptions<T>,
    configs: string[],
  ): Promise<ComponentsManager<T>> {
    const componentsManager = await ComponentsManager.build(loaderProperties);
    for (const config of configs) {
      await componentsManager.configRegistry.register(config);
    }
    return componentsManager;
  }

  /**
   * Instantiates the {@link CliResolver}.
   */
  private async createCliResolver(componentsManager: ComponentsManager<CliResolver>): Promise<CliResolver> {
    try {
      // Create a CliResolver, which combines a CliExtractor and a VariableResolver
      return await componentsManager.instantiate(DEFAULT_CLI_RESOLVER, {});
    } catch (error: unknown) {
      this.resolveError(`Could not create the CLI resolver`, error);
    }
  }

  /**
   * Uses the {@link CliExtractor} to convert the CLI args to a {@link Shorthand} object.
   */
  private async extractShorthand(cliExtractor: CliExtractor, argv: CliArgv): Promise<Shorthand> {
    try {
      // Convert CLI args to CLI bindings
      return await cliExtractor.handleSafe(argv);
    } catch (error: unknown) {
      this.resolveError(`Could not parse the CLI parameters`, error);
    }
  }

  /**
   * Uses the {@link ShorthandResolver} to convert {@link Shorthand} to {@link VariableBindings} .
   */
  private async resolveShorthand(shorthandResolver: ShorthandResolver, shorthand: Shorthand):
  Promise<VariableBindings> {
    try {
      // Convert CLI bindings into variable bindings
      return await shorthandResolver.handleSafe(shorthand);
    } catch (error: unknown) {
      this.resolveError(`Could not resolve the shorthand values`, error);
    }
  }

  /**
   * The second Components.js instantiation,
   * where the App is created and started using the variable mappings.
   */
  private async createApp(componentsManager: ComponentsManager<App>, variables: Record<string, unknown>): Promise<App> {
    let app: App;
    // Create the app
    try {
      app = await componentsManager.instantiate(DEFAULT_APP, { variables });
    } catch (error: unknown) {
      this.resolveError(`Could not create the server`, error);
    }

    // Ensure thread safety
    if (!app.clusterManager.isSingleThreaded()) {
      const violatingClasses = await listSingleThreadedComponents(componentsManager);
      if (violatingClasses.length > 0) {
        const verb = violatingClasses.length > 1 ? 'are' : 'is';
        const detailedError = new InternalServerError(
          `[${violatingClasses.join(', ')}] ${verb} not threadsafe and should not be run in multithreaded setups!`,
        );
        this.resolveError('Cannot run a singlethreaded-only component in a multithreaded setup!', detailedError);
      }
    }
    return app;
  }

  /**
   * Throws a new error that provides additional information through the extra message.
   * Also appends the stack trace to the message.
   * This is needed for errors that are thrown before the logger is created as we can't log those the standard way.
   */
  private resolveError(message: string, error: unknown): never {
    const errorMessage = `${message}\n${isError(error) ? error.stack : createErrorMessage(error)}\n`;
    throw new Error(errorMessage);
  }
}

import { getLoggerFor } from '../logging/LogUtil';
import type { KeyValueStorage } from '../storage/keyvalue/KeyValueStorage';
import { Initializer } from './Initializer';

/**
 * Stores the `baseUrl` value that was used to start the server
 * and warns the user in case it differs from the previous one.
 */
export class BaseUrlVerifier extends Initializer {
  private readonly baseUrl: string;
  private readonly storageKey: string;
  private readonly storage: KeyValueStorage<string, string>;

  private readonly logger = getLoggerFor(this);

  public constructor(baseUrl: string, storageKey: string, storage: KeyValueStorage<string, string>) {
    super();
    this.baseUrl = baseUrl;
    this.storageKey = storageKey;
    this.storage = storage;
  }

  public async handle(): Promise<void> {
    const previousValue = await this.storage.get(this.storageKey);
    if (previousValue && this.baseUrl !== previousValue) {
      this.logger.warn(`The server is being started with a base URL of ${this.baseUrl
      } while it was previously started with ${previousValue
      }. Resources generated with the previous server instance, such as a WebID, might no longer work correctly.`);
    }
    await this.storage.set(this.storageKey, this.baseUrl);
  }
}

import type { Arguments, Argv, Options } from 'yargs';
import yargs from 'yargs';
import { CliExtractor } from './CliExtractor';

// This type exists to prevent Components.js from erroring on an unknown type
export type YargsOptions = Options;

/**
 * This class exists as wrapper around a yargs Options object,
 * thereby allowing us to create these in a Components.js configuration.
 *
 * Format details can be found at https://yargs.js.org/docs/#api-reference-optionskey-opt
 */
export class YargsParameter {
  public readonly name: string;
  public readonly options: YargsOptions;

  /**
   * @param name - Name of the parameter. Corresponds to the first parameter passed to the `yargs.options` function.
   * @param options - Options for a single parameter that should be parsed. @range {json}
   */
  public constructor(name: string, options: Record<string, unknown>) {
    this.name = name;
    this.options = options;
  }
}

export interface CliOptions {
  // Usage string printed in case of CLI errors
  usage?: string;
  // Errors on unknown CLI parameters when enabled.
  // @see https://yargs.js.org/docs/#api-reference-strictenabledtrue
  strictMode?: boolean;
  // Loads CLI args from environment variables when enabled.
  // @see http://yargs.js.org/docs/#api-reference-envprefix
  loadFromEnv?: boolean;
  // Prefix to be used when `loadFromEnv` is enabled.
  // @see http://yargs.js.org/docs/#api-reference-envprefix
  envVarPrefix?: string;
}

/**
 * Parses CLI args using the yargs library.
 * Specific settings can be enabled through the provided options.
 */
export class YargsCliExtractor extends CliExtractor {
  protected readonly yargsArgOptions: Record<string, YargsOptions>;
  protected readonly yargvOptions: CliOptions;

  /**
   * @param parameters - Parameters that should be parsed from the CLI.
   * @param options - Additional options to configure yargs. @range {json}
   *
   * JSON parameters cannot be optional due to https://github.com/LinkedSoftwareDependencies/Components-Generator.js/issues/87
   */
  public constructor(parameters: YargsParameter[], options: CliOptions) {
    super();
    this.yargsArgOptions = Object.fromEntries(
      parameters.map((entry): [string, YargsOptions] => [ entry.name, entry.options ]),
    );
    this.yargvOptions = { ...options };
  }

  public async handle(argv: readonly string[]): Promise<Arguments> {
    return this.createYArgv(argv).parse();
  }

  /**
   * Creates the yargs Argv object based on the input CLI argv.
   */
  private createYArgv(argv: readonly string[]): Argv {
    let yArgv = yargs(argv.slice(2));

    // Error and show help message when multiple values were provided
    // for a non Array type parameter
    yArgv.check((args): boolean => {
      for (const [ name, options ] of Object.entries(this.yargsArgOptions)) {
        if (options.type !== 'array' && Array.isArray(args[name])) {
          throw new Error(
            `Multiple values for --${name} (-${options.alias as string}) were provided where only one is allowed`,
          );
        }
      }
      return true;
    });

    if (this.yargvOptions.usage !== undefined) {
      yArgv = yArgv.usage(this.yargvOptions.usage);
    }
    if (this.yargvOptions.strictMode) {
      yArgv = yArgv.strict();
    }
    if (this.yargvOptions.loadFromEnv) {
      yArgv = yArgv.env(this.yargvOptions.envVarPrefix ?? '');
    }
    return yArgv.options(this.yargsArgOptions);
  }
}

import type { CliExtractor } from './cli/CliExtractor';
import type { ShorthandResolver } from './variables/ShorthandResolver';

/**
 * A class that combines a {@link CliExtractor} and a {@link ShorthandResolver}.
 * Mainly exists so both such classes can be generated in a single Components.js instance.
 */
export class CliResolver {
  public readonly cliExtractor: CliExtractor;
  public readonly shorthandResolver: ShorthandResolver;

  public constructor(cliExtractor: CliExtractor, shorthandResolver: ShorthandResolver) {
    this.cliExtractor = cliExtractor;
    this.shorthandResolver = shorthandResolver;
  }
}

import type { Worker } from 'node:cluster';
import cluster from 'node:cluster';
import { cpus } from 'node:os';
import { getLoggerFor } from '../../logging/LogUtil';
import { InternalServerError } from '../../util/errors/InternalServerError';

/**
 * Different cluster modes.
 */
enum ClusterMode {
  /** Scales in relation to `core_count`. */
  autoScale,
  /** Single threaded mode, no clustering */
  singleThreaded,
  /** Fixed amount of workers being forked. (limited to core_count) */
  fixed,
}

/**
 * Convert workers amount to {@link ClusterMode}
 *
 * @param workers - Amount of workers
 *
 * @returns ClusterMode enum value
 */
function toClusterMode(workers: number): ClusterMode {
  if (workers <= 0) {
    return ClusterMode.autoScale;
  }
  if (workers === 1) {
    return ClusterMode.singleThreaded;
  }
  return ClusterMode.fixed;
}

/**
 * This class is responsible for deciding how many affective workers are needed.
 * It also contains the logic for respawning workers when they are killed by the os.
 *
 * The workers values are interpreted as follows:
 * value | actual workers |
 * ------|--------------|
 * `-m` | `num_cores - m` workers _(autoscale)_ (`m < num_cores`) |
 * `-1` | `num_cores - 1` workers _(autoscale)_ |
 * `0` | `num_cores` workers _(autoscale)_ |
 * `1` | `single threaded mode` _(default)_ |
 * `n` | `n` workers |
 */
export class ClusterManager {
  private readonly logger = getLoggerFor(this);
  private readonly workers: number;
  private readonly clusterMode: ClusterMode;

  public constructor(workers: number) {
    const cores = cpus().length;

    if (workers <= -cores) {
      throw new InternalServerError('Invalid workers value (should be in the interval ]-num_cores, +∞).');
    }

    this.workers = toClusterMode(workers) === ClusterMode.autoScale ? cores + workers : workers;
    this.clusterMode = toClusterMode(this.workers);
  }

  /**
   * Spawn all required workers.
   */
  public spawnWorkers(): void {
    let counter = 0;
    this.logger.info(`Setting up ${this.workers} workers`);

    for (let i = 0; i < this.workers; i++) {
      cluster.fork().on('message', (msg: string): void => {
        this.logger.info(msg);
      });
    }

    cluster.on('online', (worker: Worker): void => {
      this.logger.info(`Worker ${worker.process.pid} is listening`);
      counter += 1;
      if (counter === this.workers) {
        this.logger.info(`All ${this.workers} requested workers have been started.`);
      }
    });

    cluster.on('exit', (worker: Worker, code: number, signal: string): void => {
      this.logger.warn(`Worker ${worker.process.pid} died with code ${code} and signal ${signal}`);
      this.logger.warn('Starting a new worker');
      cluster.fork().on('message', (msg: string): void => {
        this.logger.info(msg);
      });
    });
  }

  /**
   * Check whether the CSS server was booted in single threaded mode.
   *
   * @returns True is single threaded.
   */
  public isSingleThreaded(): boolean {
    return this.clusterMode === ClusterMode.singleThreaded;
  }

  /**
   * Whether the calling process is the primary process.
   *
   * @returns True if primary
   */
  public isPrimary(): boolean {
    return cluster.isPrimary;
  }

  /**
   * Whether the calling process is a worker process.
   *
   * @returns True if worker
   */
  public isWorker(): boolean {
    return cluster.isWorker;
  }
}

import type { ComponentsManager } from 'componentsjs';
import { PrefetchedDocumentLoader } from 'componentsjs';
import { ContextParser } from 'jsonld-context-parser';
import { InternalServerError } from '../../util/errors/InternalServerError';
import { readPackageJson } from '../../util/PathUtil';

/**
 * Indicates a class is only meant to work in singlethreaded setups and is thus not threadsafe.
 */
export interface SingleThreaded {}

/**
 * Convert an exported interface name to the properly expected Components.js type URI.
 *
 * @param componentsManager - The currently used ComponentsManager
 * @param interfaceName - An interface name
 *
 * @returns A Components.js type URI
 */
export async function toComponentsJsType<T>(componentsManager: ComponentsManager<T>, interfaceName: string):
Promise<string> {
  const pkg = await readPackageJson();
  const contextParser = new ContextParser({
    documentLoader: new PrefetchedDocumentLoader({ contexts: componentsManager.moduleState.contexts }),
    skipValidation: true,
  });
  // The keys of the package.json `lsd:contexts` array contains all the IRIs of the relevant contexts;
  const lsdContexts = Object.keys(pkg['lsd:contexts'] as Record<string, string>);
  // Feed the lsd:context IRIs to the ContextParser
  const cssContext = await contextParser.parse(lsdContexts);
  // We can now expand a simple interface name, to its full Components.js type identifier.
  const interfaceIRI = cssContext.expandTerm(interfaceName, true);

  if (!interfaceIRI) {
    throw new InternalServerError(`Could not expand ${interfaceName} to IRI!`);
  }
  return interfaceIRI;
}

/**
 * Will list class names of components instantiated implementing the {@link SingleThreaded}
 * interface while the application is being run in multithreaded mode.
 *
 * @param componentsManager - The componentsManager being used to set up the application
 */
export async function listSingleThreadedComponents<T>(componentsManager: ComponentsManager<T>): Promise<string[]> {
  const interfaceType = await toComponentsJsType(componentsManager, 'SingleThreaded');
  const violatingClasses: string[] = [];

  // Loop through all instantiated Resources
  for (const resource of componentsManager.getInstantiatedResources()) {
    // If implementing interfaceType, while not being the interfaceType itself.
    if (resource?.isA(interfaceType) && resource.value !== interfaceType) {
      // Part after the # in an IRI is the actual class name
      const name = resource.property?.type?.value?.split('#')?.[1];
      violatingClasses.push(name);
    }
  }
  return violatingClasses;
}

import { Initializer } from '../Initializer';
import type { ClusterManager } from './ClusterManager';

/**
 * Spawns the necessary workers when starting in multithreaded mode.
 */
export class WorkerManager extends Initializer {
  private readonly clusterManager: ClusterManager;

  public constructor(clusterManager: ClusterManager) {
    super();
    this.clusterManager = clusterManager;
  }

  public async handle(): Promise<void> {
    if (!this.clusterManager.isSingleThreaded()) {
      this.clusterManager.spawnWorkers();
    }
  }
}

import { getLoggerFor } from '../logging/LogUtil';
import type { ComponentsJsFactory } from '../pods/generate/ComponentsJsFactory';
import { TEMPLATE, TEMPLATE_VARIABLE } from '../pods/generate/variables/Variables';
import type { KeyValueStorage } from '../storage/keyvalue/KeyValueStorage';
import type { ResourceStore } from '../storage/ResourceStore';
import { Initializer } from './Initializer';

/**
 * Initializes all pods that have been stored and loads them in memory.
 * This reads the pod settings from a permanent storage and uses those
 * to create the corresponding ResourceStores in memory,
 * so this is required every time the server starts.
 *
 * Part of the dynamic pod creation.
 * Reads the contents from the configuration storage, uses those values to instantiate ResourceStores,
 * and then adds them to the routing storage.
 *
 * @see {@link ConfigPodManager}, {@link TemplatedPodGenerator}, {@link BaseUrlRouterRule}
 */
export class ConfigPodInitializer extends Initializer {
  protected readonly logger = getLoggerFor(this);
  private readonly storeFactory: ComponentsJsFactory;
  private readonly configStorage: KeyValueStorage<string, unknown>;
  private readonly routingStorage: KeyValueStorage<string, ResourceStore>;

  public constructor(
    storeFactory: ComponentsJsFactory,
    configStorage: KeyValueStorage<string, unknown>,
    routingStorage: KeyValueStorage<string, ResourceStore>,
  ) {
    super();
    this.storeFactory = storeFactory;
    this.configStorage = configStorage;
    this.routingStorage = routingStorage;
  }

  public async handle(): Promise<void> {
    let count = 0;
    for await (const [ path, value ] of this.configStorage.entries()) {
      const config = value as NodeJS.Dict<string>;
      const store: ResourceStore =
        await this.storeFactory.generate(config[TEMPLATE_VARIABLE.templateConfig]!, TEMPLATE.ResourceStore, config);
      await this.routingStorage.set(path, store);
      this.logger.debug(`Initialized pod at ${path}`);
      count += 1;
    }
    this.logger.info(`Initialized ${count} dynamic pods.`);
  }
}

import type { ResourceIdentifier } from '../http/representation/ResourceIdentifier';
import { getLoggerFor } from '../logging/LogUtil';
import type { ResourcesGenerator } from '../pods/generate/ResourcesGenerator';
import type { KeyValueStorage } from '../storage/keyvalue/KeyValueStorage';
import type { ResourceStore } from '../storage/ResourceStore';
import { createErrorMessage } from '../util/errors/ErrorUtil';
import { ensureTrailingSlash, joinUrl } from '../util/PathUtil';
import { Initializer } from './Initializer';

export interface ContainerInitializerArgs {
  /**
   * Base URL of the server.
   */
  baseUrl: string;
  /**
   * Relative path of the container.
   */
  path: string;
  /**
   * ResourceStore where the container should be stored.
   */
  store: ResourceStore;
  /**
   * Generator that should be used to generate container contents.
   */
  generator: ResourcesGenerator;
  /**
   * Key that is used to store the boolean in the storage indicating the container is initialized.
   */
  storageKey: string;
  /**
   * Used to store initialization status.
   */
  storage: KeyValueStorage<string, boolean>;
}

/**
 * Initializer that sets up a container.
 * Will copy all the files and folders in the given path to the corresponding documents and containers.
 */
export class ContainerInitializer extends Initializer {
  protected readonly logger = getLoggerFor(this);

  private readonly store: ResourceStore;
  private readonly containerId: ResourceIdentifier;
  private readonly generator: ResourcesGenerator;
  private readonly storageKey: string;
  private readonly storage: KeyValueStorage<string, boolean>;

  public constructor(args: ContainerInitializerArgs) {
    super();
    this.containerId = { path: ensureTrailingSlash(joinUrl(args.baseUrl, args.path)) };
    this.store = args.store;
    this.generator = args.generator;
    this.storageKey = args.storageKey;
    this.storage = args.storage;
  }

  public async handle(): Promise<void> {
    this.logger.info(`Initializing container ${this.containerId.path}`);
    const resources = this.generator.generate(this.containerId, {});
    let count = 0;
    for await (const { identifier: resourceId, representation } of resources) {
      try {
        await this.store.setRepresentation(resourceId, representation);
        count += 1;
      } catch (error: unknown) {
        this.logger.warn(`Failed to create resource ${resourceId.path}: ${createErrorMessage(error)}`);
      }
    }
    this.logger.info(`Initialized container ${this.containerId.path} with ${count} resources.`);

    // Mark the initialization as finished
    await this.storage.set(this.storageKey, true);
  }
}

/**
 * Allows for cleaning up an object and stopping relevant loops when the application needs to be stopped.
 * Use this interface to add finalization logic to classes that already extend some other type.
 * NOTE: classes without an existing extends-relation should extend from Finalizer instead!
 */
export interface Finalizable {
  finalize: () => Promise<void>;
}

import type { Finalizable } from './Finalizable';
import { Finalizer } from './Finalizer';

/**
 * Allows using a Finalizable as a Finalizer Handler.
 */
export class FinalizableHandler extends Finalizer {
  protected readonly finalizable: Finalizable;

  public constructor(finalizable: Finalizable) {
    super();
    this.finalizable = finalizable;
  }

  public async handle(): Promise<void> {
    return this.finalizable.finalize();
  }
}

import { AsyncHandler } from '../../util/handlers/AsyncHandler';

/**
 * Finalizer is used to indicate an AsyncHandler that performs finalization logic.
 */
export abstract class Finalizer extends AsyncHandler {}

/**
 * Allows for initializing state or executing logic when the application is started.
 * Use this interface to add initialization logic to classes that already extend some other type.
 * NOTE: classes without an existing extends-relation should extend from Initializer instead!
 */
export interface Initializable {
  initialize: () => Promise<void>;
}

import type { Initializable } from './Initializable';
