import type { ResourceIdentifier } from '../../http/representation/ResourceIdentifier';
import { JsonResourceStorage } from '../../storage/keyvalue/JsonResourceStorage';
import { createErrorMessage } from '../../util/errors/ErrorUtil';
import { isContainerIdentifier } from '../../util/PathUtil';
import { readableToString } from '../../util/StreamUtil';
import { LDP } from '../../util/Vocabularies';

/**
 * A variant of a {@link JsonResourceStorage} where the `entries()` call
 * does not recursively iterate through all containers.
 * Only the documents that are found in the root container are returned.
 *
 * This class was created to support migration where different storages are nested in one main `.internal` container,
 * and we specifically want to only return entries of one storage.
 */
export class SingleContainerJsonStorage<T> extends JsonResourceStorage<T> {
  protected async* getResourceEntries(containerId: ResourceIdentifier): AsyncIterableIterator<[string, T]> {
    const container = await this.safelyGetResource(containerId);
    if (!container) {
      return;
    }

    // Only need the metadata
    container.data.destroy();
    const members = container.metadata.getAll(LDP.terms.contains).map((term): string => term.value);

    for (const path of members) {
      const documentId = { path };
      if (isContainerIdentifier(documentId)) {
        continue;
      }

      const document = await this.safelyGetResource(documentId);
      if (!document) {
        continue;
      }

      const key = this.identifierToKey(documentId);
      try {
        const json = JSON.parse(await readableToString(document.data)) as T;
        yield [ key, json ];
      } catch (error: unknown) {
        this.logger.error(`Unable to parse ${path}. You should probably delete this resource manually. Error: ${
          createErrorMessage(error)}`);
      }
    }
  }
}

import { createInterface } from 'node:readline';
import type { ACCOUNT_STORAGE_DESCRIPTION } from '../../identity/interaction/account/util/BaseAccountStore';
import type { AccountLoginStorage } from '../../identity/interaction/account/util/LoginStorage';
import { ACCOUNT_TYPE } from '../../identity/interaction/account/util/LoginStorage';
import type {
  CLIENT_CREDENTIALS_STORAGE_DESCRIPTION,
} from '../../identity/interaction/client-credentials/util/BaseClientCredentialsStore';
import {
  CLIENT_CREDENTIALS_STORAGE_TYPE,
} from '../../identity/interaction/client-credentials/util/BaseClientCredentialsStore';
import type {
  PASSWORD_STORAGE_DESCRIPTION,
} from '../../identity/interaction/password/util/BasePasswordStore';
import {
  PASSWORD_STORAGE_TYPE,
} from '../../identity/interaction/password/util/BasePasswordStore';
import type {
  OWNER_STORAGE_DESCRIPTION,
  POD_STORAGE_DESCRIPTION,
} from '../../identity/interaction/pod/util/BasePodStore';
import {
  OWNER_STORAGE_TYPE,
  POD_STORAGE_TYPE,
} from '../../identity/interaction/pod/util/BasePodStore';
import type { WEBID_STORAGE_DESCRIPTION } from '../../identity/interaction/webid/util/BaseWebIdStore';
import { WEBID_STORAGE_TYPE } from '../../identity/interaction/webid/util/BaseWebIdStore';
import { getLoggerFor } from '../../logging/LogUtil';
import type { KeyValueStorage } from '../../storage/keyvalue/KeyValueStorage';
import { Initializer } from '../Initializer';

type Account = {
  webId: string;
  email: string;
  password: string;
  verified: boolean;
};

type Settings = {
  useIdp: boolean;
  podBaseUrl?: string;
  clientCredentials?: string[];
};

type ClientCredentials = {
  webId: string;
  secret: string;
};

type StorageDescription = {
  [ACCOUNT_TYPE]: typeof ACCOUNT_STORAGE_DESCRIPTION;
  [PASSWORD_STORAGE_TYPE]: typeof PASSWORD_STORAGE_DESCRIPTION;
  [WEBID_STORAGE_TYPE]: typeof WEBID_STORAGE_DESCRIPTION;
  [POD_STORAGE_TYPE]: typeof POD_STORAGE_DESCRIPTION;
  [OWNER_STORAGE_TYPE]: typeof OWNER_STORAGE_DESCRIPTION;
  [CLIENT_CREDENTIALS_STORAGE_TYPE]: typeof CLIENT_CREDENTIALS_STORAGE_DESCRIPTION;
};

export interface V6MigrationInitializerArgs {
  /**
   * The storage in which all setup values are stored, including the version of the server.
   */
  setupStorage: KeyValueStorage<string, string>;
  /**
   * The key necessary to get the version from the `setupStorage`.
   */
  versionKey: string;
  /**
   * The storage in which account data of the previous version is stored.
   */
  accountStorage: KeyValueStorage<string, Account | Settings>;
  /**
   * The storage in which client credentials are stored from the previous version.
   */
  clientCredentialsStorage: KeyValueStorage<string, ClientCredentials>;
  /**
   * Storages for which all entries need to be removed.
   */
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  cleanupStorages: KeyValueStorage<string, any>[];
  /**
   * The storage that will contain the account data in the new format.
   * Wrong typings to prevent Components.js typing issues.
   */
  newAccountStorage: AccountLoginStorage<Record<string, never>>;
  /**
   * The storage that will contain the setup entries in the new format.
   */
  newSetupStorage: KeyValueStorage<string, string>;
  /**
   * If true, no confirmation prompt will be printed to the stdout.
   */
  skipConfirmation?: boolean;
}

/**
 * Handles migrating account data from v6 to the newer format.
 * Will only trigger if it is detected that this server was previously started on an older version
 * and at least one account was found.
 * Confirmation will be asked to the user through a CLI prompt.
 * After migration is complete the old data will be removed.
 */
export class V6MigrationInitializer extends Initializer {
  private readonly logger = getLoggerFor(this);

  private readonly skipConfirmation: boolean;

  private readonly versionKey: string;
  private readonly setupStorage: KeyValueStorage<string, string>;

  private readonly accountStorage: KeyValueStorage<string, Account | Settings>;
  private readonly clientCredentialsStorage: KeyValueStorage<string, ClientCredentials>;
  private readonly cleanupStorages: KeyValueStorage<string, unknown>[];

  private readonly newAccountStorage: AccountLoginStorage<StorageDescription>;
  private readonly newSetupStorage: KeyValueStorage<string, string>;

  public constructor(args: V6MigrationInitializerArgs) {
    super();
    this.skipConfirmation = Boolean(args.skipConfirmation);
    this.versionKey = args.versionKey;
    this.setupStorage = args.setupStorage;
    this.accountStorage = args.accountStorage;
    this.clientCredentialsStorage = args.clientCredentialsStorage;
    this.cleanupStorages = args.cleanupStorages;
    this.newAccountStorage = args.newAccountStorage as unknown as AccountLoginStorage<StorageDescription>;
    this.newSetupStorage = args.newSetupStorage;
  }

  public async handle(): Promise<void> {
    const previousVersion = await this.setupStorage.get(this.versionKey);
    if (!previousVersion) {
      // This happens if this is the first time the server is started
      this.logger.debug('No previous version found');
      return;
    }

    const [ prevMajor ] = previousVersion.split('.');
    if (Number.parseInt(prevMajor, 10) > 6) {
      return;
    }

    // Ask the user for confirmation
    if (!this.skipConfirmation) {
      const readline = createInterface({ input: process.stdin, output: process.stdout });
      const answer = await new Promise<string>((resolve): void => {
        readline.question([
          'The server is now going to migrate v6 data to the new storage format internally.',
          'Existing accounts will be migrated.',
          'All other internal data, such as notification subscriptions will be removed.',
          'In case you have not yet done this,',
          'it is recommended to cancel startup and first backup the existing data,',
          'in case something goes wrong.',
          'When using default configurations with a file backend,',
          'this data can be found in the ".internal" folder.',
          '\n\nDo you want to migrate the data now? [y/N] ',
        ].join(' '), resolve);
      });
      readline.close();
      if (!/^y(?:es)?$/iu.test(answer)) {
        throw new Error('Stopping server as migration was cancelled.');
      }
    }

    this.logger.info('Migrating v6 data...');

    const webIdAccountMap: Record<string, string> = {};

    for await (const [ , account ] of this.accountStorage.entries()) {
      const result = await this.createAccount(account);
      if (result) {
        // Store link between WebID and account ID for client credentials
        webIdAccountMap[result.webId] = result.accountId;
      }
    }

    this.logger.debug('Converting client credentials tokens.');
    // Convert the existing client credentials tokens
    for await (const [ label, { webId, secret }] of this.clientCredentialsStorage.entries()) {
      const accountId = webIdAccountMap[webId];
      if (!accountId) {
        this.logger.warn(`Unable to find account for client credentials ${label}. Skipping migration of this token.`);
        continue;
      }
      await this.newAccountStorage.create(CLIENT_CREDENTIALS_STORAGE_TYPE, { webId, label, secret, accountId });
    }

    this.logger.debug('Converting setup entries.');
    for await (const [ key, value ] of this.setupStorage.entries()) {
      await this.newSetupStorage.set(key, value);
      await this.setupStorage.delete(key);
    }

    // Cleanup all old entries
    this.logger.debug('Cleaning up older entries.');
    for (const storage of this.cleanupStorages) {
      for await (const [ key ] of storage.entries()) {
        await storage.delete(key);
      }
    }

    this.logger.info('Finished migrating v6 data.');
  }

  protected isAccount(data: Account | Settings): data is Account {
    return Boolean((data as Account).email);
  }

  /**
   * Creates a new account based on the account data found in the old storage.
   * Will always create an account and password entry.
   * In case `useIdp` is true, will create a WebID link entry.
   * In case there is an associated `podBaseUrl`, will create a pod and owner entry.
   */
  protected async createAccount(account: Account | Settings):
  Promise<{ accountId: string; webId: string } | undefined> {
    if (!this.isAccount(account)) {
      return;
    }

    const { webId, email, password, verified } = account;

    this.logger.debug(`Migrating account ${email} with WebID ${webId}`);

    const settings = await this.accountStorage.get(webId) as Settings | undefined;
    if (!settings) {
      this.logger.warn(`Unable to find settings for account ${email}. Skipping migration of this account.`);
      return;
    }

    const { id: accountId } = await this.newAccountStorage.create(ACCOUNT_TYPE, {});
    // The `toLowerCase` call is important here to have the expected value
    await this.newAccountStorage.create(
      PASSWORD_STORAGE_TYPE,
      { email: email.toLowerCase(), password, verified, accountId },
    );
    if (settings.useIdp) {
      await this.newAccountStorage.create(WEBID_STORAGE_TYPE, { webId, accountId });
    }
    if (settings.podBaseUrl) {
      const { id: podId } = await this.newAccountStorage.create(
        POD_STORAGE_TYPE,
        { baseUrl: settings.podBaseUrl, accountId },
      );
      await this.newAccountStorage.create(OWNER_STORAGE_TYPE, { webId, podId, visible: false });
    }

    return { accountId, webId };
  }
}

import type { KeyValueStorage } from '../storage/keyvalue/KeyValueStorage';
import { readPackageJson } from '../util/PathUtil';
import { Initializer } from './Initializer';

/**
 * This initializer simply writes the version number of the server to the storage.
 * This will be relevant in the future when we look into migration initializers.
 *
 * It automatically parses the version number from the `package.json`.
 */
export class ModuleVersionVerifier extends Initializer {
  private readonly storageKey: string;
  private readonly storage: KeyValueStorage<string, string>;

  public constructor(storageKey: string, storage: KeyValueStorage<string, string>) {
    super();
    this.storageKey = storageKey;
    this.storage = storage;
  }

  public async handle(): Promise<void> {
    const pkg = await readPackageJson();
    await this.storage.set(this.storageKey, pkg.version as string);
  }
}

import { readJson } from 'fs-extra';
import { array, object, string } from 'yup';
import type { AccountStore } from '../identity/interaction/account/util/AccountStore';
import type { PasswordStore } from '../identity/interaction/password/util/PasswordStore';
import type { PodCreator } from '../identity/interaction/pod/util/PodCreator';
import { URL_SCHEMA } from '../identity/interaction/YupUtil';
import { getLoggerFor } from '../logging/LogUtil';
import { createErrorMessage } from '../util/errors/ErrorUtil';
import { Initializer } from './Initializer';

const inSchema = array().of(object({
  email: string().trim().email().lowercase()
    .required(),
  password: string().trim().min(1).required(),
  pods: array().of(object({
    name: string().trim().min(1).required(),
    settings: object({
      webId: URL_SCHEMA,
    }).optional(),
  })).optional(),
})).required();

export interface SeededAccountInitializerArgs {
  /**
   * Creates the accounts.
   */
  accountStore: AccountStore;
  /**
   * Adds the login methods.
   */
  passwordStore: PasswordStore;
  /**
   * Creates the pods.
   */
  podCreator: PodCreator;
  /**
   * File path of the JSON describing the accounts to seed.
   */
  configFilePath?: string;
}

/**
 * Initializes a set of accounts based on the input data.
 * These accounts have exactly 1 email/password login method, and 0 or more pods.
 * The pod settings that can be defined are identical to those of the {@link CreatePodHandler}.
 */
export class SeededAccountInitializer extends Initializer {
  protected readonly logger = getLoggerFor(this);

  private readonly accountStore: AccountStore;
  private readonly passwordStore: PasswordStore;
  private readonly podCreator: PodCreator;
  private readonly configFilePath?: string;

  public constructor(args: SeededAccountInitializerArgs) {
    super();
    this.accountStore = args.accountStore;
    this.passwordStore = args.passwordStore;
    this.podCreator = args.podCreator;
    this.configFilePath = args.configFilePath;
  }

  public async handle(): Promise<void> {
    // This value being undefined means that the variable linking to the seed config is not defined
    // and this class should just do nothing.
    if (!this.configFilePath) {
      return;
    }

    let configuration: typeof inSchema.__outputType;
    try {
      configuration = await inSchema.validate(await readJson(this.configFilePath, 'utf8'));
    } catch (error: unknown) {
      const msg = `Invalid account seed file: ${createErrorMessage(error)}`;
      this.logger.error(msg);
      throw new Error(msg);
    }

    let accountCount = 0;
    let podCount = 0;
    for (const { email, password, pods } of configuration) {
      try {
        this.logger.info(`Creating account for ${email}`);
        const accountId = await this.accountStore.create();
        const id = await this.passwordStore.create(email, accountId, password);
        await this.passwordStore.confirmVerification(id);
        accountCount += 1;

        for (const { name, settings } of pods ?? []) {
          this.logger.info(`Creating pod with name ${name}`);
          await this.podCreator.handleSafe({ accountId, name, webId: settings?.webId, settings });
          podCount += 1;
        }
      } catch (error: unknown) {
        this.logger.warn(`Error while initializing seeded account: ${createErrorMessage(error)}`);
      }
    }
    this.logger.info(`Initialized ${accountCount} accounts and ${podCount} pods.`);
  }
}

import type { Server } from 'node:http';
import { promisify } from 'node:util';
import { getLoggerFor } from '../logging/LogUtil';
import { isHttpsServer } from '../server/HttpServerFactory';
import type { HttpServerFactory } from '../server/HttpServerFactory';
import type { Finalizable } from './final/Finalizable';
import { Initializer } from './Initializer';

/**
 * Creates and starts an HTTP server.
 */
export class ServerInitializer extends Initializer implements Finalizable {
  protected readonly logger = getLoggerFor(this);

  private readonly serverFactory: HttpServerFactory;
  private readonly port?: number;
  private readonly socketPath?: string;

  private server?: Server;

  public constructor(serverFactory: HttpServerFactory, port?: number, socketPath?: string) {
    super();
    this.serverFactory = serverFactory;
    this.port = port;
    this.socketPath = socketPath;
    if (!port && !socketPath) {
      throw new Error('Either Port or Socket arguments must be set');
    }
  }

  public async handle(): Promise<void> {
    this.server = await this.serverFactory.createServer();

    if (this.socketPath) {
      this.logger.info(`Listening to server at ${this.server.address() as string}`);
      this.server.listen(this.socketPath);
    } else {
      const url = new URL(`http${isHttpsServer(this.server) ? 's' : ''}://localhost:${this.port}/`).href;
      this.logger.info(`Listening to server at ${url}`);
      this.server.listen(this.port);
    }
  }

  public async finalize(): Promise<void> {
    if (this.server) {
      return promisify(this.server.close.bind(this.server))();
    }
  }
}

import { createErrorMessage } from '../../util/errors/ErrorUtil';
import type { ShorthandExtractor } from './extractors/ShorthandExtractor';
import { ShorthandResolver } from './ShorthandResolver';

/**
 * Generates variable values by running a set of {@link ShorthandExtractor}s on the input.
 */
export class CombinedShorthandResolver extends ShorthandResolver {
  public readonly resolvers: Record<string, ShorthandExtractor>;

  public constructor(resolvers: Record<string, ShorthandExtractor>) {
    super();
    this.resolvers = resolvers;
  }

  public async handle(input: Record<string, unknown>): Promise<Record<string, unknown>> {
    const vars: Record<string, unknown> = {};
    for (const [ name, computer ] of Object.entries(this.resolvers)) {
      try {
        vars[name] = await computer.handleSafe(input);
      } catch (err: unknown) {
        throw new Error(`Error in computing value for variable ${name}: ${createErrorMessage(err)}`);
      }
    }
    return vars;
  }
}

import { resolveAssetPath } from '../../../util/PathUtil';
import type { Shorthand } from '../Types';
import { ShorthandExtractor } from './ShorthandExtractor';

/**
 * A {@link ShorthandExtractor} that converts a path value to an absolute asset path
 * by making use of `resolveAssetPath`.
 * Returns the default path in case it is defined and no path was found in the map.
 */
export class AssetPathExtractor extends ShorthandExtractor {
  private readonly key: string;
  private readonly defaultPath?: string;

  public constructor(key: string, defaultPath?: string) {
    super();
    this.key = key;
    this.defaultPath = defaultPath;
  }

  public async handle(args: Shorthand): Promise<unknown> {
    const path = args[this.key] ?? this.defaultPath;
    if (path) {
      if (typeof path !== 'string') {
        throw new TypeError(`Invalid ${this.key} argument`);
      }

      return resolveAssetPath(path);
    }

    return null;
  }
}

import { ensureTrailingSlash } from '../../../util/PathUtil';
import type { Shorthand } from '../Types';
import { ShorthandExtractor } from './ShorthandExtractor';

/**
 * A {@link ShorthandExtractor} that that generates the base URL based on the input `baseUrl` value,
 * or by using the port if the first isn't provided.
 */
export class BaseUrlExtractor extends ShorthandExtractor {
  private readonly defaultPort: number;

  public constructor(defaultPort = 3000) {
    super();
    this.defaultPort = defaultPort;
  }

  public async handle(args: Shorthand): Promise<unknown> {
    if (typeof args.baseUrl === 'string') {
      return ensureTrailingSlash(args.baseUrl);
    }
    if (typeof args.socket === 'string') {
      throw new TypeError('BaseUrl argument should be provided when using Unix Domain Sockets.');
    }
    const port = (args.port as string) ?? this.defaultPort;
    const url = new URL('http://localhost/');
    url.port = port;
    return url.href;
  }
}

import type { Shorthand } from '../Types';
import { ShorthandExtractor } from './ShorthandExtractor';

/**
 * A simple {@link ShorthandExtractor} that extracts a single value from the input map.
 * Returns the default value if it was defined in case no value was found in the map.
 */
export class KeyExtractor extends ShorthandExtractor {
  private readonly key: string;
  private readonly defaultValue: unknown;

  public constructor(key: string, defaultValue?: unknown) {
    super();
    this.key = key;
    this.defaultValue = defaultValue;
  }

  public async handle(args: Shorthand): Promise<unknown> {
    return typeof args[this.key] === 'undefined' ? this.defaultValue : args[this.key];
  }
}

import { AsyncHandler } from '../../../util/handlers/AsyncHandler';
import type { Shorthand } from '../Types';

/**
 * A handler that computes a specific value from a given map of values.
 */
export abstract class ShorthandExtractor extends AsyncHandler<Shorthand, unknown> {}

import { AsyncHandler } from '../../util/handlers/AsyncHandler';
import type { Shorthand, VariableBindings } from './Types';

/**
 * Converts a key/value object, extracted from the CLI or passed as a parameter,
 * into a new key/value object where the keys are variables defined in the Components.js configuration.
 * The resulting values are the values that should be assigned to those variables.
 */
export abstract class ShorthandResolver extends AsyncHandler<Shorthand, VariableBindings> {}

// These types are used to clarify what is expected for the CLI-related handlers

/**
 * A list of command line arguments provided to the process.
 */
export type CliArgv = string[];

/**
 * A key/value mapping of parsed command line arguments.
 */
export type Shorthand = Record<string, unknown>;

/**
 * A key/value mapping of Components.js variables.
 */
export type VariableBindings = Record<string, unknown>;

import cluster from 'node:cluster';
import { WrappingLogger } from './Logger';
import type { Logger } from './Logger';
import type { LoggerFactory } from './LoggerFactory';
import type { LogLevel } from './LogLevel';

/**
 * Temporary {@link LoggerFactory} that buffers log messages in memory
 * until the {@link TemporaryLoggerFactory#switch} method is called.
 */
class TemporaryLoggerFactory implements LoggerFactory {
  private bufferSpaces: number;
  private readonly wrappers: { wrapper: WrappingLogger; label: string }[] = [];
  private readonly buffer: { logger: Logger; level: LogLevel; message: string }[] = [];

  public constructor(bufferSize = 1024) {
    this.bufferSpaces = bufferSize;
  }

  public createLogger(label: string): WrappingLogger {
    const wrapper = new WrappingLogger({
      log: (level: LogLevel, message: string): Logger =>
        this.bufferLogEntry(wrapper, level, message),
    });
    this.wrappers.push({ wrapper, label });
    return wrapper;
  }

  private bufferLogEntry(logger: WrappingLogger, level: LogLevel, message: string): Logger {
    // Buffer the message if spaces are still available
    if (this.bufferSpaces > 0) {
      this.bufferSpaces -= 1;
      // If this is the last space, instead generate a warning through a new logger
      if (this.bufferSpaces === 0) {
        logger = this.createLogger('LazyLoggerFactory');
        level = 'warn';
        message = `Memory-buffered logging limit of ${this.buffer.length + 1} reached`;
      }
      this.buffer.push({ logger, level, message });
    }
    return logger;
  }

  /**
   * Swaps all lazy loggers to new loggers from the given factory,
   * and emits any buffered messages through those actual loggers.
   */
  public switch(loggerFactory: LoggerFactory): void {
    // Instantiate an actual logger within every lazy logger
    for (const { wrapper, label } of this.wrappers.splice(0, this.wrappers.length)) {
      wrapper.logger = loggerFactory.createLogger(label);
    }
    // Emit all buffered log messages
    for (const { logger, level, message } of this.buffer.splice(0, this.buffer.length)) {
      logger.log(level, message, { isPrimary: cluster.isPrimary, pid: process.pid });
    }
  }
}

/**
 * Wraps around another {@link LoggerFactory} that can be set lazily.
 * This is useful when objects are instantiated (and when they create loggers)
 * before the logging system has been fully instantiated,
 * as is the case when using a dependency injection framework such as Components.js.
 *
 * Loggers can be created even before a {@link LoggerFactory} is set;
 * any log messages will be buffered and re-emitted.
 */
export class LazyLoggerFactory implements LoggerFactory {
  private factory: LoggerFactory;

  public constructor(options: { bufferSize?: number } = {}) {
    this.factory = new TemporaryLoggerFactory(options.bufferSize);
  }

  public get loggerFactory(): LoggerFactory {
    if (this.factory instanceof TemporaryLoggerFactory) {
      throw new TypeError('Logger factory not yet set.');
    }
    return this.factory;
  }

  public set loggerFactory(loggerFactory: LoggerFactory) {
    if (this.factory instanceof TemporaryLoggerFactory) {
      this.factory.switch(loggerFactory);
    }
    this.factory = loggerFactory;
  }

  public createLogger(label: string): Logger {
    return this.factory.createLogger(label);
  }
}

import cluster from 'node:cluster';
import type { LogLevel } from './LogLevel';

export interface LogMetadata {
  /** Is the current process the Primary process */
  isPrimary: boolean;
  /** The process id of the current process */
  pid: number;
}

/**
 * Logs messages on a specific level.
 *
 * @see getLoggerFor on how to instantiate loggers.
 */
export interface SimpleLogger {
  /**
   * Log the given message at the given level.
   * If the internal level is higher than the given level, the message may be voided.
   *
   * @param level - The level to log at.
   * @param message - The message to log.
   * @param meta - Optional metadata to include in the log message.
   */
  log: (level: LogLevel, message: string, meta?: LogMetadata) => SimpleLogger;
}

/**
 * Logs messages, with convenience methods to log on a specific level.
 *
 * @see getLoggerFor on how to instantiate loggers.
 */
export interface Logger extends SimpleLogger {
  /**
   * Log the given message at the given level.
   * If the internal level is higher than the given level, the message may be voided.
   *
   * @param level - The level to log at.
   * @param message - The message to log.
   * @param meta - Optional metadata to include in the log message.
   */
  log: (level: LogLevel, message: string, meta?: LogMetadata) => Logger;

  /**
   * Log a message at the 'error' level.
   *
   * @param message - The message to log.
   * @param meta - Optional metadata to include in the log message.
   */
  error: (message: string) => Logger;

  /**
   * Log a message at the 'warn' level.
   *
   * @param message - The message to log.
   * @param meta - Optional metadata to include in the log message.
   */
  warn: (message: string) => Logger;

  /**
   * Log a message at the 'info' level.
   *
   * @param message - The message to log.
   * @param meta - Optional metadata to include in the log message.
   */
  info: (message: string) => Logger;

  /**
   * Log a message at the 'verbose' level.
   *
   * @param message - The message to log.
   * @param meta - Optional metadata to include in the log message.
   */
  verbose: (message: string) => Logger;

  /**
   * Log a message at the 'debug' level.
   *
   * @param message - The message to log.
   * @param meta - Optional metadata to include in the log message.
   */
  debug: (message: string) => Logger;

  /**
   * Log a message at the 'silly' level.
   *
   * @param message - The message to log.
   * @param meta - Optional metadata to include in the log message.
   */
  silly: (message: string) => Logger;
}

/**
 * Base class that implements all additional {@link BaseLogger} methods,
 * leaving only the implementation of {@link SimpleLogger}.
 */
export abstract class BaseLogger implements Logger {
  public abstract log(level: LogLevel, message: string, meta?: LogMetadata): Logger;

  private readonly getMeta = (): LogMetadata => ({
    pid: process.pid,
    isPrimary: cluster.isPrimary,
  });

  public error(message: string): Logger {
    return this.log('error', message, this.getMeta());
  }

  public warn(message: string): Logger {
    return this.log('warn', message, this.getMeta());
  }

  public info(message: string): Logger {
    return this.log('info', message, this.getMeta());
  }

  public verbose(message: string): Logger {
    return this.log('verbose', message, this.getMeta());
  }

  public debug(message: string): Logger {
    return this.log('debug', message, this.getMeta());
  }

  public silly(message: string): Logger {
    return this.log('silly', message, this.getMeta());
  }
}

/**
 * Implements {@link BaseLogger} around a {@link SimpleLogger},
 * which can be swapped out a runtime.
 */
export class WrappingLogger extends BaseLogger {
  public logger: SimpleLogger;

  public constructor(logger: SimpleLogger) {
    super();
    this.logger = logger;
  }

  public log(level: LogLevel, message: string, meta?: LogMetadata): this {
    this.logger.log(level, message, meta);
    return this;
  }
}

import type { Logger } from './Logger';

/**
 * Instantiates new logger instances.
 */
export interface LoggerFactory {
  /**
   * Create a logger instance for the given label.
   *
   * @param label - A label that is used to identify the given logger.
   */
  createLogger: (label: string) => Logger;
}

export const LOG_LEVELS = [ 'error', 'warn', 'info', 'verbose', 'debug', 'silly' ] as const;

/**
 * Different log levels, from most important to least important.
 */
export type LogLevel = typeof LOG_LEVELS[number];

import { LazyLoggerFactory } from './LazyLoggerFactory';
import type { Logger } from './Logger';
import type { LoggerFactory } from './LoggerFactory';

let loggerFactoryWrapper = new LazyLoggerFactory();
let classLoggers = new WeakMap<Constructor, Logger>();

/**
 * Gets a logger instance for the given class instance.
 *
 * The following shows a typical pattern on how to create loggers:
 * ```
 * class MyClass {
 *   protected readonly logger = getLoggerFor(this);
 * }
 * ```
 * If no class is applicable, a logger can also be created as follows:
 * ```
 * const logger = getLoggerFor('MyFunction');
 * ```
 *
 * @param loggable - A class instance or a class string name.
 */
export function getLoggerFor(loggable: string | Instance): Logger {
  let logger: Logger;
  // Create a logger with a text label
  if (typeof loggable === 'string') {
    logger = loggerFactoryWrapper.createLogger(loggable);
  // Create or reuse a logger for a specific class
  } else {
    const { constructor } = loggable;
    if (classLoggers.has(constructor)) {
      logger = classLoggers.get(constructor)!;
    } else {
      logger = loggerFactoryWrapper.createLogger(constructor.name);
      classLoggers.set(constructor, logger);
    }
  }
  return logger;
}

/**
 * Sets the global logger factory.
 * This causes loggers created by {@link getLoggerFor} to delegate to a logger from the given factory.
 *
 * @param loggerFactory - A logger factory.
 */
export function setGlobalLoggerFactory(loggerFactory: LoggerFactory): void {
  loggerFactoryWrapper.loggerFactory = loggerFactory;
}

/**
 * Resets the internal logger factory, which holds the global logger factory.
 * For testing purposes only.
 */
export function resetInternalLoggerFactory(factory = new LazyLoggerFactory()): void {
  loggerFactoryWrapper = factory;
  classLoggers = new WeakMap();
}

/**
 * Any class constructor.
 */
interface Constructor {
  name: string;
}

/**
 * Any class instance.
 */
interface Instance {
  constructor: Constructor;
}

import { BaseLogger } from './Logger';

/**
 * A logger that does nothing on a log message.
 */
export class VoidLogger extends BaseLogger {
  public log(): this {
    // Do nothing
    return this;
  }
}

import type { LoggerFactory } from './LoggerFactory';
import { VoidLogger } from './VoidLogger';

/**
 * A factory that always returns {@link VoidLogger}, which does nothing on log messages.
 */
export class VoidLoggerFactory implements LoggerFactory {
  private readonly logger = new VoidLogger();

  // eslint-disable-next-line unused-imports/no-unused-vars
  public createLogger(label: string): VoidLogger {
    return this.logger;
  }
}

import type { Logger as WinstonInnerLogger } from 'winston';
import { BaseLogger } from './Logger';
import type { LogLevel } from './LogLevel';

/**
 * A WinstonLogger implements the {@link Logger} interface using a given winston logger.
 */
export class WinstonLogger extends BaseLogger {
  private readonly logger: WinstonInnerLogger;

  public constructor(logger: WinstonInnerLogger) {
    super();
    this.logger = logger;
  }

  public log(level: LogLevel, message: string, meta?: unknown): this {
    this.logger.log(level, message, meta);
    return this;
  }
}

import type { TransformableInfo } from 'logform';
import { createLogger, format, transports } from 'winston';
import type * as Transport from 'winston-transport';
import type { Logger, LogMetadata } from './Logger';
import type { LoggerFactory } from './LoggerFactory';
import { WinstonLogger } from './WinstonLogger';

/**
 * Uses the winston library to create loggers for the given logging level.
 * By default, it will print to the console with colorized logging levels.
 *
 * This creates instances of {@link WinstonLogger}.
 */
export class WinstonLoggerFactory implements LoggerFactory {
  private readonly level: string;

  public constructor(level: string) {
    this.level = level;
  }

  private readonly clusterInfo = (meta: LogMetadata): string => {
    if (meta.isPrimary) {
      return 'Primary';
    }
    return `W-${meta.pid ?? '???'}`;
  };

  public createLogger(label: string): Logger {
    return new WinstonLogger(createLogger({
      level: this.level,
      format: format.combine(
        format.label({ label }),
        format.colorize(),
        format.timestamp(),
        format.metadata({ fillExcept: [ 'level', 'timestamp', 'label', 'message' ]}),
        format.printf(
          ({ level: levelInner, message, label: labelInner, timestamp, metadata: meta }: TransformableInfo): string =>
            `${timestamp} [${labelInner}] {${this.clusterInfo(meta as LogMetadata)}} ${levelInner}: ${message}`,
        ),
      ),
      transports: this.createTransports(),
    }));
  }

  protected createTransports(): Transport[] {
    return [ new transports.Console() ];
  }
}

import { getLoggerFor } from '../logging/LogUtil';
import type { KeyValueStorage } from '../storage/keyvalue/KeyValueStorage';
import type { ResourceStore } from '../storage/ResourceStore';
import { addGeneratedResources } from './generate/GenerateUtil';
import type { PodGenerator } from './generate/PodGenerator';
import type { ResourcesGenerator } from './generate/ResourcesGenerator';
import type { PodManager } from './PodManager';
import type { PodSettings } from './settings/PodSettings';

/**
 * Pod manager that creates a store for the pod with a {@link PodGenerator}
 * and fills it with resources from a {@link ResourcesGenerator}.
 *
 * Part of the dynamic pod creation.
 *  1. Calls a PodGenerator to instantiate a new resource store for the pod.
 *  2. Generates the pod resources based on the templates as usual.
 *  3. Adds the created pod to the routing storage, which is used for linking pod identifiers to their resource stores.
 *
 * @see {@link TemplatedPodGenerator}, {@link ConfigPodInitializer}, {@link BaseUrlRouterRule}
 */
export class ConfigPodManager implements PodManager {
  protected readonly logger = getLoggerFor(this);
  private readonly podGenerator: PodGenerator;
  private readonly routingStorage: KeyValueStorage<string, ResourceStore>;
  private readonly resourcesGenerator: ResourcesGenerator;
  private readonly store: ResourceStore;

  /**
   * @param podGenerator - Generator for the pod stores.
   * @param resourcesGenerator - Generator for the pod resources.
   * @param routingStorage - Where to store the generated pods so they can be routed to.
   * @param store - The default ResourceStore
   */
  public constructor(
    podGenerator: PodGenerator,
    resourcesGenerator: ResourcesGenerator,
    routingStorage: KeyValueStorage<string, ResourceStore>,
    store: ResourceStore,
  ) {
    this.podGenerator = podGenerator;
    this.routingStorage = routingStorage;
    this.resourcesGenerator = resourcesGenerator;
    this.store = store;
  }

  public async createPod(settings: PodSettings): Promise<void> {
    this.logger.info(`Creating pod ${settings.base.path}`);

    // Will error in case there already is a store for the given identifier
    const store = await this.podGenerator.generate(settings);

    await this.routingStorage.set(settings.base.path, store);
    const count = await addGeneratedResources(settings, this.resourcesGenerator, this.store);

    this.logger.info(`Added ${count} resources to ${settings.base.path}`);
  }
}

import type { IComponentsManagerBuilderOptions, LogLevel } from 'componentsjs';
import { ComponentsManager } from 'componentsjs';
import { joinFilePath } from '../../util/PathUtil';
import type { ComponentsJsFactory } from './ComponentsJsFactory';

/**
 * Can be used to instantiate objects using Components.js.
 * Default main module path is the root folder of the project.
 * For every generate call a new manager will be made,
 * but moduleState will be stored in between calls.
 */
export class BaseComponentsJsFactory implements ComponentsJsFactory {
  private readonly options: IComponentsManagerBuilderOptions<unknown>;

  public constructor(relativeModulePath = '../../../', logLevel = 'error') {
    this.options = {
      mainModulePath: joinFilePath(__dirname, relativeModulePath),
      logLevel: logLevel as LogLevel,
      dumpErrorState: false,
      typeChecking: false,
    };
  }

  private async buildManager(): Promise<ComponentsManager<unknown>> {
    const manager = await ComponentsManager.build(this.options);
    this.options.moduleState = manager.moduleState;
    return manager;
  }

  /**
   * Calls Components.js to instantiate a new object.
   *
   * @param configPath - Location of the config to instantiate.
   * @param componentIri - Iri of the object in the config that will be the result.
   * @param variables - Variables to send to Components.js
   *
   * @returns The resulting object, corresponding to the given component IRI.
   */
  public async generate<T>(configPath: string, componentIri: string, variables: Record<string, unknown>):
  Promise<T> {
    const manager = await this.buildManager();
    await manager.configRegistry.register(configPath);
    return manager.instantiate(componentIri, { variables });
  }
}

import { createReadStream, promises as fsPromises } from 'node:fs';
import type { Readable } from 'node:stream';
import { pathExists } from 'fs-extra';
import { Parser } from 'n3';
import type { AuxiliaryStrategy } from '../../http/auxiliary/AuxiliaryStrategy';
import { BasicRepresentation } from '../../http/representation/BasicRepresentation';
import { RepresentationMetadata } from '../../http/representation/RepresentationMetadata';
import type { ResourceIdentifier } from '../../http/representation/ResourceIdentifier';
import { getLoggerFor } from '../../logging/LogUtil';
import type {
  FileIdentifierMapper,
  FileIdentifierMapperFactory,
  ResourceLink,
} from '../../storage/mapping/FileIdentifierMapper';
import type { ResourceSet } from '../../storage/ResourceSet';
import { INTERNAL_QUADS } from '../../util/ContentTypes';
import { guardStream } from '../../util/GuardedStream';
import type { Guarded } from '../../util/GuardedStream';
import { isContainerIdentifier, joinFilePath, resolveAssetPath } from '../../util/PathUtil';
import { addResourceMetadata } from '../../util/ResourceUtil';
import { guardedStreamFrom, readableToString } from '../../util/StreamUtil';
import type { TemplateEngine } from '../../util/templates/TemplateEngine';
import type { Resource } from './ResourcesGenerator';
import type { TemplatedResourcesGenerator } from './TemplatedResourcesGenerator';
import Dict = NodeJS.Dict;

interface TemplateResourceLink extends ResourceLink {
  isTemplate: boolean;
}

/**
 * Input arguments required for {@link BaseResourcesGenerator}
 */
export interface SubfolderResourcesGeneratorArgs {
  /**
   * Factory used to generate mapper relative to the base identifier.
   */
  factory: FileIdentifierMapperFactory;
  /**
   * Template engine for generating the resources.
   */
  templateEngine: TemplateEngine;
  /**
   * The extension of files that need to be interpreted as templates.
   * Will be removed to generate the identifier.
   */
  templateExtension?: string;
  /**
   * The metadataStrategy
   */
  metadataStrategy: AuxiliaryStrategy;
  /**
   * The default ResourceStore
   */
  store: ResourceSet;
}

// Comparator for the results of the `groupLinks` call
function comparator(left: { link: TemplateResourceLink }, right: { link: TemplateResourceLink }): number {
  return left.link.identifier.path.localeCompare(right.link.identifier.path);
}

/**
 * Generates resources by making use of a template engine.
 * The template folder structure will be kept.
 * Folders will be interpreted as containers and files as documents.
 * A FileIdentifierMapper will be used to generate identifiers that correspond to the relative structure.
 *
 * Metadata resources will be yielded separately from their subject resource.
 *
 * A relative `templateFolder` is resolved relative to cwd,
 * unless it's preceded by `@css:`, e.g. `@css:foo/bar`.
 */
export class BaseResourcesGenerator implements TemplatedResourcesGenerator {
  protected readonly logger = getLoggerFor(this);

  private readonly factory: FileIdentifierMapperFactory;
  private readonly templateEngine: TemplateEngine;
  private readonly templateExtension: string;
  private readonly metadataStrategy: AuxiliaryStrategy;
  private readonly store: ResourceSet;

  /**
   * A mapper is needed to convert the template file paths to identifiers relative to the given base identifier.
   *
   * @param args - TemplatedResourcesGeneratorArgs
   */
  public constructor(args: SubfolderResourcesGeneratorArgs) {
    this.factory = args.factory;
    this.templateEngine = args.templateEngine;
    this.templateExtension = args.templateExtension ?? '.hbs';
    this.metadataStrategy = args.metadataStrategy;
    this.store = args.store;
  }

  public async* generate(templateFolder: string, location: ResourceIdentifier, options: Dict<unknown>):
  AsyncIterable<Resource> {
    templateFolder = resolveAssetPath(templateFolder);

    // Ignore folders that don't exist
    if (!await pathExists(templateFolder)) {
      this.logger.warn(`Ignoring non-existing template folder ${templateFolder}`);
      return;
    }

    const mapper = await this.factory.create(location.path, templateFolder);
    const folderLink = await this.toTemplateLink(templateFolder, mapper);
    yield* this.processFolder(folderLink, mapper, options);
  }

  /**
   * Generates results for all entries in the given folder, including the folder itself.
   */
  private async* processFolder(folderLink: TemplateResourceLink, mapper: FileIdentifierMapper, options: Dict<unknown>):
  AsyncIterable<Resource> {
    // Group resource links with their corresponding metadata links
    const links = await this.groupLinks(folderLink.filePath, mapper);

    // Remove root metadata if it exists
    const metaLink = links[folderLink.identifier.path]?.meta;
    delete links[folderLink.identifier.path];

    yield* this.generateResource(folderLink, options, metaLink);

    // Make sure the results are sorted
    for (const { link, meta } of Object.values(links).sort(comparator)) {
      if (isContainerIdentifier(link.identifier)) {
        yield* this.processFolder(link, mapper, options);
      } else {
        yield* this.generateResource(link, options, meta);
      }
    }
  }

  /**
   * Creates a TemplateResourceLink for the given filePath,
   * which connects a resource URL to its template file.
   * The identifier will be based on the file path stripped from the template extension,
   * but the filePath parameter will still point to the original file.
   */
  private async toTemplateLink(filePath: string, mapper: FileIdentifierMapper): Promise<TemplateResourceLink> {
    const stats = await fsPromises.lstat(filePath);

    // Slice the template extension from the filepath for correct identifier generation
    const isTemplate = filePath.endsWith(this.templateExtension);
    const slicedPath = isTemplate ? filePath.slice(0, -this.templateExtension.length) : filePath;
    const link = await mapper.mapFilePathToUrl(slicedPath, stats.isDirectory());
    // We still need the original file path for disk reading though
    return {
      ...link,
      filePath,
      isTemplate,
    };
  }

  /**
   * Generates TemplateResourceLinks for each entry in the given folder
   * and combines the results so resources and their metadata are grouped together.
   */
  private async groupLinks(folderPath: string, mapper: FileIdentifierMapper):
  Promise<Record<string, { link: TemplateResourceLink; meta?: TemplateResourceLink }>> {
    const files = await fsPromises.readdir(folderPath);
    const links: Record<string, { link: TemplateResourceLink; meta?: TemplateResourceLink }> = {};
    for (const name of files) {
      const link = await this.toTemplateLink(joinFilePath(folderPath, name), mapper);
      const { path } = link.identifier;
      links[path] = Object.assign(links[path] || {}, link.isMetadata ? { meta: link } : { link });
    }
    return links;
  }

  /**
   * Generates a Resource object for the given ResourceLink.
   * In the case of documents the corresponding template will be used.
   * If a ResourceLink of metadata is provided the corresponding metadata resource
   * will be yielded as a separate resource.
   */
  private async* generateResource(link: TemplateResourceLink, options: Dict<unknown>, metaLink?: TemplateResourceLink):
  AsyncIterable<Resource> {
    let data: Guarded<Readable> | undefined;
    const metadata = new RepresentationMetadata(link.identifier);

    // Read file if it is not a container
    if (!isContainerIdentifier(link.identifier)) {
      data = await this.processFile(link, options);
      metadata.contentType = link.contentType;
    }

    // Add metadata from .meta file if there is one
    if (metaLink) {
      const rawMetadata = await this.generateMetadata(metaLink, options);
      if (rawMetadata.contentType) {
        // Prevent having 2 content types
        metadata.contentType = undefined;
      }
      metadata.setMetadata(rawMetadata);
      this.logger.debug(`Adding metadata for ${metaLink.identifier.path}`);
    }

    const shouldYield = !isContainerIdentifier(link.identifier) || !await this.store.hasResource(link.identifier);
    if (shouldYield) {
      this.logger.debug(`Generating resource ${link.identifier.path}`);
      yield {
        identifier: link.identifier,
        representation: new BasicRepresentation(data ?? [], metadata),
      };
    }

    // Still need to yield metadata in case the actual resource is not being yielded.
    // We also do this for containers as existing containers can't be edited in the same way.
    if (metaLink && (!shouldYield || isContainerIdentifier(link.identifier))) {
      const metaIdentifier = this.metadataStrategy.getAuxiliaryIdentifier(link.identifier);
      addResourceMetadata(metadata, isContainerIdentifier(link.identifier));
      this.logger.debug(`Generating resource ${metaIdentifier.path}`);
      yield {
        identifier: metaIdentifier,
        representation: new BasicRepresentation(metadata.quads(), metaIdentifier, INTERNAL_QUADS),
      };
    }
  }

  /**
   * Generates a RepresentationMetadata using the given template.
   */
  private async generateMetadata(metaLink: TemplateResourceLink, options: Dict<unknown>):
  Promise<RepresentationMetadata> {
    const metadata = new RepresentationMetadata(metaLink.identifier);

    const data = await this.processFile(metaLink, options);
    const parser = new Parser({ format: metaLink.contentType, baseIRI: metaLink.identifier.path });
    const quads = parser.parse(await readableToString(data));
    metadata.addQuads(quads);

    return metadata;
  }

  /**
   * Creates a read stream from the file and applies the template if necessary.
   */
  private async processFile(link: TemplateResourceLink, contents: Dict<unknown>): Promise<Guarded<Readable>> {
    if (link.isTemplate) {
      const rendered = await this.templateEngine.handleSafe({ contents, template: { templateFile: link.filePath }});
      return guardedStreamFrom(rendered);
    }
    return guardStream(createReadStream(link.filePath));
  }
}

/**
 * Used for instantiating new object using Components.js configurations.
 */
export interface ComponentsJsFactory {
  /**
   * Instantiates a new object using Components.js.
   *
   * @param configPath - Location of the config to instantiate.
   * @param componentIri - IRI of the object in the config that will be the result.
   * @param variables - Variables to send to Components.js
   *
   * @returns The resulting object, corresponding to the given component IRI.
   */
  generate: <T>(configPath: string, componentIri: string, variables: Record<string, unknown>) => Promise<T>;
}

import type { ResourceStore } from '../../storage/ResourceStore';
import type { PodSettings } from '../settings/PodSettings';
import type { ResourcesGenerator } from './ResourcesGenerator';

/**
 * Generates resources with the given generator and adds them to the given store.
 *
 * @param settings - Settings from which the pod is being created.
 * @param generator - Generator to be used.
 * @param store - Store to be updated.
 *
 * @returns The amount of resources that were added.
 */
export async function addGeneratedResources(
  settings: PodSettings,
  generator: ResourcesGenerator,
  store: ResourceStore,
): Promise<number> {
  const resources = generator.generate(settings.base, settings);
  let count = 0;
  for await (const { identifier: resourceId, representation } of resources) {
    await store.setRepresentation(resourceId, representation);
    count += 1;
  }
  return count;
}

import type { ResourceIdentifier } from '../../http/representation/ResourceIdentifier';

/**
 * Utility class for generating container identifiers.
 */
export interface IdentifierGenerator {
  /**
   * Generates container identifiers based on an input name.
   * This is simply string generation, no resource-related checks are run.
   */
  generate: (name: string) => ResourceIdentifier;

  /**
   * Extracts the root pod this identifier would be in.
   * This assumes the identifier of that pod was generated by the same instance of this interface.
   */
  extractPod: (identifier: ResourceIdentifier) => ResourceIdentifier;
}

import type { ResourceStore } from '../../storage/ResourceStore';
