/**
 * Generator used to create resources relative to a given base identifier.
 * Note that this is not an AsyncHandler since it returns an AsyncIterable instead of a promise.
 */
export interface ResourcesGenerator {
  /**
   * Generates resources with the given options.
   * The output Iterable should be sorted so that containers always appear before their contents.
   *
   * @param location - Base identifier.
   * @param options - Options that can be used when generating resources.
   *
   * @returns A map where the keys are the identifiers and the values the corresponding representations to store.
   */
  generate: (location: ResourceIdentifier, options: Dict<unknown>) => AsyncIterable<Resource>;
}

import type { ResourceIdentifier } from '../../http/representation/ResourceIdentifier';
import type { Resource, ResourcesGenerator } from './ResourcesGenerator';
import type { TemplatedResourcesGenerator } from './TemplatedResourcesGenerator';
import Dict = NodeJS.Dict;

/**
 * Stores a static template folder that will be used to call the wrapped {@link TemplatedResourcesGenerator}.
 */
export class StaticFolderGenerator implements ResourcesGenerator {
  private readonly resourcesGenerator: TemplatedResourcesGenerator;
  private readonly templateFolder: string;

  public constructor(resourcesGenerator: TemplatedResourcesGenerator, templateFolder: string) {
    this.resourcesGenerator = resourcesGenerator;
    this.templateFolder = templateFolder;
  }

  public generate(location: ResourceIdentifier, options: Dict<unknown>): AsyncIterable<Resource> {
    return this.resourcesGenerator.generate(this.templateFolder, location, options);
  }
}

import type { ResourceIdentifier } from '../../http/representation/ResourceIdentifier';
import { BadRequestHttpError } from '../../util/errors/BadRequestHttpError';
import { ensureTrailingSlash, extractScheme } from '../../util/PathUtil';
import { sanitizeUrlPart } from '../../util/StringUtil';
import type { IdentifierGenerator } from './IdentifierGenerator';

/**
 * Generates identifiers by using the name as a subdomain on the base URL.
 * Non-alphanumeric characters will be replaced with `-`.
 *
 * When extracting the pod, the base URl is also seen as a pod as there is no issue of nested containers here.
 */
export class SubdomainIdentifierGenerator implements IdentifierGenerator {
  private readonly baseParts: { scheme: string; rest: string };

  public constructor(baseUrl: string) {
    this.baseParts = extractScheme(ensureTrailingSlash(baseUrl));
  }

  public generate(name: string): ResourceIdentifier {
    // Using the punycode converter is a risk as it doesn't convert slashes for example
    const cleanName = sanitizeUrlPart(name).toLowerCase();
    return { path: `${this.baseParts.scheme}${cleanName}.${this.baseParts.rest}` };
  }

  public extractPod(identifier: ResourceIdentifier): ResourceIdentifier {
    const { path } = identifier;

    // Invalid identifiers that have no result should never reach this point,
    // but some safety checks just in case.
    if (!path.startsWith(this.baseParts.scheme)) {
      throw new BadRequestHttpError(`Invalid identifier ${path}`);
    }

    const idx = path.indexOf(this.baseParts.rest);

    // If the idx is smaller than this, there was no match
    if (idx < 0) {
      throw new BadRequestHttpError(`Invalid identifier ${path}`);
    }

    // Slice of everything after the base URL tail
    return { path: path.slice(0, idx + this.baseParts.rest.length) };
  }
}

import type { ResourceIdentifier } from '../../http/representation/ResourceIdentifier';
import { sortedAsyncMerge } from '../../util/IterableUtil';
import { joinFilePath, resolveAssetPath } from '../../util/PathUtil';
import type { Resource } from './ResourcesGenerator';
import type { TemplatedResourcesGenerator } from './TemplatedResourcesGenerator';
import Dict = NodeJS.Dict;

// Sorts Resources based on their identifiers
function comparator(left: Resource, right: Resource): number {
  return left.identifier.path.localeCompare(right.identifier.path);
}

/**
 * Generates all resources found in specific subfolders of the given template folder.
 * In case the same resource is defined in several subfolders,
 * the data of the last subfolder in the list will be used.
 *
 * The results of all the subfolders will be merged so the end result is still a sorted stream of identifiers.
 *
 * One of the main use cases for this class is so template resources can be in a separate folder
 * than their corresponding authorization resources,
 * allowing for authorization-independent templates.
 */
export class SubfolderResourcesGenerator implements TemplatedResourcesGenerator {
  private readonly resourcesGenerator: TemplatedResourcesGenerator;
  private readonly subfolders: string[];

  public constructor(resourcesGenerator: TemplatedResourcesGenerator, subfolders: string[]) {
    this.resourcesGenerator = resourcesGenerator;
    this.subfolders = subfolders;
  }

  public async* generate(templateFolder: string, location: ResourceIdentifier, options: Dict<unknown>):
  AsyncIterable<Resource> {
    const root = resolveAssetPath(templateFolder);
    const templateSubfolders = this.subfolders.map((subfolder): string => joinFilePath(root, subfolder));

    // Build all generators
    const generators: AsyncIterator<Resource>[] = [];
    for (const templateSubfolder of templateSubfolders) {
      generators.push(this.resourcesGenerator.generate(templateSubfolder, location, options)[Symbol.asyncIterator]());
    }

    let previous: ResourceIdentifier = { path: '' };
    for await (const result of sortedAsyncMerge(generators, comparator)) {
      // Skip duplicate results.
      // In practice these are just going to be the same empty containers.
      if (result.identifier.path === previous.path) {
        result.representation.data.destroy();
      } else {
        previous = result.identifier;
        yield result;
      }
    }
  }
}

import type { ResourceIdentifier } from '../../http/representation/ResourceIdentifier';
import { BadRequestHttpError } from '../../util/errors/BadRequestHttpError';
import { ensureTrailingSlash } from '../../util/PathUtil';
import { sanitizeUrlPart } from '../../util/StringUtil';
import type { IdentifierGenerator } from './IdentifierGenerator';

/**
 * Generates identifiers by appending the name to a stored base identifier.
 * Non-alphanumeric characters will be replaced with `-`.
 */
export class SuffixIdentifierGenerator implements IdentifierGenerator {
  private readonly base: string;

  public constructor(base: string) {
    this.base = base;
  }

  public generate(name: string): ResourceIdentifier {
    const cleanName = sanitizeUrlPart(name).toLowerCase();
    return { path: ensureTrailingSlash(new URL(cleanName, this.base).href) };
  }

  public extractPod(identifier: ResourceIdentifier): ResourceIdentifier {
    const { path } = identifier;

    // Invalid identifiers that have no result should never reach this point,
    // but some safety checks just in case.
    if (!path.startsWith(this.base)) {
      throw new BadRequestHttpError(`Invalid identifier ${path}`);
    }

    // The first slash after the base URL indicates the first container on the path
    const idx = path.indexOf('/', this.base.length + 1);

    if (idx < 0) {
      throw new BadRequestHttpError(`Invalid identifier ${path}`);
    }

    // Slice of everything after the first container
    return { path: path.slice(0, idx + 1) };
  }
}

import { getLoggerFor } from '../../logging/LogUtil';
import type { KeyValueStorage } from '../../storage/keyvalue/KeyValueStorage';
import type { ResourceStore } from '../../storage/ResourceStore';
import { BadRequestHttpError } from '../../util/errors/BadRequestHttpError';
import { ConflictHttpError } from '../../util/errors/ConflictHttpError';
import { joinFilePath } from '../../util/PathUtil';
import type { PodSettings } from '../settings/PodSettings';
import type { ComponentsJsFactory } from './ComponentsJsFactory';
import type { PodGenerator } from './PodGenerator';
import type { VariableHandler } from './variables/VariableHandler';
import { isValidVariable, TEMPLATE, TEMPLATE_VARIABLE } from './variables/Variables';

const DEFAULT_CONFIG_PATH = joinFilePath(__dirname, '../../../templates/config/');

/**
 * Creates a new ResourceStore when creating a pod based on a Components.js configuration.
 *
 * Part of the dynamic pod creation.
 *  1. It calls a VariableHandler to add necessary variable values.
 *     E.g. setting the base url variable for components.js to the pod identifier.
 *  2. It filters/cleans the input agent values using {@link VariableHandler}s
 *  3. It calls a ComponentsJsFactory with the variables and template location to instantiate a new ResourceStore.
 *  4. It stores these values in the configuration storage, which is used as a permanent storage for pod configurations.
 *
 * @see {@link ConfigPodManager}, {@link ConfigPodInitializer}, {@link BaseUrlRouterRule}
 */
export class TemplatedPodGenerator implements PodGenerator {
  protected readonly logger = getLoggerFor(this);
  private readonly storeFactory: ComponentsJsFactory;
  private readonly variableHandler: VariableHandler;
  private readonly configStorage: KeyValueStorage<string, unknown>;
  private readonly configTemplatePath: string;
  private readonly baseUrl: string;

  /**
   * @param storeFactory - Factory used for Components.js instantiation.
   * @param variableHandler - Handler used for setting variable values.
   * @param configStorage - Where to store the configuration values to instantiate the store for this pod.
   * @param baseUrl - Base URL of the server.
   * @param configTemplatePath - Where to find the configuration templates.
   */
  public constructor(
    storeFactory: ComponentsJsFactory,
    variableHandler: VariableHandler,
    configStorage: KeyValueStorage<string, unknown>,
    baseUrl: string,
    configTemplatePath?: string,
  ) {
    this.storeFactory = storeFactory;
    this.variableHandler = variableHandler;
    this.configStorage = configStorage;
    this.baseUrl = baseUrl;
    this.configTemplatePath = configTemplatePath ?? DEFAULT_CONFIG_PATH;
  }

  public async generate(settings: PodSettings): Promise<ResourceStore> {
    const identifier = settings.base;
    if (!settings.template) {
      throw new BadRequestHttpError('Settings require template field.');
    }

    if (await this.configStorage.has(identifier.path)) {
      this.logger.warn(`There already is a pod at ${identifier.path}`);
      throw new ConflictHttpError(`There already is a pod at ${identifier.path}`);
    }

    await this.variableHandler.handleSafe({ identifier, settings });

    // Filter out irrelevant data in the agent
    const variables: NodeJS.Dict<unknown> = {};
    for (const key of Object.keys(settings)) {
      if (isValidVariable(key)) {
        variables[key] = settings[key];
      }
    }

    // Prevent unsafe template names
    if (!/^[a-zA-Z0-9.-]+$/u.test(settings.template)) {
      this.logger.warn(`Invalid template name ${settings.template}`);
      throw new BadRequestHttpError(`Invalid template name ${settings.template}`);
    }
    // Storing the template in the variables so it also gets stored in the config for later re-use
    variables[TEMPLATE_VARIABLE.templateConfig] = joinFilePath(this.configTemplatePath, settings.template);

    const store: ResourceStore =
      await this.storeFactory.generate(
        variables[TEMPLATE_VARIABLE.templateConfig] as string,
        TEMPLATE.ResourceStore,
        // eslint-disable-next-line @typescript-eslint/naming-convention
        { ...variables, 'urn:solid-server:default:variable:baseUrl': this.baseUrl },
      );
    this.logger.debug(`Generating store ${identifier.path} with variables ${JSON.stringify(variables)}`);

    // Store the variables permanently
    await this.configStorage.set(identifier.path, variables);

    return store;
  }
}

import type { ResourceIdentifier } from '../../http/representation/ResourceIdentifier';
import type { Resource } from './ResourcesGenerator';
import Dict = NodeJS.Dict;

/**
 * Generator used to create resources relative to a given base identifier.
 * Similar to {@link ResourcesGenerator}, but takes as input a string
 * indicating where the templates are stored that need to be used for resource generation.
 */
export interface TemplatedResourcesGenerator {
  /**
   * Generates resources with the given options, based on the given template folder.
   * The output Iterable should be sorted so that containers always appear before their contents.
   *
   * @param templateFolder - Folder where the templates are located.
   * @param location - Base identifier.
   * @param options - Options that can be used when generating resources.
   *
   * @returns A map where the keys are the identifiers and the values the corresponding representations to store.
   */
  generate: (templateFolder: string, location: ResourceIdentifier, options: Dict<unknown>) => AsyncIterable<Resource>;
}

import type { ResourceIdentifier } from '../../../http/representation/ResourceIdentifier';
import type { PodSettings } from '../../settings/PodSettings';
import { VariableHandler } from './VariableHandler';
import { TEMPLATE_VARIABLE } from './Variables';

/**
 * Adds the pod identifier as base url variable to the agent.
 * This allows for config templates that require a value for TEMPLATE_BASE_URL_URN,
 * which should equal the pod identifier.
 */
export class BaseUrlHandler extends VariableHandler {
  public async handle({ identifier, settings }: { identifier: ResourceIdentifier; settings: PodSettings }):
  Promise<void> {
    settings[TEMPLATE_VARIABLE.baseUrl] = identifier.path;
  }
}

import { promises as fsPromises } from 'node:fs';
import type { ResourceIdentifier } from '../../../http/representation/ResourceIdentifier';
import type { FileIdentifierMapper } from '../../../storage/mapping/FileIdentifierMapper';
import { ConflictHttpError } from '../../../util/errors/ConflictHttpError';
import { isSystemError } from '../../../util/errors/SystemError';
import type { PodSettings } from '../../settings/PodSettings';
import { VariableHandler } from './VariableHandler';
import { TEMPLATE_VARIABLE } from './Variables';

/**
 * Uses a FileIdentifierMapper to generate a root file path variable based on the identifier.
 * Will throw an error if the resulting file path already exists.
 */
export class RootFilePathHandler extends VariableHandler {
  private readonly fileMapper: FileIdentifierMapper;

  public constructor(fileMapper: FileIdentifierMapper) {
    super();
    this.fileMapper = fileMapper;
  }

  public async handle({ identifier, settings }: { identifier: ResourceIdentifier; settings: PodSettings }):
  Promise<void> {
    const path = (await this.fileMapper.mapUrlToFilePath(identifier, false)).filePath;
    try {
      // Even though we check if it already exists, there is still a potential race condition
      // in between this check and the store being created.
      await fsPromises.access(path);
      throw new ConflictHttpError(`There already is a folder that corresponds to ${identifier.path}`);
    } catch (error: unknown) {
      if (!(isSystemError(error) && error.code === 'ENOENT')) {
        throw error;
      }
      settings[TEMPLATE_VARIABLE.rootFilePath] = path;
    }
  }
}

import type { ResourceIdentifier } from '../../../http/representation/ResourceIdentifier';
import { AsyncHandler } from '../../../util/handlers/AsyncHandler';
import type { PodSettings } from '../../settings/PodSettings';

/**
 * Updates the variables stored in the given agent.
 * Can be used to set variables that are required for the Components.js instantiation
 * but which should not be provided by the request.
 * E.g.: The exact file path (when required) should be determined by the server to prevent abuse.
 */
export abstract class VariableHandler extends AsyncHandler<{ identifier: ResourceIdentifier; settings: PodSettings }> {}

import { createVocabulary } from '../../../util/Vocabularies';

export const TEMPLATE = createVocabulary(
  'urn:solid-server:template:',
  'ResourceStore',
);

// Variables used for configuration templates
// This is not an exclusive list
export const TEMPLATE_VARIABLE = createVocabulary(
  `${TEMPLATE.namespace}variable:`,
  'baseUrl',
  'rootFilePath',
  'sparqlEndpoint',
  'templateConfig',
);

/**
 * Checks if the given variable is one that is supported.
 * This can be used to weed out irrelevant parameters in an object.
 */
export function isValidVariable(variable: string): boolean {
  return variable.startsWith(TEMPLATE_VARIABLE.namespace);
}

import type { PodSettings } from '../../settings/PodSettings';
import { VariableHandler } from './VariableHandler';

/**
 * A VariableHandler that will set the given variable to the given value,
 * unless there already is a value for the variable and override is false.
 */
export class VariableSetter extends VariableHandler {
  private readonly variable: string;
  private readonly value: string;
  private readonly override: boolean;

  public constructor(variable: string, value: string, override = false) {
    super();
    this.variable = variable;
    this.value = value;
    this.override = override;
  }

  public async handle({ settings }: { settings: PodSettings }): Promise<void> {
    if (this.override || !settings[this.variable]) {
      settings[this.variable] = this.value;
    }
  }
}

import { getLoggerFor } from '../logging/LogUtil';
import type { ResourceStore } from '../storage/ResourceStore';
import { ConflictHttpError } from '../util/errors/ConflictHttpError';
import { addGeneratedResources } from './generate/GenerateUtil';
import type { ResourcesGenerator } from './generate/ResourcesGenerator';
import type { PodManager } from './PodManager';
import type { PodSettings } from './settings/PodSettings';

/**
 * Pod manager that uses an {@link IdentifierGenerator} and {@link ResourcesGenerator}
 * to create the default resources and identifier for a new pod.
 */
export class GeneratedPodManager implements PodManager {
  protected readonly logger = getLoggerFor(this);

  private readonly store: ResourceStore;
  private readonly resourcesGenerator: ResourcesGenerator;

  public constructor(store: ResourceStore, resourcesGenerator: ResourcesGenerator) {
    this.store = store;
    this.resourcesGenerator = resourcesGenerator;
  }

  /**
   * Creates a new pod, pre-populating it with the resources created by the data generator.
   * Will throw an error if the given identifier already has a resource.
   */
  public async createPod(settings: PodSettings, overwrite: boolean): Promise<void> {
    this.logger.info(`Creating pod ${settings.base.path}`);
    if (!overwrite && await this.store.hasResource(settings.base)) {
      throw new ConflictHttpError(`There already is a resource at ${settings.base.path}`);
    }

    const count = await addGeneratedResources(settings, this.resourcesGenerator, this.store);
    this.logger.info(`Added ${count} resources to ${settings.base.path}`);
  }
}

import type { PodSettings } from './settings/PodSettings';

/**
 * Covers all functions related to pod management.
 * In the future this should also include delete, and potentially recovery functions.
 */
export interface PodManager {
  /**
   * Creates a pod for the given settings.
   *
   * @param settings - Settings describing the pod.
   * @param overwrite - If the creation should proceed if there already is a resource there.
   */
  createPod: (settings: PodSettings, overwrite: boolean) => Promise<void>;
}

import type { ResourceIdentifier } from '../../http/representation/ResourceIdentifier';

/**
 * Metadata related to pod generation.
 */
export interface PodSettings extends NodeJS.Dict<unknown> {
  /**
   * The root of the pod. Determines where the pod will be created.
