import type { NamedNode, Quad, Quad_Object, Term } from '@rdfjs/types';
import { DataFactory } from 'n3';
import { stringToTerm } from 'rdf-string';
import type { ResourceIdentifier } from '../../http/representation/ResourceIdentifier';
import { StorageDescriber } from './StorageDescriber';
import quad = DataFactory.quad;
import namedNode = DataFactory.namedNode;

/**
 * Adds a fixed set of triples to the storage description resource,
 * with the resource identifier as subject.
 *
 * This can be used to add descriptions that a storage always needs to have,
 * such as the `<> a pim:Storage` triple.
 */
export class StaticStorageDescriber extends StorageDescriber {
  private readonly terms: ReadonlyMap<NamedNode, Quad_Object[]>;

  public constructor(terms: Record<string, string | string[]>) {
    super();
    const termMap = new Map<NamedNode, Quad_Object[]>();
    for (const [ predicate, objects ] of Object.entries(terms)) {
      const predTerm = stringToTerm(predicate);
      if (predTerm.termType !== 'NamedNode') {
        throw new Error('Predicate needs to be a named node.');
      }
      const objTerms = (Array.isArray(objects) ? objects : [ objects ]).map((obj): Term => stringToTerm(obj));
      // `stringToTerm` can only generate valid term types
      termMap.set(predTerm, objTerms as Quad_Object[]);
    }
    this.terms = termMap;
  }

  public async handle(target: ResourceIdentifier): Promise<Quad[]> {
    const subject = namedNode(target.path);
    return [ ...this.generateTriples(subject) ];
  }

  private* generateTriples(subject: NamedNode): Iterable<Quad> {
    for (const [ predicate, objects ] of this.terms.entries()) {
      for (const object of objects) {
        yield quad(subject, predicate, object);
      }
    }
  }
}

import type { Quad } from '@rdfjs/types';
import type { ResourceIdentifier } from '../../http/representation/ResourceIdentifier';
import { AsyncHandler } from '../../util/handlers/AsyncHandler';

/**
 * Generates Quads that need to be added to the given storage description resource.
 */
export abstract class StorageDescriber extends AsyncHandler<ResourceIdentifier, Quad[]> {}

import { OkResponseDescription } from '../../http/output/response/OkResponseDescription';
import type { ResponseDescription } from '../../http/output/response/ResponseDescription';
import { BasicRepresentation } from '../../http/representation/BasicRepresentation';
import type { ResourceIdentifier } from '../../http/representation/ResourceIdentifier';
import type { ResourceStore } from '../../storage/ResourceStore';
import { INTERNAL_QUADS } from '../../util/ContentTypes';
import { MethodNotAllowedHttpError } from '../../util/errors/MethodNotAllowedHttpError';
import { NotImplementedHttpError } from '../../util/errors/NotImplementedHttpError';
import { ensureTrailingSlash } from '../../util/PathUtil';
import { PIM, RDF } from '../../util/Vocabularies';
import type { OperationHttpHandlerInput } from '../OperationHttpHandler';
import { OperationHttpHandler } from '../OperationHttpHandler';
import type { StorageDescriber } from './StorageDescriber';

/**
 * Generates the response for GET requests targeting a storage description resource.
 * The input path needs to match the relative path used to generate storage description resources
 * and will be used to verify if the container it is linked to is an actual storage.
 */
export class StorageDescriptionHandler extends OperationHttpHandler {
  private readonly store: ResourceStore;
  private readonly path: string;
  private readonly describer: StorageDescriber;

  public constructor(store: ResourceStore, path: string, describer: StorageDescriber) {
    super();
    this.store = store;
    this.path = path;
    this.describer = describer;
  }

  public async canHandle({ operation: { target, method }}: OperationHttpHandlerInput): Promise<void> {
    if (method !== 'GET') {
      throw new MethodNotAllowedHttpError([ method ], `Only GET requests can target the storage description.`);
    }
    const container = this.getStorageIdentifier(target);
    const representation = await this.store.getRepresentation(container, {});
    representation.data.destroy();
    if (!representation.metadata.has(RDF.terms.type, PIM.terms.Storage)) {
      throw new NotImplementedHttpError(`Only supports descriptions of storage containers.`);
    }

    await this.describer.canHandle(target);
  }

  public async handle({ operation: { target }}: OperationHttpHandlerInput): Promise<ResponseDescription> {
    const quads = await this.describer.handle(this.getStorageIdentifier(target));

    const representation = new BasicRepresentation(quads, INTERNAL_QUADS);

    return new OkResponseDescription(representation.metadata, representation.data);
  }

  /**
   * Determine the identifier of the root storage based on the identifier of the root storage description resource.
   */
  protected getStorageIdentifier(descriptionIdentifier: ResourceIdentifier): ResourceIdentifier {
    return { path: ensureTrailingSlash(descriptionIdentifier.path.slice(0, -this.path.length)) };
  }
}

import type { ResourceIdentifier } from '../../http/representation/ResourceIdentifier';

/**
 * Interface used to find the storage a specific identifier is located in.
 */
export interface StorageLocationStrategy {
  /**
   * Returns the identifier of the storage that contains the given resource.
   * Can error if the input identifier is not part of any storage.
   */
  getStorageIdentifier: (identifier: ResourceIdentifier) => Promise<ResourceIdentifier>;
}

import type { IncomingMessage, Server, ServerResponse } from 'node:http';
import { getLoggerFor } from '../logging/LogUtil';
import { isError } from '../util/errors/ErrorUtil';
import { guardStream } from '../util/GuardedStream';
import type { HttpHandler } from './HttpHandler';
import { ServerConfigurator } from './ServerConfigurator';

/**
 * A {@link ServerConfigurator} that attaches an {@link HttpHandler} to the `request` event of a {@link Server}.
 * All incoming requests will be sent to the provided handler.
 * Failsafes are added to make sure a valid response is sent in case something goes wrong.
 *
 * The `showStackTrace` parameter can be used to add stack traces to error outputs.
 */
export class HandlerServerConfigurator extends ServerConfigurator {
  protected readonly logger = getLoggerFor(this);
  protected readonly errorLogger = (error: Error): void => {
    this.logger.error(`Request error: ${error.message}`);
  };

  /** The main HttpHandler */
  private readonly handler: HttpHandler;
  private readonly showStackTrace: boolean;

  public constructor(handler: HttpHandler, showStackTrace = false) {
    super();
    this.handler = handler;
    this.showStackTrace = showStackTrace;
  }

  public async handle(server: Server): Promise<void> {
    server.on(
      'request',
      // eslint-disable-next-line @typescript-eslint/no-misused-promises
      async(request: IncomingMessage, response: ServerResponse): Promise<void> => {
        try {
          this.logger.info(`Received ${request.method} request for ${request.url}`);
          const guardedRequest = guardStream(request);
          guardedRequest.on('error', this.errorLogger);
          await this.handler.handleSafe({ request: guardedRequest, response });
        } catch (error: unknown) {
          const errMsg = this.createErrorMessage(error);
          this.logger.error(errMsg);
          if (response.headersSent) {
            response.end();
          } else {
            response.setHeader('Content-Type', 'text/plain; charset=utf-8');
            response.writeHead(500).end(errMsg);
          }
        } finally {
          if (!response.headersSent) {
            response.writeHead(404).end();
          }
        }
      },
    );
  }

  /**
   * Creates a readable error message based on the error and the `showStackTrace` parameter.
   */
  private createErrorMessage(error: unknown): string {
    if (!isError(error)) {
      return `Unknown error: ${error as string}.\n`;
    }
    if (this.showStackTrace && isError(error) && error.stack) {
      return `${error.stack}\n`;
    }
    return `${error.name}: ${error.message}\n`;
  }
}

import { AsyncHandler } from '../util/handlers/AsyncHandler';
import type { HttpRequest } from './HttpRequest';
import type { HttpResponse } from './HttpResponse';

export interface HttpHandlerInput {
  request: HttpRequest;
  response: HttpResponse;
}

/**
 * An HTTP request handler.
 */
export abstract class HttpHandler extends AsyncHandler<HttpHandlerInput> {}

import type { IncomingMessage } from 'node:http';
import type { Guarded } from '../util/GuardedStream';

/**
 * An incoming HTTP request;
 */
export type HttpRequest = Guarded<IncomingMessage>;

/**
 * Checks if the given stream is an HttpRequest.
 */
export function isHttpRequest(stream: unknown): stream is HttpRequest {
  const req = stream as HttpRequest;
  return typeof req.socket === 'object' && typeof req.url === 'string' && typeof req.method === 'string';
}

import type { ServerResponse } from 'node:http';

/**
 * An outgoing HTTP response;
 */
export type HttpResponse = ServerResponse;

import type { Server } from 'node:http';
import { Server as HttpsServer } from 'node:https';

/**
 * Returns `true` if the server is an HTTPS server.
 */
export function isHttpsServer(server: Server): server is HttpsServer {
  return server instanceof HttpsServer;
}

/**
 * A factory for HTTP servers.
 */
export interface HttpServerFactory {
  createServer: () => Promise<Server>;
}

import type { AuxiliaryIdentifierStrategy } from '../../http/auxiliary/AuxiliaryIdentifierStrategy';
import type { TargetExtractor } from '../../http/input/identifier/TargetExtractor';
import { addHeader } from '../../util/HeaderUtil';
import { ACP } from '../../util/Vocabularies';
import type { HttpHandlerInput } from '../HttpHandler';
import { HttpHandler } from '../HttpHandler';

/**
 * Handles all the required ACP headers as defined at
 * https://solid.github.io/authorization-panel/acp-specification/#conforming-acp-server
 */
export class AcpHeaderHandler extends HttpHandler {
  private readonly targetExtractor: TargetExtractor;
  private readonly strategy: AuxiliaryIdentifierStrategy;
  private readonly modes: string[];
  private readonly attributes: string[];

  public constructor(
    targetExtractor: TargetExtractor,
    strategy: AuxiliaryIdentifierStrategy,
    modes: string[],
    attributes: string[],
  ) {
    super();
    this.targetExtractor = targetExtractor;
    this.strategy = strategy;
    this.modes = modes;
    this.attributes = attributes;
  }

  public async handle({ request, response }: HttpHandlerInput): Promise<void> {
    const identifier = await this.targetExtractor.handleSafe({ request });
    if (!this.strategy.isAuxiliaryIdentifier(identifier)) {
      return;
    }
    const linkValues = [
      `<${ACP.AccessControlResource}>; rel="type"`,
      ...this.modes.map((mode): string => `<${mode}>; rel="${ACP.grant}"`),
      ...this.attributes.map((attribute): string => `<${attribute}>; rel="${ACP.attribute}"`),
    ];
    addHeader(response, 'Link', linkValues);
  }
}

import cors from 'cors';
import type { CorsOptions, CorsRequest } from 'cors';
import type { HttpHandlerInput } from '../HttpHandler';
import { HttpHandler } from '../HttpHandler';

const defaultOptions: CorsOptions = {
  origin: (origin: string | undefined, callback: (err: Error | null, origin?: string) => void): void =>
    callback(null, origin ?? '*'),
};

// Components.js does not support the full CorsOptions yet
interface SimpleCorsOptions {
  origin?: string;
  methods?: string[];
  allowedHeaders?: string[];
  exposedHeaders?: string[];
  credentials?: boolean;
  maxAge?: number;
  preflightContinue?: boolean;
  optionsSuccessStatus?: number;
}

/**
 * Handler that sets CORS options on the response.
 * In case of an OPTIONS request this handler will close the connection after adding its headers
 * if `preflightContinue` is set to `false`.
 *
 * Solid, §8.1: "A server MUST implement the CORS protocol [FETCH] such that, to the extent possible,
 * the browser allows Solid apps to send any request and combination of request headers to the server,
 * and the Solid app can read any response and response headers received from the server."
 * Full details: https://solidproject.org/TR/2021/protocol-20211217#cors-server
 */
export class CorsHandler extends HttpHandler {
  private readonly corsHandler: (
    req: CorsRequest,
    res: {
      statusCode?: number;
      setHeader: (key: string, value: string) => unknown;
      end: () => unknown;
    },
    next: (err?: unknown) => unknown,
  ) => void;

  public constructor(options: SimpleCorsOptions = {}) {
    super();
    this.corsHandler = cors({ ...defaultOptions, ...options });
  }

  public async handle(input: HttpHandlerInput): Promise<void> {
    return new Promise((resolve): void => {
      this.corsHandler(input.request, input.response, (): void => resolve());
    });
  }
}

import { HttpHandler } from '../HttpHandler';
import type { HttpResponse } from '../HttpResponse';

/**
 * Handler that sets custom headers on the response.
 */
export class HeaderHandler extends HttpHandler {
  private readonly headers: Record<string, string>;

  public constructor(headers: Record<string, string>) {
    super();
    this.headers = { ...headers };
  }

  public async handle({ response }: { response: HttpResponse }): Promise<void> {
    for (const header of Object.keys(this.headers)) {
      response.setHeader(header, this.headers[header]);
    }
  }
}

import { createReadStream } from 'node:fs';
import escapeStringRegexp from 'escape-string-regexp';
import * as mime from 'mime-types';
import { getLoggerFor } from '../../logging/LogUtil';
import { APPLICATION_OCTET_STREAM } from '../../util/ContentTypes';
import { InternalServerError } from '../../util/errors/InternalServerError';
import { NotFoundHttpError } from '../../util/errors/NotFoundHttpError';
import { NotImplementedHttpError } from '../../util/errors/NotImplementedHttpError';
import type { SystemError } from '../../util/errors/SystemError';
import { ensureTrailingSlash, joinFilePath, resolveAssetPath, trimLeadingSlashes } from '../../util/PathUtil';
import { pipeSafely } from '../../util/StreamUtil';
import type { HttpHandlerInput } from '../HttpHandler';
import { HttpHandler } from '../HttpHandler';
import type { HttpRequest } from '../HttpRequest';

/**
 * Used to link file paths with relative URLs.
 * By using a separate class instead of a key/value map it is easier to replace values in Components.js.
 */
export class StaticAssetEntry {
  public constructor(
    public readonly relativeUrl: string,
    public readonly filePath: string,
  ) {}
}

/**
 * Handler that serves static resources on specific paths.
 * Relative file paths are assumed to be relative to the current working directory.
 * Relative file paths can be preceded by `@css:`, e.g. `@css:foo/bar`,
 * in case they need to be relative to the module root.
 * File paths ending in a slash assume the target is a folder and map all of its contents.
 */
export class StaticAssetHandler extends HttpHandler {
  private readonly mappings: Record<string, string>;
  private readonly pathMatcher: RegExp;
  private readonly expires: number;
  private readonly logger = getLoggerFor(this);

  /**
   * Creates a handler for the provided static resources.
   *
   * @param assets - A list of {@link StaticAssetEntry}.
   * @param baseUrl - The base URL of the server.
   * @param options - Specific options.
   * @param options.expires - Cache expiration time in seconds.
   */
  public constructor(assets: StaticAssetEntry[], baseUrl: string, options: { expires?: number } = {}) {
    super();
    this.mappings = {};
    const rootPath = ensureTrailingSlash(new URL(baseUrl).pathname);

    for (const { relativeUrl, filePath } of assets) {
      this.mappings[trimLeadingSlashes(relativeUrl)] = resolveAssetPath(filePath);
    }
    this.pathMatcher = this.createPathMatcher(rootPath);
    this.expires = Number.isInteger(options.expires) ? Math.max(0, options.expires!) : 0;
  }

  /**
   * Creates a regular expression that matches the URL paths.
   */
  private createPathMatcher(rootPath: string): RegExp {
    // Sort longest paths first to ensure the longest match has priority
    const paths = Object.keys(this.mappings)
      .sort((pathA, pathB): number => pathB.length - pathA.length);

    // Collect regular expressions for files and folders separately.
    // The arrays need initial values to prevent matching everything, as they will if these are empty.
    const files = [ '.^' ];
    const folders = [ '.^' ];
    for (const path of paths) {
      const filePath = this.mappings[path];
      if (filePath.endsWith('/') && !path.endsWith('/')) {
        throw new InternalServerError(
          `Server is misconfigured: StaticAssetHandler can not ` +
          `have a file path ending on a slash if the URL does not, but received ${path} and ${filePath}`,
        );
      }
      (filePath.endsWith('/') ? folders : files).push(escapeStringRegexp(path));
    }

    // Either match an exact document or a file within a folder (stripping the query string)
    return new RegExp(`^${rootPath}(?:(${files.join('|')})|(${folders.join('|')})([^?]+))(?:\\?.*)?$`, 'u');
  }

  /**
   * Obtains the file path corresponding to the asset URL
   */
  private getFilePath({ url }: HttpRequest): string {
    // Verify if the URL matches any of the paths
    const match = this.pathMatcher.exec(url ?? '');
    if (!match || match[0].includes('/..')) {
      throw new NotImplementedHttpError(`No static resource configured at ${url}`);
    }

    // The mapping is either a known document, or a file within a folder
    const [ , document, folder, file ] = match;

    return typeof document === 'string' ?
      this.mappings[document] :
        joinFilePath(this.mappings[folder], decodeURIComponent(file));
  }

  public async canHandle({ request }: HttpHandlerInput): Promise<void> {
    if (request.method !== 'GET' && request.method !== 'HEAD') {
      throw new NotImplementedHttpError('Only GET and HEAD requests are supported');
    }
    this.getFilePath(request);
  }

  public async handle({ request, response }: HttpHandlerInput): Promise<void> {
    // Determine the asset to serve
    const filePath = this.getFilePath(request);
    this.logger.debug(`Serving ${request.url} via static asset ${filePath}`);

    // Resolve when asset loading succeeds
    const asset = createReadStream(filePath);
    return new Promise((resolve, reject): void => {
      // Write a 200 response when the asset becomes readable
      asset.once('readable', (): void => {
        const contentType = mime.lookup(filePath) || APPLICATION_OCTET_STREAM;
        response.writeHead(200, {
          // eslint-disable-next-line @typescript-eslint/naming-convention
          'content-type': contentType,
          ...this.getCacheHeaders(),
        });

        // With HEAD, only write the headers
        if (request.method === 'HEAD') {
          response.end();
          asset.destroy();
        // With GET, pipe the entire response
        } else {
          pipeSafely(asset, response);
        }
        resolve();
      });

      // Pass the error when something goes wrong
      asset.once('error', (error): void => {
        const { code } = error as SystemError;
        // When the file if not found or a folder, signal a 404
        if (code === 'ENOENT' || code === 'EISDIR') {
          this.logger.debug(`Static asset ${filePath} not found`);
          reject(new NotFoundHttpError(`Cannot find ${request.url}`));
        // In other cases, we might already have started writing, so just hang up
        } else {
          this.logger.warn(`Error reading asset ${filePath}: ${error.message}`);
          response.end();
          asset.destroy();
          resolve();
        }
      });
    });
  }

  private getCacheHeaders(): Record<string, string> {
    return this.expires <= 0 ?
        {} :
        {
          // eslint-disable-next-line @typescript-eslint/naming-convention
          'cache-control': `max-age=${this.expires}`,
          expires: new Date(Date.now() + this.expires * 1000).toUTCString(),
        };
  }
}

import { addHeader, hasScheme } from '../../util/HeaderUtil';
import { HttpHandler } from '../HttpHandler';
import type { HttpResponse } from '../HttpResponse';

/**
 * Handler that advertises a WebSocket through the Updates-Via header.
 */
export class WebSocketAdvertiser extends HttpHandler {
  private readonly socketUrl: string;

  public constructor(baseUrl: string) {
    super();
    const socketUrl = new URL(baseUrl);
    socketUrl.protocol = hasScheme(baseUrl, 'http', 'ws') ? 'ws:' : 'wss:';
    this.socketUrl = socketUrl.href;
  }

  public async handle({ response }: { response: HttpResponse }): Promise<void> {
    addHeader(response, 'Updates-Via', this.socketUrl);
  }
}

import type { RepresentationMetadata } from '../../http/representation/RepresentationMetadata';
import type { ResourceIdentifier } from '../../http/representation/ResourceIdentifier';
import type { GenericEventEmitter } from '../../util/GenericEventEmitter';
import { createGenericEventEmitterClass } from '../../util/GenericEventEmitter';
import type { AS, VocabularyTerm, VocabularyValue } from '../../util/Vocabularies';

/**
 * An event emitter used to report changes made to resources.
 * Both generic `change` events and ActivityStream-specific events are emitted.
 */
export type ActivityEmitter =
  GenericEventEmitter<
    'changed',
    (target: ResourceIdentifier, activity: VocabularyTerm<typeof AS>, metadata: RepresentationMetadata) => void
  > &
  GenericEventEmitter<
    VocabularyValue<typeof AS>,
    (target: ResourceIdentifier, metadata: RepresentationMetadata) => void
  >;

/**
 * A class implementation of {@link ActivityEmitter}.
 */
// eslint-disable-next-line @typescript-eslint/naming-convention
export const BaseActivityEmitter = createGenericEventEmitterClass<ActivityEmitter>();

import { Readable } from 'node:stream';
import { KeysRdfParseJsonLd } from '@comunica/context-entries';
import { parse, toSeconds } from 'iso8601-duration';
import { DataFactory } from 'n3';
import type { Store } from 'n3';
import type { NamedNode, Term } from '@rdfjs/types';
import rdfParser from 'rdf-parse';
import SHACLValidator from 'rdf-validate-shacl';
import { v4 } from 'uuid';
import type { Credentials } from '../../authentication/Credentials';
import type { AccessMap } from '../../authorization/permissions/Permissions';
import { AccessMode } from '../../authorization/permissions/Permissions';
import type { InteractionRoute } from '../../identity/interaction/routing/InteractionRoute';
import { ContextDocumentLoader } from '../../storage/conversion/ConversionUtil';
import { UnprocessableEntityHttpError } from '../../util/errors/UnprocessableEntityHttpError';
import { IdentifierSetMultiMap } from '../../util/map/IdentifierMap';
import { joinUrl } from '../../util/PathUtil';
import { readableToQuads } from '../../util/StreamUtil';
import { msToDuration } from '../../util/StringUtil';
import { NOTIFY, RDF, XSD } from '../../util/Vocabularies';
import { CONTEXT_NOTIFICATION } from './Notification';
import type { NotificationChannel } from './NotificationChannel';
import type { NotificationChannelType, SubscriptionService } from './NotificationChannelType';
import namedNode = DataFactory.namedNode;

/**
 * Helper type used to store information about the default features.
 */
type Feature = {
  predicate: NamedNode;
  key: keyof NotificationChannel;
  dataType: string;
};

/**
 * All the necessary fields of the default features that are possible for all Notification Channels.
 */
const featureDefinitions: Feature[] = [
  { predicate: NOTIFY.terms.accept, key: 'accept', dataType: XSD.string },
  { predicate: NOTIFY.terms.endAt, key: 'endAt', dataType: XSD.dateTime },
  { predicate: NOTIFY.terms.rate, key: 'rate', dataType: XSD.duration },
  { predicate: NOTIFY.terms.startAt, key: 'startAt', dataType: XSD.dateTime },
  { predicate: NOTIFY.terms.state, key: 'state', dataType: XSD.string },
];

/**
 * The default notification features that are available on all channel types.
 */
export const DEFAULT_NOTIFICATION_FEATURES = featureDefinitions.map((feat): string => feat.predicate.value);

// This context is slightly outdated but seems to be the only "official" source for a SHACL context.
const CONTEXT_SHACL = 'https://w3c.github.io/shacl/shacl-jsonld-context/shacl.context.ld.json';
/**
 * The SHACL shape for the minimum requirements on a notification channel subscription request.
 */
export const DEFAULT_SUBSCRIPTION_SHACL = {
  // eslint-disable-next-line @typescript-eslint/naming-convention
  '@context': [ CONTEXT_SHACL ],
  // eslint-disable-next-line @typescript-eslint/naming-convention
  '@type': 'sh:NodeShape',
  // Use the topic predicate to find the focus node
  targetSubjectsOf: NOTIFY.topic,
  closed: true,
  property: [
    { path: RDF.type, minCount: 1, maxCount: 1, nodeKind: 'sh:IRI' },
    { path: NOTIFY.topic, minCount: 1, maxCount: 1, nodeKind: 'sh:IRI' },
    ...featureDefinitions.map((feat): unknown =>
      ({ path: feat.predicate.value, maxCount: 1, datatype: feat.dataType })),
  ],
} as const;

/**
 * A {@link NotificationChannelType} that handles the base case of parsing and serializing a notification channel.
 * Note that the `extractModes` call always requires Read permissions on the target resource.
 *
 * Uses SHACL to validate the incoming data in `initChannel`.
 * Classes extending this can pass extra SHACL properties in the constructor to extend the validation check.
 *
 * The `completeChannel` implementation is an empty function.
 */
export abstract class BaseChannelType implements NotificationChannelType {
  protected readonly type: NamedNode;
  protected readonly path: string;
  protected readonly shacl: unknown;
  protected shaclQuads?: Store;
  protected readonly features: NamedNode[];

  /**
   * @param type - The URI of the notification channel type.
   *               This will be added to the SHACL shape to validate incoming subscription data.
   * @param route - The route corresponding to the URL of the subscription service of this channel type.
   *                Channel identifiers will be generated by appending a value to this URL.
   * @param features - The features that should be enabled for this channel type.
   *                   Values are expected to be full URIs, but the `notify:` prefix can also be used.
   * @param additionalShaclProperties - Any additional properties that need to be added to the default SHACL shape.
   */
  protected constructor(
    type: NamedNode,
    route: InteractionRoute,
    features: string[] = DEFAULT_NOTIFICATION_FEATURES,
    additionalShaclProperties: unknown[] = [],
  ) {
    this.type = type;
    this.path = route.getPath();
    this.features = features.map((feature): NamedNode => {
      if (feature.startsWith('notify:')) {
        feature = `${NOTIFY.namespace}${feature.slice('notify:'.length)}`;
      }
      return namedNode(feature);
    });

    // Inject requested properties into default SHACL shape
    this.shacl = {
      ...DEFAULT_SUBSCRIPTION_SHACL,
      property: [
        ...DEFAULT_SUBSCRIPTION_SHACL.property,
        // Add type check
        // eslint-disable-next-line @typescript-eslint/naming-convention
        { path: RDF.type, hasValue: { '@id': type.value }},
        ...additionalShaclProperties,
      ],
    };
  }

  public getDescription(): SubscriptionService {
    return {
      // eslint-disable-next-line @typescript-eslint/naming-convention
      '@context': [ CONTEXT_NOTIFICATION ],
      id: this.path,
      // At the time of writing, there is no base value for URIs in the notification context,
      // so we use the full URI instead.
      channelType: this.type.value,
      // Shorten known features to make the resulting JSON more readable
      feature: this.features.map((node): string => {
        if (DEFAULT_NOTIFICATION_FEATURES.includes(node.value)) {
          return node.value.slice(NOTIFY.namespace.length);
        }
        if (node.value.startsWith(NOTIFY.namespace)) {
          return `notify:${node.value.slice(NOTIFY.namespace.length)}`;
        }
        return node.value;
      }),
    };
  }

  /**
   * Initiates the channel by first calling {@link validateSubscription} followed by {@link quadsToChannel}.
   * Subclasses can override either function safely to impact the result of the function.
   */
  // eslint-disable-next-line unused-imports/no-unused-vars
  public async initChannel(data: Store, credentials: Credentials): Promise<NotificationChannel> {
    const subject = await this.validateSubscription(data);
    return this.quadsToChannel(data, subject);
  }

  /**
   * Returns an N3.js {@link Store} containing quads corresponding to the stored SHACL representation.
   * Caches this result so the conversion from JSON-LD to quads only has to happen once.
   */
  protected async getShaclQuads(): Promise<Store> {
    if (!this.shaclQuads) {
      const shaclStream = rdfParser.parse(
        Readable.from(JSON.stringify(this.shacl)),
        {
          contentType: 'application/ld+json',
          // Make sure our internal version of the context gets used
          [KeysRdfParseJsonLd.documentLoader.name]: new ContextDocumentLoader({
            [CONTEXT_SHACL]: '@css:templates/contexts/shacl.jsonld',
          }),
        },
      );
      // Typing issue with rdf-parse library
      this.shaclQuads = await readableToQuads(shaclStream as unknown as Readable);
    }
    return this.shaclQuads;
  }

  /**
   * Validates whether the given data conforms to the stored SHACL shape.
   * Will throw an {@link UnprocessableEntityHttpError} if validation fails.
   * Along with the SHACL check, this also makes sure there is only one matching entry in the dataset.
   *
   * @param data - The data to validate.
   *
   * @returns The focus node that corresponds to the subject of the found notification channel description.
   */
  protected async validateSubscription(data: Store): Promise<Term> {
    // Need to make sure there is exactly one matching entry, which can't be done with SHACL.
    // The predicate used here must be the same as is used for `targetSubjectsOf` in the SHACL shape.
    const focusNodes = data.getSubjects(NOTIFY.terms.topic, null, null);
    if (focusNodes.length === 0) {
      throw new UnprocessableEntityHttpError('Missing topic value.');
    }
    if (focusNodes.length > 1) {
      throw new UnprocessableEntityHttpError('Only one subscription can be done at the same time.');
    }

    const validator = new SHACLValidator(await this.getShaclQuads());
    const report = validator.validate(data);

    if (!report.conforms) {
      // Use the first error to generate error message
      const result = report.results[0];
      const message = result.message[0];
      throw new UnprocessableEntityHttpError(`${message.value} - ${result.path?.value}`);
    }

    // From this point on, we can assume the subject corresponds to a valid subscription request
    return focusNodes[0] as NamedNode;
  }

  /**
   * Converts a set of quads to a {@link NotificationChannel}.
   * Assumes the data is valid, so this should be called after {@link validateSubscription}.
   *
   * The generated identifier will be a URL made by combining the base URL of the channel type with a unique identifier.
   *
   * The values of the default features will be added to the resulting channel,
   * subclasses with additional features that need to be added are responsible for parsing those quads.
   *
   * @param data - Data to convert.
   * @param subject - The identifier of the notification channel description in the dataset.
   *
   * @returns The generated {@link NotificationChannel}.
   */
  protected async quadsToChannel(data: Store, subject: Term): Promise<NotificationChannel> {
    const topic = data.getObjects(subject, NOTIFY.terms.topic, null)[0] as NamedNode;
    const type = data.getObjects(subject, RDF.terms.type, null)[0] as NamedNode;

    const channel: NotificationChannel = {
      id: joinUrl(this.path, v4()),
      type: type.value,
      topic: topic.value,
    };

    // Apply the values for all present features that are enabled
    for (const feature of DEFAULT_NOTIFICATION_FEATURES) {
      const featNode = this.features.find((node): boolean => node.value === feature);
      if (featNode) {
        const objects = data.getObjects(subject, feature, null);
        if (objects.length === 1) {
          // Will always succeed since we are iterating over a list which was built using `featureDefinitions`
          const { dataType, key } = featureDefinitions.find((feat): boolean => feat.predicate.value === feature)!;
          let val: string | number = objects[0].value;
          if (dataType === XSD.dateTime) {
            val = Date.parse(val);
          } else if (dataType === XSD.duration) {
            val = toSeconds(parse(val)) * 1000;
          }
          // Need to convince TS that we can assign `string | number` to this key
          (channel as Record<typeof key, string | number>)[key] = val;
        }
      }
    }

    return channel;
  }

  /**
   * Converts the given channel to a JSON-LD description.
   * All fields found in the channel, except `lastEmit`, will be part of the result subject,
   * so subclasses should remove any fields that should not be exposed.
   */
  public async toJsonLd(channel: NotificationChannel): Promise<Record<string, unknown>> {
    const result: Record<string, unknown> = {
      // eslint-disable-next-line @typescript-eslint/naming-convention
      '@context': [
        CONTEXT_NOTIFICATION,
      ],
      ...channel,
    };
    // No need to expose this field
    delete result.lastEmit;

    // Convert all the epoch values back to the expected date/rate format
    for (const { key, dataType } of featureDefinitions) {
      const value = channel[key];
      if (value) {
        if (dataType === XSD.dateTime) {
          result[key] = new Date(value).toISOString();
        } else if (dataType === XSD.duration) {
          result[key] = msToDuration(value as number);
        }
      }
    }

    return result;
  }

  public async extractModes(channel: NotificationChannel): Promise<AccessMap> {
    return new IdentifierSetMultiMap<AccessMode>([[{ path: channel.topic }, AccessMode.read ]]);
  }

  // eslint-disable-next-line unused-imports/no-unused-vars
  public async completeChannel(channel: NotificationChannel): Promise<void> {
    // Do nothing
  }
}

import { getLoggerFor } from '../../logging/LogUtil';
import { createErrorMessage } from '../../util/errors/ErrorUtil';
import type { NotificationChannel } from './NotificationChannel';
import type { NotificationChannelStorage } from './NotificationChannelStorage';
import type { NotificationHandler } from './NotificationHandler';
import { StateHandler } from './StateHandler';

/**
 * Handles the `state` feature by calling a {@link NotificationHandler}
 * in case the {@link NotificationChannel} has a `state` value.
 *
 * Deletes the `state` parameter from the channel afterwards.
 */
export class BaseStateHandler extends StateHandler {
  protected readonly logger = getLoggerFor(this);

  private readonly handler: NotificationHandler;
  private readonly storage: NotificationChannelStorage;

  public constructor(handler: NotificationHandler, storage: NotificationChannelStorage) {
    super();
    this.handler = handler;
    this.storage = storage;
  }

  public async handle({ channel }: { channel: NotificationChannel }): Promise<void> {
    if (channel.state) {
      const topic = { path: channel.topic };
      try {
        await this.handler.handleSafe({ channel, topic });
        // Remove the state once the relevant notification has been sent
        delete channel.state;
        await this.storage.update(channel);
      } catch (error: unknown) {
        this.logger.error(`Problem emitting state notification: ${createErrorMessage(error)}`);
      }
    }
  }
}

import type { ETagHandler } from '../../storage/conditions/ETagHandler';
import type { NotificationGenerator } from './generate/NotificationGenerator';
import type { NotificationEmitter } from './NotificationEmitter';
import type { NotificationHandlerInput } from './NotificationHandler';
import { NotificationHandler } from './NotificationHandler';
import type { NotificationSerializer } from './serialize/NotificationSerializer';

export interface ComposedNotificationHandlerArgs {
  generator: NotificationGenerator;
  serializer: NotificationSerializer;
  emitter: NotificationEmitter;
  eTagHandler: ETagHandler;
}

/**
 * Generates, serializes and emits a {@link Notification} using a {@link NotificationGenerator},
 * {@link NotificationSerializer} and {@link NotificationEmitter}.
 *
 * Will not emit an event when it has the same state as the notification channel.
 */
export class ComposedNotificationHandler extends NotificationHandler {
  private readonly generator: NotificationGenerator;
  private readonly serializer: NotificationSerializer;
  private readonly emitter: NotificationEmitter;
  private readonly eTagHandler: ETagHandler;

  public constructor(args: ComposedNotificationHandlerArgs) {
    super();
    this.generator = args.generator;
    this.serializer = args.serializer;
    this.emitter = args.emitter;
    this.eTagHandler = args.eTagHandler;
  }

  public async canHandle(input: NotificationHandlerInput): Promise<void> {
    await this.generator.canHandle(input);
  }

  public async handle(input: NotificationHandlerInput): Promise<void> {
    const notification = await this.generator.handle(input);

    const { state } = input.channel;
    // In case the state matches there is no need to send the notification
    if (typeof state === 'string' && notification.state &&
      this.eTagHandler.sameResourceState(state, notification.state)) {
      return;
    }

    const representation = await this.serializer.handleSafe({ channel: input.channel, notification });
    await this.emitter.handleSafe({ channel: input.channel, representation });
  }
}

import type { ETagHandler } from '../../../storage/conditions/ETagHandler';
import type { ResourceStore } from '../../../storage/ResourceStore';
import { NotImplementedHttpError } from '../../../util/errors/NotImplementedHttpError';
import { AS } from '../../../util/Vocabularies';
import type { Notification } from '../Notification';
import { CONTEXT_ACTIVITYSTREAMS, CONTEXT_NOTIFICATION } from '../Notification';
import type { NotificationHandlerInput } from '../NotificationHandler';
import { NotificationGenerator } from './NotificationGenerator';

/**
 * A {@link NotificationGenerator} that creates a {@link Notification} by using the provided activity as type.
 * Requests metadata of the topic from the {@link ResourceStore} to fill in the details.
 */
export class ActivityNotificationGenerator extends NotificationGenerator {
  private readonly store: ResourceStore;
  private readonly eTagHandler: ETagHandler;

  public constructor(store: ResourceStore, eTagHandler: ETagHandler) {
    super();
    this.store = store;
    this.eTagHandler = eTagHandler;
  }

  public async canHandle({ activity }: NotificationHandlerInput): Promise<void> {
    if (!activity) {
      throw new NotImplementedHttpError(`Only defined activities are supported.`);
    }
  }

  public async handle({ topic, activity }: NotificationHandlerInput): Promise<Notification> {
    const representation = await this.store.getRepresentation(topic, {});
    representation.data.destroy();
    const state = this.eTagHandler.getETag(representation.metadata);

    return {
      // eslint-disable-next-line @typescript-eslint/naming-convention
      '@context': [
        CONTEXT_ACTIVITYSTREAMS,
        CONTEXT_NOTIFICATION,
      ],
      id: `urn:${Date.now()}:${topic.path}`,
      type: activity!.value.slice(AS.namespace.length),
      object: topic.path,
      state,
      published: new Date().toISOString(),
    };
  }
}

import type { ETagHandler } from '../../../storage/conditions/ETagHandler';
import type { ResourceStore } from '../../../storage/ResourceStore';
import { InternalServerError } from '../../../util/errors/InternalServerError';
import { NotImplementedHttpError } from '../../../util/errors/NotImplementedHttpError';
import { AS } from '../../../util/Vocabularies';
import type { Notification } from '../Notification';
import { CONTEXT_ACTIVITYSTREAMS, CONTEXT_NOTIFICATION } from '../Notification';
import type { NotificationHandlerInput } from '../NotificationHandler';
import { NotificationGenerator } from './NotificationGenerator';

/**
 * A {@link NotificationGenerator} specifically for Add/Remove notifications.
 * Creates the notification so the `target` is set to input topic,
 * and the `object` value is extracted from the provided metadata.
 */
export class AddRemoveNotificationGenerator extends NotificationGenerator {
  private readonly store: ResourceStore;
  private readonly eTagHandler: ETagHandler;

  public constructor(store: ResourceStore, eTagHandler: ETagHandler) {
    super();
    this.store = store;
    this.eTagHandler = eTagHandler;
  }

  public async canHandle({ activity }: NotificationHandlerInput): Promise<void> {
    if (!activity || (!activity.equals(AS.terms.Add) && !activity.equals(AS.terms.Remove))) {
      throw new NotImplementedHttpError(`Only Add/Remove activity updates are supported.`);
    }
  }

  public async handle({ activity, topic, metadata }: NotificationHandlerInput): Promise<Notification> {
    const representation = await this.store.getRepresentation(topic, {});
    representation.data.destroy();
    const state = this.eTagHandler.getETag(representation.metadata);

    const objects = metadata?.getAll(AS.terms.object);
    if (!objects || objects.length === 0) {
      throw new InternalServerError(`Missing as:object metadata for ${activity?.value} activity on ${topic.path}`);
    }
    if (objects.length > 1) {
      throw new InternalServerError(`Found more than one as:object for ${activity?.value} activity on ${topic.path}`);
    }

    return {
      // eslint-disable-next-line @typescript-eslint/naming-convention
      '@context': [
        CONTEXT_ACTIVITYSTREAMS,
        CONTEXT_NOTIFICATION,
      ],
      id: `urn:${Date.now()}:${topic.path}`,
      type: activity!.value.slice(AS.namespace.length),
      object: objects[0].value,
      target: topic.path,
      state,
      published: new Date().toISOString(),
    };
  }
}

import { NotImplementedHttpError } from '../../../util/errors/NotImplementedHttpError';
import { AS } from '../../../util/Vocabularies';
