/**
 * Generates a {@link Notification} for a resource that was deleted.
 * This differs from other activity notifications in that there is no state and no resource metadata
 * since the resource no longer exists.
 */
export class DeleteNotificationGenerator extends NotificationGenerator {
  public async canHandle({ activity }: NotificationHandlerInput): Promise<void> {
    if (!activity?.equals(AS.terms.Delete)) {
      throw new NotImplementedHttpError(`Only Delete activity updates are supported.`);
    }
  }

  public async handle({ topic }: NotificationHandlerInput): Promise<Notification> {
    return {
      // eslint-disable-next-line @typescript-eslint/naming-convention
      '@context': [
        CONTEXT_ACTIVITYSTREAMS,
        CONTEXT_NOTIFICATION,
      ],
      id: `urn:${Date.now()}:${topic.path}`,
      type: 'Delete',
      object: topic.path,
      published: new Date().toISOString(),
    };
  }
}

import { AsyncHandler } from '../../../util/handlers/AsyncHandler';
import type { Notification } from '../Notification';
import type { NotificationHandlerInput } from '../NotificationHandler';

/**
 * Creates a {@link Notification} based on the provided input.
 */
export abstract class NotificationGenerator extends AsyncHandler<NotificationHandlerInput, Notification> {}

import type { ResourceSet } from '../../../storage/ResourceSet';
import { AS } from '../../../util/Vocabularies';
import type { Notification } from '../Notification';
import type { NotificationHandlerInput } from '../NotificationHandler';
import { NotificationGenerator } from './NotificationGenerator';

/**
 * Determines the most relevant activity for a {@link Notification} in case none was provided.
 * This is relevant for the `state` feature where a notification channel needs to know the current state of a resource.
 */
export class StateNotificationGenerator extends NotificationGenerator {
  private readonly source: NotificationGenerator;
  private readonly resourceSet: ResourceSet;

  public constructor(source: NotificationGenerator, resourceSet: ResourceSet) {
    super();
    this.source = source;
    this.resourceSet = resourceSet;
  }

  public async handle(input: NotificationHandlerInput): Promise<Notification> {
    if (input.activity) {
      return this.source.handleSafe(input);
    }

    const activity = await this.resourceSet.hasResource(input.topic) ? AS.terms.Update : AS.terms.Delete;
    return this.source.handleSafe({ ...input, activity });
  }
}

import type { ResourceIdentifier } from '../../http/representation/ResourceIdentifier';
import { getLoggerFor } from '../../logging/LogUtil';
import type { KeyValueStorage } from '../../storage/keyvalue/KeyValueStorage';
import { InternalServerError } from '../../util/errors/InternalServerError';
import type { ReadWriteLocker } from '../../util/locking/ReadWriteLocker';
import type { NotificationChannel } from './NotificationChannel';
import type { NotificationChannelStorage } from './NotificationChannelStorage';

type StorageValue = string | string[] | NotificationChannel;

/**
 * Stores all the {@link NotificationChannel} in a {@link KeyValueStorage}.
 * Encodes IDs/topics before storing them in the KeyValueStorage.
 *
 * Uses a {@link ReadWriteLocker} to prevent internal race conditions.
 */
export class KeyValueChannelStorage implements NotificationChannelStorage {
  protected logger = getLoggerFor(this);

  private readonly storage: KeyValueStorage<string, StorageValue>;
  private readonly locker: ReadWriteLocker;

  public constructor(storage: KeyValueStorage<string, StorageValue>, locker: ReadWriteLocker) {
    this.storage = storage;
    this.locker = locker;
  }

  public async get(id: string): Promise<NotificationChannel | undefined> {
    const channel = await this.storage.get(encodeURIComponent(id));
    if (channel && this.isChannel(channel)) {
      if (typeof channel.endAt === 'number' && channel.endAt < Date.now()) {
        this.logger.info(`Notification channel ${id} has expired.`);
        await this.locker.withWriteLock(this.getLockKey(id), async(): Promise<void> => {
          await this.deleteChannel(channel);
        });
        return;
      }

      return channel;
    }
  }

  public async getAll(topic: ResourceIdentifier): Promise<string[]> {
    const channels = await this.storage.get(encodeURIComponent(topic.path));
    if (Array.isArray(channels)) {
      return channels;
    }
    return [];
  }

  public async add(channel: NotificationChannel): Promise<void> {
    const target = { path: channel.topic };
    return this.locker.withWriteLock(this.getLockKey(target), async(): Promise<void> => {
      const channels = await this.getAll(target);
      await this.storage.set(encodeURIComponent(channel.id), channel);
      channels.push(channel.id);
      await this.storage.set(encodeURIComponent(channel.topic), channels);
    });
  }

  public async update(channel: NotificationChannel): Promise<void> {
    return this.locker.withWriteLock(this.getLockKey(channel.id), async(): Promise<void> => {
      const oldChannel = await this.storage.get(encodeURIComponent(channel.id));

      if (oldChannel) {
        if (!this.isChannel(oldChannel)) {
          throw new InternalServerError(`Trying to update ${channel.id} which is not a NotificationChannel.`);
        }
        if (channel.topic !== oldChannel.topic) {
          throw new InternalServerError(`Trying to change the topic of a notification channel ${channel.id}`);
        }
      }

      await this.storage.set(encodeURIComponent(channel.id), channel);
    });
  }

  public async delete(id: string): Promise<boolean> {
    return this.locker.withWriteLock(this.getLockKey(id), async(): Promise<boolean> => {
      const channel = await this.get(id);
      if (!channel) {
        return false;
      }
      await this.deleteChannel(channel);
      return true;
    });
  }

  /**
   * Utility function for deleting a specific {@link NotificationChannel} object.
   * Does not create a lock on the channel ID so should be wrapped in such a lock.
   */
  private async deleteChannel(channel: NotificationChannel): Promise<void> {
    await this.locker.withWriteLock(this.getLockKey(channel.topic), async(): Promise<void> => {
      const channels = await this.getAll({ path: channel.topic });
      const idx = channels.indexOf(channel.id);
      // If idx < 0 we have an inconsistency
      if (idx < 0) {
        this.logger.error(`Channel ${channel.id} was not found in the list of channels targeting ${channel.topic}.`);
        this.logger.error('This should not happen and indicates a data consistency issue.');
      } else {
        channels.splice(idx, 1);
        if (channels.length > 0) {
          await this.storage.set(encodeURIComponent(channel.topic), channels);
        } else {
          await this.storage.delete(encodeURIComponent(channel.topic));
        }
      }
      await this.storage.delete(encodeURIComponent(channel.id));
    });
  }

  private isChannel(value: StorageValue): value is NotificationChannel {
    return Boolean((value as NotificationChannel).id);
  }

  private getLockKey(identifier: ResourceIdentifier | string): ResourceIdentifier {
    return { path: `${typeof identifier === 'string' ? identifier : identifier.path}.notification-storage` };
  }
}

import type { RepresentationMetadata } from '../../http/representation/RepresentationMetadata';
import type { ResourceIdentifier } from '../../http/representation/ResourceIdentifier';
import { getLoggerFor } from '../../logging/LogUtil';
import { createErrorMessage } from '../../util/errors/ErrorUtil';
import { StaticHandler } from '../../util/handlers/StaticHandler';
import type { AS, VocabularyTerm } from '../../util/Vocabularies';
import type { ActivityEmitter } from './ActivityEmitter';
import type { NotificationChannelStorage } from './NotificationChannelStorage';
import type { NotificationHandler } from './NotificationHandler';

/**
 * Listens to an {@link ActivityEmitter} and calls the stored {@link NotificationHandler}s in case of an event
 * for every matching notification channel found.
 *
 * Takes the `rate` feature into account so only channels that want a new notification will receive one.
 *
 * Extends {@link StaticHandler} so it can be more easily injected into a Components.js configuration.
 * No class takes this one as input, so to make sure Components.js instantiates it,
 * it needs to be added somewhere where its presence has no impact, such as the list of initializers.
 */
export class ListeningActivityHandler extends StaticHandler {
  protected readonly logger = getLoggerFor(this);

  private readonly storage: NotificationChannelStorage;
  private readonly handler: NotificationHandler;

  public constructor(storage: NotificationChannelStorage, emitter: ActivityEmitter, handler: NotificationHandler) {
    super();
    this.storage = storage;
    this.handler = handler;

    emitter.on('changed', (topic, activity, metadata): void => {
      this.emit(topic, activity, metadata).catch((error: unknown): void => {
        this.logger.error(`Something went wrong emitting notifications: ${createErrorMessage(error)}`);
      });
    });
  }

  private async emit(
    topic: ResourceIdentifier,
    activity: VocabularyTerm<typeof AS>,
    metadata: RepresentationMetadata,
  ): Promise<void> {
    const channelIds = await this.storage.getAll(topic);

    for (const id of channelIds) {
      const channel = await this.storage.get(id);
      if (!channel) {
        // Notification channel has expired
        continue;
      }

      // Don't emit if the previous notification was too recent according to the requested rate
      if (channel.lastEmit && channel.rate && channel.rate > Date.now() - channel.lastEmit) {
        continue;
      }

      // Don't emit if we have not yet reached the requested starting time
      if (channel.startAt && channel.startAt > Date.now()) {
        continue;
      }

      // No need to wait on this to resolve before going to the next channel.
      // Prevent failed notification from blocking other notifications.
      this.handler.handleSafe({ channel, activity, topic, metadata })
        .then(async(): Promise<void> => {
          // Update the `lastEmit` value if the channel has a rate limit
          if (channel.rate) {
            channel.lastEmit = Date.now();
            return this.storage.update(channel);
          }
        })
        .catch((error: unknown): void => {
          this.logger.error(`Error trying to handle notification for ${id}: ${createErrorMessage(error)}`);
        });
    }
  }
}

export const CONTEXT_ACTIVITYSTREAMS = 'https://www.w3.org/ns/activitystreams';
export const CONTEXT_NOTIFICATION = 'https://www.w3.org/ns/solid/notification/v1';

/**
 * The minimally expected fields for a Notification
 * as defined in https://solidproject.org/TR/2022/notifications-protocol-20221231#data-model.
 */
export interface Notification {
  // eslint-disable-next-line @typescript-eslint/naming-convention
  '@context': [
    typeof CONTEXT_ACTIVITYSTREAMS,
    typeof CONTEXT_NOTIFICATION,
    ...string[],
  ];
  id: string;
  type: string;
  object: string;
  state?: string;
  target?: string | string[];
  published: string;
}

/**
 * Internal representation of a notification channel.
 * Most of the fields are those defined in
 * https://solidproject.org/TR/2022/notifications-protocol-20221231#notification-channel-data-model
 *
 * We only support notification channels with a single topic.
 */
export interface NotificationChannel {
  /**
   * The unique identifier of the channel.
   */
  id: string;
  /**
   * The channel type.
   */
  type: string;
  /**
   * The resource this channel sends notifications about.
   */
  topic: string;
  /**
   * The state parameter sent by the receiver.
   * This is used to send a notification when the channel is established and the topic resource has a different state.
   */
  state?: string;
  /**
   * When the channel should start sending notifications, in milliseconds since epoch.
   */
  startAt?: number;
  /**
   * When the channel should stop existing, in milliseconds since epoch.
   */
  endAt?: number;
  /**
   * The minimal time required between notifications, in milliseconds.
   */
  rate?: number;
  /**
   * The media type in which the receiver expects the notifications.
   */
  accept?: string;
  /**
   * The resource receivers can use to establish a connection and receive notifications.
   */
  receiveFrom?: string;
  /**
   * The resource on the receiver where notifications can be sent.
   */
  sendTo?: string;
  /**
   * Can be used to identify the sender.
   */
  sender?: string;

  /**
   * Internal value that we use to track when this channel last sent a notification.
   */
  lastEmit?: number;
}

import type { ResourceIdentifier } from '../../http/representation/ResourceIdentifier';
import type { NotificationChannel } from './NotificationChannel';

/**
 * Stores all the information necessary to keep track of notification channels.
 * Besides the standard channel info it also stores features specific to a certain channel type.
 *
 * This storage assumes that a channel can only have a single identifier as its topic.
 */
export interface NotificationChannelStorage {
  /**
   * Returns the requested channel.
   * `undefined` if no match was found or if the notification channel expired.
   *
   * @param id - The identifier of the notification channel.
   */
  get: (id: string) => Promise<NotificationChannel | undefined>;

  /**
   * Returns the identifiers of all notification channel entries that have the given identifier as their topic.
   * The identifiers can potentially correspond to expired channels.
   *
   * @param topic - The identifier that is the topic.
   */
  getAll: (topic: ResourceIdentifier) => Promise<string[]>;

  /**
   * Adds the given channel to the storage.
   *
   * @param channel - Channel to add.
   */
  add: (channel: NotificationChannel) => Promise<void>;

  /**
   * Updates the given notification channel.
   * The `id` and the `topic` can not be updated.
   *
   * @param channel - The channel to update.
   */
  update: (channel: NotificationChannel) => Promise<void>;

  /**
   * Deletes the given notification channel from the storage.
   * Returns true if the channel existed.
   *
   * @param id - The identifier of the notification channel
   */
  delete: (id: string) => Promise<boolean>;
}

import type { Store } from 'n3';
import type { Credentials } from '../../authentication/Credentials';
import type { AccessMap } from '../../authorization/permissions/Permissions';
import type { CONTEXT_NOTIFICATION } from './Notification';
import type { NotificationChannel } from './NotificationChannel';

/**
 * A subscription service description as based on the specification data model
 * https://solidproject.org/TR/2022/notifications-protocol-20221231#subscription-service-data-model
 */
export interface SubscriptionService {
  // eslint-disable-next-line @typescript-eslint/naming-convention
  '@context': [ typeof CONTEXT_NOTIFICATION ];
  id: string;
  channelType: string;
  feature: string[];
}

/**
 * A specific channel type as defined at
 * https://solidproject.org/TR/2022/notifications-protocol-20221231#notification-channel-types.
 *
 * All functions that take a {@link NotificationChannel} as input
 * only need to support channels generated by an `initChannel` on the same class.
 */
export interface NotificationChannelType {
  /**
   * Returns the {@link SubscriptionService} that describes how to subscribe to this channel type.
   */
  getDescription: () => SubscriptionService;

  /**
   * Validate and convert the input quads into a {@link NotificationChannel}.
   *
   * @param data - The input quads.
   * @param credentials - The credentials of the agent doing the request.
   */
  initChannel: (data: Store, credentials: Credentials) => Promise<NotificationChannel>;

  /**
   * Converts a {@link NotificationChannel} to a serialized JSON-LD representation.
   *
   * @param channel - The notification channel to serialize.
   */
  toJsonLd: (channel: NotificationChannel) => Promise<Record<string, unknown>>;

  /**
   * Determines which modes are required to allow the given notification channel.
   *
   * @param channel - The notification channel to verify.
   *
   * @returns The required modes.
   */
  extractModes: (channel: NotificationChannel) => Promise<AccessMap>;

  /**
   * This function will be called after the serialized channel is sent back as a response,
   * allowing for any final actions that need to happen.
   *
   * @param channel - The notification channel that is completed.
   */
  completeChannel: (channel: NotificationChannel) => Promise<void>;
}

import type { Quad } from '@rdfjs/types';
import arrayifyStream from 'arrayify-stream';
import { DataFactory } from 'n3';
import { BasicRepresentation } from '../../http/representation/BasicRepresentation';
import type { ResourceIdentifier } from '../../http/representation/ResourceIdentifier';
import type { RepresentationConverter } from '../../storage/conversion/RepresentationConverter';
import { APPLICATION_LD_JSON, INTERNAL_QUADS } from '../../util/ContentTypes';
import { NOTIFY } from '../../util/Vocabularies';
import { StorageDescriber } from '../description/StorageDescriber';
import type { NotificationChannelType } from './NotificationChannelType';

const { namedNode, quad } = DataFactory;

/**
 * Outputs quads describing all the subscription services of the server,
 * as described in https://solidproject.org/TR/2022/notifications-protocol-20221231#discovery and
 * https://solidproject.org/TR/2022/notifications-protocol-20221231#description-resource-data-model.
 *
 * In the future, if there is ever a need to add notification channels to the description resource as described above,
 * this functionality should probably be added here as well.
 */
export class NotificationDescriber extends StorageDescriber {
  private readonly converter: RepresentationConverter;
  private readonly subscriptions: NotificationChannelType[];

  public constructor(converter: RepresentationConverter, subscriptions: NotificationChannelType[]) {
    super();
    this.converter = converter;
    this.subscriptions = subscriptions;
  }

  public async handle(identifier: ResourceIdentifier): Promise<Quad[]> {
    const subject = namedNode(identifier.path);

    const subscriptionLinks: Quad[] = [];
    const preferences = { type: { [INTERNAL_QUADS]: 1 }};
    const subscriptionQuads = await Promise.all(this.subscriptions.map(async(sub): Promise<Quad[]> => {
      const jsonld = sub.getDescription();
      const representation = new BasicRepresentation(JSON.stringify(jsonld), { path: jsonld.id }, APPLICATION_LD_JSON);
      const converted = await this.converter.handleSafe({ identifier, representation, preferences });
      const arr = await arrayifyStream<Quad>(converted.data);
      subscriptionLinks.push(quad(subject, NOTIFY.terms.subscription, namedNode(jsonld.id)));
      return arr;
    }));

    return [
      ...subscriptionLinks,
      ...subscriptionQuads.flat(),
    ];
  }
}

