import { getLoggerFor } from '../../../logging/LogUtil';
import type { Representation } from '../../../http/representation/Representation';
import { AsyncHandler } from '../../../util/handlers/AsyncHandler';
import { readableToString } from '../../../util/StreamUtil';
import type { NotificationChannel } from '../NotificationChannel';
import type { StreamingHttpMap } from './StreamingHttpMap';

export interface StreamingHttpEmitterInput {
  channel: NotificationChannel;
  representation: Representation;
}

/**
 * Emits notifications on StreamingHTTPChannel2023 streams.
 * Uses the response streams found in the provided map.
 * The key should be the identifier of the topic resource.
 */
export class StreamingHttp2023Emitter extends AsyncHandler<StreamingHttpEmitterInput> {
  protected readonly logger = getLoggerFor(this);

  public constructor(
    private readonly streamMap: StreamingHttpMap,
  ) {
    super();
  }

  public async handle({ channel, representation }: StreamingHttpEmitterInput): Promise<void> {
    // Called as a NotificationEmitter: emit the notification
    const streams = this.streamMap.get(channel.topic);
    if (streams) {
      // Ensure that the whole notification gets sent in a single chunk
      const chunk = await readableToString(representation.data);
      for (const stream of streams) {
        stream.write(chunk);
      }
    } else {
      representation.data.destroy();
    }
  }
}

import type { ResourceIdentifier } from '../../../http/representation/ResourceIdentifier';
import { NOTIFY } from '../../../util/Vocabularies';
import type { NotificationChannel } from '../NotificationChannel';

/**
 * Default StreamingHTTPChanel2023 for a topic.
 * Currently channel description is only used internally and never sent to the client.
 * The default channel uses Turtle.
 */
export function generateChannel(topic: ResourceIdentifier): NotificationChannel {
  return {
    id: `${topic.path}.channel`,
    type: NOTIFY.StreamingHTTPChannel2023,
    topic: topic.path,
    accept: 'text/turtle',
  };
}

import type { RepresentationMetadata } from '../../../http/representation/RepresentationMetadata';
import type { ResourceIdentifier } from '../../../http/representation/ResourceIdentifier';
import { getLoggerFor } from '../../../logging/LogUtil';
import { createErrorMessage } from '../../../util/errors/ErrorUtil';
import { StaticHandler } from '../../../util/handlers/StaticHandler';
import type { AS, VocabularyTerm } from '../../../util/Vocabularies';
import type { ActivityEmitter } from '../ActivityEmitter';
import type { NotificationHandler } from '../NotificationHandler';
import { generateChannel } from './StreamingHttp2023Util';
import type { StreamingHttpMap } from './StreamingHttpMap';

/**
 * Listens to an {@link ActivityEmitter} and calls the stored {@link NotificationHandler}s in case of an event
 * for every matching notification channel found.
 *
 * Extends {@link StaticHandler} so it can be more easily injected into a Components.js configuration.
 * No class takes this one as input, so to make sure Components.js instantiates it,
 * it needs to be added somewhere where its presence has no impact, such as the list of initializers.
 */
export class StreamingHttpListeningActivityHandler extends StaticHandler {
  protected readonly logger = getLoggerFor(this);

  public constructor(
    emitter: ActivityEmitter,
    private readonly streamMap: StreamingHttpMap,
    private readonly source: NotificationHandler,
  ) {
    super();

    emitter.on('changed', (topic, activity, metadata): void => {
      if (this.streamMap.has(topic.path)) {
        this.emit(topic, activity, metadata).catch(
          (error: unknown): void => {
            this.logger.error(`Error trying to handle notification for ${topic.path}: ${createErrorMessage(error)}`);
          },
        );
      }
    });
  }

  private async emit(
    topic: ResourceIdentifier,
    activity: VocabularyTerm<typeof AS>,
    metadata: RepresentationMetadata,
  ): Promise<void> {
    const channel = generateChannel(topic);
    return this.source.handleSafe({ channel, activity, topic, metadata });
  }
}

import type { PassThrough } from 'node:stream';
import type { SingleThreaded } from '../../../init/cluster/SingleThreaded';
import { WrappedSetMultiMap } from '../../../util/map/WrappedSetMultiMap';

/**
 * A {@link SetMultiMap} linking identifiers to a set of Streaming HTTP streams.
 * An extension of {@link WrappedSetMultiMap} to make sure Components.js allows us to create this in the config,
 * as {@link WrappedSetMultiMap} has a constructor not supported.
 */
export class StreamingHttpMap extends WrappedSetMultiMap<string, PassThrough> implements SingleThreaded {}

import { getLoggerFor } from '../../../logging/LogUtil';
import type { HttpResponse } from '../../HttpResponse';
import { addHeader } from '../../../util/HeaderUtil';
import { joinUrl } from '../../../util/PathUtil';
import type { InteractionRoute } from '../../../identity/interaction/routing/InteractionRoute';
import type { RepresentationMetadata } from '../../../http/representation/RepresentationMetadata';
import { MetadataWriter } from '../../../http/output/metadata/MetadataWriter';

/**
 * A {@link MetadataWriter} that adds a link to the receiveFrom endpoint
 * of the corresponding Streaming HTTP notifications channel
 */
export class StreamingHttpMetadataWriter extends MetadataWriter {
  protected readonly logger = getLoggerFor(this);

  public constructor(
    private readonly route: InteractionRoute,
  ) {
    super();
  }

  public async handle(input: { response: HttpResponse; metadata: RepresentationMetadata }): Promise<void> {
    const encodedUrl = encodeURIComponent(input.metadata.identifier.value);
    const receiveFrom = joinUrl(this.route.getPath(), encodedUrl);
    const link = `<${receiveFrom}>; rel="http://www.w3.org/ns/solid/terms#updatesViaStreamingHttp2023"`;
    this.logger.debug('Adding updatesViaStreamingHttp2023  to the Link header');
    addHeader(input.response, 'Link', link);
  }
}

import { PassThrough } from 'node:stream';
import type { Credentials } from '../../../authentication/Credentials';
import type { CredentialsExtractor } from '../../../authentication/CredentialsExtractor';
import type { Authorizer } from '../../../authorization/Authorizer';
import type { PermissionReader } from '../../../authorization/PermissionReader';
import { AccessMode } from '../../../authorization/permissions/Permissions';
import { OkResponseDescription } from '../../../http/output/response/OkResponseDescription';
import type { ResponseDescription } from '../../../http/output/response/ResponseDescription';
import { BasicRepresentation } from '../../../http/representation/BasicRepresentation';
import type { InteractionRoute } from '../../../identity/interaction/routing/InteractionRoute';
import { getLoggerFor } from '../../../logging/LogUtil';
import type { OperationHttpHandlerInput } from '../../OperationHttpHandler';
import { OperationHttpHandler } from '../../OperationHttpHandler';
import { guardStream } from '../../../util/GuardedStream';
import { IdentifierSetMultiMap } from '../../../util/map/IdentifierMap';
import { createErrorMessage } from '../../../util/errors/ErrorUtil';
import type { NotificationGenerator } from '../generate/NotificationGenerator';
import type { NotificationSerializer } from '../serialize/NotificationSerializer';
import { readableToString } from '../../../util/StreamUtil';
import type { StreamingHttpMap } from './StreamingHttpMap';
import { generateChannel } from './StreamingHttp2023Util';

/**
 * Handles request to Streaming HTTP receiveFrom endopints.
 * All allowed requests are stored in the {@link StreamingHttpMap}
 */
export class StreamingHttpRequestHandler extends OperationHttpHandler {
  protected logger = getLoggerFor(this);

  public constructor(
    private readonly streamMap: StreamingHttpMap,
    private readonly route: InteractionRoute,
    private readonly generator: NotificationGenerator,
    private readonly serializer: NotificationSerializer,
    private readonly credentialsExtractor: CredentialsExtractor,
    private readonly permissionReader: PermissionReader,
    private readonly authorizer: Authorizer,
  ) {
    super();
  }

  public async handle({ operation, request }: OperationHttpHandlerInput): Promise<ResponseDescription> {
    const encodedUrl = operation.target.path.replace(this.route.getPath(), '');
    const topic = decodeURIComponent(encodedUrl);

    // Verify if the client is allowed to connect
    const credentials = await this.credentialsExtractor.handleSafe(request);
    await this.authorize(credentials, topic);

    const stream = guardStream(new PassThrough());
    this.streamMap.add(topic, stream);
    stream.on('error', (): boolean => this.streamMap.deleteEntry(topic, stream));
    stream.on('close', (): boolean => this.streamMap.deleteEntry(topic, stream));

    const channel = generateChannel({ path: topic });
    // Send initial notification
    try {
      const notification = await this.generator.handle({ channel, topic: { path: topic }});
      const representation = await this.serializer.handleSafe({ channel, notification });
      // Ensure that the whole notification gets sent in a single chunk
      const chunk = await readableToString(representation.data);
      stream.write(chunk);
    } catch (error: unknown) {
      this.logger.error(`Problem emitting initial notification: ${createErrorMessage(error)}`);
    }
    // Pre-established channels use Turtle
    const representation = new BasicRepresentation(topic, operation.target, channel.accept);
    return new OkResponseDescription(
      representation.metadata,
      stream,
    );
  }

  private async authorize(credentials: Credentials, topic: string): Promise<void> {
    const requestedModes = new IdentifierSetMultiMap<AccessMode>([[{ path: topic }, AccessMode.read ]]);
    this.logger.debug(`Retrieved required modes: ${[ ...requestedModes.entrySets() ]
      .map(([ id, set ]): string => `{ ${id.path}: ${[ ...set ].join(',')} }`).join(',')}`);

    const availablePermissions = await this.permissionReader.handleSafe({ credentials, requestedModes });
    this.logger.debug(`Available permissions are ${[ ...availablePermissions.entries() ]
      .map(([ id, map ]): string => `{ ${id.path}: ${JSON.stringify(map)} }`).join(',')}`);

    await this.authorizer.handleSafe({ credentials, requestedModes, availablePermissions });
    this.logger.debug(`Authorization succeeded, creating notification channel`);
  }
}

import { NotImplementedHttpError } from '../../util/errors/NotImplementedHttpError';
import type { NotificationHandlerInput } from './NotificationHandler';
import { NotificationHandler } from './NotificationHandler';

/**
 * A {@link NotificationHandler} that only accepts input for a specific notification channel type.
 */
export class TypedNotificationHandler extends NotificationHandler {
  private readonly type: string;
  private readonly source: NotificationHandler;

  public constructor(type: string, source: NotificationHandler) {
    super();
    this.type = type;
    this.source = source;
  }

  public async canHandle(input: NotificationHandlerInput): Promise<void> {
    if (input.channel.type !== this.type) {
      throw new NotImplementedHttpError(`Only ${this.type} notification channels are supported.`);
    }
    await this.source.canHandle(input);
  }

  public async handle(input: NotificationHandlerInput): Promise<void> {
    await this.source.handle(input);
  }
}

import type { Store } from 'n3';
import type { InteractionRoute } from '../../../identity/interaction/routing/InteractionRoute';
import { getLoggerFor } from '../../../logging/LogUtil';
import { createErrorMessage } from '../../../util/errors/ErrorUtil';
import { NOTIFY } from '../../../util/Vocabularies';
import { BaseChannelType } from '../BaseChannelType';
import type { NotificationChannel } from '../NotificationChannel';
import type { StateHandler } from '../StateHandler';

/**
 * A {@link NotificationChannel} containing the necessary fields for a WebhookChannel2023 channel.
 */
export interface WebhookChannel2023 extends NotificationChannel {
  /**
   * The "WebhookChannel2023" type.
   */
  type: typeof NOTIFY.WebhookChannel2023;
  /**
   * Where the notifications have to be sent.
   */
  sendTo: string;
}

export function isWebhook2023Channel(channel: NotificationChannel): channel is WebhookChannel2023 {
  return channel.type === NOTIFY.WebhookChannel2023;
}

/**
 * The notification channel type WebhookChannel2023 as described in
 * https://solid.github.io/notifications/webhook-channel-2023
 *
 * Requires read permissions on a resource to be able to receive notifications.
 *
 * Also handles the `state` feature if present.
 */
export class WebhookChannel2023Type extends BaseChannelType {
  protected readonly logger = getLoggerFor(this);

  private readonly stateHandler: StateHandler;
  private readonly webId: string;

  /**
   * @param route - The route corresponding to the URL of the subscription service of this channel type.
   * @param webIdRoute - The route to the WebID that needs to be used when generating DPoP tokens for notifications.
   * @param stateHandler - The {@link StateHandler} that will be called after a successful subscription.
   * @param features - The features that need to be enabled for this channel type.
   */
  public constructor(
    route: InteractionRoute,
    webIdRoute: InteractionRoute,
    stateHandler: StateHandler,
    features?: string[],
  ) {
    super(NOTIFY.terms.WebhookChannel2023, route, features, [{ path: NOTIFY.sendTo, minCount: 1, maxCount: 1 }]);
    this.stateHandler = stateHandler;
    this.webId = webIdRoute.getPath();
  }

  public async initChannel(data: Store): Promise<WebhookChannel2023> {
    const subject = await this.validateSubscription(data);
    const channel = await this.quadsToChannel(data, subject);
    const sendTo = data.getObjects(subject, NOTIFY.terms.sendTo, null)[0];

    return {
      ...channel,
      type: NOTIFY.WebhookChannel2023,
      sendTo: sendTo.value,
    };
  }

  public async toJsonLd(channel: NotificationChannel): Promise<Record<string, unknown>> {
    const json = await super.toJsonLd(channel);

    // Add the stored WebID as sender.
    // We don't store it in the channel object itself as we always know what it is anyway.
    json.sender = this.webId;

    return json;
  }

  public async completeChannel(channel: NotificationChannel): Promise<void> {
    try {
      // Send the state notification, if there is one
      await this.stateHandler.handleSafe({ channel });
    } catch (error: unknown) {
      this.logger.error(`Error emitting state notification: ${createErrorMessage(error)}`);
    }
  }
}

import fetch from 'cross-fetch';
import { calculateJwkThumbprint, importJWK, SignJWT } from 'jose';
import { v4 } from 'uuid';
import type { JwkGenerator } from '../../../identity/configuration/JwkGenerator';
import type { InteractionRoute } from '../../../identity/interaction/routing/InteractionRoute';
import { getLoggerFor } from '../../../logging/LogUtil';
import { NotImplementedHttpError } from '../../../util/errors/NotImplementedHttpError';
import { trimTrailingSlashes } from '../../../util/PathUtil';
import { readableToString } from '../../../util/StreamUtil';
import type { NotificationEmitterInput } from '../NotificationEmitter';
import { NotificationEmitter } from '../NotificationEmitter';
import type { WebhookChannel2023 } from './WebhookChannel2023Type';
import { isWebhook2023Channel } from './WebhookChannel2023Type';

/**
 * Emits a notification representation using the WebhookChannel2023 specification.
 *
 * At the time of writing it is not specified how exactly a notification sender should make its requests verifiable,
 * so for now we use a token similar to those from Solid-OIDC, signed by the server itself.
 *
 * Generates a DPoP token and proof, and adds those to the HTTP request that is sent to the target.
 *
 * The `expiration` input parameter is how long the generated token should be valid in minutes.
 * Default is 20.
 */
export class WebhookEmitter extends NotificationEmitter {
  protected readonly logger = getLoggerFor(this);

  private readonly issuer: string;
  private readonly webId: string;
  private readonly jwkGenerator: JwkGenerator;
  private readonly expiration: number;

  public constructor(baseUrl: string, webIdRoute: InteractionRoute, jwkGenerator: JwkGenerator, expiration = 20) {
    super();
    this.issuer = trimTrailingSlashes(baseUrl);
    this.webId = webIdRoute.getPath();
    this.jwkGenerator = jwkGenerator;
    this.expiration = expiration * 60 * 1000;
  }

  public async canHandle({ channel }: NotificationEmitterInput): Promise<void> {
    if (!isWebhook2023Channel(channel)) {
      throw new NotImplementedHttpError(`${channel.id} is not a WebhookChannel2023 channel.`);
    }
  }

  public async handle({ channel, representation }: NotificationEmitterInput): Promise<void> {
    // Cast was checked in `canHandle`
    const webhookChannel = channel as WebhookChannel2023;
    this.logger.debug(`Emitting Webhook notification with target ${webhookChannel.sendTo}`);

    const privateKey = await this.jwkGenerator.getPrivateKey();
    const publicKey = await this.jwkGenerator.getPublicKey();

    const privateKeyObject = await importJWK(privateKey);

    // Make sure both header and proof have the same timestamp
    const time = Date.now();

    // Currently the spec does not define how the notification sender should identify.
    // The format used here has been chosen to be similar
    // to how ID tokens are described in the Solid-OIDC specification for consistency.
    const dpopToken = await new SignJWT({
      webid: this.webId,
      azp: this.webId,
      sub: this.webId,
      cnf: {
        jkt: await calculateJwkThumbprint(publicKey, 'sha256'),
      },
    }).setProtectedHeader({ alg: privateKey.alg })
      .setIssuedAt(time)
      .setExpirationTime(time + this.expiration)
      .setAudience([ this.webId, 'solid' ])
      .setIssuer(this.issuer)
      .setJti(v4())
      .sign(privateKeyObject);

    // https://datatracker.ietf.org/doc/html/draft-ietf-oauth-dpop#section-4.2
    const dpopProof = await new SignJWT({
      htu: webhookChannel.sendTo,
      htm: 'POST',
    }).setProtectedHeader({ alg: privateKey.alg, jwk: publicKey, typ: 'dpop+jwt' })
      .setIssuedAt(time)
      .setJti(v4())
      .sign(privateKeyObject);

    const response = await fetch(webhookChannel.sendTo, {
      method: 'POST',
      headers: {
        // eslint-disable-next-line @typescript-eslint/naming-convention
        'content-type': representation.metadata.contentType!,
        authorization: `DPoP ${dpopToken}`,
        dpop: dpopProof,
      },
      body: await readableToString(representation.data),
    });
    if (response.status >= 400) {
      this.logger.error(`There was an issue emitting a Webhook notification with target ${webhookChannel.sendTo}: ${
        await response.text()}`);
    }
  }
}

import { Parser } from 'n3';
import { OkResponseDescription } from '../../../http/output/response/OkResponseDescription';
import type { ResponseDescription } from '../../../http/output/response/ResponseDescription';
import { BasicRepresentation } from '../../../http/representation/BasicRepresentation';
import { TEXT_TURTLE } from '../../../util/ContentTypes';
import { createErrorMessage } from '../../../util/errors/ErrorUtil';
import { trimTrailingSlashes } from '../../../util/PathUtil';
import type { OperationHttpHandlerInput } from '../../OperationHttpHandler';
import { OperationHttpHandler } from '../../OperationHttpHandler';

/**
 * Generates a fixed WebID that we use to identify the server for notifications sent using a WebhookChannel2023.
 * This is used in tandem with the tokens generated by the {@link WebhookEmitter}.
 * This is a minimal WebID with only the `solid:oidcIssuer` triple.
 */
export class WebhookWebId extends OperationHttpHandler {
  private readonly turtle: string;

  public constructor(baseUrl: string) {
    super();

    this.turtle = `@prefix solid: <http://www.w3.org/ns/solid/terms#>.
<> solid:oidcIssuer <${trimTrailingSlashes(baseUrl)}>.`;

    // This will throw an error if something is wrong with the issuer URL
    const parser = new Parser();
    try {
      parser.parse(this.turtle);
    } catch (error: unknown) {
      throw new Error(`Invalid issuer URL: ${createErrorMessage(error)}`);
    }
  }

  public async handle(input: OperationHttpHandlerInput): Promise<ResponseDescription> {
    const representation = new BasicRepresentation(this.turtle, input.operation.target, TEXT_TURTLE);
    return new OkResponseDescription(representation.metadata, representation.data);
  }
}

import type { WebSocket } from 'ws';
import { getLoggerFor } from '../../../logging/LogUtil';
import type { SetMultiMap } from '../../../util/map/SetMultiMap';
import { readableToString } from '../../../util/StreamUtil';
import { NotificationEmitter } from '../NotificationEmitter';
import type { NotificationEmitterInput } from '../NotificationEmitter';

/**
 * Emits notifications on WebSocketChannel2023 subscription.
 * Uses the WebSockets found in the provided map.
 * The key should be the identifier of the matching channel.
 */
export class WebSocket2023Emitter extends NotificationEmitter {
  protected readonly logger = getLoggerFor(this);

  private readonly socketMap: SetMultiMap<string, WebSocket>;

  public constructor(socketMap: SetMultiMap<string, WebSocket>) {
    super();

    this.socketMap = socketMap;
  }

  public async handle({ channel, representation }: NotificationEmitterInput): Promise<void> {
    // Called as a NotificationEmitter: emit the notification
    const webSockets = this.socketMap.get(channel.id);
    if (webSockets) {
      const data = await readableToString(representation.data);
      for (const webSocket of webSockets) {
        webSocket.send(data);
      }
    } else {
      representation.data.destroy();
    }
  }
}

import type { WebSocket } from 'ws';
import { AsyncHandler } from '../../../util/handlers/AsyncHandler';
import type { NotificationChannel } from '../NotificationChannel';

export interface WebSocket2023HandlerInput {
  channel: NotificationChannel;
  webSocket: WebSocket;
}

/**
 * A handler that is called when a valid WebSocketChannel2023 connection has been made.
 */
export abstract class WebSocket2023Handler extends AsyncHandler<WebSocket2023HandlerInput> {}

import { getLoggerFor } from '../../../logging/LogUtil';
import { NotImplementedHttpError } from '../../../util/errors/NotImplementedHttpError';
import type { WebSocketHandlerInput } from '../../WebSocketHandler';
import { WebSocketHandler } from '../../WebSocketHandler';
import type { NotificationChannelStorage } from '../NotificationChannelStorage';
import type { WebSocket2023Handler } from './WebSocket2023Handler';
import { parseWebSocketRequest } from './WebSocket2023Util';

/**
 * Listens for WebSocket connections and verifies whether they are valid WebSocketChannel2023 connections,
 * in which case its {@link WebSocket2023Handler} will be alerted.
 */
export class WebSocket2023Listener extends WebSocketHandler {
  protected readonly logger = getLoggerFor(this);

  private readonly storage: NotificationChannelStorage;
  private readonly handler: WebSocket2023Handler;
  private readonly baseUrl: string;

  public constructor(storage: NotificationChannelStorage, handler: WebSocket2023Handler, baseUrl: string) {
    super();
    this.storage = storage;
    this.handler = handler;
    this.baseUrl = baseUrl;
  }

  public async canHandle({ upgradeRequest }: WebSocketHandlerInput): Promise<void> {
    const id = parseWebSocketRequest(this.baseUrl, upgradeRequest);
    const channel = await this.storage.get(id);

    if (!channel) {
      throw new NotImplementedHttpError(`Unknown or expired WebSocket channel ${id}`);
    }
  }

  public async handle({ webSocket, upgradeRequest }: WebSocketHandlerInput): Promise<void> {
    const id = parseWebSocketRequest(this.baseUrl, upgradeRequest);
    const channel = (await this.storage.get(id))!;

    this.logger.info(`Accepted WebSocket connection listening to changes on ${channel.topic}`);

    await this.handler.handleSafe({ channel, webSocket });
  }
}

import type { WebSocket } from 'ws';
import { getLoggerFor } from '../../../logging/LogUtil';
import type { SetMultiMap } from '../../../util/map/SetMultiMap';
import { setSafeInterval } from '../../../util/TimerUtil';
import type { NotificationChannelStorage } from '../NotificationChannelStorage';
import type { WebSocket2023HandlerInput } from './WebSocket2023Handler';
import { WebSocket2023Handler } from './WebSocket2023Handler';

/**
 * Keeps track of the WebSockets that were opened for a WebSocketChannel2023 channel.
 * The WebSockets are stored in the map using the identifier of the matching channel.
 *
 * `cleanupTimer` defines in minutes how often the stored WebSockets are closed
 * if their corresponding channel has expired.
 * Defaults to 60 minutes.
 * Open WebSockets will not receive notifications if their channel expired.
 */
export class WebSocket2023Storer extends WebSocket2023Handler {
  protected readonly logger = getLoggerFor(this);

  private readonly storage: NotificationChannelStorage;
  private readonly socketMap: SetMultiMap<string, WebSocket>;

  public constructor(
    storage: NotificationChannelStorage,
    socketMap: SetMultiMap<string, WebSocket>,
    cleanupTimer = 60,
  ) {
    super();
    this.socketMap = socketMap;
    this.storage = storage;

    const timer = setSafeInterval(
      this.logger,
      'Failed to remove closed WebSockets',
      this.closeExpiredSockets.bind(this),
      cleanupTimer * 60 * 1000,
    );
    timer.unref();
  }

  public async handle({ webSocket, channel }: WebSocket2023HandlerInput): Promise<void> {
    this.socketMap.add(channel.id, webSocket);
    webSocket.on('error', (): boolean => this.socketMap.deleteEntry(channel.id, webSocket));
    webSocket.on('close', (): boolean => this.socketMap.deleteEntry(channel.id, webSocket));
  }

  /**
   * Close all WebSockets that are attached to a channel that no longer exists.
   */
  private async closeExpiredSockets(): Promise<void> {
    this.logger.debug('Closing expired WebSockets');
    for (const [ id, sockets ] of this.socketMap.entrySets()) {
      const result = await this.storage.get(id);
      if (!result) {
        for (const socket of sockets) {
          // Due to the attached listener, this also deletes the entries in the `socketMap`
          socket.send(`Notification channel has expired`);
          socket.close();
        }
      }
    }
    this.logger.debug('Finished closing expired WebSockets');
  }
}

import type { IncomingMessage } from 'node:http';
import { BadRequestHttpError } from '../../../util/errors/BadRequestHttpError';

/**
 * Generates a WebSocket URL by converting an HTTP(S) URL into a WS(S) URL.
 *
 * @param id - The identifier of the channel. Needs to be a URL.
 */
export function generateWebSocketUrl(id: string): string {
  return `ws${id.slice('http'.length)}`;
}

/**
 * Parses a {@link IncomingMessage} to extract its path used for authentication.
 *
 * @param baseUrl - The base URL of the server.
 * @param request - The request to parse.
 */
export function parseWebSocketRequest(baseUrl: string, request: IncomingMessage): string {
  const path = request.url;

  if (!path) {
    throw new BadRequestHttpError('Missing url parameter in WebSocket request');
  }

  // Use dummy base and then explicitly set the host and protocol from the base URL.
  const id = new URL(path, 'http://example.com');
  const base = new URL(baseUrl);
  id.host = base.host;
  id.protocol = base.protocol;

  return id.href;
}

import type { Store } from 'n3';
import type { Credentials } from '../../../authentication/Credentials';
import type { InteractionRoute } from '../../../identity/interaction/routing/InteractionRoute';
import { getLoggerFor } from '../../../logging/LogUtil';
import { NOTIFY } from '../../../util/Vocabularies';
import { BaseChannelType } from '../BaseChannelType';
import type { NotificationChannel } from '../NotificationChannel';
import { generateWebSocketUrl } from './WebSocket2023Util';

/**
 * A {@link NotificationChannel} containing the necessary fields for a WebSocketChannel2023 channel.
 */
export interface WebSocketChannel2023 extends NotificationChannel {
  /**
   * The "notify:WebSocketChannel2023" type.
   */
  type: typeof NOTIFY.WebSocketChannel2023;
  /**
   * The WebSocket through which the channel will send notifications.
   */
  receiveFrom: string;
}

export function isWebSocket2023Channel(channel: NotificationChannel): channel is WebSocketChannel2023 {
  return channel.type === NOTIFY.WebSocketChannel2023;
}

/**
 * The notification channel type WebSocketChannel2023 as described in
 * https://solid.github.io/notifications/websocket-channel-2023
 *
 * Requires read permissions on a resource to be able to receive notifications.
 */
export class WebSocketChannel2023Type extends BaseChannelType {
  protected readonly logger = getLoggerFor(this);

  public constructor(route: InteractionRoute, features?: string[]) {
    super(NOTIFY.terms.WebSocketChannel2023, route, features);
  }

  public async initChannel(data: Store, credentials: Credentials): Promise<WebSocketChannel2023> {
    const channel = await super.initChannel(data, credentials);
    return {
      ...channel,
      type: NOTIFY.WebSocketChannel2023,
      receiveFrom: generateWebSocketUrl(channel.id),
    };
  }
}

