import type { Quad } from '@rdfjs/types';
import arrayifyStream from 'arrayify-stream';
import type { Response } from 'cross-fetch';
import rdfDereferencer from 'rdf-dereference';
import { BasicRepresentation } from '../http/representation/BasicRepresentation';
import type { Representation } from '../http/representation/Representation';
import { getLoggerFor } from '../logging/LogUtil';
import type { RepresentationConverter } from '../storage/conversion/RepresentationConverter';
import { INTERNAL_QUADS } from './ContentTypes';
import { BadRequestHttpError } from './errors/BadRequestHttpError';
import { createErrorMessage } from './errors/ErrorUtil';

const logger = getLoggerFor('FetchUtil');

/**
 * Fetches an RDF dataset from the given URL.
 *
 * Response will be a Representation with content-type internal/quads.
 */
export async function fetchDataset(url: string): Promise<Representation> {
  // Try content negotiation to parse quads from the URL
  return (async(): Promise<Representation> => {
    try {
      const quadStream = (await rdfDereferencer.dereference(url)).data;
      const quadArray = await arrayifyStream<Quad>(quadStream);
      return new BasicRepresentation(quadArray, { path: url }, INTERNAL_QUADS, false);
    } catch (error: unknown) {
      throw new BadRequestHttpError(
        `Could not parse resource at URL (${url})! ${createErrorMessage(error)}`,
        { cause: error },
      );
    }
  })();
}

/**
 * Converts a given Response (from a request that was already made) to  an RDF dataset.
 * In case the given Response object was already parsed its body can be passed along as a string.
 *
 * The converter will be used to convert the response body to RDF.
 *
 * Response will be a Representation with content-type internal/quads.
 */
export async function responseToDataset(response: Response, converter: RepresentationConverter, body?: string):
Promise<Representation> {
  if (!body) {
    body = await response.text();
  }

  // Keeping the error message the same everywhere to prevent leaking possible information about intranet.
  const error = new BadRequestHttpError(`Unable to access data at ${response.url}`);

  if (response.status !== 200) {
    logger.warn(`Cannot fetch ${response.url}: ${body}`);
    throw error;
  }

  const contentType = response.headers.get('content-type');
  if (!contentType) {
    logger.warn(`Missing content-type header from ${response.url}`);
    throw error;
  }

  // Try to convert to quads
  const representation = new BasicRepresentation(body, contentType);
  const preferences = { type: { [INTERNAL_QUADS]: 1 }};
  return converter.handleSafe({ representation, identifier: { path: response.url }, preferences });
}

import { EventEmitter } from 'node:events';

/**
 * A typed interface of {@link EventEmitter}.
 *
 * Use the `&` operator to combine multiple event/function pairs into a single event emitter.
 * The result needs to be a type and not an interface because of https://github.com/microsoft/TypeScript/issues/16936.
 *
 * Use the {@link createGenericEventEmitterClass} function to generate an event emitter class with the correct typings
 * in case {@link EventEmitter} needs to be extended.
 */
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export interface GenericEventEmitter<TEvent extends string | symbol, TFunc extends (...args: any[]) => void>
  extends EventEmitter {
  addListener: (event: TEvent, listener: TFunc) => this;
  on: (event: TEvent, listener: TFunc) => this;
  once: (event: TEvent, listener: TFunc) => this;
  removeListener: (event: TEvent, listener: TFunc) => this;
  off: (event: TEvent, listener: TFunc) => this;
  removeAllListeners: (event: TEvent) => this;
  listeners: (event: TEvent) => TFunc[];
  rawListeners: (event: TEvent) => TFunc[];
  emit: (event: TEvent, ...args: Parameters<TFunc>) => boolean;
  listenerCount: (event: TEvent) => number;
  prependListener: (event: TEvent, listener: TFunc) => this;
  prependOnceListener: (event: TEvent, listener: TFunc) => this;
  eventNames: () => TEvent[];
}

/**
 * Creates a class that is an implementation of {@link EventEmitter}
 * but with specific typings based on {@link GenericEventEmitter}.
 * Useful in case a class needs to extend {@link EventEmitter} and wants specific internal typings.
 */
export function createGenericEventEmitterClass<T extends EventEmitter>(): new() => T {
  return EventEmitter as unknown as new() => T;
}

import { getLoggerFor } from '../logging/LogUtil';

const logger = getLoggerFor('GuardedStream');

// Using symbols to make sure we don't override existing parameters
const guardedErrors = Symbol('guardedErrors');
const guardedTimeout = Symbol('guardedTimeout');

// Private fields for guarded streams
class Guard {
  // Workaround for the fact that we don't initialize this variable as expected
  declare private [guardedErrors]: Error[];
  private [guardedTimeout]?: NodeJS.Timeout;
}

/**
 * A stream that is guarded from emitting errors when there are no listeners.
 * If an error occurs while no listener is attached,
 * it will store the error and emit it once a listener is added (or a timeout occurs).
 */
export type Guarded<T extends NodeJS.EventEmitter = NodeJS.EventEmitter> = T & Guard;

/**
 * Determines whether the stream is guarded against emitting errors.
 */
export function isGuarded<T extends NodeJS.EventEmitter>(stream: T): stream is Guarded<T> {
  return typeof (stream as unknown as Guarded)[guardedErrors] === 'object';
}

/**
 * Callback that is used when a stream emits an error and no other error listener is attached.
 * Used to store the error and start the logger timer.
 *
 * It is important that this listener always remains attached for edge cases where an error listener gets removed
 * and the number of error listeners is checked immediately afterwards.
 * See https://github.com/CommunitySolidServer/CommunitySolidServer/pull/462#issuecomment-758013492 .
 */
function guardingErrorListener(this: Guarded, error: Error): void {
  // Only fall back to this if no new listeners are attached since guarding started.
  const errorListeners = this.listeners('error');
  if (errorListeners.at(-1) === guardingErrorListener) {
    this[guardedErrors].push(error);
    if (!this[guardedTimeout]) {
      this[guardedTimeout] = setTimeout((): void => {
        logger.error(`No error listener was attached but error was thrown: ${error.message}`);
      }, 1000);
    }
  }
}

/**
 * Callback that is used when a new listener is attached and there are errors that were not emitted yet.
 */
function emitStoredErrors(this: Guarded, event: string, func: (error: Error) => void): void {
  if (event === 'error' && func !== guardingErrorListener) {
    // Cancel an error timeout
    if (this[guardedTimeout]) {
      clearTimeout(this[guardedTimeout]);
      this[guardedTimeout] = undefined;
    }

    // Emit any errors that were guarded
    const errors = this[guardedErrors];
    if (errors.length > 0) {
      this[guardedErrors] = [];
      setImmediate((): void => {
        for (const error of errors) {
          this.emit('error', error);
        }
      });
    }
  }
}

/**
 * Makes sure that listeners always receive the error event of a stream,
 * even if it was thrown before the listener was attached.
 *
 * When guarding a stream it is assumed that error listeners already attached should be ignored,
 * only error listeners attached after the stream is guarded will prevent an error from being logged.
 *
 * If the input is already guarded the guard will be reset,
 * which means ignoring error listeners already attached.
 *
 * @param stream - Stream that can potentially throw an error.
 *
 * @returns The stream.
 */
export function guardStream<T extends NodeJS.EventEmitter>(stream: T): Guarded<T> {
  const guarded = stream as Guarded<T>;
  if (isGuarded(stream)) {
    // This makes sure the guarding error listener is the last one in the list again
    guarded.removeListener('error', guardingErrorListener);
    guarded.on('error', guardingErrorListener);
  } else {
    guarded[guardedErrors] = [];
    guarded.on('error', guardingErrorListener);
    guarded.on('newListener', emitStoredErrors);
  }
  return guarded;
}

import type { AsyncHandler, AsyncHandlerOutput } from './AsyncHandler';
import { UnionHandler } from './UnionHandler';

/**
 * A utility handler that concatenates the results of all its handlers into a single result.
 */
export class ArrayUnionHandler<T extends AsyncHandler<unknown, unknown[]>> extends UnionHandler<T> {
  public constructor(handlers: T[], requireAll?: boolean, ignoreErrors?: boolean) {
    super(handlers, requireAll, ignoreErrors);
  }

  protected async combine(results: AsyncHandlerOutput<T>[]): Promise<AsyncHandlerOutput<T>> {
    return results.flat() as AsyncHandlerOutput<T>;
  }
}

type Awaited<T> = T extends PromiseLike<infer U> ? U : T;
export type AsyncHandlerInput<T extends AsyncHandler<unknown, unknown>> = Parameters<T['handle']>[0];
export type AsyncHandlerOutput<T extends AsyncHandler<unknown, unknown>> = Awaited<ReturnType<T['handle']>>;

/**
 * Simple interface for classes that can potentially handle a specific kind of data asynchronously.
 */
export abstract class AsyncHandler<TIn = void, TOut = void> {
  /**
   * Checks whether the input can be handled by this class.
   * If it cannot handle the input, rejects with an error explaining why.
   *
   * @param input - Input that could potentially be handled.
   *
   * @returns A promise resolving if the input can be handled, rejecting with an Error if not.
   */
  // eslint-disable-next-line unused-imports/no-unused-vars
  public async canHandle(input: TIn): Promise<void> {
    // Support any input by default
  }

  /**
   * Handles the given input. This may only be called if {@link canHandle} did not reject.
   * When unconditionally calling both in sequence, consider {@link handleSafe} instead.
   *
   * @param input - Input that needs to be handled.
   *
   * @returns A promise resolving when handling is finished.
   */
  public abstract handle(input: TIn): Promise<TOut>;

  /**
   * Helper function that first runs {@link canHandle} followed by {@link handle}.
   * Throws the error of {@link canHandle} if the data cannot be handled,
   * or returns the result of {@link handle} otherwise.
   *
   * @param input - Input data that will be handled if it can be handled.
   *
   * @returns A promise resolving if the input can be handled, rejecting with an Error if not.
   */
  public async handleSafe(input: TIn): Promise<TOut> {
    await this.canHandle(input);
    return this.handle(input);
  }
}

import { getLoggerFor } from '../../logging/LogUtil';
import { InternalServerError } from '../errors/InternalServerError';
import { promiseSome } from '../PromiseUtil';
import { AsyncHandler } from './AsyncHandler';
import { filterHandlers } from './HandlerUtil';

/**
 * A composite handler that returns true if any of its handlers can handle the input and return true.
 * Handler errors are interpreted as false results.
 */
export class BooleanHandler<TIn> extends AsyncHandler<TIn, boolean> {
  protected readonly logger = getLoggerFor(this);

  private readonly handlers: AsyncHandler<TIn, boolean>[];

  /**
   * Creates a new BooleanHandler that stores the given handlers.
   *
   * @param handlers - Handlers over which it will run.
   */
  public constructor(handlers: AsyncHandler<TIn, boolean>[]) {
    super();
    this.handlers = handlers;
  }

  public async canHandle(input: TIn): Promise<void> {
    // We use this to generate an error if no handler supports the input
    await filterHandlers(this.handlers, input);
  }

  public async handleSafe(input: TIn): Promise<boolean> {
    const handlers = await filterHandlers(this.handlers, input);
    return promiseSome(handlers.map(async(handler): Promise<boolean> => handler.handle(input)));
  }

  public async handle(input: TIn): Promise<boolean> {
    let handlers: AsyncHandler<TIn, boolean>[];
    try {
      handlers = await filterHandlers(this.handlers, input);
    } catch (error: unknown) {
      this.logger.warn('All handlers failed. This might be the consequence of calling handle before canHandle.');
      throw new InternalServerError('All handlers failed', { cause: error });
    }
    return promiseSome(handlers.map(async(handler): Promise<boolean> => handler.handle(input)));
  }
}

import { AsyncHandler } from './AsyncHandler';

type NestedMap<TOut> = TOut | WeakMap<object, NestedMap<TOut>>;

/**
 * Caches output data from the source handler based on the input object.
 * The `fields` parameter can be used to instead use one or more specific entries from the input object as cache key,
 * so has as actual required typing `(keyof TIn)[]`.
 *
 * A {@link WeakMap} is used internally so strict object equality determines cache hits,
 * and data will be removed once the key stops existing.
 * This also means that the cache key needs to be an object.
 * Errors will be thrown in case a primitive is used.
 */
export class CachedHandler<TIn extends Record<string, unknown>, TOut = void> extends AsyncHandler<TIn, TOut> {
  private readonly source: AsyncHandler<TIn, TOut>;
  private readonly fields?: [keyof TIn, ...(keyof TIn)[]];

  private readonly cache: WeakMap<object, NestedMap<TOut>>;

  public constructor(source: AsyncHandler<TIn, TOut>, fields?: string[]) {
    super();
    this.source = source;
    if (fields) {
      if (fields.length === 0) {
        throw new Error('The fields parameter needs to have at least 1 entry if defined.');
      }
      // This is the first of many casts in this class.
      // All of them are 100% correct though and are a consequence
      // of the cache depth depending on the length of `fields`
      // and the Node.js array functions not always having strict enough typings.
      this.fields = fields as [keyof TIn, ...(keyof TIn)[]];
    }
    this.cache = new WeakMap();
  }

  public async canHandle(input: TIn): Promise<void> {
    const keys = this.getKeys(input);
    const map = this.findDestination(input, keys, this.cache);

    if (map?.has(keys.pop()!)) {
      return;
    }

    return this.source.canHandle(input);
  }

  public async handle(input: TIn): Promise<TOut> {
    const keys = this.getKeys(input);
    const map = this.findDestination(input, keys, this.cache, true)!;

    const key = keys.pop()!;
    let result = map.get(key);
    if (result) {
      return result;
    }

    result = await this.source.handle(input);
    map.set(key, result);

    return result;
  }

  /**
   * Extracts the values that will be used as keys from the input object.
   * In case the `fields` value was undefined, this will return an array containing the input object itself.
   */
  protected getKeys(input: TIn): [object, ...object[]] {
    if (!this.fields) {
      return [ input ];
    }

    return this.fields.map((field): object => input[field] as object) as [object, ...object[]];
  }

  /**
   * Returns the `WeakMap` that contains actual objects that were cached,
   * so the last `WeakMap` in the chain of maps.
   *
   * Returns `undefined` if no such map exists because earlier keys were not cached.
   *
   * Will always return a map if `ensure` is set to true,
   * in such a case the intermediate maps will be created and added to the previous map.
   */
  protected findDestination(input: TIn, keys: object[], cache: WeakMap<object, NestedMap<TOut>>, ensure = false):
  WeakMap<object, TOut> | undefined {
    if (keys.length === 1) {
      return cache as WeakMap<object, TOut>;
    }

    const key = keys[0];
    let nextCache = cache.get(key) as WeakMap<object, NestedMap<TOut>> | undefined;
    if (!nextCache) {
      if (!ensure) {
        return;
      }
      nextCache = new WeakMap<object, NestedMap<TOut>>();
      cache.set(key, nextCache);
    }

    return this.findDestination(input, keys.slice(1), nextCache, ensure);
  }
}

import type { KeyValueStorage } from '../../storage/keyvalue/KeyValueStorage';
import { NotImplementedHttpError } from '../errors/NotImplementedHttpError';
import { AsyncHandler } from './AsyncHandler';

/**
 * This handler will pass all requests to the wrapped handler,
 * until a specific value has been set in the given storage.
 * After that all input will be rejected.
 * Once the value has been matched this behaviour will be cached,
 * so changing the value again afterwards will not enable this handler again.
 *
 * If `handleStorage` is set to `true`,
 * this handler will set the value itself in the given storage after the source handler successfully resolved.
 */
export class ConditionalHandler<TIn, TOut> extends AsyncHandler<TIn, TOut> {
  private readonly source: AsyncHandler<TIn, TOut>;
  private readonly storage: KeyValueStorage<string, unknown>;
  private readonly storageKey: string;
  private readonly storageValue: unknown;
  private readonly handleStorage: boolean;

  private finished: boolean;

  public constructor(
    source: AsyncHandler<TIn, TOut>,
    storage: KeyValueStorage<string, unknown>,
    storageKey: string,
    storageValue: unknown,
    handleStorage = false,
  ) {
    super();
    this.source = source;
    this.storage = storage;
    this.storageKey = storageKey;
    this.storageValue = storageValue;
    this.handleStorage = handleStorage;

    this.finished = false;
  }

  public async canHandle(input: TIn): Promise<void> {
    await this.checkCondition();
    await this.source.canHandle(input);
  }

  public async handleSafe(input: TIn): Promise<TOut> {
    await this.checkCondition();
    const result = await this.source.handleSafe(input);
    if (this.handleStorage) {
      await this.storage.set(this.storageKey, this.storageValue);
      this.finished = true;
    }
    return result;
  }

  public async handle(input: TIn): Promise<TOut> {
    const result = await this.source.handle(input);
    if (this.handleStorage) {
      await this.storage.set(this.storageKey, this.storageValue);
      this.finished = true;
    }
    return result;
  }

  /**
   * Checks if the condition has already been fulfilled.
   */
  private async checkCondition(): Promise<void> {
    if (!this.finished) {
      this.finished = await this.storage.get(this.storageKey) === this.storageValue;
    }

    if (this.finished) {
      throw new NotImplementedHttpError('The condition has been fulfilled.');
    }
  }
}

import { createErrorMessage, isError } from '../errors/ErrorUtil';
import { createAggregateError } from '../errors/HttpErrorUtil';
import type { AsyncHandler } from './AsyncHandler';

/**
 * Finds a handler that can handle the given input data.
 * Otherwise an error gets thrown.
 *
 * @param handlers - List of handlers to search in.
 * @param input - The input data.
 *
 * @returns A promise resolving to a handler that supports the data or otherwise rejecting.
 */
export async function findHandler<TIn, TOut>(handlers: AsyncHandler<TIn, TOut>[], input: TIn):
Promise<AsyncHandler<TIn, TOut>> {
  const errors: Error[] = [];

  for (const handler of handlers) {
    try {
      await handler.canHandle(input);

      return handler;
    } catch (error: unknown) {
      if (isError(error)) {
        errors.push(error);
      } else {
        errors.push(new Error(createErrorMessage(error)));
      }
    }
  }

  throw createAggregateError(errors);
}

/**
 * Filters a list of handlers to only keep those that can handle the input.
 * Will error if no matching handlers are found.
 *
 * @param handlers - Handlers to filter.
 * @param input - Input that needs to be supported.
 */
export async function filterHandlers<TIn, TOut>(handlers: AsyncHandler<TIn, TOut>[], input: TIn):
Promise<AsyncHandler<TIn, TOut>[]> {
  const results = await Promise.allSettled(handlers.map(async(handler): Promise<AsyncHandler<TIn, TOut>> => {
    await handler.canHandle(input);
    return handler;
  }));
  const matches = results.filter(({ status }): boolean => status === 'fulfilled')
    .map((result): AsyncHandler<TIn, TOut> =>
      (result as PromiseFulfilledResult<AsyncHandler<TIn, TOut>>).value);

  if (matches.length > 0) {
    return matches;
  }

  // Generate error in case no matches were found
  const errors = results.map((result): Error => (result as PromiseRejectedResult).reason as Error);

  throw createAggregateError(errors);
}

import { NotImplementedHttpError } from '../errors/NotImplementedHttpError';
import { AsyncHandler } from './AsyncHandler';

// The formats from which we can detect the method
type InType = { method: string } | { request: { method: string }} | { operation: { method: string }};

/**
 * Only accepts requests where the input has a (possibly nested) `method` field
 * that matches any one of the given methods.
 * In case of a match, the input will be sent to the source handler.
 */
export class MethodFilterHandler<TIn extends InType, TOut> extends AsyncHandler<TIn, TOut> {
  private readonly methods: string[];
  private readonly source: AsyncHandler<TIn, TOut>;

  public constructor(methods: string[], source: AsyncHandler<TIn, TOut>) {
    super();
    this.methods = methods;
    this.source = source;
  }

  public async canHandle(input: TIn): Promise<void> {
    const method = this.findMethod(input);
    if (!this.methods.includes(method)) {
      throw new NotImplementedHttpError(
        `Cannot determine permissions of ${method}, only ${this.methods.join(',')}.`,
      );
    }
    await this.source.canHandle(input);
  }

  public async handle(input: TIn): Promise<TOut> {
    return this.source.handle(input);
  }

  /**
   * Finds the correct method in the input object.
   */
  private findMethod(input: InType): string {
    if ('method' in input) {
      return input.method;
    }
    if ('request' in input) {
      return this.findMethod(input.request);
    }
    if ('operation' in input) {
      return this.findMethod(input.operation);
    }
    throw new NotImplementedHttpError('Could not find method in input object.');
  }
}

import { AsyncHandler } from './AsyncHandler';

/**
 * A composite handler that executes handlers in parallel.
 */
export class ParallelHandler<TIn = void, TOut = void> extends AsyncHandler<TIn, TOut[]> {
  private readonly handlers: AsyncHandler<TIn, TOut>[];

  public constructor(handlers: AsyncHandler<TIn, TOut>[]) {
    super();
    this.handlers = [ ...handlers ];
  }

  public async canHandle(input: TIn): Promise<void> {
    await Promise.all(this.handlers.map(async(handler): Promise<void> => handler.canHandle(input)));
  }

  public async handle(input: TIn): Promise<TOut[]> {
    return Promise.all(this.handlers.map(async(handler): Promise<TOut> => handler.handle(input)));
  }
}

import type { ClusterManager } from '../../init/cluster/ClusterManager';
import { NotImplementedHttpError } from '../errors/NotImplementedHttpError';
import { AsyncHandler } from './AsyncHandler';

/**
 * A wrapper handler that will only run the wrapped handler if it is executed from:
 * * when running multithreaded: either the **primary** or a **worker process**
 * * when running singlethreaded: **the only process** (i.e. always)
 */
export class ProcessHandler<TIn, TOut> extends AsyncHandler<TIn, TOut> {
  private readonly clusterManager: ClusterManager;
  private readonly source: AsyncHandler<TIn, TOut>;
  private readonly executeOnPrimary: boolean;

  /**
   * Creates a new ProcessHandler
   *
   * @param source - The wrapped handler
   * @param clusterManager - The ClusterManager in use
   * @param executeOnPrimary - Whether to execute the source handler when the process is the _primary_ or a _worker_.
   */
  public constructor(source: AsyncHandler<TIn, TOut>, clusterManager: ClusterManager, executeOnPrimary: boolean) {
    super();
    this.source = source;
    this.clusterManager = clusterManager;
    this.executeOnPrimary = executeOnPrimary;
  }

  public async canHandle(input: TIn): Promise<void> {
    if (!this.canExecute()) {
      throw new NotImplementedHttpError(`Will not execute on ${this.executeOnPrimary ? 'worker' : 'primary'} process.`);
    }
    await this.source.canHandle(input);
  }

  public async handle(input: TIn): Promise<TOut> {
    return this.source.handle(input);
  }

  /**
   * Checks if the condition has already been fulfilled.
   */
  private canExecute(): boolean {
    return this.clusterManager.isSingleThreaded() ||
      (this.executeOnPrimary ? this.clusterManager.isPrimary() : this.clusterManager.isWorker());
  }
}

import { AsyncHandler } from './AsyncHandler';

/**
 * A composite handler that will try to run all supporting handlers sequentially
 * and return the value of the last supported handler.
 * The `canHandle` check of this handler will always succeed.
 */
export class SequenceHandler<TIn = void, TOut = void> extends AsyncHandler<TIn, TOut | undefined> {
  private readonly handlers: AsyncHandler<TIn, TOut>[];

  public constructor(handlers: AsyncHandler<TIn, TOut>[]) {
    super();
    this.handlers = [ ...handlers ];
  }

  public async handle(input: TIn): Promise<TOut | undefined> {
    let result: TOut | undefined;
    for (const handler of this.handlers) {
      let supported: boolean;
      try {
        await handler.canHandle(input);
        supported = true;
      } catch {
        supported = false;
      }
      if (supported) {
        result = await handler.handle(input);
      }
    }
    return result;
  }
}

import { AsyncHandler } from './AsyncHandler';

/**
 * A handler that always resolves and always returns the stored value.
 * Will return undefined if no value is stored.
 *
 * The generic type extends `any` due to Components.js requirements.
 */
export class StaticHandler<T = void> extends AsyncHandler<unknown, T> {
  private readonly value?: T;

  public constructor(value?: T) {
    super();
    this.value = value;
  }

  public async handle(): Promise<T> {
    return this.value!;
  }
}

import type { HttpError, HttpErrorClass } from '../errors/HttpError';
import { AsyncHandler } from './AsyncHandler';

/**
 * Utility handler that can handle all input and always throws an instance of the given error.
 */
export class StaticThrowHandler extends AsyncHandler<unknown, never> {
  protected readonly error: HttpError;

  public constructor(error: HttpError) {
    super();
    this.error = error;
  }

  public async handle(): Promise<never> {
    // We are creating a new instance of the error instead of rethrowing the error,
    // as reusing the same error can cause problem as the metadata is then also reused.
    throw new (this.error.constructor as HttpErrorClass)();
  }
}

import { allFulfilled } from '../PromiseUtil';
import type { AsyncHandlerInput, AsyncHandlerOutput } from './AsyncHandler';
import { AsyncHandler } from './AsyncHandler';
import { filterHandlers, findHandler } from './HandlerUtil';

/**
 * Utility handler that allows combining the results of multiple handlers into one.
 * Will run the handlers and then call the abstract `combine` function with the results,
 * which then generates the handler's output.
 */
export abstract class UnionHandler<T extends AsyncHandler<unknown, unknown>> extends
  AsyncHandler<AsyncHandlerInput<T>, AsyncHandlerOutput<T>> {
  protected readonly handlers: T[];
  private readonly requireAll: boolean;
  private readonly ignoreErrors: boolean;

  /**
   * Creates a new `UnionHandler`.
   *
   * When `requireAll` is false or `ignoreErrors` is true,
   * the length of the input to `combine` can vary;
   * otherwise, it is exactly the number of handlers.
   *
   * @param handlers - The handlers whose output is to be combined.
   * @param requireAll - If true, will fail if any of the handlers do not support the input.
                         If false, only the handlers that support the input will be called;
   *                     will fail only if none of the handlers can handle the input.
   * @param ignoreErrors - If true, ignores handlers that fail by omitting their output;
   *                       if false, fails when any handlers fail.
   */
  public constructor(handlers: T[], requireAll = false, ignoreErrors = !requireAll) {
    super();
    this.handlers = handlers;
    this.requireAll = requireAll;
    this.ignoreErrors = ignoreErrors;
  }

  public async canHandle(input: AsyncHandlerInput<T>): Promise<void> {
    if (this.requireAll) {
      await this.allCanHandle(input);
    } else {
      // This will error if no handler supports the input
      await findHandler(this.handlers, input);
    }
  }

  public async handle(input: AsyncHandlerInput<T>): Promise<AsyncHandlerOutput<T>> {
    const handlers = this.requireAll ? this.handlers : (await filterHandlers(this.handlers, input)) as T[];
    const results = handlers.map(async(handler): Promise<AsyncHandlerOutput<T>> =>
      (handler.handle(input)) as Promise<AsyncHandlerOutput<T>>);
    return this.combine(await allFulfilled(results, this.ignoreErrors));
  }

  /**
   * Checks if all handlers can handle the input.
   * If not, throw an error based on the errors of the failed handlers.
   */
  protected async allCanHandle(input: AsyncHandlerInput<T>): Promise<void> {
    await allFulfilled(this.handlers.map(async(handler): Promise<void> => handler.canHandle(input)));
  }

  /**
   * Combines the results of the handlers into a single output.
   */
  protected abstract combine(results: AsyncHandlerOutput<T>[]): Promise<AsyncHandlerOutput<T>>;
}

import { NotImplementedHttpError } from '../errors/NotImplementedHttpError';
import { AsyncHandler } from './AsyncHandler';

/**
 * Handler that does not support any input and will always throw an error.
 */
export class UnsupportedAsyncHandler extends AsyncHandler<unknown, never> {
  private readonly errorMessage?: string;

  public constructor(errorMessage?: string) {
    super();
    this.errorMessage = errorMessage;
  }

  public async canHandle(): Promise<never> {
    throw new NotImplementedHttpError(this.errorMessage);
  }

  public async handle(): Promise<never> {
    return this.canHandle();
  }
}

import { getLoggerFor } from '../../logging/LogUtil';
import { InternalServerError } from '../errors/InternalServerError';
import type { AsyncHandler } from './AsyncHandler';
import { findHandler } from './HandlerUtil';

/**
 * A composite handler that tries multiple handlers one by one
 * until it finds a handler that supports the input.
 * The handlers will be checked in the order they appear in the input array,
 * allowing for more fine-grained handlers to check before catch-all handlers.
 */
export class WaterfallHandler<TIn, TOut> implements AsyncHandler<TIn, TOut> {
  protected readonly logger = getLoggerFor(this);

  private readonly handlers: AsyncHandler<TIn, TOut>[];

  /**
   * Creates a new WaterfallHandler that stores the given handlers.
   *
   * @param handlers - Handlers over which it will run.
   */
  public constructor(handlers: AsyncHandler<TIn, TOut>[]) {
    this.handlers = handlers;
  }

  /**
   * Checks whether any of the stored handlers can handle the given input.
   *
   * @param input - The data that would need to be handled.
   *
   * @returns A promise resolving if at least 1 handler supports to input, or rejecting if none do.
   */
  public async canHandle(input: TIn): Promise<void> {
    await findHandler(this.handlers, input);
  }

  /**
   * Finds a handler that supports the given input and then lets it handle the given data.
   *
   * @param input - The data that needs to be handled.
   *
   * @returns A promise corresponding to the handle call of a handler that supports the input.
   * It rejects if no handlers support the given data.
   */
  public async handle(input: TIn): Promise<TOut> {
    let handler: AsyncHandler<TIn, TOut>;

    try {
      handler = await findHandler(this.handlers, input);
    } catch (error: unknown) {
      this.logger.warn('All handlers failed. This might be the consequence of calling handle before canHandle.');
      throw new InternalServerError('All handlers failed', { cause: error });
    }

    return handler.handle(input);
  }

  /**
   * Identical to {@link AsyncHandler.handleSafe} but optimized for composite
   * by only needing 1 canHandle call on members.
   *
   * @param input - The input data.
   *
   * @returns A promise corresponding to the handle call of a handler that supports the input.
   * It rejects if no handlers support the given data.
   */
  public async handleSafe(input: TIn): Promise<TOut> {
    const handler = await findHandler(this.handlers, input);

    return handler.handle(input);
  }
}

// The interfaces here are split off from HttpErrorUtil.ts to prevent a dependency loop in RepresentationMetadata

/**
 * General interface for all Accept* headers.
 */
export interface AcceptHeader {
  /** Requested range. Can be a specific value or `*`, matching all. */
  range: string;
  /** Weight of the preference [0, 1]. */
  weight: number;
}

/**
 * Contents of an HTTP Accept header.
 * Range is type/subtype. Both can be `*`.
 */
export interface Accept extends AcceptHeader {
  parameters: {
    /** Media type parameters. These are the parameters that came before the q value. */
    mediaType: Record<string, string>;
    /**
     * Extension parameters. These are the parameters that came after the q value.
     * Value will be an empty string if there was none.
     */
    extension: Record<string, string>;
  };
}

/**
 * Contents of an HTTP Accept-Charset header.
 */
export interface AcceptCharset extends AcceptHeader { }

/**
 * Contents of an HTTP Accept-Encoding header.
 */
export interface AcceptEncoding extends AcceptHeader { }

/**
 * Contents of an HTTP Accept-Language header.
 */
export interface AcceptLanguage extends AcceptHeader { }

/**
 * Contents of an HTTP Accept-Datetime header.
 */
export interface AcceptDatetime extends AcceptHeader { }

/**
 * Contents of an HTTP Content-Type Header.
 * Optional parameters Record is included.
 */
export class ContentType {
  public constructor(public value: string, public parameters: Record<string, string> = {}) {}

  /**
   * Serialize this ContentType object to a ContentType header appropriate value string.
   *
   * @returns The value string, including parameters, if present.
   */
  public toHeaderValueString(): string {
    const parameterStrings = Object.entries(this.parameters)
      .sort((entry1, entry2): number => entry1[0].localeCompare(entry2[0]))
      .map(([ key, value ]): string => `${key}=${value}`);
    return [ this.value, ...parameterStrings ].join('; ');
  }
}

export interface LinkEntryParameters extends Record<string, string> {
  /** Required rel properties of Link entry */
  rel: string;
}

export interface LinkEntry {
  target: string;
  parameters: LinkEntryParameters;
}

// BNF based on https://tools.ietf.org/html/rfc7231
//
// media-type = type "/" subtype *( OWS ";" OWS parameter )
//
// media-range    = ( "*/*"
//                / ( type "/" "*" )
//                / ( type "/" subtype )
//                ) *( OWS ";" OWS parameter ) ; media type parameters
// accept-params  = weight *( accept-ext )
// accept-ext     = OWS ";" OWS token [ "=" ( token / quoted-string ) ] ; extension parameters
//
// weight = OWS ";" OWS "q=" qvalue
// qvalue = ( "0" [ "." 0*3DIGIT ] )
//        / ( "1" [ "." 0*3("0") ] )
//
// type       = token
// subtype    = token
// parameter  = token "=" ( token / quoted-string )
//
// quoted-string  = DQUOTE *( qdtext / quoted-pair ) DQUOTE
// qdtext         = HTAB / SP / %x21 / %x23-5B / %x5D-7E / obs-text
// obs-text       = %x80-FF
// quoted-pair    = "\" ( HTAB / SP / VCHAR / obs-text )
//
// charset = token
//
// codings          = content-coding / "identity" / "*"
// content-coding   = token
//
// language-range   = (1*8ALPHA *("-" 1*8alphanum)) / "*"
// alphanum         = ALPHA / DIGIT
//
// Delimiters are chosen from the set of US-ASCII visual characters
// not allowed in a token (DQUOTE and "(),/:;<=>?@[\]{}").
// token          = 1*tchar
// tchar          = "!" / "#" / "$" / "%" / "&" / "'" / "*"
//                / "+" / "-" / "." / "^" / "_" / "`" / "|" / "~"
//                / DIGIT / ALPHA
//                ; any VCHAR, except delimiters
//

// REUSED REGEXES
export const TCHAR = /[-\w!#$%&'*+.^`|~]/u;
export const TOKEN = new RegExp(`^${TCHAR.source}+$`, 'u');
export const SIMPLE_MEDIA_RANGE = new RegExp(`^${TCHAR.source}+/${TCHAR.source}+$`, 'u');
export const QUOTED_STRING =
  /^"(?:[\t !\u0023-\u005B\u005D-\u007E\u0080-\u00FF]|(\\[\t\u0020-\u007E\u0080-\u00FF]))*"$/u;
export const QVALUE = /^(?:(0(?:\.\d{0,3})?)|(1(?:\.0{0,3})?))$/u;

import type { IncomingHttpHeaders } from 'node:http';
import escapeStringRegexp from 'escape-string-regexp';
import { getLoggerFor } from '../logging/LogUtil';
import type { HttpResponse } from '../server/HttpResponse';
import { BadRequestHttpError } from './errors/BadRequestHttpError';
import type {
  Accept,
  AcceptCharset,
  AcceptDatetime,
  AcceptEncoding,
  AcceptHeader,
  AcceptLanguage,
  LinkEntry,
  LinkEntryParameters,
} from './Header';
import { ContentType, QUOTED_STRING, QVALUE, SIMPLE_MEDIA_RANGE, TOKEN } from './Header';

const logger = getLoggerFor('HeaderUtil');

// BNF based on https://tools.ietf.org/html/rfc7231
//
// Accept =          #( media-range [ accept-params ] )
// Accept-Charset =  1#( ( charset / "*" ) [ weight ] )
// Accept-Encoding  = #( codings [ weight ] )
// Accept-Language = 1#( language-range [ weight ] )
//
// Content-Type = media-type

// HELPER FUNCTIONS
/**
 * Replaces all double quoted strings in the input string with `"0"`, `"1"`, etc.
 *
 * @param input - The Accept header string.
 *
 * @returns The transformed string and a map with keys `"0"`, etc. and values the original string that was there.
 *
 * @throws BadRequestHttpError
 * Thrown if invalid characters are detected in a quoted string.
 */
export function transformQuotedStrings(input: string): { result: string; replacements: Record<string, string> } {
  let idx = 0;
  const replacements: Record<string, string> = {};
  const result = input.replaceAll(/"(?:[^"\\]|\\.)*"/gu, (match): string => {
    // Not all characters allowed in quoted strings, see BNF above
    if (!QUOTED_STRING.test(match)) {
      logger.warn(`Invalid quoted string in header: ${match}`);
      throw new BadRequestHttpError(`Invalid quoted string in header: ${match}`);
    }
    const replacement = `"${idx}"`;
    replacements[replacement] = match.slice(1, -1);
    idx += 1;
    return replacement;
  });
  return { result, replacements };
}

/**
 * Splits the input string on commas, trims all parts and filters out empty ones.
 *
 * @param input - Input header string.
 *
 * @returns An array of trimmed strings.
 */
export function splitAndClean(input: string): string[] {
  return input.split(',')
    .map((part): string => part.trim())
    .filter((part): boolean => part.length > 0);
}

/**
 * Converts a qvalue to a number.
 * Returns 1 if the value is not a valid number or 1 if it is more than 1.
 * Returns 0 if the value is negative.
 * Otherwise, the parsed value is returned.
 *
 * @param qvalue - Value to convert.
 */
function parseQValue(qvalue: string): number {
  const result = Number(qvalue);
  if (Number.isNaN(result) || result >= 1) {
    return 1;
  }
  if (result < 0) {
    return 0;
  }
  return result;
}

/**
 * Logs a warning to indicate there was an invalid value.
 * Throws a {@link BadRequestHttpError} in case `strict` is `true`.
 *
 * @param message - Message to log and potentially put in the error.
 * @param strict - `true` if an error needs to be thrown.
 */
function handleInvalidValue(message: string, strict: boolean): void | never {
  logger.warn(message);
  if (strict) {
    throw new BadRequestHttpError(message);
  }
}

/**
 * Parses a list of split parameters and checks their validity. Parameters with invalid
 * syntax are ignored and not returned.
 *
 * @param parameters - A list of split parameters (token [ "=" ( token / quoted-string ) ])
 * @param replacements - The double quoted strings that need to be replaced.
 * @param strict - Determines if invalid values throw errors (`true`) or log warnings (`false`). Defaults to `false`.
 *
 * @returns An array of name/value objects corresponding to the parameters.
 */
export function parseParameters(parameters: string[], replacements: Record<string, string>, strict = false):
{ name: string; value: string }[] {
  const parsed: { name: string; value: string }[] = [];
  for (const param of parameters) {
    const [ name, rawValue ] = param.split('=').map((str): string => str.trim());

    // Test replaced string for easier check
    // parameter  = token "=" ( token / quoted-string )
    // second part is optional for certain parameters
    if (!(TOKEN.test(name) && (!rawValue || /^"\d+"$/u.test(rawValue) || TOKEN.test(rawValue)))) {
      handleInvalidValue(`Invalid parameter value: ${name}=${replacements[rawValue] || rawValue
      } does not match (token ( "=" ( token / quoted-string ))?). `, strict);
      continue;
    }

    let value = rawValue;
    if (value in replacements) {
      value = replacements[rawValue];
    }

    parsed.push({ name, value });
  }
  return parsed;
}

/**
 * Parses a single media range with corresponding parameters from an Accept header.
 * For every parameter value that is a double quoted string,
 * we check if it is a key in the replacements map.
 * If yes the value from the map gets inserted instead.
 * Invalid q values and parameter values are ignored and not returned.
 *
 * @param part - A string corresponding to a media range and its corresponding parameters.
 * @param replacements - The double quoted strings that need to be replaced.
 * @param strict - Determines if invalid values throw errors (`true`) or log warnings (`false`). Defaults to `false`.
 *
 * @returns An object corresponding to the header string, or
 * undefined if an invalid type or sub-type is detected.
 */
function parseAcceptPart(part: string, replacements: Record<string, string>, strict: boolean): Accept | undefined {
  const [ range, ...parameters ] = part.split(';').map((param): string => param.trim());

  // No reason to test differently for * since we don't check if the type exists
  if (!SIMPLE_MEDIA_RANGE.test(range)) {
    handleInvalidValue(
      `Invalid Accept range: ${range} does not match ( "*/*" / ( token "/" "*" ) / ( token "/" token ) )`,
      strict,
    );
    return;
  }

  let weight = 1;
  const mediaTypeParams: Record<string, string> = {};
  const extensionParams: Record<string, string> = {};
  let map = mediaTypeParams;
  const parsedParams = parseParameters(parameters, replacements);
  for (const { name, value } of parsedParams) {
    if (name === 'q') {
      // Extension parameters appear after the q value
      map = extensionParams;
      if (!QVALUE.test(value)) {
        handleInvalidValue(`Invalid q value for range ${range}: ${value
        } does not match ( "0" [ "." 0*3DIGIT ] ) / ( "1" [ "." 0*3("0") ] ).`, strict);
      }
      weight = parseQValue(value);
    } else {
      if (!value && map !== extensionParams) {
        handleInvalidValue(
          `Invalid Accept parameter ${name}: ` +
          `Accept parameter values are not optional when preceding the q value`,
          strict,
        );
        continue;
      }
      map[name] = value || '';
    }
  }

  return {
    range,
    weight,
    parameters: {
      mediaType: mediaTypeParams,
      extension: extensionParams,
    },
  };
}

/**
 * Parses an Accept-* header where each part is only a value and a weight, so roughly /.*(q=.*)?/ separated by commas.
 * The returned weights default to 1 if no q value is found or the q value is invalid.
 *
 * @param input - Input header string.
 * @param strict - Determines if invalid values throw errors (`true`) or log warnings (`false`). Defaults to `false`.
 *
 * @returns An array of ranges and weights.
 */
function parseNoParameters(input: string, strict = false): AcceptHeader[] {
  const parts = splitAndClean(input);

  return parts.map((part): AcceptHeader => {
    const [ range, qvalue ] = part.split(';').map((param): string => param.trim());
    const result = { range, weight: 1 };
    if (qvalue) {
      if (!qvalue.startsWith('q=')) {
        handleInvalidValue(`Only q parameters are allowed in ${input}`, strict);
        return result;
      }
      const val = qvalue.slice(2);
      if (!QVALUE.test(val)) {
        handleInvalidValue(`Invalid q value for range ${range}: ${val
        } does not match ( "0" [ "." 0*3DIGIT ] ) / ( "1" [ "." 0*3("0") ] ).`, strict);
      }
      result.weight = parseQValue(val);
    }
    return result;
  }).sort((left, right): number => right.weight - left.weight);
}

// EXPORTED FUNCTIONS

/**
 * Parses an Accept header string.
 *
 * @param input - The Accept header string.
 * @param strict - Determines if invalid values throw errors (`true`) or log warnings (`false`). Defaults to `false`.
 *
 * @returns An array of {@link Accept} objects, sorted by weight. Accept parts
 * with invalid syntax are ignored and removed from the returned array.
 */
export function parseAccept(input: string, strict = false): Accept[] {
  // Quoted strings could prevent split from having correct results
  const { result, replacements } = transformQuotedStrings(input);

  const accepts: Accept[] = [];
  for (const part of splitAndClean(result)) {
    const partOrUndef = parseAcceptPart(part, replacements, strict);

    if (partOrUndef !== undefined) {
      accepts.push(partOrUndef);
    }
  }
  return accepts.sort((left, right): number => right.weight - left.weight);
}

/**
 * Parses an Accept-Charset header string.
 *
 * @param input - The Accept-Charset header string.
 * @param strict - Determines if invalid values throw errors (`true`) or log warnings (`false`). Defaults to `false`.
 *
 * @returns An array of {@link AcceptCharset} objects, sorted by weight. Invalid ranges
 * are ignored and not returned.
 */
export function parseAcceptCharset(input: string, strict = false): AcceptCharset[] {
  const results = parseNoParameters(input);
  return results.filter((result): boolean => {
    if (!TOKEN.test(result.range)) {
      handleInvalidValue(
        `Invalid Accept-Charset range: ${result.range} does not match (content-coding / "identity" / "*")`,
        strict,
      );
      return false;
    }
    return true;
  });
}

/**
 * Parses an Accept-Encoding header string.
 *
 * @param input - The Accept-Encoding header string.
 * @param strict - Determines if invalid values throw errors (`true`) or log warnings (`false`). Defaults to `false`.
 *
 * @returns An array of {@link AcceptEncoding} objects, sorted by weight. Invalid ranges
 * are ignored and not returned.
 */
export function parseAcceptEncoding(input: string, strict = false): AcceptEncoding[] {
  const results = parseNoParameters(input);
  return results.filter((result): boolean => {
    if (!TOKEN.test(result.range)) {
      handleInvalidValue(`Invalid Accept-Encoding range: ${result.range} does not match (charset / "*")`, strict);
      return false;
    }
    return true;
  });
}

/**
 * Parses an Accept-Language header string.
 *
 * @param input - The Accept-Language header string.
 * @param strict - Determines if invalid values throw errors (`true`) or log warnings (`false`). Defaults to `false`.
 *
 * @returns An array of {@link AcceptLanguage} objects, sorted by weight. Invalid ranges
 * are ignored and not returned.
 */
export function parseAcceptLanguage(input: string, strict = false): AcceptLanguage[] {
  const results = parseNoParameters(input);
  return results.filter((result): boolean => {
    // (1*8ALPHA *("-" 1*8alphanum)) / "*"
    if (result.range !== '*' && !/^[a-zA-Z]{1,8}(?:-[a-zA-Z0-9]{1,8})*$/u.test(result.range)) {
      handleInvalidValue(
        `Invalid Accept-Language range: ${result.range} does not match ((1*8ALPHA *("-" 1*8alphanum)) / "*")`,
        strict,
      );
      return false;
    }
    return true;
  });
}

// eslint-disable-next-line max-len
const rfc1123Date = /^(?:Mon|Tue|Wed|Thu|Fri|Sat|Sun), \d{2} (?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec) \d{4} \d{2}:\d{2}:\d{2} GMT$/u;

/**
 * Parses an Accept-DateTime header string.
 *
 * @param input - The Accept-DateTime header string.
 * @param strict - Determines if invalid values throw errors (`true`) or log warnings (`false`). Defaults to `false`.
 *
 * @returns An array with a single {@link AcceptDatetime} object,
 * or an empty array if a range in an invalid format is detected.
 */
export function parseAcceptDateTime(input: string, strict = false): AcceptDatetime[] {
  const range = input.trim();
  if (!range) {
    return [];
  }
  if (!rfc1123Date.test(range)) {
    handleInvalidValue(`Invalid Accept-DateTime range: ${range} does not match the RFC1123 format`, strict);
    return [];
  }
  return [{ range, weight: 1 }];
}

/**
 * Adds a header value without overriding previous values.
 */
export function addHeader(response: HttpResponse, name: string, value: string | string[]): void {
  let allValues: string[] = [];
  if (response.hasHeader(name)) {
    let oldValues = response.getHeader(name)!;
    if (typeof oldValues === 'string') {
      oldValues = [ oldValues ];
    } else if (typeof oldValues === 'number') {
      oldValues = [ `${oldValues}` ];
    }
    allValues = oldValues;
  }
  if (Array.isArray(value)) {
    allValues.push(...value);
  } else {
    allValues.push(value);
  }
  response.setHeader(name, allValues.length === 1 ? allValues[0] : allValues);
}

/**
 * Parses the Content-Type header and also parses any parameters in the header.
 *
 * @param input - The Content-Type header string.
 *
 * @returns A {@link ContentType} object containing the value and optional parameters.
 *
 * @throws BadRequestHttpError
 * Thrown on invalid header syntax.
 */
export function parseContentType(input: string): ContentType {
  // Quoted strings could prevent split from having correct results
  const { result, replacements } = transformQuotedStrings(input);
  const [ value, ...params ] = result.split(';').map((str): string => str.trim());
  if (!SIMPLE_MEDIA_RANGE.test(value)) {
    logger.warn(`Invalid content-type: ${value}`);
    throw new BadRequestHttpError(`Invalid content-type: ${value} does not match ( token "/" token )`);
  }

  const contentType = new ContentType(value);
  for (const param of parseParameters(params, replacements)) {
    contentType.parameters[param.name] = param.value;
  }
  return contentType;
}

/**
 * The Forwarded header from RFC7239
 */
export interface Forwarded {
  /** The user-agent facing interface of the proxy */
  by?: string;
  /** The node making the request to the proxy */
  for?: string;
  /** The host request header field as received by the proxy */
  host?: string;
  /** The protocol used to make the request */
  proto?: string;
}

/**
 * Parses a Forwarded header value and will fall back to X-Forwarded-* headers.
 *
 * @param headers - The incoming HTTP headers.
 *
 * @returns The parsed Forwarded header.
 */
export function parseForwarded(headers: IncomingHttpHeaders): Forwarded {
  const forwarded: Record<string, string> = {};
  if (headers.forwarded) {
    for (const pair of headers.forwarded.replace(/\s*,.*/u, '').split(';')) {
      const components = /^(by|for|host|proto)=(.+)$/u.exec(pair);
      if (components) {
        forwarded[components[1]] = components[2];
      }
    }
  } else {
    const suffixes = [ 'host', 'proto' ];
    for (const suffix of suffixes) {
      const value = headers[`x-forwarded-${suffix}`] as string;
      if (value) {
        forwarded[suffix] = value.trim().replace(/\s*,.*/u, '');
      }
    }
  }
  return forwarded;
}

/**
 * Parses the link header(s) and returns an array of LinkEntry objects.
 *
 * @param link - A single link header or an array of link headers
 *
 * @returns A LinkEntry array, LinkEntry contains a link and a params Record&lt;string,string&gt;
 */
export function parseLinkHeader(link: string | string[] = []): LinkEntry[] {
  const linkHeaders = Array.isArray(link) ? link : [ link ];
  const links: LinkEntry[] = [];
  for (const entry of linkHeaders) {
    const { result, replacements } = transformQuotedStrings(entry);
    for (const part of splitAndClean(result)) {
      const [ target, ...parameters ] = part.split(/\s*;\s*/u);
      if (/^[^<]|[^>]$/u.test(target)) {
        logger.warn(`Invalid link header ${part}.`);
        continue;
      }

      // RFC 8288 - Web Linking (https://datatracker.ietf.org/doc/html/rfc8288)
      //
      //     The rel parameter MUST be
      //     present but MUST NOT appear more than once in a given link-value;
      //     occurrences after the first MUST be ignored by parsers.
      //
      const params: Record<string, string> = {};
      for (const { name, value } of parseParameters(parameters, replacements)) {
        if (name === 'rel' && 'rel' in params) {
          continue;
        }
        params[name] = value;
      }

      if (!('rel' in params)) {
        logger.warn(`Invalid link header ${part} contains no 'rel' parameter.`);
        continue;
      }

      links.push({ target: target.slice(1, -1), parameters: params as LinkEntryParameters });
    }
  }
  return links;
}

// Map used as a simple cache in the helper function matchesAuthorizationScheme.
const authSchemeRegexCache = new Map<string, RegExp>();
/**
 * Checks if the value of an HTTP Authorization header matches a specific scheme (e.g. Basic, Bearer, etc).
 *
 * @param scheme - Name of the authorization scheme (case insensitive).
 * @param authorization - The value of the Authorization header (may be undefined).
 *
 * @returns True if the Authorization header uses the specified scheme, false otherwise.
 */
export function matchesAuthorizationScheme(scheme: string, authorization?: string): boolean {
  const lowerCaseScheme = scheme.toLowerCase();
  if (!authSchemeRegexCache.has(lowerCaseScheme)) {
    authSchemeRegexCache.set(lowerCaseScheme, new RegExp(`^${escapeStringRegexp(lowerCaseScheme)} `, 'iu'));
  }
  // Support authorization being undefined (for the sake of usability).
  return typeof authorization !== 'undefined' && authSchemeRegexCache.get(lowerCaseScheme)!.test(authorization);
}

/**
 * Checks if the scheme part of the specified url matches at least one of the provided options.
 *
 * @param url - A string representing the URL.
 * @param schemes - Scheme value options (the function will check whether at least one matches the URL scheme).
 *
 * @returns True if the URL scheme matches at least one of the provided options, false otherwise.
 */
export function hasScheme(url: string, ...schemes: string[]): boolean {
  const schemeOptions = new Set(schemes.map((item): string => item.toLowerCase()));
  const urlSchemeResult = /^(.+?):\/\//u.exec(url);
  return urlSchemeResult ? schemeOptions.has(urlSchemeResult[1].toLowerCase()) : false;
}

import type { ResourceIdentifier } from '../../http/representation/ResourceIdentifier';
import { errorTermsToMetadata } from '../errors/HttpErrorUtil';
import { InternalServerError } from '../errors/InternalServerError';
import { isContainerIdentifier } from '../PathUtil';
import type { IdentifierStrategy } from './IdentifierStrategy';

/**
 * Regular expression used to determine the parent container of a resource.
 */
const parentRegex = /^(.+\/)[^/]+\/*$/u;

/**
 * Used during containment check to determine if an identifier is a direct child or not.
 */
const tailRegex = /\/./u;

/**
 * Provides a default implementation for `getParentContainer`
 * which checks if the identifier is supported and not a root container.
 * If not, the last part before the first relevant slash will be removed to find the parent.
 *
 * Provides a default implementation for `contains`
 * which does standard slash-semantics based string comparison.
 */
export abstract class BaseIdentifierStrategy implements IdentifierStrategy {
  public abstract supportsIdentifier(identifier: ResourceIdentifier): boolean;

  public getParentContainer(identifier: ResourceIdentifier): ResourceIdentifier {
    if (!this.supportsIdentifier(identifier)) {
      throw new InternalServerError(
        `The identifier ${identifier.path} is outside the configured identifier space.`,
        { errorCode: 'E0001', metadata: errorTermsToMetadata({ path: identifier.path }) },
      );
    }
    if (this.isRootContainer(identifier)) {
      throw new InternalServerError(`Cannot obtain the parent of ${identifier.path} because it is a root container.`);
    }

    // Due to the checks above we know this will always succeed
    const match = parentRegex.exec(identifier.path);
    return { path: match![1] };
  }

  public abstract isRootContainer(identifier: ResourceIdentifier): boolean;

  public contains(container: ResourceIdentifier, identifier: ResourceIdentifier, transitive: boolean): boolean {
    if (!isContainerIdentifier(container)) {
      return false;
    }

    if (!identifier.path.startsWith(container.path)) {
      return false;
    }

    if (transitive) {
      return true;
    }

    const tail = identifier.path.slice(container.path.length);
    // If there is at least one `/` followed by a char this is not a direct parent container
    return !tailRegex.test(tail);
  }
}

import type { ResourceIdentifier } from '../../http/representation/ResourceIdentifier';

/**
 * Captures the behavior of container identifiers in a certain storage configuration.
 */
export interface IdentifierStrategy {
  /**
   * Verifies if this identifier is supported.
   * This does not check if this identifier actually exists,
   * but checks if the identifier is in scope for this class.
   */
  supportsIdentifier: (identifier: ResourceIdentifier) => boolean;

  /**
   * Generates the identifier of the container this resource would be a member of.
   * This does not check if that identifier actually exists.
   * Will throw an error if the input identifier is a root container or is not supported.
   */
  getParentContainer: (identifier: ResourceIdentifier) => ResourceIdentifier;

  /**
   * Checks if the input corresponds to the identifier of a root container.
   * This does not check if this identifier actually exists.
   */
  isRootContainer: (identifier: ResourceIdentifier) => boolean;

  /**
   * Checks if the given container would contain the given identifier.
   * This does not check that either of these identifiers actually exist.
   * This is similar to calling {@link getParentContainer} on an identifier
   * and comparing the result.
   *
   * If `transitive` is `false` this only checks if `container` is the direct parent container of `identifier`.
   */
  contains: (container: ResourceIdentifier, identifier: ResourceIdentifier, transitive: boolean) => boolean;
}

import type { ResourceIdentifier } from '../../http/representation/ResourceIdentifier';
import { getLoggerFor } from '../../logging/LogUtil';
import { ensureTrailingSlash } from '../PathUtil';
import { BaseIdentifierStrategy } from './BaseIdentifierStrategy';

/**
 * An IdentifierStrategy that assumes there is only 1 root and all other identifiers are made by appending to that root.
 */
export class SingleRootIdentifierStrategy extends BaseIdentifierStrategy {
  private readonly baseUrl: string;
  protected readonly logger = getLoggerFor(this);

  public constructor(baseUrl: string) {
    super();
    this.baseUrl = ensureTrailingSlash(baseUrl);
  }

  public supportsIdentifier(identifier: ResourceIdentifier): boolean {
    const supported = identifier.path.startsWith(this.baseUrl);
    this.logger.debug(supported ?
      `Identifier ${identifier.path} is part of ${this.baseUrl}` :
      `Identifier ${identifier.path} is not part of ${this.baseUrl}`);
    return supported;
  }

  public isRootContainer(identifier: ResourceIdentifier): boolean {
    return identifier.path === this.baseUrl;
  }
}

import type { ResourceIdentifier } from '../../http/representation/ResourceIdentifier';
import { getLoggerFor } from '../../logging/LogUtil';
import { createSubdomainRegexp, ensureTrailingSlash } from '../PathUtil';
import { BaseIdentifierStrategy } from './BaseIdentifierStrategy';

/**
 * An IdentifierStrategy that interprets all subdomains of the given base URL as roots.
 */
export class SubdomainIdentifierStrategy extends BaseIdentifierStrategy {
  private readonly baseUrl: string;
  private readonly regex: RegExp;
  protected readonly logger = getLoggerFor(this);

  public constructor(baseUrl: string) {
    super();
    this.baseUrl = ensureTrailingSlash(baseUrl);
    this.regex = createSubdomainRegexp(this.baseUrl);
  }

  public supportsIdentifier(identifier: ResourceIdentifier): boolean {
    const supported = this.regex.test(identifier.path);
    this.logger.debug(supported ?
      `Identifier ${identifier.path} is part of ${this.baseUrl}` :
      `Identifier ${identifier.path} is not part of ${this.baseUrl}`);
    return supported;
  }

  public isRootContainer(identifier: ResourceIdentifier): boolean {
    const match = this.regex.exec(identifier.path);
    return Array.isArray(match) && match[0].length === identifier.path.length;
  }
}

// Utility functions for iterables that avoid array conversion

/**
 * Creates a new iterable with the results of calling a provided function on every element in the calling array.
 * Similar to the {@link Array.prototype.map} function.
 * See the documentation of the above function for more details.
 *
 * @param iterable - Iterable on which to call the map function.
 * @param callbackFn - Function that is called for every element.
 * @param thisArg - Value to use as `this` when executing `callbackFn`.
 */
export function* map<TIn, TOut>(
  iterable: Iterable<TIn>,
  callbackFn: (element: TIn, index: number) => TOut,
  thisArg?: unknown,
): Iterable<TOut> {
  const boundMapFn = callbackFn.bind(thisArg);
  let count = 0;
  for (const value of iterable) {
    yield boundMapFn(value, count);
    count += 1;
  }
}

/**
 * Creates a new iterable with all elements that pass the test implemented by the provided function.
 * Similar to the {@link Array.prototype.filter} function.
 * See the documentation of the above function for more details.
 *
 * @param iterable - Iterable on which to call the map function.
 * @param callbackFn - Function that is called to test every element.
 * @param thisArg - Value to use as `this` when executing `callbackFn`.
 */
export function* filter<T>(
  iterable: Iterable<T>,
  callbackFn: (element: T, index: number) => boolean,
  thisArg?: unknown,
): Iterable<T> {
  const boundFilterFn = callbackFn.bind(thisArg);
  let count = 0;
  for (const value of iterable) {
    if (boundFilterFn(value, count)) {
      yield value;
    }
    count += 1;
  }
}

/**
 * Creates a new iterable that is a concatenation of all the iterables in the input.
 *
 * @param iterables - An iterable of which the contents will be concatenated into a new iterable.
 */
export function* concat<T>(iterables: Iterable<Iterable<T>>): Iterable<T> {
  for (const iterable of iterables) {
    yield* iterable;
  }
}

/**
 * Returns the first element in the provided iterable that satisfies the provided testing function.
 * If no values satisfy the testing function, `undefined` is returned.
 * Similar to the {@link Array.prototype.find} function.
 * See the documentation of the above function for more details.
 *
 * @param iterable - Iterable on which to call the map function.
 * @param callbackFn - Function that is called to test every element.
 * @param thisArg - Value to use as `this` when executing `callbackFn`.
 */
export function find<T>(iterable: Iterable<T>, callbackFn: (element: T, index: number) => boolean, thisArg?: unknown):
T | undefined {
  const boundMapFn = callbackFn.bind(thisArg);
  const count = 0;
  for (const value of iterable) {
    if (boundMapFn(value, count)) {
      return value;
    }
  }
}

/**
 * Similar to the {@link Array.prototype.reduce} function, but for an iterable.
 * See the documentation of the above function for more details.
 * The first element will be used as the initial value.
 *
 * @param iterable - Iterable of which to reduce the elements.
 * @param callbackFn - A reducer function.
 */
export function reduce<TIn>(iterable: Iterable<TIn>,
  callbackFn: (previousValue: TIn, currentValue: TIn, currentIndex: number) => TIn): TIn;
/**
 * Similar to the {@link Array.prototype.reduce} function, but for an iterable.
 * See the documentation of the above function for more details.
 *
 * @param iterable - Iterable of which to reduce the elements.
 * @param callbackFn - A reducer function.
 * @param initialValue - The value to start from.
 */
export function reduce<TIn, TOut>(
  iterable: Iterable<TIn>,
  callbackFn: (previousValue: TOut, currentValue: TIn, currentIndex: number) => TOut, initialValue: TOut
): TOut;
export function reduce<TIn, TOut>(
  iterable: Iterable<TIn>,
  callbackFn: (previousValue: TOut, currentValue: TIn, currentIndex: number) => TOut,
  initialValue?: TOut,
): TOut {
  const iterator = iterable[Symbol.iterator]();
  let count = 0;
  if (!initialValue) {
    const next = iterator.next();
    if (next.done) {
      throw new TypeError('Iterable is empty and no initial value was provided.');
    }
    // `initialValue` being undefined means the first signature was used where TIn === TOut
    initialValue = next.value as unknown as TOut;
    count += 1;
  }
  let previousValue = initialValue;
  let next = iterator.next();
  while (!next.done) {
    previousValue = callbackFn(previousValue, next.value, count);
    next = iterator.next();
    count += 1;
  }
  return previousValue;
}

/**
 * Helper function for {@link sortedAsyncMerge}.
 *
 * Returns the next result of an AsyncIterator, or undefined if the iterator is finished.
 */
async function nextAsyncEntry<T>(iterator: AsyncIterator<T>): Promise<T | undefined> {
  const result = await iterator.next();
  if (result.done) {
    return;
  }
  return result.value;
}

/**
 * Helper function for {@link sortedAsyncMerge}.
 *
 * Compares the next results of all `iterators` and returns the first one,
 * determined by the provided `comparator`.
 *
 * `results` should contain the first result of all these iterators.
 * This array will also be updated, replacing the result of the iterator whose result was chosen by the next one.
 */
async function findNextSorted<T>(
  iterators: AsyncIterator<T>[],
  results: (T | undefined)[],
  comparator: (left: T, right: T) => number,
): Promise<T | undefined> {
  let best: { idx: number; value: T } | undefined;
  // For every iterator: see if their next result is the best one so far
  for (let i = 0; i < iterators.length; ++i) {
    const value = results[i];
    if (typeof value !== 'undefined') {
      let compare = 1;
      if (best) {
        compare = comparator(best.value, value);
      }

      if (compare > 0) {
        best = { idx: i, value };
      }
    }
  }

  if (best) {
    // Advance the iterator that returned the new result
    results[best.idx] = await nextAsyncEntry(iterators[best.idx]);
  }

  // Will return undefined if `best` was never initialized above
  return best?.value;
}

/**
 * Merges the results of several sorted iterators.
 * In case the results of the individual iterators are not sorted the outcome results will also not be sorted.
 *
 * @param iterators - The iterators whose results need to be merged.
 * @param comparator - The comparator to use to compare the results.
 */
export async function* sortedAsyncMerge<T>(iterators: AsyncIterator<T>[], comparator?: (left: T, right: T) => number):
AsyncIterable<T> {
  if (!comparator) {
    comparator = (left, right): number => {
      if (left < right) {
        return -1;
      }
      return left > right ? 1 : 0;
    };
  }

  // Initialize the array to the first result of every iterator
  const results: (T | undefined)[] = [];
  for (const iterator of iterators) {
    results.push(await nextAsyncEntry(iterator));
  }

  // Keep returning results as long as we find them
  while (true) {
    const next = await findNextSorted(iterators, results, comparator);
    if (typeof next === 'undefined') {
      return;
    }
    yield next;
  }
}

/**
 * Converts an `AsyncIterator` to an array.
 */
export async function asyncToArray<T>(iterable: AsyncIterable<T>): Promise<T[]> {
  const arr: T[] = [];
  for await (const result of iterable) {
    arr.push(result);
  }
  return arr;
}

/**
 * A JSON object.
 */
export type Json = string | number | boolean | NodeJS.Dict<Json> | Json[];

import type { ResourceIdentifier } from '../../http/representation/ResourceIdentifier';
import type { PromiseOrValue } from '../PromiseUtil';
import { EqualReadWriteLocker } from './EqualReadWriteLocker';
import type { ResourceLocker } from './ResourceLocker';

/**
 * A {@link ReadWriteLocker} that allows for multiple simultaneous read operations.
 * Write operations will be blocked as long as read operations are not finished.
 * New read operations are allowed while this is going on, which will cause write operations to wait longer.
 *
 * Based on https://en.wikipedia.org/wiki/Readers%E2%80%93writer_lock#Using_two_mutexes .
 * As soon as 1 read lock request is made, the main lock is locked.
 * Internally a counter keeps track of the amount of active read locks.
 * Only when this number reaches 0 will the main lock be released again.
 * The internal count lock is only locked to increase/decrease this counter and is released afterwards.
 * This allows for multiple read operations, although only 1 at the time can update the counter,
 * which means there can still be a small waiting period if there are multiple simultaneous read operations.
 *
 * Classes extending this need to implement `getCountLockIdentifier` and `modifyCount`.
 */
export abstract class BaseReadWriteLocker extends EqualReadWriteLocker {
  protected readonly countLocker: ResourceLocker;

  /**
   * @param resourceLocker - Used for creating read and write locks.
   * @param countLocker - Used for creating locks when updating the counter.
   */
  protected constructor(resourceLocker: ResourceLocker, countLocker: ResourceLocker) {
    super(resourceLocker);
    this.countLocker = countLocker;
  }

  public async withReadLock<T>(identifier: ResourceIdentifier, whileLocked: () => PromiseOrValue<T>): Promise<T> {
    await this.acquireReadLock(identifier);
    try {
      return await whileLocked();
    } finally {
      await this.releaseReadLock(identifier);
    }
  }

  /**
   * Safely updates the count before starting a read operation.
   */
  private async acquireReadLock(identifier: ResourceIdentifier): Promise<void> {
    await this.withInternalCountLock(identifier, async(): Promise<void> => {
      const count = await this.modifyCount(identifier, 1);
      if (count === 1) {
        await this.locker.acquire(identifier);
      }
    });
  }

  /**
   * Safely decreases the count after the read operation is finished.
   */
  private async releaseReadLock(identifier: ResourceIdentifier): Promise<void> {
    await this.withInternalCountLock(identifier, async(): Promise<void> => {
      const count = await this.modifyCount(identifier, -1);
      if (count === 0) {
        await this.locker.release(identifier);
      }
    });
  }

  /**
   * Safely runs an action on the count.
   */
  private async withInternalCountLock<T>(identifier: ResourceIdentifier, whileLocked: () => PromiseOrValue<T>):
  Promise<T> {
    const read = this.getCountLockIdentifier(identifier);
    await this.countLocker.acquire(read);
    try {
      return await whileLocked();
    } finally {
      await this.countLocker.release(read);
    }
  }

  /**
   * Generate the identifier that will be used to acquire the count lock for the given identifier.
   * There will be cases where this lock needs to be acquired
   * while an active lock on the main resource is still being maintained.
   * This means that if the input `resourceLocker` and `countLocker` use the same locking system
   * this generated identifier needs to be different.
   */
  protected abstract getCountLockIdentifier(identifier: ResourceIdentifier): ResourceIdentifier;

  /**
   * Update the counter that keeps track of having open read locks there currently are.
   *
   * @param identifier - Identifier on which to update the number of read locks.
   * @param mod - `+1` or `-1`.
   */
  protected abstract modifyCount(identifier: ResourceIdentifier, mod: number): PromiseOrValue<number>;
}

import type { ResourceIdentifier } from '../../http/representation/ResourceIdentifier';
import type { PromiseOrValue } from '../PromiseUtil';
import type { ReadWriteLocker } from './ReadWriteLocker';
import type { ResourceLocker } from './ResourceLocker';

/**
 * A {@link ReadWriteLocker} that gives no priority to read or write operations: both use the same lock.
 */
export class EqualReadWriteLocker implements ReadWriteLocker {
  protected readonly locker: ResourceLocker;

  public constructor(locker: ResourceLocker) {
    this.locker = locker;
  }

  public async withReadLock<T>(identifier: ResourceIdentifier, whileLocked: () => PromiseOrValue<T>): Promise<T> {
    return this.withLock(identifier, whileLocked);
  }

  public async withWriteLock<T>(identifier: ResourceIdentifier, whileLocked: () => PromiseOrValue<T>): Promise<T> {
    return this.withLock(identifier, whileLocked);
  }

  /**
   * Acquires a new lock for the requested identifier.
   * Will resolve when the input function resolves.
   *
   * @param identifier - Identifier of resource that needs to be locked.
   * @param whileLocked - Function to resolve while the resource is locked.
   */
  protected async withLock<T>(identifier: ResourceIdentifier, whileLocked: () => PromiseOrValue<T>): Promise<T> {
    await this.locker.acquire(identifier);
    try {
      return await whileLocked();
    } finally {
      await this.locker.release(identifier);
    }
  }
}

import type { ResourceIdentifier } from '../../http/representation/ResourceIdentifier';
import type { PromiseOrValue } from '../PromiseUtil';
import type { ReadWriteLocker } from './ReadWriteLocker';

/**
 * A {@link ReadWriteLocker} where the locks expire after a given time.
 */
export interface ExpiringReadWriteLocker extends ReadWriteLocker {
  /**
   * As {@link ReadWriteLocker.withReadLock} but the locked function gets called with a `maintainLock` callback function
   * to reset the lock expiration every time it is called.
   * The resulting promise will reject once the lock expires.
   *
   * @param identifier - Identifier of the resource that needs to be locked.
   * @param whileLocked - A function to execute while the resource is locked.
   * Receives a callback as input parameter to maintain the lock.
   */
  withReadLock: <T>(identifier: ResourceIdentifier, whileLocked: (maintainLock: () => void) => PromiseOrValue<T>)
  => Promise<T>;

  /**
   * As {@link ReadWriteLocker.withWriteLock} but the locked function gets called with a `maintainLock`
   * callback function to reset the lock expiration every time it is called.
   * The resulting promise will reject once the lock expires.
   *
   * @param identifier - Identifier of the resource that needs to be locked.
   * @param whileLocked - A function to execute while the resource is locked.
   * Receives a callback as input parameter to maintain the lock.
   */
  withWriteLock: <T>(identifier: ResourceIdentifier, whileLocked: (maintainLock: () => void) => PromiseOrValue<T>)
  => Promise<T>;
}

import { createHash } from 'node:crypto';
import { ensureDir, remove } from 'fs-extra';
import type { LockOptions, UnlockOptions } from 'proper-lockfile';
import { lock, unlock } from 'proper-lockfile';
import type { ResourceIdentifier } from '../../http/representation/ResourceIdentifier';
import type { Finalizable } from '../../init/final/Finalizable';
import type { Initializable } from '../../init/Initializable';
import { getLoggerFor } from '../../logging/LogUtil';
import { createErrorMessage } from '../errors/ErrorUtil';
import { InternalServerError } from '../errors/InternalServerError';
import type { AttemptSettings } from '../LockUtils';
import { retryFunction } from '../LockUtils';
import { joinFilePath } from '../PathUtil';
import type { ResourceLocker } from './ResourceLocker';

const defaultLockOptions: LockOptions = {
  // This must be set to false! If not every lock request will try to resolve the path to the file.
  // Since however this locker maps all locks to a common internal folder that might be non-existing on start,
  // resolving those paths would throw an filesystem error.
  realpath: false,
  /** The number of retries or a [retry](https://www.npmjs.org/package/retry) options object, defaults to 0 */
  retries: 0,
};

const defaultUnlockOptions: UnlockOptions = {
  // This must be set to false! If not every lock request will try to resolve the path to the file.
  // Since however this locker maps all locks to a common internal folder that might be non-existing on start,
  // resolving those paths would throw an filesystem error.
  realpath: false,
};

const attemptDefaults: Required<AttemptSettings> = { retryCount: -1, retryDelay: 50, retryJitter: 30 };

/**
 * Argument interface of the FileSystemResourceLocker constructor.
 */
interface FileSystemResourceLockerArgs {
  /** The root filepath of where the server is allowed to write files */
  rootFilePath: string;
  /**
   * The path to the directory where locks will be stored (relative to rootFilePath)
   * _[default is `/.internal/locks`]_
   */
  lockDirectory?: string;
  /** Custom settings concerning retrying locks */
  attemptSettings?: AttemptSettings;
  /**
   * Throws an error when a lock is compromised, instead of logging an error.
   */
  throwOnCompromise?: boolean;
}

function isCodedError(err: unknown): err is { code: string } & Error {
  return typeof err === 'object' && err !== null && 'code' in err;
}

/**
 * A resource locker making use of the [proper-lockfile](https://www.npmjs.com/package/proper-lockfile) library.
 * Note that no locks are kept in memory, thus this is considered thread- and process-safe.
 * While it stores the actual locks on disk, it also tracks them in memory for when they need to be released.
 * This means only the worker thread that acquired a lock can release it again,
 * making this implementation unusable in combination with a wrapping read/write lock implementation.
 *
 * This **proper-lockfile** library has its own retry mechanism for the operations, since a lock/unlock call will
 * either resolve successfully or reject immediately with the causing error. The retry function of the library
 * however will be ignored and replaced by our own LockUtils' {@link retryFunction} function.
 */
export class FileSystemResourceLocker implements ResourceLocker, Initializable, Finalizable {
  protected readonly logger = getLoggerFor(this);
  private readonly attemptSettings: Required<AttemptSettings>;
  private readonly lockOptions: LockOptions;
  private readonly throwOnCompromise?: boolean;
  /** Folder that stores the locks */
  private readonly lockFolder: string;
  private finalized = false;

  /**
   * Create a new FileSystemResourceLocker
   *
   * @param args - Configures the locker using the specified FileSystemResourceLockerArgs instance.
   */
  public constructor(args: FileSystemResourceLockerArgs) {
    const { rootFilePath, lockDirectory, attemptSettings } = args;
    // Need to create lock options for this instance due to the custom `onCompromised`
    this.lockOptions = { ...defaultLockOptions, onCompromised: this.customOnCompromised.bind(this) };
    this.attemptSettings = { ...attemptDefaults, ...attemptSettings };
    this.throwOnCompromise = args.throwOnCompromise;
    this.lockFolder = joinFilePath(rootFilePath, lockDirectory ?? '/.internal/locks');
  }

  /**
   * Wrapper function for all (un)lock operations. Any errors coming from the `fn()` will be swallowed.
   * Only `ENOTACQUIRED` errors wills be thrown (trying to release lock that didn't exist).
   * This wrapper returns undefined because {@link retryFunction} expects that when a retry needs to happen.
   *
   * @param fn - The function reference to swallow errors from.
   *
   * @returns Boolean or undefined.
   */
  private swallowErrors(fn: () => Promise<unknown>): () => Promise<unknown> {
    return async(): Promise<unknown> => {
      try {
        await fn();
        return true;
      } catch (err: unknown) {
        // Only this error should be thrown
        if (isCodedError(err) && err.code === 'ENOTACQUIRED') {
          throw err;
        }
      }
    };
  }

  public async acquire(identifier: ResourceIdentifier): Promise<void> {
    const { path } = identifier;
    this.logger.debug(`Acquiring lock for ${path}`);
    try {
      const opt = this.generateOptions(identifier, this.lockOptions);
      await retryFunction(
        this.swallowErrors(lock.bind(null, path, opt)),
        this.attemptSettings,
      );
    } catch (err: unknown) {
      throw new InternalServerError(
        `Error trying to acquire lock for ${path}. ${createErrorMessage(err)}`,
        { cause: err },
      );
    }
  }

  public async release(identifier: ResourceIdentifier): Promise<void> {
    const { path } = identifier;
    this.logger.debug(`Releasing lock for ${path}`);
    try {
      const opt = this.generateOptions(identifier, defaultUnlockOptions);
      await retryFunction(
        this.swallowErrors(unlock.bind(null, path, opt)),
        this.attemptSettings,
      );
    } catch (err: unknown) {
      throw new InternalServerError(
        `Error trying to release lock for ${path}.  ${createErrorMessage(err)}`,
        { cause: err },
      );
    }
  }

  /**
   * Map the identifier path to a unique path inside the {@link lockFolder}.
   *
   * @param identifier - ResourceIdentifier to generate (Un)LockOptions for.
   *
   * @returns Full path.
   */
  private toLockfilePath(identifier: ResourceIdentifier): string {
    const hash = createHash('md5');
    const { path } = identifier;
    return joinFilePath(this.lockFolder, hash.update(path).digest('hex'));
  }

  /**
   * Generate LockOptions or UnlockOptions depending on the type of defauls given.
   * A custom lockFilePath mapping strategy will be used.
   *
   * @param identifier - ResourceIdentifier to generate (Un)LockOptions for
   * @param defaults - The default options. (lockFilePath will get overwritten)
   *
   * @returns LockOptions or UnlockOptions
   */
  private generateOptions<T>(identifier: ResourceIdentifier, defaults: T): T {
    const lockfilePath = this.toLockfilePath(identifier);
    return {
      ...defaults,
      lockfilePath,
    };
  }

  /**
   * Initializer method to be executed on server start. This makes sure that no pre-existing (dangling) locks
   * remain on disk, so that request will not be blocked because a lock was acquired in the previous server instance.
   *
   * NOTE: this also removes locks created by the GreedyReadWriteLocker.
   * (See issue: https://github.com/CommunitySolidServer/CommunitySolidServer/issues/1358)
   */
  public async initialize(): Promise<void> {
    // Remove all existing (dangling) locks so new requests are not blocked (by removing the lock folder).
    await remove(this.lockFolder);
    // Put the folder back since `proper-lockfile` depends on its existence.
    return ensureDir(this.lockFolder);
  }

  public async finalize(): Promise<void> {
    // Register that finalize was called by setting a state variable.
    this.finalized = true;
    // NOTE: in contrast with initialize(), the lock folder is not cleared here, as the proper-lock library
    // manages these files and will attempt to clear existing files when the process is shutdown gracefully.
  }

  /**
   * This function is used to override the proper-lock onCompromised function.
   * Once the locker was finalized, it will log the provided error instead of throwing it
   * This allows for a clean shutdown procedure.
   */
  private customOnCompromised(err: Error): void {
    if (this.finalized) {
      this.logger.warn(`onCompromised was called with error: ${err.message}`);
    } else if (this.throwOnCompromise) {
      throw err;
    } else {
      this.logger.error(`Lock was compromised: ${err.message}`);
    }
  }
}

import type { ResourceIdentifier } from '../../http/representation/ResourceIdentifier';
import type { KeyValueStorage } from '../../storage/keyvalue/KeyValueStorage';
import { InternalServerError } from '../errors/InternalServerError';
import { BaseReadWriteLocker } from './BaseReadWriteLocker';
import type { ResourceLocker } from './ResourceLocker';

/**
 * A {@link BaseReadWriteLocker} that uses the same locker for the main lock and the count lock,
 * and uses a {@link KeyValueStorage} for keeping track of the counter.
 *
 * Since it is completely dependent on other implementations,
 * this locker is threadsafe if its inputs are as well.
 */
export class GreedyReadWriteLocker extends BaseReadWriteLocker {
  protected readonly storage: KeyValueStorage<string, number>;
  protected readonly readSuffix: string;
  protected readonly countSuffix: string;

  /**
   * @param locker - Used for creating read and write locks.
   * @param storage - Used for storing the amount of active read operations on a resource.
   * @param readSuffix - Used to generate the identifier for the lock that is applied when updating the counter.
   * @param countSuffix - Used to generate the identifier that will be used in the storage for storing the counter.
   */
  public constructor(
    locker: ResourceLocker,
    storage: KeyValueStorage<string, number>,
    readSuffix = 'read',
    countSuffix = 'count',
  ) {
    super(locker, locker);
    this.storage = storage;
    this.readSuffix = readSuffix;
    this.countSuffix = countSuffix;
  }

  protected getCountLockIdentifier(identifier: ResourceIdentifier): ResourceIdentifier {
    return { path: `${identifier.path}.${this.readSuffix}` };
  }

  /**
   * This key is used for storing the count of active read operations.
   */
  protected getCountKey(identifier: ResourceIdentifier): string {
    return `${identifier.path}.${this.countSuffix}`;
  }

  /**
   * Updates the count with the given modifier.
   * Creates the data if it didn't exist yet.
   * Deletes the data when the count reaches zero.
   */
  protected async modifyCount(identifier: ResourceIdentifier, mod: number): Promise<number> {
    const countKey = this.getCountKey(identifier);
    let number = await this.storage.get(countKey) ?? 0;
    number += mod;
    if (number === 0) {
      // Make sure there is no remaining data once all locks are released
      await this.storage.delete(countKey);
    } else if (number > 0) {
      await this.storage.set(countKey, number);
    } else {
      // Failsafe in case something goes wrong with the count storage
      throw new InternalServerError('Read counter would become negative. Something is wrong with the count storage.');
    }
    return number;
  }
}

import AsyncLock from 'async-lock';
import type { ResourceIdentifier } from '../../http/representation/ResourceIdentifier';
import type { SingleThreaded } from '../../init/cluster/SingleThreaded';
import { getLoggerFor } from '../../logging/LogUtil';
import { InternalServerError } from '../errors/InternalServerError';
import type { ResourceLocker } from './ResourceLocker';

/**
 * A resource locker making use of the `async-lock` library.
 * Note that all locks are kept in memory until they are unlocked which could potentially result
 * in a memory leak if locks are never unlocked, so make sure this is covered with expiring locks for example,
 * and/or proper `finally` handles.
 */
export class MemoryResourceLocker implements ResourceLocker, SingleThreaded {
  protected readonly logger = getLoggerFor(this);

  private readonly locker: AsyncLock;
  private readonly unlockCallbacks: Record<string, () => void>;

  public constructor() {
    this.locker = new AsyncLock();
    this.unlockCallbacks = {};
  }

  public async acquire(identifier: ResourceIdentifier): Promise<void> {
    const { path } = identifier;
    this.logger.debug(`Acquiring lock for ${path}`);
    return new Promise((resolve): void => {
      this.locker.acquire(path, (done): void => {
        this.unlockCallbacks[path] = done;
        this.logger.debug(`Acquired lock for ${path}. ${this.getLockCount()} locks active.`);
        resolve();
      }, (): void => {
        delete this.unlockCallbacks[path];
        this.logger.debug(`Released lock for ${path}. ${this.getLockCount()} active locks remaining.`);
      });
    });
  }

  public async release(identifier: ResourceIdentifier): Promise<void> {
    const { path } = identifier;
    if (!this.unlockCallbacks[path]) {
      throw new InternalServerError(`Trying to unlock resource that is not locked: ${path}`);
    }
    this.unlockCallbacks[path]();
  }

  /**
   * Counts the number of active locks.
   */
  private getLockCount(): number {
    return Object.keys(this.unlockCallbacks).length;
  }
}

import type { ResourceIdentifier } from '../../http/representation/ResourceIdentifier';
import { BaseReadWriteLocker } from './BaseReadWriteLocker';
import { MemoryResourceLocker } from './MemoryResourceLocker';
import type { ResourceLocker } from './ResourceLocker';

/**
 * A {@link BaseReadWriteLocker} that stores the counter and its associated locks in memory.
 * The consequence of this is that multiple read requests are possible as long as they occur on the same worker thread.
 * A read request from a different worker thread will have to wait
 * until those from the current worker thread are finished.
 *
 * The main reason for this class is due to the file locker that we use only allowing locks to be released
 * by the same worker thread that acquired them.
 */
export class PartialReadWriteLocker extends BaseReadWriteLocker {
  private readonly readCount: Map<string, number>;

  public constructor(locker: ResourceLocker) {
    // This goes against how we generally link classes together using Components.js.
    // The reason for doing this is that `MemoryResourceLocker` implements `SingleThreaded`,
    // meaning that when the server is started with worker threads an error will be thrown by Components.js.
    // Instantiating it here "hides" it from Components.js.
    // If at some point in the future this causes issues because we want to split up the code,
    // this should not be blocking and an alternative solution should be used,
    // such as removing the SingleThreaded interface from the locker.
    super(locker, new MemoryResourceLocker());
    this.readCount = new Map();
  }

  protected getCountLockIdentifier(identifier: ResourceIdentifier): ResourceIdentifier {
    return identifier;
  }

  protected modifyCount(identifier: ResourceIdentifier, mod: number): number {
    const modified = (this.readCount.get(identifier.path) ?? 0) + mod;
    if (modified === 0) {
      this.readCount.delete(identifier.path);
    } else {
      this.readCount.set(identifier.path, modified);
    }
    return modified;
  }
}

import type { ResourceIdentifier } from '../../http/representation/ResourceIdentifier';
import type { PromiseOrValue } from '../PromiseUtil';

/**
 * Allows the locking of resources which is needed for non-atomic {@link ResourceStore}s.
 */
export interface ReadWriteLocker {
  /**
   * Run the given function while the resource is locked.
   * The lock will be released when the (async) input function resolves.
   * This function should be used for operations that only require reading the resource.
   *
   * @param identifier - Identifier of the resource that needs to be locked.
   * @param whileLocked - A function to execute while the resource is locked.
   *
   * @returns A promise resolving when the lock is released.
   */
  withReadLock: <T>(identifier: ResourceIdentifier, whileLocked: () => PromiseOrValue<T>) => Promise<T>;

  /**
   * Run the given function while the resource is locked.
   * The lock will be released when the (async) input function resolves.
   * This function should be used for operations that could modify the resource.
   *
   * @param identifier - Identifier of the resource that needs to be locked.
   * @param whileLocked - A function to execute while the resource is locked.
   *
   * @returns A promise resolving when the lock is released.
   */
  withWriteLock: <T>(identifier: ResourceIdentifier, whileLocked: () => PromiseOrValue<T>) => Promise<T>;
}

import Redis from 'ioredis';
import type { ResourceIdentifier } from '../../http/representation/ResourceIdentifier';
import type { Finalizable } from '../../init/final/Finalizable';
import type { Initializable } from '../../init/Initializable';
import { getLoggerFor } from '../../logging/LogUtil';
import type { AttemptSettings } from '../LockUtils';
import { retryFunction } from '../LockUtils';
import type { PromiseOrValue } from '../PromiseUtil';
import type { ReadWriteLocker } from './ReadWriteLocker';
import type { ResourceLocker } from './ResourceLocker';
import type { RedisAnswer, RedisReadWriteLock, RedisResourceLock } from './scripts/RedisLuaScripts';
import { fromResp2ToBool, REDIS_LUA_SCRIPTS } from './scripts/RedisLuaScripts';

const attemptDefaults: Required<AttemptSettings> = { retryCount: -1, retryDelay: 50, retryJitter: 30 };

// Internal prefix for Redis keys;
const PREFIX_RW = '__RW__';
const PREFIX_LOCK = '__L__';

export interface RedisSettings {
  /* Override default namespacePrefixes (used to prefix keys in Redis) */
  namespacePrefix?: string;
  /* Username used for AUTH on the Redis server */
  username?: string;
  /* Password used for AUTH on the Redis server */
  password?: string;
  /* The number of the database to use */
  db?: number;
}

/**
 * A Redis Locker that can be used as both:
 *  *  a Read Write Locker that uses a (single) Redis server to store the locks and counts.
 *  *  a Resource Locker that uses a (single) Redis server to store the lock.
 * This solution should be process-safe. The only references to locks are string keys
 * derived from identifier paths.
 *
 * The Read Write algorithm roughly goes as follows:
 *  * Acquire a read lock: allowed as long as there is no write lock. On acquiring the read counter goes up.
 *  * Acquire a write lock: allowed as long as there is no other write lock AND the read counter is 0.
 *  * Release a read lock: decreases the read counter with 1
 *  * Release a write lock: unlocks the write lock
 *
 * The Resource locking algorithm uses a single mutex/lock.
 *
 * All operations, such as checking for a write lock AND read count, are executed in a single Lua script.
 * These scripts are used by Redis as a single new command.
 * Redis executes its operations in a single thread, as such, each such operation can be considered atomic.
 *
 * The operation to (un)lock will always resolve with either 1/OK/true if succeeded or 0/false if not succeeded.
 * Rejection with errors will be happen on actual failures. Retrying the (un)lock operations will be done by making
 * use of the LockUtils' {@link retryFunctionUntil} function.
 *
 * * @see [Redis Commands documentation](https://redis.io/commands/)
 * * @see [Redis Lua scripting documentation](https://redis.io/docs/manual/programmability/)
 * * @see [ioredis Lua scripting API](https://github.com/luin/ioredis#lua-scripting)
 */
export class RedisLocker implements ReadWriteLocker, ResourceLocker, Initializable, Finalizable {
  protected readonly logger = getLoggerFor(this);

  private readonly redis: Redis;
  private readonly redisRw: RedisReadWriteLock;
  private readonly redisLock: RedisResourceLock;
  private readonly attemptSettings: Required<AttemptSettings>;
  private readonly namespacePrefix: string;
  private finalized = false;

  /**
   * Creates a new RedisClient
   *
   * @param redisClient - Redis connection string of a standalone Redis node
   * @param attemptSettings - Override default AttemptSettings
   * @param redisSettings - Addition settings used to create the Redis client or to interact with the Redis server
   */
  public constructor(
    redisClient = '127.0.0.1:6379',
    attemptSettings: AttemptSettings = {},
    redisSettings?: RedisSettings,
  ) {
    redisSettings = { namespacePrefix: '', ...redisSettings };
    const { namespacePrefix, ...options } = redisSettings;
    this.redis = this.createRedisClient(redisClient, options);
    this.attemptSettings = { ...attemptDefaults, ...attemptSettings };
    this.namespacePrefix = namespacePrefix!;

    // Register lua scripts
    for (const [ name, script ] of Object.entries(REDIS_LUA_SCRIPTS)) {
      this.redis.defineCommand(name, { numberOfKeys: 1, lua: script });
    }

    this.redisRw = this.redis as RedisReadWriteLock;
    this.redisLock = this.redis as RedisResourceLock;
  }

  /**
   * Generate and return a RedisClient based on the provided string
   *
   * @param redisClientString - A string that contains either a host address and a
   *                            port number like '127.0.0.1:6379' or just a port number like '6379'.
   */
  private createRedisClient(redisClientString: string, options: Omit<RedisSettings, 'namespacePrefix'>): Redis {
    if (redisClientString.length > 0) {
      // Check if port number or ip with port number
      // Definitely not perfect, but configuring this is only for experienced users
      const match = /^(?:([^:]+):)?(\d{4,5})$/u.exec(redisClientString);
      if (!match?.[2]) {
        // At least a port number should be provided
        throw new Error(`Invalid data provided to create a Redis client: ${redisClientString}\n
            Please provide a port number like '6379' or a host address and a port number like '127.0.0.1:6379'`);
      }
      const port = Number(match[2]);
      const host = match[1];
      return new Redis(port, host, options);
    }
    throw new Error(`Empty redisClientString provided!\n
            Please provide a port number like '6379' or a host address and a port number like '127.0.0.1:6379'`);
  }

  /**
   * Create a scoped Redis key for Read-Write locking.
   *
   * @param identifier - The identifier object to create a Redis key for
   *
   * @returns A scoped Redis key that allows cleanup afterwards without affecting other keys.
   */
  private getReadWriteKey(identifier: ResourceIdentifier): string {
    return `${this.namespacePrefix}${PREFIX_RW}${identifier.path}`;
  }

  /**
   * Create a scoped Redis key for Resource locking.
   *
   * @param identifier - The identifier object to create a Redis key for
   *
   * @returns A scoped Redis key that allows cleanup afterwards without affecting other keys.
   */
  private getResourceKey(identifier: ResourceIdentifier): string {
    return `${this.namespacePrefix}${PREFIX_LOCK}${identifier.path}`;
  }

  /* ReadWriteLocker methods */

  /**
   * Wrapper function for all (un)lock operations. If the `fn()` resolves to false (after applying
   * {@link fromResp2ToBool}, the result will be swallowed. When `fn()` resolves to true, this wrapper
   * will return true. Any error coming from `fn()` will be thrown.
   *
   * @param fn - The function reference to swallow false from.
   */
  private swallowFalse(fn: () => Promise<RedisAnswer>): () => Promise<unknown> {
    if (this.finalized) {
      throw new Error('Invalid state: cannot execute Redis operation once finalize() has been called.');
    }
    return async(): Promise<unknown> => {
      const result = await fromResp2ToBool(fn());
      // Swallow any result resolving to `false`
      if (result) {
        return true;
      }
    };
  }

  public async withReadLock<T>(identifier: ResourceIdentifier, whileLocked: () => PromiseOrValue<T>): Promise<T> {
    const key = this.getReadWriteKey(identifier);
    await retryFunction(
      this.swallowFalse(this.redisRw.acquireReadLock.bind(this.redisRw, key)),
      this.attemptSettings,
    );
    try {
      return await whileLocked();
    } finally {
      await retryFunction(
        this.swallowFalse(this.redisRw.releaseReadLock.bind(this.redisRw, key)),
        this.attemptSettings,
      );
    }
  }

  public async withWriteLock<T>(identifier: ResourceIdentifier, whileLocked: () => PromiseOrValue<T>): Promise<T> {
    const key = this.getReadWriteKey(identifier);
    await retryFunction(
      this.swallowFalse(this.redisRw.acquireWriteLock.bind(this.redisRw, key)),
      this.attemptSettings,
    );
    try {
      return await whileLocked();
    } finally {
      await retryFunction(
        this.swallowFalse(this.redisRw.releaseWriteLock.bind(this.redisRw, key)),
        this.attemptSettings,
      );
    }
  }

  /* ResourceLocker methods */

  public async acquire(identifier: ResourceIdentifier): Promise<void> {
    const key = this.getResourceKey(identifier);
    await retryFunction(
      this.swallowFalse(this.redisLock.acquireLock.bind(this.redisLock, key)),
      this.attemptSettings,
    );
  }

  public async release(identifier: ResourceIdentifier): Promise<void> {
    const key = this.getResourceKey(identifier);
    await retryFunction(
      this.swallowFalse(this.redisLock.releaseLock.bind(this.redisLock, key)),
      this.attemptSettings,
    );
  }

  /* Initializer & Finalizer methods */

  public async initialize(): Promise<void> {
    // On server start: remove all existing (dangling) locks, so new requests are not blocked.
    return this.clearLocks();
  }

  public async finalize(): Promise<void> {
    this.finalized = true;
    try {
      // On controlled server shutdown: clean up all existing locks.
      await this.clearLocks();
    } finally {
      // Always quit the redis client
      await this.redis.quit();
    }
  }

  /**
   * Remove any lock still open
   */
  private async clearLocks(): Promise<void> {
    const keysRw = await this.redisRw.keys(`${this.namespacePrefix}${PREFIX_RW}*`);
    if (keysRw.length > 0) {
      await this.redisRw.del(...keysRw);
    }

    const keysLock = await this.redisLock.keys(`${this.namespacePrefix}${PREFIX_LOCK}*`);
    if (keysLock.length > 0) {
      await this.redisLock.del(...keysLock);
    }
  }
}

import type { ResourceIdentifier } from '../../http/representation/ResourceIdentifier';

/**
 * An interface for classes that only have 1 way to lock interfaces.
 * In general this should only be used by components implementing the {@link ReadWriteLocker} interface.
 * Other components that require locking of resources should use that interface.
 */
export interface ResourceLocker {
  /**
   * Acquires a lock on the requested identifier.
   * The promise will resolve when the lock has been acquired.
   *
   * @param identifier - Resource to acquire a lock on.
   */
  acquire: (identifier: ResourceIdentifier) => Promise<void>;

  /**
   * Releases a lock on the requested identifier.
   * The promise will resolve when the lock has been released.
   * If there is no lock on the resource, an error should be thrown.
   *
   * @param identifier - Resource to release the lock on.
   */
  release: (identifier: ResourceIdentifier) => Promise<void>;
}

import type { Callback, Redis } from 'ioredis';
import { InternalServerError } from '../../errors/InternalServerError';

const SUFFIX_WLOCK = '.wlock';
const SUFFIX_LOCK = '.lock';
const SUFFIX_COUNT = '.count';
const LOCKED = 'locked';

/**
 * Lua scripts to be used as Redis operations.
 */
export const REDIS_LUA_SCRIPTS = {
  acquireReadLock: `
    -- Return 0 if an entry already exists.
    local lockKey = KEYS[1].."${SUFFIX_WLOCK}"
    if redis.call("exists", lockKey) == 1 then
      return 0
    end

    -- Return true if succeeded (and counter is incremented)
    local countKey = KEYS[1].."${SUFFIX_COUNT}"
    return redis.call("incr", countKey) > 0
    `,
  acquireWriteLock: `
    -- Return 0 if a lock entry already exists or read count is > 0
    local lockKey = KEYS[1].."${SUFFIX_WLOCK}"
    local countKey = KEYS[1].."${SUFFIX_COUNT}"
    local count = tonumber(redis.call("get", countKey))
    if ((redis.call("exists", lockKey) == 1) or (count ~= nil and count > 0)) then
      return 0
    end

    -- Set lock and respond with 'OK' if succeeded (otherwise null)
    return redis.call("set", lockKey, "${LOCKED}");
    `,
  releaseReadLock: `
      -- Return 1 after decreasing the counter, if counter is < 0 now: return '-ERR'
      local countKey = KEYS[1].."${SUFFIX_COUNT}"
      local result = redis.call("decr", countKey)
      if result >= 0 then
        return 1
      else 
        return redis.error_reply("Error trying to release readlock when read count was 0.")
      end
    `,
  releaseWriteLock: `
      -- Release the lock and reply with 1 if succeeded (otherwise return '-ERR')
      local lockKey = KEYS[1].."${SUFFIX_WLOCK}"
      local result = redis.call("del", lockKey)
      if (result > 0) then
        return 1
      else
        return redis.error_reply("Error trying to release writelock that did not exist.")
      end
    `,
  acquireLock: `
      -- Return 0 if lock entry already exists, or 'OK' if it succeeds in setting the lock entry.
      local key = KEYS[1].."${SUFFIX_LOCK}"
      if redis.call("exists", key) == 1 then
        return 0
      end

      -- Return 'OK' if succeeded setting entry
      return redis.call("set", key, "${LOCKED}");
      `,
  releaseLock: `
      -- Release the lock and reply with 1 if succeeded (otherwise return '-ERR')
      local key = KEYS[1].."${SUFFIX_LOCK}"
      local result = redis.call("del", key)
      if result > 0 then
        return 1
      else
        return redis.error_reply("Error trying to release lock that did not exist.")
      end
    `,
} as const;

export type RedisAnswer = 0 | 1 | null | string;

/**
 * Convert a RESP2 response to a boolean.
 *
 * @param result - The Promise-wrapped result of a RESP2 Redis function.
 *
 * @returns * `1`, `'OK'`: return `true`
 *          * `0`: returns `false`
 *          * `-ERR`: throw error
 *
 * @throws On `-ERR*` `null` or any other value
 */
export async function fromResp2ToBool(result: Promise<RedisAnswer>): Promise<boolean> {
  const res = await result;
  switch (res) {
    case 1:
    case 'OK':
      return true;
    case 0:
      return false;
    case null:
      throw new Error('Redis operation error detected (value was null).');
    default:
      if (res.startsWith('-ERR')) {
        throw new InternalServerError(`Redis error: ${res.slice(5)}`);
      } else {
        throw new InternalServerError(`Unexpected Redis answer received! (${res})`);
      }
  }
}

export interface RedisReadWriteLock extends Redis {
  /**
   * Try to acquire a readLock on `resourceIdentifierPath`.
   * Will succeed if there are no write locks.
   *
   * @returns 1 if succeeded. 0 if not possible.
   */
  acquireReadLock: (resourceIdentifierPath: string, callback?: Callback<string>) => Promise<RedisAnswer>;

  /**
   * Try to acquire a writeLock on `resourceIdentifierPath`.
   * Only works if no other write lock is present and the read counter is 0.
   *
   * @returns 'OK' if succeeded, 0 if not possible.
   */
  acquireWriteLock: (resourceIdentifierPath: string, callback?: Callback<string>) => Promise<RedisAnswer>;

  /**
   * Release readLock. This means decrementing the read counter with 1.
   *
   * @returns 1 if succeeded. '-ERR' if read count goes below 0
   */
  releaseReadLock: (resourceIdentifierPath: string, callback?: Callback<string>) => Promise<RedisAnswer>;

  /**
   * Release writeLock. This means deleting the write lock.
   *
   * @returns 1 if succeeded. '-ERR' if write lock was non-existing.
   */
  releaseWriteLock: (resourceIdentifierPath: string, callback?: Callback<string>) => Promise<RedisAnswer>;
}

export interface RedisResourceLock extends Redis {
  /**
   * Try to acquire a lock  on `resourceIdentifierPath`.
   * Only works if no other lock is present.
   *
   * @returns 'OK' if succeeded, 0 if not possible.
   */
  acquireLock: (resourceIdentifierPath: string, callback?: Callback<string>) => Promise<RedisAnswer>;

  /**
   * Release lock. This means deleting the lock.
   *
   * @returns 1 if succeeded. '-ERR' if lock was non-existing.
   */
  releaseLock: (resourceIdentifierPath: string, callback?: Callback<string>) => Promise<RedisAnswer>;
}

import type { ResourceIdentifier } from '../../http/representation/ResourceIdentifier';
import { getLoggerFor } from '../../logging/LogUtil';
import type { PromiseOrValue } from '../PromiseUtil';
import type { ExpiringReadWriteLocker } from './ExpiringReadWriteLocker';

/**
 * This locker will execute the whileLocked function without any locking mechanism
 *
 * Do not use this locker in combination with storages that doesn't handle concurrent read/writes gracefully
 */

function noop(): void { /* Empty */ }

export class VoidLocker implements ExpiringReadWriteLocker {
  protected readonly logger = getLoggerFor(this);

  public constructor() {
    this.logger.warn('Locking mechanism disabled; data integrity during parallel requests not guaranteed.');
  }

  public async withReadLock<T>(
    identifier: ResourceIdentifier,
    whileLocked: (maintainLock: () => void) => PromiseOrValue<T>,
  ): Promise<T> {
    return whileLocked(noop);
  }

  public async withWriteLock<T>(
    identifier: ResourceIdentifier,
    whileLocked: (maintainLock: () => void) => PromiseOrValue<T>,
  ): Promise<T> {
    return whileLocked(noop);
  }
}

import type { ResourceIdentifier } from '../../http/representation/ResourceIdentifier';
import { getLoggerFor } from '../../logging/LogUtil';
import { InternalServerError } from '../errors/InternalServerError';
import type { PromiseOrValue } from '../PromiseUtil';
import type { ExpiringReadWriteLocker } from './ExpiringReadWriteLocker';
import type { ReadWriteLocker } from './ReadWriteLocker';
import Timeout = NodeJS.Timeout;

/**
 * Wraps around an existing {@link ReadWriteLocker} and adds expiration logic to prevent locks from getting stuck.
 */
export class WrappedExpiringReadWriteLocker implements ExpiringReadWriteLocker {
  protected readonly logger = getLoggerFor(this);

  protected readonly locker: ReadWriteLocker;
  protected readonly expiration: number;

  /**
   * @param locker - Instance of ResourceLocker to use for acquiring a lock.
   * @param expiration - Time in ms after which the lock expires.
   */
  public constructor(locker: ReadWriteLocker, expiration: number) {
    this.locker = locker;
    this.expiration = expiration;
  }

  public async withReadLock<T>(
    identifier: ResourceIdentifier,
    whileLocked: (maintainLock: () => void) => PromiseOrValue<T>,
  ): Promise<T> {
    return this.locker.withReadLock(identifier, async(): Promise<T> => this.expiringPromise(identifier, whileLocked));
  }

  public async withWriteLock<T>(
    identifier: ResourceIdentifier,
    whileLocked: (maintainLock: () => void) => PromiseOrValue<T>,
  ): Promise<T> {
    return this.locker.withWriteLock(identifier, async(): Promise<T> => this.expiringPromise(identifier, whileLocked));
  }

  /**
   * Creates a Promise that either resolves the given input function or rejects if time runs out,
   * whichever happens first. The input function can reset the timer by calling the `maintainLock` function
   * it receives. The ResourceIdentifier is only used for logging.
   */
  private async expiringPromise<T>(
    identifier: ResourceIdentifier,
    whileLocked: (maintainLock: () => void) => PromiseOrValue<T>,
  ): Promise<T> {
    let timer: Timeout;
    let createTimeout: () => Timeout;

    // Promise that throws an error when the timer finishes
    const timerPromise = new Promise<never>((resolve, reject): void => {
      // Starts the timer that will cause this promise to error after a given time
      createTimeout = (): Timeout => setTimeout((): void => {
        this.logger.error(`Lock expired after ${this.expiration}ms on ${identifier.path}`);
        reject(new InternalServerError(`Lock expired after ${this.expiration}ms on ${identifier.path}`));
      }, this.expiration);

      timer = createTimeout();
    });

    // Restarts the timer
    const renewTimer = (): void => {
      this.logger.verbose(`Renewed expiring lock on ${identifier.path}`);
      clearTimeout(timer);
      timer = createTimeout();
    };

    // Runs the main function and cleans up the timer afterwards
    async function runWithTimeout(): Promise<T> {
      try {
        return await whileLocked(renewTimer);
      } finally {
        clearTimeout(timer);
      }
    }

    return Promise.race([ timerPromise, runWithTimeout() ]);
  }
}

import { getLoggerFor } from '../logging/LogUtil';
import { InternalServerError } from './errors/InternalServerError';

const logger = getLoggerFor('LockUtil');

/**
 * Waits a set amount of time, without consuming cpu, with a set amount of jitter.
 *
 * @param delay - How long to wait.
 * @param jitter - A fraction of this jitter will be added to the delay.
 *
 * @returns A promise that resolves after the specified amount of time.
 */
export async function setJitterTimeout(delay: number, jitter = 0): Promise<void> {
  jitter = Math.max(0, Math.floor(Math.random() * jitter));
  delay = Math.max(0, delay + jitter);
  return new Promise<void>((resolve): unknown => setTimeout(resolve, delay));
}

export interface AttemptSettings {
  /** How many times should an operation be retried. (-1 is indefinitely). */
  retryCount?: number;
  /** The how long should the next retry be delayed (+ some retryJitter) (in ms). */
  retryDelay?: number;
  /** Add a fraction of jitter to the original delay each attempt (in ms). */
  retryJitter?: number;
}

/**
 * Will execute the given function until one of the following cases occurs:
 * * The function resolves to a value: the value is returned.
 * * The function errors: the rejected error is thrown.
 * * The function did not resolve after the set amount of retries: the rejected error is returned.
 *
 * @param fn - The function to retry. **This function must return a value!**
 * @param settings - The options on how to retry the function
 */
export async function retryFunction<T>(fn: () => Promise<T>, settings: Required<AttemptSettings>): Promise<T> {
  const { retryCount, retryDelay, retryJitter } = settings;
  const maxTries = retryCount === -1 ? Number.POSITIVE_INFINITY : retryCount + 1;
  let tries = 1;
  let result = await fn();

  while (typeof result === 'undefined' && tries < maxTries) {
    await setJitterTimeout(retryDelay, retryJitter);
    result = await fn();
    tries += 1;
  }

  // Max tries was reached: throw first!
  if (tries >= maxTries) {
    const err = `The operation did not succeed after the set maximum of tries (${maxTries}).`;
    logger.warn(err);
    throw new InternalServerError(err);
  }

  return result;
}

import { map } from '../IterableUtil';

type Entry<TKey, TVal> = { key: TKey; value: TVal };

/**
 * A {@link Map} implementation that maps the Key object to a string using the provided hash function.
 * This ensures that equal objects that are not the same instance are mapped to the same value.
 */
export class HashMap<TKey = unknown, TVal = unknown> implements Map<TKey, TVal> {
  private readonly hashMap: Map<string, Entry<TKey, TVal>>;
  private readonly hashFn: (key: TKey) => string;

  public constructor(hashFn: (key: TKey) => string, iterable?: Iterable<readonly [TKey, TVal]>) {
    this.hashFn = hashFn;

    if (iterable) {
      this.hashMap = new Map(map(iterable, ([ key, value ]): [string, Entry<TKey, TVal>] =>
        [ this.hashFn(key), { key, value }]));
    } else {
      this.hashMap = new Map();
    }
  }

  public has(key: TKey): boolean {
    return this.hashMap.has(this.hashFn(key));
  }

  public get(key: TKey): TVal | undefined {
    return this.hashMap.get(this.hashFn(key))?.value;
  }

  public set(key: TKey, value: TVal): this {
    this.hashMap.set(this.hashFn(key), { key, value });
    return this;
  }

  public delete(key: TKey): boolean {
    return this.hashMap.delete(this.hashFn(key));
  }

  public clear(): void {
    this.hashMap.clear();
  }

  public [Symbol.iterator](): IterableIterator<[TKey, TVal]> {
    return this.entries();
  }

  public* entries(): IterableIterator<[TKey, TVal]> {
    for (const [ , { key, value }] of this.hashMap) {
      yield [ key, value ];
    }
  }

  public* keys(): IterableIterator<TKey> {
    for (const [ , { key }] of this.hashMap) {
      yield key;
    }
  }

  public* values(): IterableIterator<TVal> {
    for (const [ , { value }] of this.hashMap) {
      yield value;
    }
  }

  public forEach(callbackfn: (value: TVal, key: TKey, map: Map<TKey, TVal>) => void, thisArg?: unknown): void {
    for (const [ key, value ] of this) {
      callbackfn.bind(thisArg)(value, key, this);
    }
  }

  public get size(): number {
    return this.hashMap.size;
  }

  public readonly [Symbol.toStringTag] = 'HashMap';
}

import type { ResourceIdentifier } from '../../http/representation/ResourceIdentifier';
import { HashMap } from './HashMap';
import { WrappedSetMultiMap } from './WrappedSetMultiMap';

/**
 * Converts a {@link ResourceIdentifier} into a string unique to that identifier.
 */
export function identifierHashFn(identifier: ResourceIdentifier): string {
  return identifier.path;
}

/**
 * A specific implementation of {@link HashMap} where the key type is {@link ResourceIdentifier}.
 */
export class IdentifierMap<T> extends HashMap<ResourceIdentifier, T> {
  public constructor(iterable?: Iterable<readonly [ResourceIdentifier, T]>) {
    super(identifierHashFn, iterable);
  }
}

/**
 * A specific implementation of {@link WrappedSetMultiMap} where the key type is {@link ResourceIdentifier}.
 */
export class IdentifierSetMultiMap<T> extends WrappedSetMultiMap<ResourceIdentifier, T> {
  public constructor(iterable?: Iterable<readonly [ResourceIdentifier, T | ReadonlySet<T>]>) {
    super(IdentifierMap, iterable);
  }
}

import { resolvePromiseOrValue } from '../PromiseUtil';
import type { PromiseOrValue } from '../PromiseUtil';
import type { SetMultiMap } from './SetMultiMap';

export type ArrayElement<TArray extends readonly unknown[]> = TArray[number];
export type EmptyObject = Record<string, never>;

export type MapKey<T> = T extends Map<infer TKey, unknown> ? TKey : never;
export type MapValue<T> = T extends Map<unknown, infer TValue> ? TValue : never;
export type MapEntry<T> = T extends Map<unknown, unknown> ? [MapKey<T>, MapValue<T>] : never;

/**
 * A simplified version of {@link MapConstructor} that only allows creating an empty {@link Map}.
 */
export type EmptyMapConstructor = new() => Map<unknown, unknown>;

/**
 * Options describing the necessary changes when calling {@link modify}.
 */
export type ModifyOptions<T extends SetMultiMap<unknown, unknown>> = {
  /**
   * Entries that need to be added to the Map.
   */
  add?: Iterable<MapEntry<T>>;
  /**
   * Keys that need to be removed from the Map.
   */
  remove?: Iterable<MapKey<T>>;
};

/**
 * Modifies a {@link SetMultiMap} in place by removing and adding the requested entries.
 * Removals happen before additions.
 *
 * @param map - Map to start from.
 * @param options - {@link ModifyOptions} describing the necessary changes.
 */
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export function modify<T extends SetMultiMap<any, any>>(map: T, options: ModifyOptions<T>): T {
  for (const key of options.remove ?? []) {
    map.delete(key);
  }
  for (const [ key, val ] of options.add ?? []) {
    map.add(key, val);
  }
  return map;
}

/**
 * Finds the result of calling `map.get(key)`.
 * If there is no result, it instead returns the result of the default function.
 * The Map will also be updated to assign that default value to the given key.
 *
 * @param map - Map to use.
 * @param key - Key to find the value for.
 * @param defaultFn - Function to generate default value to insert and return if no result was found.
 */
export function getDefault<TKey, TValue>(map: Map<TKey, TValue>, key: TKey, defaultFn: () => TValue): TValue;
/**
 * Finds the result of calling `map.get(key)`.
 * If there is no result, it instead returns the result of the default function.
 * The Map will also be updated to assign the resolved default value to the given key.
 *
 * @param map - Map to use.
 * @param key - Key to find the value for.
 * @param defaultFn - Function to generate default value to insert and return if no result was found.
 */
export function getDefault<TKey, TValue>(map: Map<TKey, TValue>, key: TKey, defaultFn: () => Promise<TValue>):
Promise<TValue>;
export function getDefault<TKey, TValue>(map: Map<TKey, TValue>, key: TKey, defaultFn: () => PromiseOrValue<TValue>):
PromiseOrValue<TValue> {
  const value = map.get(key);
  if (value) {
    return value;
  }
  return resolvePromiseOrValue<TValue, TValue>(defaultFn(), (val): TValue => {
    map.set(key, val);
    return val;
  });
}

/**
 * A SetMultiMap is a Map where a single key can have multiple unique values.
 * Deleting a key removes all bindings with this key from the Map.
 * Setting a value for a key replaces all previous bindings with this key.
 * Using an empty Set when calling the `set` function is the same as deleting that key.
 */
export interface SetMultiMap<TKey, TVal> extends Map<TKey, TVal | ReadonlySet<TVal>> {
  /**
   * Returns all values stored for the given key.
   * Returns `undefined` if there are no values for this key.
   */
  get: (key: TKey) => ReadonlySet<TVal> | undefined;
  /**
   * Returns true if this key/value binding exists in the Map.
   */
  hasEntry: (key: TKey, value: TVal) => boolean;
  /**
   * Adds the given key/value binding to the Map.
   */
  add: (key: TKey, value: TVal | ReadonlySet<TVal>) => this;
  /**
   * Deletes the given key/value binding from the Map.
   */
  deleteEntry: (key: TKey, value: TVal) => boolean;

  /**
   * Returns a Readonly {@link Map} representation of this Map.
   */
  asMap: () => ReadonlyMap<TKey, ReadonlySet<TVal>>;

  /**
   * Iterates over all key/value bindings in this Map.
   */
  [Symbol.iterator]: () => IterableIterator<[TKey, TVal]>;
  /**
   * Iterates over all key/value bindings in this Map.
   */
  entries: () => IterableIterator<[TKey, TVal]>;
  /**
   * Iterates over all distinct keys in this Map, together with a {@link Set} of their values.
   */
  entrySets: () => IterableIterator<[TKey, ReadonlySet<TVal>]>;
  /**
   * Iterates over all distinct keys in this Map.
   */
  distinctKeys: () => IterableIterator<TKey>;
  /**
   * Iterates over all values in this Map.
   */
  values: () => IterableIterator<TVal>;
  /**
   * Iterates over all distinct keys and returns their {@link Set} of values.
   */
  valueSets: () => IterableIterator<ReadonlySet<TVal>>;
  /**
   * Loops over all key/value bindings.
   */
  forEach: (callbackfn: (value: TVal, key: TKey, map: SetMultiMap<TKey, TVal>) => void, thisArg?: unknown) => void;
}

import type { SetMultiMap } from './SetMultiMap';

/**
 * A {@link SetMultiMap} that uses an internal Map based on the provided constructor.
 *
 * In case no input constructor is provided, the default Map implementation will be used.
 *
 * It is required that the value type of this map is not Set or any extension of Set,
 * otherwise the `set` and `add` functions wil break.
 */
export class WrappedSetMultiMap<TKey, TVal> implements SetMultiMap<TKey, TVal> {
  private count: number;
  private readonly map: Map<TKey, Set<TVal>>;

  /**
   * @param mapConstructor - Will be used to instantiate the internal Map.
   * @param iterable - Entries to add to the map.
   */
  public constructor(
    mapConstructor: new() => Map<TKey, Set<TVal>> = Map,
    iterable?: Iterable<readonly [TKey, TVal | ReadonlySet<TVal>]>,
  ) {
    // eslint-disable-next-line new-cap
    this.map = new mapConstructor();
    this.count = 0;

    if (iterable) {
      for (const [ key, val ] of iterable) {
        this.add(key, val);
      }
    }
  }

  public has(key: TKey): boolean {
    return this.map.has(key);
  }

  public hasEntry(key: TKey, value: TVal): boolean {
    return Boolean(this.map.get(key)?.has(value));
  }

  public get(key: TKey): ReadonlySet<TVal> | undefined {
    return this.map.get(key);
  }

  public set(key: TKey, value: ReadonlySet<TVal> | TVal): this {
    const setCount = this.get(key)?.size ?? 0;
    const set = value instanceof Set ? new Set<TVal>(value) : new Set([ value as TVal ]);
    this.count += set.size - setCount;
    if (set.size > 0) {
      this.map.set(key, set);
    } else {
      this.map.delete(key);
    }

    return this;
  }

  public add(key: TKey, value: TVal | ReadonlySet<TVal>): this {
    const it = value instanceof Set ? value as Set<TVal> : [ value as TVal ];
    let set = this.map.get(key);
    if (set) {
      const originalCount = set.size;
      for (const entry of it) {
        set.add(entry);
      }
      this.count += set.size - originalCount;
    } else {
      set = new Set(it);
      this.count += set.size;
      this.map.set(key, set);
    }

    return this;
  }

  public delete(key: TKey): boolean {
    const setCount = this.get(key)?.size ?? 0;
    const existed = this.map.delete(key);
    this.count -= setCount;
    return existed;
  }

  public deleteEntry(key: TKey, value: TVal): boolean {
    const set = this.map.get(key);
    if (set?.delete(value)) {
      this.count -= 1;
      if (set.size === 0) {
        this.map.delete(key);
      }
      return true;
    }
    return false;
  }

  public clear(): void {
    this.map.clear();
    this.count = 0;
  }

  public asMap(): ReadonlyMap<TKey, ReadonlySet<TVal>> {
    return this.map;
  }

  public [Symbol.iterator](): IterableIterator<[TKey, TVal]> {
    return this.entries();
  }

  public* entries(): IterableIterator<[TKey, TVal]> {
    for (const [ key, set ] of this.map) {
      for (const value of set) {
        yield [ key, value ];
      }
    }
  }

  public* entrySets(): IterableIterator<[TKey, ReadonlySet<TVal>]> {
    yield* this.map.entries();
  }

  public* keys(): IterableIterator<TKey> {
    for (const [ key ] of this.entries()) {
      yield key;
    }
  }

  public distinctKeys(): IterableIterator<TKey> {
    return this.map.keys();
  }

  public* values(): IterableIterator<TVal> {
    for (const [ , value ] of this.entries()) {
      yield value;
    }
  }

  public valueSets(): IterableIterator<ReadonlySet<TVal>> {
    return this.map.values();
  }

  public forEach(callbackfn: (value: TVal, key: TKey, map: SetMultiMap<TKey, TVal>) => void, thisArg?: unknown): void {
    for (const [ key, value ] of this) {
      callbackfn.bind(thisArg)(value, key, this);
    }
  }

  public get size(): number {
    return this.count;
  }

  public readonly [Symbol.toStringTag] = 'WrappedSetMultiMap';
}

import { posix, win32 } from 'node:path';
import { readJson } from 'fs-extra';
import urljoin from 'url-join';
import type { TargetExtractor } from '../http/input/identifier/TargetExtractor';
import type { ResourceIdentifier } from '../http/representation/ResourceIdentifier';
import type { HttpRequest } from '../server/HttpRequest';
import { BadRequestHttpError } from './errors/BadRequestHttpError';
import { errorTermsToMetadata } from './errors/HttpErrorUtil';
import type { Json } from './Json';

/**
 * Changes a potential Windows path into a POSIX path.
 *
 * @param path - Path to check (POSIX or Windows).
 *
 * @returns The potentially changed path (POSIX).
 */
function windowsToPosixPath(path: string): string {
  return path.replaceAll(/\\+/gu, '/');
}

/**
 * Resolves relative segments in the path.
 *
 * @param path - Path to check (POSIX or Windows).
 *
 * @returns The potentially changed path (POSIX).
 */
export function normalizeFilePath(path: string): string {
  return posix.normalize(windowsToPosixPath(path));
}

/**
 * Adds the paths to the base path.
 *
 * @param basePath - The base path (POSIX or Windows).
 * @param paths - Subpaths to attach (POSIX).
 *
 * @returns The potentially changed path (POSIX).
 */
export function joinFilePath(basePath: string, ...paths: string[]): string {
  return posix.join(windowsToPosixPath(basePath), ...paths);
}

/**
 * Resolves a path to its absolute form.
 * Absolute inputs will not be changed (except changing Windows to POSIX).
 * Relative inputs will be interpreted relative to process.cwd().
 *
 * @param path - Path to check (POSIX or Windows).
 *
 * @returns The potentially changed path (POSIX).
 */
export function absoluteFilePath(path: string): string {
  if (posix.isAbsolute(path)) {
    return path;
  }
  if (win32.isAbsolute(path)) {
    return windowsToPosixPath(path);
  }

  return joinFilePath(process.cwd(), path);
}

/**
 * Makes sure the input path has exactly 1 slash at the end.
 * Multiple slashes will get merged into one.
 * If there is no slash it will be added.
 *
 * @param path - Path to check.
 *
 * @returns The potentially changed path.
 */
export function ensureTrailingSlash(path: string): string {
  return path.replace(/\/*$/u, '/');
}

/**
 * Makes sure the input path has no slashes at the end.
 *
 * @param path - Path to check.
 *
 * @returns The potentially changed path.
 */
export function trimTrailingSlashes(path: string): string {
  return path.replace(/\/+$/u, '');
}

/**
 * Makes sure the input path has exactly 1 slash at the beginning.
 * Multiple slashes will get merged into one.
 * If there is no slash it will be added.
 *
 * @param path - Path to check.
 *
 * @returns The potentially changed path.
 */
export function ensureLeadingSlash(path: string): string {
  return path.replace(/^\/*/u, '/');
}

/**
 * Makes sure the input path has no slashes at the beginning.
 *
 * @param path - Path to check.
 *
 * @returns The potentially changed path.
 */
export function trimLeadingSlashes(path: string): string {
  return path.replace(/^\/+/u, '');
}

/**
 * Extracts the extension (without dot) from a path.
 * Custom function since `path.extname` does not work on all cases (e.g. ".acl")
 *
 * @param path - Input path to parse.
 */
export function getExtension(path: string): string {
  const extension = /\.([^./]+)$/u.exec(path);
  return extension ? extension[1] : '';
}

/**
 * Performs a transformation on the path components of a URI,
 * preserving but normalizing path delimiters and their escaped forms.
 */
function transformPathComponents(path: string, transform: (part: string) => string): string {
  const [ , base, queryString ] = /^([^?]*)(\?.*)?$/u.exec(path)!;
  const transformed = base
    // We split on actual URI path component delimiters (slash and backslash),
    // but also on things that could be wrongly interpreted as component delimiters,
    // such that they cannot be transformed incorrectly.
    // We thus ensure that encoded slashes (%2F) and backslashes (%5C) are preserved,
    // since they would become _actual_ delimiters if accidentally decoded.
    // Additionally, we need to preserve any encoded percent signs (%25)
    // that precede them, because these might change their interpretation as well.
    .split(/(\/|\\|%(?:25)*(?:2f|5c))/iu)
    // Even parts map to components that need to be transformed,
    // odd parts to (possibly escaped) delimiters that need to be normalized.
    .map((part, index): string =>
      index % 2 === 0 ? transform(part) : part.toUpperCase())
    .join('');
  return queryString ? `${transformed}${queryString}` : transformed;
}

/**
 * Converts a URI path to the canonical version by splitting on slashes,
 * decoding any percent-based encodings, and then encoding any special characters.
 * This function is used to clean unwanted characters in the components of
 * the provided path.
 *
 * @param path - The path to convert to its canonical URI path form.
 *
 * @returns The canonical URI path form of the provided path.
 */
export function toCanonicalUriPath(path: string): string {
  return transformPathComponents(path, (part): string =>
    encodeURIComponent(decodeURIComponent(part)));
}

/* eslint-disable @typescript-eslint/naming-convention */
// Characters not allowed in a Windows file path
const forbiddenSymbols = {
  '<': '%3C',
  '>': '%3E',
  ':': '%3A',
  '"': '%22',
  '|': '%7C',
  '?': '%3F',
  // `*` does not get converted by `encodeUriComponent`
  '*': '%2A',
} as const;
/* eslint-enable @typescript-eslint/naming-convention */
const forbiddenRegex = new RegExp(`[${Object.keys(forbiddenSymbols).join('')}]`, 'gu');
/**
 * This function is used when converting a URI to a file path. Decodes all components of a URI path,
 * with the exception of encoded slash characters, as this would lead to unexpected file locations
 * being targeted (resulting in erroneous behaviour of the file based backend).
 * Characters that would result in an illegal file path remain percent encoded.
 *
 * @param path - The path to decode the URI path components of.
 *
 * @returns A decoded copy of the provided URI path (ignoring encoded slash characters).
 */
export function decodeUriPathComponents(path: string): string {
  return transformPathComponents(path, (part): string => decodeURIComponent(part)
    // The characters replaced below result in illegal Windows file paths so need to be encoded
    .replaceAll(forbiddenRegex, (val): string => forbiddenSymbols[val as keyof typeof forbiddenSymbols]));
}

/**
 * This function is used in the process of converting a file path to a URI. Encodes all (non-slash)
 * special characters in a URI path, with the exception of encoded slash characters, as this would
 * lead to unnecessary double encoding, resulting in a URI that differs from the expected result.
 *
 * @param path - The path to encode the URI path components of.
 *
 * @returns An encoded copy of the provided URI path (ignoring encoded slash characters).
 */
export function encodeUriPathComponents(path: string): string {
  return transformPathComponents(path, encodeURIComponent);
}

/**
 * Checks whether the path corresponds to a container path (ending in a /).
 *
 * @param path - Path to check.
 */
export function isContainerPath(path: string): boolean {
  // Solid, §3.1: "Paths ending with a slash denote a container resource."
  // https://solid.github.io/specification/protocol#uri-slash-semantics
  return path.endsWith('/');
}

/**
 * Checks whether the identifier corresponds to a container identifier.
 *
 * @param identifier - Identifier to check.
 */
export function isContainerIdentifier(identifier: ResourceIdentifier): boolean {
  return isContainerPath(identifier.path);
}

/**
 * Splits a URL (or similar) string into a part containing its scheme and one containing the rest.
 * E.g., `http://test.com/` results in `{ scheme: 'http://', rest: 'test.com/' }`.
 *
 * @param url - String to parse.
 */
export function extractScheme(url: string): { scheme: string; rest: string } {
  const match = /^([^:]+:\/\/)(.*)$/u.exec(url)!;
  return { scheme: match[1], rest: match[2] };
}

/**
 * Creates a relative URL by removing the base URL.
 * Will throw an error in case the resulting target is not withing the base URL scope.
 *
 * @param baseUrl - Base URL.
 * @param request - Incoming request of which the target needs to be extracted.
 * @param targetExtractor - Will extract the target from the request.
 */
export async function getRelativeUrl(baseUrl: string, request: HttpRequest, targetExtractor: TargetExtractor):
Promise<string> {
  baseUrl = ensureTrailingSlash(baseUrl);
  const target = await targetExtractor.handleSafe({ request });
  if (!target.path.startsWith(baseUrl)) {
    throw new BadRequestHttpError(
      `The identifier ${target.path} is outside the configured identifier space.`,
      { errorCode: 'E0001', metadata: errorTermsToMetadata({ path: target.path }) },
    );
  }
  return target.path.slice(baseUrl.length - 1);
}

/**
 * Creates a regular expression that matches URLs containing the given baseUrl, or a subdomain of the given baseUrl.
 * In case there is a subdomain, the first match of the regular expression will be that subdomain.
 *
 * Examples with baseUrl `http://test.com/foo/`:
 * - Will match `http://test.com/foo/`
 * - Will match `http://test.com/foo/bar/baz`
 * - Will match `http://alice.bob.test.com/foo/bar/baz`, first match result will be `alice.bob`
 * - Will not match `http://test.com/`
 * - Will not match `http://alicetest.com/foo/`
 *
 * @param baseUrl - Base URL for the regular expression.
 */
export function createSubdomainRegexp(baseUrl: string): RegExp {
  const { scheme, rest } = extractScheme(baseUrl);
  return new RegExp(`^${scheme}(?:([^/]+)\\.)?${rest}`, 'u');
}

/**
 * Returns the folder corresponding to the root of the Community Solid Server module
 */
export function getModuleRoot(): string {
  return joinFilePath(__dirname, '../../');
}

/**
 * A placeholder for the path to the `@solid/community-server` module root.
 * The `resolveAssetPath` function will replace this string with the actual path.
 */
export const modulePathPlaceholder = '@css:';

/**
 * Creates a path starting from the `@solid/community-server` module root,
 * to be resolved by the `resolveAssetPath` function.
 */
export function modulePath(relativePath = ''): string {
  return `${modulePathPlaceholder}${relativePath}`;
}

/**
 * Creates an absolute path starting from the `@solid/community-server` module root.
 */
export function resolveModulePath(relativePath = ''): string {
  return joinFilePath(getModuleRoot(), relativePath);
}

/**
 * Converts file path inputs into absolute paths.
 * Works similar to `absoluteFilePath` but paths that start with the `modulePathPlaceholder`
 * will be relative to the module directory instead of the cwd.
 */
export function resolveAssetPath(path = modulePathPlaceholder): string {
  if (path.startsWith(modulePathPlaceholder)) {
    return resolveModulePath(path.slice(modulePathPlaceholder.length));
  }
  return absoluteFilePath(path);
}

/**
 * Reads the project package.json and returns it.
 */
export async function readPackageJson(): Promise<Record<string, Json>> {
  return readJson(resolveModulePath('package.json')) as Promise<Record<string, Json>>;
}

/**
 * Concatenates all the given strings into a normalized URL.
 * Will place slashes between input strings if necessary.
 */
export const joinUrl = urljoin;

import { types } from 'node:util';
import { createAggregateError } from './errors/HttpErrorUtil';

export type PromiseOrValue<T> = T | Promise<T>;

/**
 * Verifies if the given value is a Promise or not.
 *
 * @param object - Object to check.
 */
export function isPromise<T>(object: PromiseOrValue<T>): object is Promise<T> {
  return types.isPromise(object);
}

/**
 * Calls `callback` with the resolved value of `object`.
 * In case `object` is a Promise, the result will also be a Promise,
 * otherwise the result will be sync.
 */
export function resolvePromiseOrValue<TIn, TOut>(object: PromiseOrValue<TIn>, callback: (val: TIn) => TOut):
PromiseOrValue<TOut> {
  if (isPromise(object)) {
    return object.then((val): TOut => callback(val));
  }
  return callback(object);
}

function noop(): void { /* Empty */ }

/**
 * A function that simulates the Array.some behaviour but on an array of Promises.
 * Returns true if at least one promise returns true.
 * Returns false if all promises return false or error.
 *
 * @remarks
 *
 * Predicates provided as input must be implemented considering
 * the following points:
 * 1. if they throw an error, it won't be propagated;
 * 2. throwing an error should be logically equivalent to returning false.
 */
export async function promiseSome(predicates: Promise<boolean>[]): Promise<boolean> {
  return new Promise((resolve): void => {
    function resolveIfTrue(value: boolean): void {
      if (value) {
        resolve(true);
      }
    }
    Promise.all(predicates.map(async(predicate): Promise<void> => predicate.then(resolveIfTrue, noop)))
      .then((): void => resolve(false), noop);
  });
}

/**
 * Obtains the values of all fulfilled promises.
 * If there are rejections (and `ignoreErrors` is false), throws a combined error of all rejected promises.
 */
export async function allFulfilled<T>(promises: Promise<T> [], ignoreErrors = false): Promise<T[]> {
  // Collect values and errors
  const values: T[] = [];
  const errors: Error[] = [];
  for (const result of await Promise.allSettled(promises)) {
    if (result.status === 'fulfilled') {
      values.push(result.value);
    } else if (!ignoreErrors) {
      errors.push(result.reason as Error);
    }
  }

  // Either throw or return
  if (errors.length > 0) {
    throw createAggregateError(errors);
  }
  return values;
}

import type { Readable } from 'node:stream';
import type { NamedNode, Quad, Term } from '@rdfjs/types';
import arrayifyStream from 'arrayify-stream';
import type { ParserOptions, Store } from 'n3';
import { StreamParser, StreamWriter } from 'n3';
import type { Guarded } from './GuardedStream';
import { guardedStreamFrom, pipeSafely } from './StreamUtil';
import { toNamedTerm } from './TermUtil';

/**
 * Helper function for serializing an array of quads, with as result a Readable object.
 *
 * @param quads - The array of quads.
 * @param contentType - The content-type to serialize to.
 *
 * @returns The Readable object.
 */
export function serializeQuads(quads: Quad[], contentType?: string): Guarded<Readable> {
  return pipeSafely(guardedStreamFrom(quads), new StreamWriter({ format: contentType }));
}

/**
 * Helper function to convert a Readable into an array of quads.
 *
 * @param readable - The readable object.
 * @param options - Options for the parser.
 *
 * @returns A promise containing the array of quads.
 */
export async function parseQuads(readable: Guarded<Readable>, options: ParserOptions = {}): Promise<Quad[]> {
  return arrayifyStream(pipeSafely(readable, new StreamParser(options)));
}

/**
 * Filter out duplicate quads from an array.
 *
 * @param quads - Quads to filter.
 *
 * @returns A new array containing the unique quads.
 */
export function uniqueQuads(quads: Quad[]): Quad[] {
  const uniques: Quad[] = [];
  for (const quad of quads) {
    if (!uniques.some((item): boolean => quad.equals(item))) {
      uniques.push(quad);
    }
  }
  return uniques;
}

/**
 * Converts a term to a number. Returns undefined if the term was undefined.
 *
 * @param term - Term to parse.
 * @param radix - Radix to use when parsing. Default is 10.
 */
export function termToInt(term?: Term, radix = 10): number | undefined {
  if (term) {
    return Number.parseInt(term.value, radix);
  }
}

/**
 * Represents a triple pattern to be used as a filter.
 */
export class FilterPattern {
  public readonly subject: NamedNode | null;
  public readonly predicate: NamedNode | null;
  public readonly object: NamedNode | null;

  /**
   * @param subject - Optionally filter based on a specific subject.
   * @param predicate - Optionally filter based on a predicate.
   * @param object - Optionally filter based on a specific object.
   */
  public constructor(subject?: string, predicate?: string, object?: string) {
    this.subject = typeof subject === 'string' ? toNamedTerm(subject) : null;
    this.predicate = typeof predicate === 'string' ? toNamedTerm(predicate) : null;
    this.object = typeof object === 'string' ? toNamedTerm(object) : null;
  }
}

/**
 * Represents a binding result from a SPARQL query.
 * The keys are the values of the Variable objects,
 * while the values are the terms mapped to those variables in a query result.
 */
export type SimpleBinding = Record<string, Term>;

/**
 * Finds the matching bindings in the given data set for the given BGP query.
 *
 * @param bgp - BGP to solve
 * @param data - Dataset to query.
 */
export function solveBgp(bgp: Quad[], data: Store): SimpleBinding[] {
  let result: SimpleBinding[] = [{}];
  for (const pattern of bgp) {
    const newResult: SimpleBinding[] = [];
    for (const binding of result) {
      newResult.push(...getAppliedBindings(pattern, binding, data));
    }
    result = newResult;
  }
  return result;
}

/**
 * Queries a data store with a pattern to find all resulting bindings.
 * Before matching the pattern with the store,
 * the given binding is applied to the pattern first.
 *
 * The resulting binding includes the given binding.
 *
 * @param pattern - Pattern to match with the data store.
 * @param binding - Pattern to first apply to the given pattern.
 * @param data - Data store to query.
 */
export function getAppliedBindings(pattern: Quad, binding: SimpleBinding, data: Store): SimpleBinding[] {
  const result: SimpleBinding[] = [];
  const matches = data.getQuads(
    pattern.subject.termType === 'Variable' ? binding[pattern.subject.value] : pattern.subject,
    pattern.predicate.termType === 'Variable' ? binding[pattern.predicate.value] : pattern.predicate,
    pattern.object.termType === 'Variable' ? binding[pattern.object.value] : pattern.object,
    null,
  );
  for (const match of matches) {
    result.push({
      ...binding,
      ...matchBinding(pattern, match),
    });
  }
  return result;
}

/**
 * Finds the binding necessary to match the given pattern to the given quad.
 * This function assumes it has been verified that the pattern can match the quad.
 *
 * @param pattern - Pattern that can match the quad.
 * @param match - A quad that can be matched by the given pattern.
 */
export function matchBinding(pattern: Quad, match: Quad): SimpleBinding {
  const result: SimpleBinding = {};
  for (const pos of [ 'subject', 'predicate', 'object' ] as const) {
    if (pattern[pos].termType === 'Variable') {
      result[pattern[pos].value] = match[pos];
    }
  }
  return result;
}

/**
 * Helper class for instantiating multiple objects with Components.js.
 * See https://github.com/LinkedSoftwareDependencies/Components.js/issues/26
 */
// eslint-disable-next-line @typescript-eslint/no-extraneous-class
export class RecordObject implements Record<string, unknown> {
  public constructor(record: Record<string, unknown> = {}) {
    // eslint-disable-next-line no-constructor-return
    return record;
  }

  [key: string]: unknown;
}

import arrayifyStream from 'arrayify-stream';
import { DataFactory } from 'n3';
import { BasicRepresentation } from '../http/representation/BasicRepresentation';
import type { Representation } from '../http/representation/Representation';
import { RepresentationMetadata } from '../http/representation/RepresentationMetadata';
import type { Conditions } from '../storage/conditions/Conditions';
import type { ETagHandler } from '../storage/conditions/ETagHandler';
import { NotModifiedHttpError } from './errors/NotModifiedHttpError';
import { guardedStreamFrom } from './StreamUtil';
import { toLiteral } from './TermUtil';
import { CONTENT_TYPE_TERM, DC, HH, LDP, RDF, SOLID_META, XSD } from './Vocabularies';
import namedNode = DataFactory.namedNode;

/**
 * Helper function to generate type quads for a Container or Resource.
 *
 * @param metadata - Metadata to add to.
 * @param isContainer - If the identifier corresponds to a container.
 */
export function addResourceMetadata(metadata: RepresentationMetadata, isContainer: boolean): void {
  if (isContainer) {
    metadata.add(RDF.terms.type, LDP.terms.Container);
    metadata.add(RDF.terms.type, LDP.terms.BasicContainer);
  }
  metadata.add(RDF.terms.type, LDP.terms.Resource);
}

/**
 * Updates the dc:modified time to the given time.
 *
 * @param metadata - Metadata to update.
 * @param date - Last modified date. Defaults to current time.
 */
export function updateModifiedDate(metadata: RepresentationMetadata, date = new Date()): void {
  const lastModified = new Date(date);
  metadata.set(DC.terms.modified, toLiteral(lastModified.toISOString(), XSD.terms.dateTime));
}

/**
 * Links a template file with a given content-type to the metadata using the SOLID_META.template predicate.
 *
 * @param metadata - Metadata to update.
 * @param templateFile - Path to the template.
 * @param contentType - Content-type of the template after it is rendered.
 */
export function addTemplateMetadata(metadata: RepresentationMetadata, templateFile: string, contentType: string):
void {
  const templateNode = namedNode(templateFile);
  metadata.add(SOLID_META.terms.template, templateNode);
  metadata.addQuad(templateNode, CONTENT_TYPE_TERM, contentType);
}

/**
 * Helper function to clone a representation, the original representation can still be used.
 * This function loads the entire stream in memory.
 *
 * @param representation - The representation to clone.
 *
 * @returns The cloned representation.
 */
export async function cloneRepresentation(representation: Representation): Promise<BasicRepresentation> {
  const data = await arrayifyStream(representation.data);
  const result = new BasicRepresentation(
    data,
    new RepresentationMetadata(representation.metadata),
    representation.binary,
  );
  representation.data = guardedStreamFrom(data);
  return result;
}

/**
 * Verify whether the given {@link Representation} matches the given conditions.
 * If true, add the corresponding ETag to the body metadata.
 * If not, destroy the data stream and throw a {@link NotModifiedHttpError} with the same ETag.
 * If `conditions` is not defined, nothing will happen.
 *
 * This uses the strict conditions check which takes the content type into account;
 * therefore, this should only be called after content negotiation, when it is certain what the output will be.
 *
 * Note that browsers only keep track of one ETag, and the Vary header has no impact on this,
 * meaning the browser could send us the ETag for a Turtle resource even though it is requesting JSON-LD;
 * this is why we have to check ETags after content negotiation.
 *
 * @param body - The representation to compare the conditions against.
 * @param eTagHandler - Used to generate the ETag to return with the 304 response.
 * @param conditions - The conditions to assert.
 */
export function assertReadConditions(body: Representation, eTagHandler: ETagHandler, conditions?: Conditions): void {
  const eTag = eTagHandler.getETag(body.metadata);
  if (conditions && !conditions.matchesMetadata(body.metadata, true)) {
    body.data.destroy();
    const error = new NotModifiedHttpError(eTag);

    // From RFC 9111:
    // > the cache MUST add each header field in the provided response to the stored response,
    // > replacing field values that are already present
    // So we need to make sure to send either no partial headers, or the exact same headers.
    // By adding the metadata of the original resource here, we ensure we send the same headers.
    error.metadata.identifier = body.metadata.identifier;
    error.metadata.addQuads(body.metadata.quads());

    throw error;
  }
  body.metadata.set(HH.terms.etag, eTag);
}

import type { Readable, TransformCallback, TransformOptions } from 'node:stream';
import { Transform } from 'node:stream';
import { RangeNotSatisfiedHttpError } from './errors/RangeNotSatisfiedHttpError';
import { pipeSafely } from './StreamUtil';

export interface SliceStreamOptions extends TransformOptions {
  start: number;
  end?: number;
  size?: number;
}

/**
 * A stream that slices a part out of another stream.
 * `start` and `end` are inclusive.
 * If `end` is not defined it is until the end of the stream.
 *
 * Negative `start` values can be used to instead slice that many streams off the end of the stream.
 * This requires the `size` field to be defined.
 *
 * Both object and non-object streams are supported.
 * This needs to be explicitly specified,
 * as the class makes no assumptions based on the object mode of the source stream.
 */
export class SliceStream extends Transform {
  protected readonly source: Readable;
  protected remainingSkip: number;
  protected remainingRead: number;

  public constructor(source: Readable, options: SliceStreamOptions) {
    super(options);
    let start = options.start;
    const end = options.end ?? Number.POSITIVE_INFINITY;
    if (options.start < 0) {
      if (typeof options.size === 'number') {
        // `start` is a negative number here so need to add
        start = options.size + start;
      } else {
        throw new RangeNotSatisfiedHttpError('Slicing data at the end of a stream requires a known size.');
      }
    }

    if (start >= end) {
      throw new RangeNotSatisfiedHttpError('Range start should be less than end.');
    }

    // Not using `end` variable as that could be infinity
    if (typeof options.end === 'number' && typeof options.size === 'number' && options.end >= options.size) {
      throw new RangeNotSatisfiedHttpError('Range end should be less than the total size.');
    }

    this.remainingSkip = start;
    // End value is inclusive
    this.remainingRead = end - options.start + 1;

    this.source = source;
    pipeSafely(source, this);
  }

  // eslint-disable-next-line @typescript-eslint/naming-convention
  public _transform(chunk: unknown, encoding: BufferEncoding, callback: TransformCallback): void {
    this.source.pause();
    if (this.writableObjectMode) {
      this.objectSlice(chunk);
    } else {
      this.binarySlice(chunk as Buffer);
    }

    this.source.resume();
    callback();
  }

  protected binarySlice(chunk: Buffer): void {
    let length = chunk.length;
    if (this.remainingSkip > 0) {
      chunk = chunk.subarray(this.remainingSkip);
      this.remainingSkip -= length - chunk.length;
      length = chunk.length;
    }
    if (length > 0 && this.remainingSkip <= 0) {
      chunk = chunk.subarray(0, this.remainingRead);
      this.push(chunk);
      this.remainingRead -= length;
      this.checkEnd();
    }
  }

  protected objectSlice(chunk: unknown): void {
    if (this.remainingSkip > 0) {
      this.remainingSkip -= 1;
    } else {
      this.remainingRead -= 1;
      this.push(chunk);
      this.checkEnd();
    }
  }

  /**
   * Stop piping the source stream and close everything once the slice is finished.
   */
  protected checkEnd(): void {
    if (this.remainingRead <= 0) {
      this.source.unpipe();
      this.end();
      this.source.destroy();
    }
  }
}

import type { DuplexOptions, ReadableOptions, Writable } from 'node:stream';
import { Readable, Transform } from 'node:stream';
import { promisify } from 'node:util';
import arrayifyStream from 'arrayify-stream';
import eos from 'end-of-stream';
import { Store } from 'n3';
import pump from 'pump';
import { getLoggerFor } from '../logging/LogUtil';
import { isHttpRequest } from '../server/HttpRequest';
import { InternalServerError } from './errors/InternalServerError';
import type { Guarded } from './GuardedStream';
import { guardStream } from './GuardedStream';
import type { Json } from './Json';
import type { PromiseOrValue } from './PromiseUtil';

export const endOfStream = promisify(eos);

const logger = getLoggerFor('StreamUtil');

/**
 * Joins all strings of a stream.
 *
 * @param stream - Stream of strings.
 *
 * @returns The joined string.
 */
export async function readableToString(stream: Readable): Promise<string> {
  return (await arrayifyStream<string>(stream)).join('');
}

/**
 * Imports quads from a stream into a Store.
 *
 * @param stream - Stream of quads.
 *
 * @returns A Store containing all the quads.
 */
export async function readableToQuads(stream: Readable): Promise<Store> {
  const quads = new Store();
  quads.import(stream);
  await endOfStream(stream);
  return quads;
}

/**
 * Interprets the stream as JSON and converts it to a Dict.
 *
 * @param stream - Stream of JSON data.
 *
 * @returns The parsed object.
 */
export async function readJsonStream(stream: Readable): Promise<Json> {
  const body = await readableToString(stream);
  return JSON.parse(body) as Json;
}

/**
 * Converts the stream to a single object.
 * This assumes the stream is in object mode and only contains a single element,
 * otherwise an error will be thrown.
 *
 * @param stream - Object stream with single entry.
 */
export async function getSingleItem(stream: Readable): Promise<unknown> {
  const items = await arrayifyStream(stream);
  if (items.length !== 1) {
    throw new InternalServerError('Expected a stream with a single object.');
  }
  return items[0] as unknown;
}

// These error messages usually indicate expected behaviour so should not give a warning.
// We compare against the error message instead of the code
// since the second one is from an external library that does not assign an error code.
// At the time of writing the first one gets thrown in Node 16 and the second one in Node 14.
const safeErrors = new Set([
  'Cannot call write after a stream was destroyed',
  'premature close',
]);

/**
 * Pipes one stream into another and emits errors of the first stream with the second.
 * If the first stream errors, the second one will be destroyed with the given error.
 * This will also make the stream {@link Guarded}.
 *
 * @param readable - Initial readable stream.
 * @param destination - The destination for writing data.
 * @param mapError - Optional function that takes the error and converts it to a new error.
 *
 * @returns The destination stream.
 */
export function pipeSafely<T extends Writable>(
  readable: NodeJS.ReadableStream,
  destination: T,
  mapError?: (error: Error) => Error,
): Guarded<T> {
  // We never want to closes the incoming HttpRequest if there is an error
  // since that also closes the outgoing HttpResponse.
  // Since `pump` sends stream errors both up and down the pipe chain,
  // in this case we need to make sure the error only goes down the chain.
  if (isHttpRequest(readable)) {
    readable.pipe(destination);
    readable.on('error', (error): void => {
      logger.warn(`HttpRequest errored with ${error.message}`);
      // From https://nodejs.org/api/stream.html#stream_readable_pipe_destination_options :
      // One important caveat is that if the Readable stream emits an error during processing,
      // the Writable destination is not closed automatically. If an error occurs,
      // it will be necessary to manually close each stream in order to prevent memory leaks.
      destination.destroy(mapError ? mapError(error) : error);
    });
  } else {
    // In case the input readable is guarded, it will no longer log errors since `pump` attaches a new error listener
    pump(readable, destination, (error): void => {
      if (error) {
        const msg = `Piped stream errored with ${error.message}`;
        logger.log(safeErrors.has(error.message) ? 'debug' : 'warn', msg);

        // Make sure the final error can be handled in a normal streaming fashion
        destination.emit('error', mapError ? mapError(error) : error);
      }
    });
  }
  // Guarding the stream now means the internal error listeners of pump will be ignored
  // when checking if there is a valid error listener.
  return guardStream(destination);
}

export interface AsyncTransformOptions<T = unknown> extends DuplexOptions {
  /**
   * Transforms data from the source by calling the `push` method
   */
  transform?: (this: Transform, data: T, encoding: string) => PromiseOrValue<unknown>;

  /**
   * Performs any final actions after the source has ended
   */
  flush?: (this: Transform) => PromiseOrValue<unknown>;
}

/**
 * Transforms a stream, ensuring that all errors are forwarded.
 *
 * @param source - The stream to be transformed.
 * @param options - The transformation options.
 * @param options.transform - The transform function to use.
 * @param options.flush - The flush function to use.
 *
 * @returns The transformed stream
 */
export function transformSafely<T = unknown>(
  source: NodeJS.ReadableStream,
  {
    transform = function(data): void {
      this.push(data);
    },
    flush = (): null => null,
    ...options
  }: AsyncTransformOptions<T> = {},
): Guarded<Transform> {
  return pipeSafely(source, new Transform({
    ...options,
    async transform(data: T, encoding, callback): Promise<void> {
      let error: Error | null = null;
      try {
        await transform.call(this, data, encoding);
      } catch (err: unknown) {
        error = err as Error;
      }
      callback(error);
    },
    async flush(callback): Promise<void> {
      let error: Error | null = null;
      try {
        await flush.call(this);
      } catch (err: unknown) {
        error = err as Error;
      }
      callback(error);
    },
  }));
}

/**
 * Converts a string or array to a stream and applies an error guard so that it is {@link Guarded}.
 *
 * @param contents - Data to stream.
 * @param options - Options to pass to the Readable constructor. See {@link Readable.from}.
 */
export function guardedStreamFrom(contents: string | Iterable<unknown>, options?: ReadableOptions): Guarded<Readable> {
  return guardStream(Readable.from(typeof contents === 'string' ? [ contents ] : contents, options));
}

/**
 * Splits a string by comma.
 *
 * @param input - String instance to split.
 *
 * @returns A String array containining the split parts.
 */
export function splitCommaSeparated(input: string): string[] {
  return input.split(/\s*,\s*/u);
}

/**
 * Sanitizes part of a URL by replacing non-word content with a '-'.
 *
 * @param urlPart - The URL part to sanitize.
 *
 * @returns The sanitized output.
 */
export function sanitizeUrlPart(urlPart: string): string {
  return urlPart.replaceAll(/\W/gu, '-');
}

/**
 * Checks the validity of a file name. A valid name consists of word characters, '-' or '.'.
 *
 * @param name - The name of the file to validate.
 *
 * @returns True if the filename is valid, false otherwise.
 */
export function isValidFileName(name: string): boolean {
  return /^[\w.-]+$/u.test(name);
}

/**
 * Checks whether the given string is a valid URL.
 *
 * @param url - String to check.
 *
 * @returns True if the string is a valid URL.
 */
export function isUrl(url: string): boolean {
  try {
    // eslint-disable-next-line no-new
    new URL(url);
    return true;
  } catch {
    return false;
  }
}

/**
 * Converts milliseconds to an ISO 8601 duration string.
 * The only categories used are days, hours, minutes, and seconds,
 * because months have no fixed size in milliseconds.
 *
 * @param ms - The duration in ms to convert.
 */
export function msToDuration(ms: number): string {
  let totalSeconds = ms / 1000;
  const days = Math.floor(totalSeconds / (60 * 60 * 24));
  totalSeconds -= days * 60 * 60 * 24;
  const hours = Math.floor(totalSeconds / (60 * 60));
  totalSeconds -= hours * 60 * 60;
  const minutes = Math.floor(totalSeconds / 60);
  const seconds = totalSeconds - (minutes * 60);

  const stringParts: string[] = [ 'P' ];
  if (days > 0) {
    stringParts.push(`${days}D`);
  }
  if (hours > 0 || minutes > 0 || seconds > 0) {
    stringParts.push('T');
  }
  if (hours > 0) {
    stringParts.push(`${hours}H`);
  }
  if (minutes > 0) {
    stringParts.push(`${minutes}M`);
  }
  if (seconds > 0) {
    stringParts.push(`${seconds}S`);
  }

  return stringParts.join('');
}

import type { TemplateEngineInput } from './TemplateEngine';
import { TemplateEngine } from './TemplateEngine';
import Dict = NodeJS.Dict;

/**
 * Calls the given array of {@link TemplateEngine}s in the order they appear,
 * feeding the output of one into the input of the next.
 *
 * The first engine will be called with the provided contents and template parameters.
 * All subsequent engines will be called with no template parameter.
 * Contents will still be passed along and another entry will be added for the body of the previous output.
 */
export class ChainedTemplateEngine<T extends Dict<unknown> = Dict<unknown>> extends TemplateEngine<T> {
  private readonly firstEngine: TemplateEngine<T>;
  private readonly chainedEngines: TemplateEngine[];
  private readonly renderedName: string;

  /**
   * @param engines - Engines will be executed in the same order as the array.
   * @param renderedName - The name of the key used to pass the body of one engine to the next.
   */
  public constructor(engines: TemplateEngine[], renderedName = 'body') {
    super();
    if (engines.length === 0) {
      throw new Error('At least 1 engine needs to be provided.');
    }
    this.firstEngine = engines[0];
    this.chainedEngines = engines.slice(1);
    this.renderedName = renderedName;
  }

  public async canHandle(input: TemplateEngineInput<T>): Promise<void> {
    return this.firstEngine.canHandle(input);
  }

  public async handle({ contents, template }: TemplateEngineInput<T>): Promise<string> {
    let body = await this.firstEngine.handle({ contents, template });
    for (const engine of this.chainedEngines) {
      body = await engine.handleSafe({ contents: { ...contents, [this.renderedName]: body }});
    }
    return body;
  }
}

import { render } from 'ejs';
import { ExtensionBasedTemplateEngine } from './ExtensionBasedTemplateEngine';
import type { TemplateEngineInput } from './TemplateEngine';
import { getTemplateFilePath, readTemplate } from './TemplateUtil';
import Dict = NodeJS.Dict;

/**
 * Fills in EJS templates.
 */
export class EjsTemplateEngine<T extends Dict<unknown> = Dict<unknown>> extends ExtensionBasedTemplateEngine<T> {
  private readonly baseUrl: string;

  /**
   * @param baseUrl - Base URL of the server.
   * @param supportedExtensions - The extensions that are supported by this template engine (defaults to 'ejs').
   */
  public constructor(baseUrl: string, supportedExtensions = [ 'ejs' ]) {
    super(supportedExtensions);
    this.baseUrl = baseUrl;
  }

  public async handle({ contents, template }: TemplateEngineInput<T>): Promise<string> {
    const options = { ...contents, filename: getTemplateFilePath(template), baseUrl: this.baseUrl };
    return render(await readTemplate(template), options);
  }
}

import { NotImplementedHttpError } from '../errors/NotImplementedHttpError';
import { getExtension } from '../PathUtil';
import type { TemplateEngineInput } from './TemplateEngine';
import { TemplateEngine } from './TemplateEngine';
import { getTemplateFilePath } from './TemplateUtil';
import Dict = NodeJS.Dict;

/**
 * Parent class for template engines that accept handling based on whether the template extension is supported.
 */
export abstract class ExtensionBasedTemplateEngine<T extends Dict<unknown> = Dict<unknown>> extends TemplateEngine<T> {
  protected readonly supportedExtensions: string[];

  /**
   * Constructor for ExtensionBasedTemplateEngine.
   *
   * @param supportedExtensions - Array of the extensions supported by the template engine (e.g. [ 'ejs' ]).
   */
  protected constructor(supportedExtensions: string[]) {
    super();
    this.supportedExtensions = supportedExtensions;
  }

  public async canHandle({ template }: TemplateEngineInput<T>): Promise<void> {
    if (typeof template === 'undefined') {
      throw new NotImplementedHttpError('No template was provided.');
    }
    // Check if the target template extension is supported.
    const filepath = getTemplateFilePath(template);
    if (typeof filepath === 'undefined' || !this.supportedExtensions.includes(getExtension(filepath))) {
      throw new NotImplementedHttpError('The provided template is not supported.');
    }
  }
}

import { compile } from 'handlebars';
import { ExtensionBasedTemplateEngine } from './ExtensionBasedTemplateEngine';
import type { TemplateEngineInput } from './TemplateEngine';
import { readTemplate } from './TemplateUtil';
import Dict = NodeJS.Dict;

/**
 * Fills in Handlebars templates.
 */
export class HandlebarsTemplateEngine<T extends Dict<unknown> = Dict<unknown>> extends ExtensionBasedTemplateEngine<T> {
  private readonly baseUrl: string;

  /**
   * @param baseUrl - Base URL of the server.
   * @param supportedExtensions - The extensions that are supported by this template engine (defaults to 'hbs').
   */
  public constructor(baseUrl: string, supportedExtensions = [ 'hbs' ]) {
    super(supportedExtensions);
    this.baseUrl = baseUrl;
  }

  public async handle({ contents, template }: TemplateEngineInput<T>): Promise<string> {
    const applyTemplate = compile(await readTemplate(template));
    return applyTemplate({ ...contents, baseUrl: this.baseUrl });
  }
}

import type { AsyncHandler } from '../handlers/AsyncHandler';
import type { Template, TemplateEngineInput } from './TemplateEngine';
import { TemplateEngine } from './TemplateEngine';
import Dict = NodeJS.Dict;

/**
 * Template engine that renders output based on a static template file.
 */
export class StaticTemplateEngine<T extends Dict<unknown> = Dict<unknown>> extends TemplateEngine<T> {
  private readonly template: Template;
  private readonly templateEngine: AsyncHandler<TemplateEngineInput<T>, string>;

  /**
   * Creates a new StaticTemplateEngine.
   *
   * @param templateEngine - The template engine that should be used for processing the template.
   * @param template - The static template to be used.
   */
  public constructor(templateEngine: AsyncHandler<TemplateEngineInput<T>, string>, template: Template) {
    super();
    this.template = template;
    this.templateEngine = templateEngine;
  }

  public async canHandle({ contents, template }: TemplateEngineInput<T>): Promise<void> {
    if (typeof template !== 'undefined') {
      throw new TypeError('StaticTemplateEngine does not support template as handle input, ' +
        'provide a template via the constructor instead!');
    }
    return this.templateEngine.canHandle({ contents, template: this.template });
  }

  public async handle({ contents }: TemplateEngineInput<T>): Promise<string> {
    return this.templateEngine.handle({ contents, template: this.template });
  }
}

import { AsyncHandler } from '../handlers/AsyncHandler';
import Dict = NodeJS.Dict;

export type Template = TemplateFileName | TemplateString | TemplatePath;

export type TemplateFileName = string;

export interface TemplateString {
  // String contents of the template
  templateString: string;
}

export interface TemplatePath {
  // Name of the template file
  templateFile: string;
  // Path of the template file
  templatePath?: string;
}

/**
 * Utility interface for representing TemplateEngine input.
 */
export interface TemplateEngineInput<T> {
  // The contents to render
  contents: T;
  // The template to use for rendering (optional)
  template?: Template;
}

/**
 * Generic interface for classes that implement a template engine.
 * A template engine renders content into a template.
 */
export abstract class TemplateEngine<T extends Dict<unknown> = Dict<unknown>>
  extends AsyncHandler<TemplateEngineInput<T>, string> {}

import { promises as fsPromises } from 'node:fs';
import { joinFilePath, resolveAssetPath } from '../PathUtil';
import type { Template } from './TemplateEngine';

/**
 * Returns the absolute path to the template.
 * Returns undefined if the input does not contain a file path.
 */
export function getTemplateFilePath(template?: Template): string | undefined {
  // The template has been passed as a filename
  if (typeof template === 'string') {
    return getTemplateFilePath({ templateFile: template });
  }
  // The template has already been given as a string so no known path
  if (!template || 'templateString' in template) {
    return;
  }
  const { templateFile, templatePath } = template;
  const fullTemplatePath = templatePath ? joinFilePath(templatePath, templateFile) : templateFile;
  return resolveAssetPath(fullTemplatePath);
}

/**
 * Reads the template and returns it as a string.
 */
export async function readTemplate(template?: Template): Promise<string> {
  // The template has already been given as a string
  if (typeof template === 'undefined' || (typeof template === 'object' && 'templateString' in template)) {
    return template?.templateString ?? '';
  }
  // The template needs to be read from disk
  return fsPromises.readFile(getTemplateFilePath(template)!, 'utf8');
}

import { DataFactory } from 'n3';
import type { Literal, NamedNode, Term } from '@rdfjs/types';

const { namedNode, literal } = DataFactory;

/**
 * @param input - Checks if this is a {@link Term}.
 */
export function isTerm(input?: unknown): input is Term {
  return Boolean(input) && typeof (input as Term).termType === 'string';
}

/**
 * Converts a string to a named node when needed.
 *
 * @param subject - Subject to potentially transform.
 */
export function toNamedTerm(subject: string): NamedNode;
export function toNamedTerm<T extends Term>(subject: T): T;
export function toNamedTerm<T extends Term>(subject: T | string): T | NamedNode;
export function toNamedTerm(subject: Term | string): Term {
  return typeof subject === 'string' ? namedNode(subject) : subject;
}

export const toPredicateTerm = toNamedTerm;

/**
 * Converts an object term when needed.
 *
 * @param object - Object to potentially transform.
 * @param preferLiteral - Whether strings are converted to literals or named nodes.
 */
export function toObjectTerm(object: string, preferLiteral?: boolean): NamedNode;
export function toObjectTerm<T extends Term>(object: T, preferLiteral?: boolean): T;
export function toObjectTerm<T extends Term>(object: T | string, preferLiteral?: boolean): T | NamedNode;
export function toObjectTerm(object: Term | string, preferLiteral = false): Term {
  if (typeof object === 'string') {
    return preferLiteral ? literal(object) : namedNode(object);
  }
  return object;
}

/**
 * Creates a literal by first converting the dataType string to a named node.
 *
 * @param object - Object value.
 * @param dataType - Object data type (as string).
 */
export function toLiteral(object: string | number, dataType: NamedNode): Literal {
  return literal(`${object}`, dataType);
}

import type { Logger } from '../logging/Logger';
import { createErrorMessage } from './errors/ErrorUtil';

/**
 * Wraps the callback for {@link setInterval} so errors get caught and logged.
 * Parameters are identical to the {@link setInterval} parameters starting from the 3rd argument.
 * The logger and message will be used when the callback throws an error.
 * Supports asynchronous callback functions.
 */
export function setSafeInterval<TArgs>(
  logger: Logger,
  message: string,
  callback: (...cbArgs: TArgs[]) => Promise<void> | void,
  ms?: number,
  ...args: TArgs[]
): NodeJS.Timeout {
  async function safeCallback(...cbArgs: TArgs[]): Promise<void> {
    try {
      // We don't know if the callback is async or not so this way we make sure
      // the full function execution is done in the try block.
      // eslint-disable-next-line callback-return
      await callback(...cbArgs);
    } catch (error: unknown) {
      logger.error(`Error during interval callback: ${message} - ${createErrorMessage(error)}`);
    }
  }
  // eslint-disable-next-line @typescript-eslint/no-misused-promises
  return setInterval(safeCallback, ms, ...args);
}

import { DataFactory } from 'n3';
import type { NamedNode } from '@rdfjs/types';

/**
 * A `Record` in which each value is a concatenation of the baseUrl and its key.
 */
type ExpandedRecord<TBase extends string, TLocal extends string> = {[K in TLocal]: `${TBase}${K}` };

/**
 * Has a base URL as `namespace` value and each key has as value the concatenation with that base URL.
 */
type ValueVocabulary<TBase extends string, TLocal extends string> =
  { namespace: TBase } & ExpandedRecord<TBase, TLocal>;
/**
 * A {@link ValueVocabulary} where the URI values are {@link NamedNode}s.
 */
type TermVocabulary<T> = T extends ValueVocabulary<string, string> ? {[K in keyof T]: NamedNode<T[K]> } : never;

/**
 * Contains a namespace and keys linking to the entries in this namespace.
 * The `terms` field contains the same values but as {@link NamedNode} instead of string.
 */
export type Vocabulary<TBase extends string, TKey extends string> =
  ValueVocabulary<TBase, TKey> & { terms: TermVocabulary<ValueVocabulary<TBase, TKey>> };

/**
 * A {@link Vocabulary} where all the non-namespace fields are of unknown value.
 * This is a fallback in case {@link createVocabulary} gets called with a non-strict string array.
 */
export type PartialVocabulary<TBase extends string> =
  { namespace: TBase } &
  Partial<Record<string, string>> &
  { terms: { namespace: NamedNode<TBase> } & Partial<Record<string, NamedNode>> };

/**
 * A local name of a {@link Vocabulary}.
 */
export type VocabularyLocal<T> = T extends Vocabulary<string, infer TKey> ? TKey : never;
/**
 * A URI string entry of a {@link Vocabulary}.
 */
export type VocabularyValue<T> = T extends Vocabulary<string, infer TKey> ? T[TKey] : never;
/**
 * A {@link NamedNode} entry of a {@link Vocabulary}.
 */
export type VocabularyTerm<T> = T extends Vocabulary<string, infer TKey> ? T['terms'][TKey] : never;

/**
 * Creates a {@link ValueVocabulary} with the given `baseUri` as namespace and all `localNames` as entries.
 */
function createValueVocabulary<TBase extends string, TLocal extends string>(baseUri: TBase, localNames: TLocal[]):
ValueVocabulary<TBase, TLocal> {
  const expanded: Partial<ExpandedRecord<TBase, TLocal>> = {};
  // Expose the listed local names as properties
  for (const localName of localNames) {
    expanded[localName] = `${baseUri}${localName}`;
  }
  return {
    namespace: baseUri,
    ...expanded as ExpandedRecord<TBase, TLocal>,
  };
}

/**
 * Creates a {@link TermVocabulary} based on the provided {@link ValueVocabulary}.
 */
function createTermVocabulary<TBase extends string, TLocal extends string>(values: ValueVocabulary<TBase, TLocal>):
TermVocabulary<ValueVocabulary<TBase, TLocal>> {
  // Need to cast since `fromEntries` typings aren't strict enough
  return Object.fromEntries(
    Object.entries(values).map(([ key, value ]): [string, NamedNode] => [ key, DataFactory.namedNode(value) ]),
  ) as TermVocabulary<ValueVocabulary<TBase, TLocal>>;
}

/**
 * Creates a {@link Vocabulary} with the given `baseUri` as namespace and all `localNames` as entries.
 * The values are the local names expanded from the given base URI as strings.
 * The `terms` field contains all the same values but as {@link NamedNode} instead.
 */
export function createVocabulary<TBase extends string, TLocal extends string>(baseUri: TBase, ...localNames: TLocal[]):
string extends TLocal ? PartialVocabulary<TBase> : Vocabulary<TBase, TLocal> {
  const values = createValueVocabulary(baseUri, localNames);
  return {
    ...values,
    terms: createTermVocabulary(values),
  };
}

/**
 * Creates a new {@link Vocabulary} that extends an existing one by adding new local names.
 *
 * @param vocabulary - The {@link Vocabulary} to extend.
 * @param newNames - The new local names that need to be added.
 */
export function extendVocabulary<TBase extends string, TLocal extends string, TNew extends string>(
  vocabulary: Vocabulary<TBase, TLocal>,
  ...newNames: TNew[]
): ReturnType<typeof createVocabulary<TBase, TLocal | TNew>> {
  const localNames = Object.keys(vocabulary)
    .filter((key): boolean => key !== 'terms' && key !== 'namespace') as TLocal[];
  const allNames = [ ...localNames, ...newNames ];
  return createVocabulary(vocabulary.namespace, ...allNames);
}

export const ACL = createVocabulary(
  'http://www.w3.org/ns/auth/acl#',
  'accessTo',
  'agent',
  'agentClass',
  'agentGroup',
  'AuthenticatedAgent',
  'Authorization',
  'default',
  'mode',

  'Write',
  'Read',
  'Append',
  'Control',
);

export const ACP = createVocabulary(
  'http://www.w3.org/ns/solid/acp#',

  // Used for ACP middleware headers
  'AccessControlResource',
  'grant',
  'attribute',

  // Access Control Resource
  'resource',
  'accessControl',
  'memberAccessControl',

  // Access Control,
  'apply',

  // Policy
  'allow',
  'deny',
  'allOf',
  'anyOf',
  'noneOf',

  // Matcher
